// Content for Equal Parents (node g62, Parenthood, Chapter 8): NEW v2 build to GDD 62 (mechanic-embodying),
// taking the equal-home work of Equal Partners (g55) into RAISING CHILDREN: the stage where gendered defaults
// snap back hardest. Parenting isn't mum's job with dad "helping". 84 researched, India-grounded scenarios across
// share-the-care → parental-mental-load → involved-dads → kids-are-watching → everyone-gains → tools-and-help,
// each encoded as one of the shared v2 play actions (strike-rewrite / branch / sort / reflect / match / role-play
// / spot): no binary "tap the right card". Lead: strike-rewrite (bust the myth), branch (your move), sort. Six
// modes: share the care (split feeds, nights, appointments & school-runs through OWNED shares; both parents
// competent; only breastfeeding is mother-specific), the parental mental load (surface & share the invisible
// tracking/planning/worrying: sharing means owning the noticing, not doing tasks on request), involved dads
// (busts "fathers help / providing is enough / nurturing isn't a man's role"; hands-on, emotionally present
// fatherhood is good fathering AND a fuller manhood; addresses maternal gatekeeping), kids are watching (children
// learn gender roles by watching their parents: modelling shared care breaks the intergenerational divide;
// chores have no gender), everyone gains (shared parenting is better for children, mothers AND fathers: not a
// sacrifice or a trade; equality matters most exactly when kids arrive), tools & help (a fair-parenting &
// mental-load map, a shared calendar & weekly check-in, rebalanced over time; parental burnout routes to Looking
// After You g63). Even-handed and warm: engages fathers as equal OWNERS, never anti-men, frames involved
// fatherhood as PRO-men, and never shames any current arrangement. Builds on Equal Partners (g55) and Equalize
// (g26); beside Us, After Kids (g61). India: childcare defaults heavily to mothers & grandmothers, fathers cast as
// providers (reinforced by joint families & minimal paternity leave); greater paternal involvement lifts child
// development, marital satisfaction and fathers' own wellbeing. gameId "equal-parents".
import type { V2GameConfig, Scenario } from "./v2-schema";

const SCENARIOS: Scenario[] = [
  {"id":"ep2-001","cat":"share-the-care","type":"strike-rewrite","hook":"\"Hands-on childcare is naturally the mother's job.\"","myth":{"un":"Hands-on childcare is naturally the mother's job.","re":"Both parents can do feeds, nappies, nights and appointments; there's nothing about care that only a mother can do.","why":"Caregiving is learned by doing, not assigned by gender."},"relearn":"Hands-on care isn't naturally the mother's job; both parents can and should do it.","persona":"Vikram","source":"care isn't gendered"},
  {"id":"ep2-002","cat":"share-the-care","type":"sort","hook":"Sort: a task only the breastfeeding mother can do, or one either parent can own?","items":[{"id":"a","text":"Changing nappies"},{"id":"b","text":"Breastfeeding specifically"},{"id":"c","text":"Night soothing and rocking"},{"id":"d","text":"Booking and attending check-ups"},{"id":"e","text":"Giving a bottle feed"},{"id":"f","text":"Doing the school-run"}],"bins":[{"id":"either","label":"Either parent","valence":"pos"},{"id":"mum","label":"Mother-specific","valence":"neutral"}],"key":{"a":"either","b":"mum","c":"either","d":"either","e":"either","f":"either"},"relearn":"Only breastfeeding is mother-specific; nappies, soothing, appointments, bottle feeds and the school-run are jobs either parent can own.","persona":"any","source":"either or mum"},
  {"id":"ep2-003","cat":"share-the-care","type":"branch","persona":"Divya","source":"split the tasks","hook":"The night feeds, school-runs and appointments have all quietly defaulted to one of you.","steps":[{"prompt":"You both sit down to talk on Sunday. What do you do first?","options":[{"text":"Ask your mother to step in more","then":"Your mother agrees. The default just moves onto her."},{"text":"Write out every recurring care task together","then":"You fill a page. The list is longer than either of you expected.","best":true},{"text":"Let the default stand, because it's just easier","then":"Another week passes on the same pattern, and one of you is more tired."},{"text":"Divide the tasks evenly by number","then":"The count is equal, and the heavy parts sit with one of you."}],"why":"Mapping the care makes the default visible so it can be split fairly."},{"prompt":"Later that week, your partner asks how you might split the care. What do you say?","options":[{"text":"The one who's better at it does more","then":"The better one keeps doing it, and the other never gets practised."},{"text":"Split every task down the middle and tally it weekly","then":"You count nappies on a whiteboard. By Friday you are arguing over the count."},{"text":"Whoever is home does whatever comes up","then":"It works when both are home. When one travels, the other is on duty."},{"text":"Each takes whole areas, and we flex for each other","then":"Your partner nods. \"I'll take health. You take school.\"","best":true}],"why":"Owned areas with room to flex beat a scorecard and keep both of you capable."},{"prompt":"Two weeks in, a work crunch keeps your partner late three nights. What do you do?","options":[{"text":"Quietly take it all back, and say nothing","then":"You cope. Your partner never knows what it cost you."},{"text":"Say the whole split was a mistake","then":"Your partner looks stung. \"It only failed for three nights.\""},{"text":"Cover this week, then agree how to rebalance","then":"Your partner exhales. \"Thank you. I'll take the weekend.\"","best":true},{"text":"Insist the split stays exact, whatever happens","then":"You do your nights, and the evenings turn tense."}],"why":"Flexing for each other during a crunch keeps the split fair over the long run."},{"prompt":"Six months on, the baby's needs have shifted and the split feels off. What do you do?","options":[{"text":"Let the busier one just adapt","then":"The busier one adapts, and burns out slowly."},{"text":"Sit down and re-split the areas together","then":"You swap two areas. Both of you feel a lot lighter.","best":true},{"text":"Keep it as is, since it once worked","then":"One of you starts to quietly resent it."},{"text":"Wait until someone gets fed up","then":"Someone gets fed up in a fortnight, and the talk starts angry."}],"why":"Rebalancing regularly keeps a fair split fair as the baby grows."}],"debrief":"Map the recurring care and split it into fair, owned shares, not a one-parent default.","relearn":"Map and split the care fairly; 'it's easier' entrenches the default."},
  {"id":"ep2-004","cat":"share-the-care","type":"sort","hook":"Sort: a fairly shared care arrangement, or a lopsided one dressed up as sharing?","items":[{"id":"a","text":"Each parent owns whole tasks"},{"id":"b","text":"One does it all, one 'helps' sometimes"},{"id":"c","text":"Nights and mornings alternated"},{"id":"d","text":"One parent is always the backup"},{"id":"e","text":"Both can run a day solo"},{"id":"f","text":"She must remind him of each task"}],"bins":[{"id":"fair","label":"Fairly shared","valence":"pos"},{"id":"lopsided","label":"Lopsided","valence":"neg"}],"key":{"a":"fair","b":"lopsided","c":"fair","d":"lopsided","e":"fair","f":"lopsided"},"relearn":"Owning whole tasks, alternating nights and both running solo is fair; one doing it all while the other 'helps' or gets reminded is lopsided.","persona":"Vikram","source":"fair vs lopsided"},
  {"id":"ep2-005","cat":"share-the-care","type":"match","hook":"Match each shared-care move to what it achieves.","pairs":[{"left":"Each owns specific tasks","right":"No constant negotiating"},{"left":"Alternating nights","right":"Both rest and both bond"},{"left":"Both know the routines","right":"Either can step in fully"},{"left":"Both on the school forms","right":"Either parent gets the call"},{"left":"Dad does solo days","right":"Real skill, not supervised"}],"relearn":"Owning tasks, alternating nights, shared routines and contacts, and solo days all make care genuinely shareable.","persona":"any","source":"shared-care moves"},
  {"id":"ep2-006","cat":"share-the-care","type":"branch","persona":"Vikram","source":"step up","hook":"You realise you have drifted into doing almost none of the hands-on care.","steps":[{"prompt":"It's Saturday morning and your child is up early. What do you do?","options":[{"text":"Offer to help if your partner needs it","then":"She's already up and does most of it. You hover."},{"text":"Take your child out for an hour, then hand back","then":"The hour is fun. Everything else is still hers."},{"text":"Let her handle it, since she is up already","then":"She sighs and gets on with it."},{"text":"Take the whole morning: feed, dress, play","then":"You manage porridge, a sock war and a park visit. Your partner sleeps in.","best":true}],"why":"Owning a whole stretch of care is how you become a real co-parent."},{"prompt":"On Monday your child wakes with a fever, and your partner has an early meeting. What do you do?","options":[{"text":"Offer to help, but wait for instructions","then":"She writes the plan for you. She still runs the day, from her office."},{"text":"Ask your mother to come over","then":"Your mother arrives, and you both go to work."},{"text":"Take the day and handle the doctor yourself","then":"You call in, book the clinic, and keep the notes.","best":true},{"text":"Ask her to reschedule her meeting","then":"She moves it, with a tight jaw."}],"why":"Taking a whole day of care, doctor included, is part of your job as a parent."},{"prompt":"A month later, she says she'd love a lie-in on Sunday. What do you say?","options":[{"text":"\"Sure, but where do the wipes live again?\"","then":"She answers from bed. She is awake by eight."},{"text":"\"Yes, but I'll hand the baby back at the first cry.\"","then":"She hears the first cry from bed, and gets up."},{"text":"\"Sleep in. I've got everything.\"","then":"She goes back to bed, and you find the baby's socks yourself.","best":true},{"text":"\"Maybe next week. I'm tired too.\"","then":"She nods. The lie-in slips again."}],"why":"Taking care without hovering lets her actually rest."}],"debrief":"Own regular hands-on care to be a true co-parent, rather than offering occasional help.","relearn":"Step up to own regular care; occasional 'helping when needed' isn't co-parenting."},
  {"id":"ep2-007","cat":"share-the-care","type":"strike-rewrite","hook":"\"As long as I provide financially, I've done my part as a parent.\"","myth":{"un":"As long as I provide financially, I've done my part as a parent.","re":"Providing matters, but children need hands-on care and presence too; caregiving is a parent's responsibility, not an extra.","why":"Presence is part of the job, not a bonus."},"relearn":"Providing isn't the whole of parenting; hands-on care and presence are a parent's responsibility too.","persona":"Vikram","source":"more than providing"},
  {"id":"ep2-008","cat":"share-the-care","type":"role-play","persona":"Vikram","source":"claim competence","hook":"Your wife has a day out with friends, her first since the baby came.","setup":"She is already writing instructions.","steps":[{"prompt":"Your wife asks: \"Are you sure you can handle him alone all day?\"","options":[{"text":"\"Maybe leave a long list. I'll probably mess up.\"","then":"She keeps writing. Two pages later she is still adding."},{"text":"\"Why do you always think I can't do this?\"","then":"She stiffens. \"I just want him to be okay.\""},{"text":"\"I've got this. Go and enjoy your day.\"","then":"She hesitates, then smiles. \"Really? Okay. I'll try not to call.\"","best":true},{"text":"\"Can Ma come over instead? Just in case.\"","then":"She relaxes. \"Good idea. I'll ask her.\""}],"why":"A calm, confident yes shows you can carry the day yourself."},{"prompt":"Your wife says: \"He gets fussy around four. Do you know what to do?\"","options":[{"text":"\"I'll follow whatever the list says.\"","then":"She adds two more lines to the list."},{"text":"\"Yes. Feed, burp, then a walk. We do it daily.\"","then":"She blinks. \"You do know it.\" She looks a little lighter.","best":true},{"text":"\"I'll manage. You can call at lunch to check in.\"","then":"She nods. She plans to call at noon and again at three."},{"text":"\"Not really. Text me at four and I'll ask.\"","then":"\"Okay,\" she says, and sets a reminder on her own phone."}],"why":"Showing you know the routine builds her trust in you as an equal."},{"prompt":"Your wife comes home and asks: \"Was it okay? Did he nap and eat?\"","options":[{"text":"\"It was exhausting. I don't know how you do it.\"","then":"She smiles wearily. \"Now you know.\" She takes the baby from you."},{"text":"\"Sorry about the mess. He skipped his bath.\"","then":"She looks at the kitchen. \"Did the day go badly?\""},{"text":"\"Fine. Everything was fine.\"","then":"She wants details and asks for them one by one. You get short."},{"text":"\"He napped and ate. I'll do it again next weekend.\"","then":"She grins. \"Next weekend? I could get used to this.\"","best":true}],"why":"Offering a repeat turns one good day into a shared routine."}],"relearn":"Confidently owning solo care builds your competence and frees your partner from being the only capable one."},
  {"id":"ep2-009","cat":"share-the-care","type":"sort","hook":"Sort: builds both parents' competence, or keeps care one-sided?","items":[{"id":"a","text":"Both doing solo stretches with the child"},{"id":"b","text":"One always supervising the other"},{"id":"c","text":"Both learning the routines fully"},{"id":"d","text":"Treating one parent as the only 'expert'"},{"id":"e","text":"Swapping who does the early start"},{"id":"f","text":"Redoing his work 'properly' after"}],"bins":[{"id":"both","label":"Builds both","valence":"pos"},{"id":"oneside","label":"Keeps it one-sided","valence":"neg"}],"key":{"a":"both","b":"oneside","c":"both","d":"oneside","e":"both","f":"oneside"},"relearn":"Solo time, shared routines and swapping starts build both; constant supervision, a single 'expert' and redoing his work keep care one-sided.","persona":"any","source":"both vs one-sided"},
  {"id":"ep2-010","cat":"share-the-care","type":"spot","hook":"Spot the two things that aren't genuine shared care.","scene":[{"id":"a","text":"Both handle nights and appointments","trick":false},{"id":"b","text":"One parent named the 'main' one by default","trick":true},{"id":"c","text":"Either can run the day solo","trick":false},{"id":"d","text":"He only 'helps' when she asks","trick":true},{"id":"e","text":"Both know the full daily routine","trick":false}],"why":"A default 'main parent' and a dad who only 'helps when asked' aren't shared care; both should own real tasks and run solo.","relearn":"Shared care means both own the real tasks and either can run solo, with no default 'main parent' and no waiting to be asked.","persona":"any","source":"genuine shared care"},
  {"id":"ep2-011","cat":"share-the-care","type":"reflect","hook":"Lensy: shared care isn't a favour one parent does the other; it's just both doing their job. Sit right?","prompt":"What do you think?","options":["Sits right","Both our job","Not a favour"],"affirm":"Shared care is simply both parents doing their own job, not one doing the other a favour.","relearn":"Shared care isn't a favour; it's both parents doing their own job.","persona":"any","source":"not a favour"},
  {"id":"ep2-012","cat":"share-the-care","type":"branch","persona":"Vikram","source":"stay hands-on","hook":"Grandparents step in to help, and the load quietly shifts to them and the mother, not you.","steps":[{"prompt":"Your mother takes the baby from your arms. \"I'll do it, beta,\" she says. What do you do?","options":[{"text":"Let her take over, since she's so happy to help","then":"Your mother beams. You watch from the doorway, then check your phone."},{"text":"Ask your partner to come and take over","then":"Your partner arrives, tired, and takes the baby. You go to your phone."},{"text":"Thank her, and stay to watch her do it","then":"Your mother shows you how she does it. You learn by watching, not doing."},{"text":"Say you want to do this one yourself","then":"She smiles, surprised, and hands the baby back with tips.","best":true}],"why":"Welcoming family help while staying hands-on keeps you a full parent."},{"prompt":"That night your partner says quietly that she is still up at 2am, even with your mother here. What do you do?","options":[{"text":"Tell her to rest, and talk about it in the morning","then":"In the morning the house is busy, and the talk is forgotten."},{"text":"Take the 2am waking tonight, and tell your mother it's yours","then":"She lets out a long breath. \"Thank you.\"","best":true},{"text":"Ask your mother to take the nights too","then":"Your mother agrees. Now the night is hers, and yours is empty."},{"text":"Say Amma is only trying to help","then":"She nods slowly. She is still up at 2am."}],"why":"Taking the night shift yourself is what actually gives her rest."},{"prompt":"Over tea, your mother says nights are a mother's job, and fathers need their sleep. What do you say?","options":[{"text":"Say you'll do nights, but not while she's looking","then":"She nods. Any nights you do now happen out of her sight."},{"text":"Say kindly that your child needs both of you","then":"She thinks. \"Well, times are different.\"","best":true},{"text":"Say she's probably right, and stop","then":"She nods, satisfied. Your partner is still up at 2am."},{"text":"Say it's not her business","then":"She stiffens, hurt. \"I only want what's best.\""}],"why":"Explaining kindly why the baby needs both parents keeps Amma on your side."},{"prompt":"A week later, your mother asks how the nights should be shared now she is here. What do you say?","options":[{"text":"Say your partner is better at nights, and leave weeknights to her","then":"She nods, pleased. Your partner does every weeknight, and your share quietly shrinks."},{"text":"Let her cover your share, while your partner keeps hers","then":"Your mother covers your share. Your partner is still up on hers."},{"text":"Welcome one night a week from her, and keep your share","then":"She beams. \"Sundays, then.\" You and your partner split the rest.","best":true},{"text":"Accept them all, since sleep helps your work","then":"Your mother takes every night, and you drift out of the baby's nights."}],"why":"Welcoming her help while keeping your own share keeps you a hands-on parent."}],"debrief":"Stay a hands-on parent even with grandparents helping; don't let your share shift to others.","relearn":"Welcome family help but stay hands-on; don't let your share pass to others."},
  {"id":"ep2-013","cat":"share-the-care","type":"strike-rewrite","hook":"\"Splitting care 'fairly' means keeping a strict scorecard.\"","myth":{"un":"Splitting care fairly means keeping a strict scorecard.","re":"Fair sharing is about both owning real responsibility and flexing for each other, not tallying every nappy.","why":"Ownership and flexibility beat score-keeping."},"relearn":"Fair care is shared ownership and flexing for each other, not a strict nappy-by-nappy scorecard.","persona":"any","source":"ownership not score"},
  {"id":"ep2-014","cat":"share-the-care","type":"match","hook":"Match each recurring duty to a fair way to share it.","pairs":[{"left":"Night wake-ups","right":"Take turns or split the week"},{"left":"Doctor and school runs","right":"Each owns some, not all on one"},{"left":"Daily feeding and bathing","right":"Whoever's free, both capable"},{"left":"Sick days off work","right":"Alternate who stays home"},{"left":"Bedtime routine","right":"Own set nights each"}],"relearn":"Night wake-ups, appointments, daily care, sick days and bedtime each have a fair split when both parents are capable and willing.","persona":"any","source":"fair splits"},
  {"id":"ep2-015","cat":"parental-mental-load","type":"strike-rewrite","hook":"\"Remembering jabs, sizes, supplies and appointments isn't real work.\"","myth":{"un":"Remembering jabs, sizes, supplies and appointments isn't real work.","re":"The parental mental load, the constant tracking, planning and worrying, is real, tiring cognitive work that must be shared.","why":"Invisible work still wears you out."},"relearn":"The parental mental load, tracking, planning and worrying, is real, tiring work that has to be shared.","persona":"Divya","source":"load is real work"},
  {"id":"ep2-016","cat":"parental-mental-load","type":"sort","hook":"Sort: visible care task, or invisible parental mental load?","items":[{"id":"a","text":"Feeding the baby"},{"id":"b","text":"Remembering the vaccine schedule"},{"id":"c","text":"Bathing the child"},{"id":"d","text":"Noticing the nappies are running out"},{"id":"e","text":"Packing the school bag"},{"id":"f","text":"Tracking when the uniform stops fitting"}],"bins":[{"id":"visible","label":"Visible task","valence":"neutral"},{"id":"mental","label":"Mental load","valence":"tell"}],"key":{"a":"visible","b":"mental","c":"visible","d":"mental","e":"visible","f":"mental"},"relearn":"Feeding, bathing and packing are visible; remembering jabs, noticing supplies and tracking sizes is the mental load.","persona":"any","source":"visible vs mental"},
  {"id":"ep2-017","cat":"parental-mental-load","type":"strike-rewrite","hook":"\"If I do tasks when asked, I'm sharing the parenting equally.\"","myth":{"un":"If I do tasks when asked, I'm sharing the parenting equally.","re":"Being asked still leaves one parent as the manager who notices and remembers; sharing means owning the noticing too.","why":"Sharing the load means sharing the thinking."},"relearn":"Doing tasks when asked isn't equal; true sharing means owning the noticing and planning, not just the doing.","persona":"Vikram","source":"share the thinking"},
  {"id":"ep2-018","cat":"parental-mental-load","type":"sort","hook":"Sort: carrying the mental load, or genuinely sharing it?","items":[{"id":"a","text":"One parent plans every meal and appointment"},{"id":"b","text":"Both track what the child needs"},{"id":"c","text":"One remembers all the dates"},{"id":"d","text":"Both own whole domains end-to-end"},{"id":"e","text":"One waits to be told what to do"},{"id":"f","text":"Both notice problems without a reminder"}],"bins":[{"id":"carry","label":"One carries it","valence":"uhoh"},{"id":"share","label":"Genuinely shared","valence":"pos"}],"key":{"a":"carry","b":"share","c":"carry","d":"share","e":"carry","f":"share"},"relearn":"One planning, remembering and waiting is carrying it; both tracking, owning domains and noticing is sharing it.","persona":"Divya","source":"carry or share"},
  {"id":"ep2-019","cat":"parental-mental-load","type":"branch","persona":"Divya","source":"own domains","hook":"You remember everything for your child while your partner waits to be told.","steps":[{"prompt":"Tonight you both sit down after bedtime. What do you propose?","options":[{"text":"Stay the memory, since you're quicker at it anyway","then":"You handle it in half the time. Your partner relaxes, and your head stays full."},{"text":"Share a checklist you both tick through daily","then":"The checklist helps for a week. You are still the one who updates it."},{"text":"Each of you owns whole domains, like health and school","then":"He nods slowly. \"Okay. Which one should be mine first?\"","best":true},{"text":"Ask him to try harder to remember things","then":"He nods. Two days later he forgets the jab, and you catch it."}],"why":"Owning whole domains moves the remembering itself, not just the doing."},{"prompt":"A few days later, your partner says he wants to take something on. Which domain do you hand over?","options":[{"text":"Health, from jabs to doctor visits","then":"He opens a calendar. \"Give me the vaccine card, then.\"","best":true},{"text":"Small chores, like the pharmacy run","then":"He does the run. The what and when still come to him through you."},{"text":"Whatever is left after your share","then":"He takes the leftovers, and health, the hardest part, stays with you."},{"text":"Nothing yet, until he shows he can keep up","then":"He looks stung. \"How do I show it if I never start?\" He takes on the school forms anyway."}],"why":"A whole domain, health end to end, lets him own the noticing and the doing."},{"prompt":"Two weeks in, your partner misses a deadline on something he took on. What do you do?","options":[{"text":"Fix it without telling him","then":"It gets done. He never learns he missed it."},{"text":"Take it back, since it is too important to risk","then":"It gets done. He feels relieved, and quietly unneeded."},{"text":"Say this shows he isn't ready yet","then":"He goes quiet and stops looking at the messages."},{"text":"Let him fix it, and ask what he will change","then":"He makes the call, sorts it out and sets a reminder himself.","best":true}],"why":"Letting him recover from a slip is how he becomes as reliable as you."},{"prompt":"A month on, your partner suggests a Sunday check-in on how the split is going. What do you say?","options":[{"text":"Say you'll do it if things go wrong","then":"Things go wrong on a Thursday, and the talk starts angry."},{"text":"Yes, and swap domains if one feels heavy","then":"He smiles. \"Good. I'd like to try meals next.\"","best":true},{"text":"Say yes, but keep it to five minutes of tasks","then":"The talk stays on chores, and the worry goes unspoken."},{"text":"Say it's not needed, since it's working","then":"Three weeks later, one of you is quietly overloaded again."}],"why":"A regular check-in keeps whole domains fair as your child grows."}],"debrief":"Share the mental load by each parent owning whole domains, not one staying the manager.","relearn":"Split the load by each owning whole domains; don't leave one as the family's memory."},
  {"id":"ep2-020","cat":"parental-mental-load","type":"match","hook":"Match each invisible duty to the parent-load it really is.","pairs":[{"left":"Tracking growth, jabs, milestones","right":"Health mental load"},{"left":"Planning meals, supplies, sizes","right":"Logistics mental load"},{"left":"Sensing moods and needs","right":"Emotional mental load"},{"left":"Knowing fees, forms and term dates","right":"School mental load"},{"left":"Remembering who to call when","right":"Social mental load"}],"relearn":"Health, logistics, emotional, school and social tracking are all real parts of the parental mental load to share.","persona":"any","source":"kinds of load"},
  {"id":"ep2-021","cat":"parental-mental-load","type":"strike-rewrite","hook":"\"Mothers are just naturally better at remembering all the kid stuff.\"","myth":{"un":"Mothers are just naturally better at remembering all the kid stuff.","re":"It's not nature; whoever does the tracking gets practised at it, and either parent can carry their share of the planning.","why":"Practice, not biology, builds the skill."},"relearn":"Mothers aren't naturally better at the mental load; whoever practises it gets good at it, and both can share it.","persona":"any","source":"not natural"},
  {"id":"ep2-022","cat":"parental-mental-load","type":"reflect","hook":"Lensy: you can't share what you can't see; naming the mental load is the first step to splitting it. Make sense?","prompt":"What do you think?","options":["Makes sense","Name it first","I see it now"],"affirm":"You can't split a load you can't see; naming the parental mental load is the first step to sharing it.","relearn":"Naming the invisible parental mental load is the first step to sharing it fairly.","persona":"any","source":"name to share"},
  {"id":"ep2-023","cat":"parental-mental-load","type":"spot","hook":"Spot the two lines that leave one parent as the only manager.","scene":[{"id":"a","text":"\"Just tell me what needs doing and I'll do it.\"","trick":true},{"id":"b","text":"\"I'll fully run all the health stuff from now.\"","trick":false},{"id":"c","text":"\"You always remember the dates, so you keep that.\"","trick":true},{"id":"d","text":"\"Let's split the calendar and both check it.\"","trick":false},{"id":"e","text":"\"I'll notice when supplies run low, not wait.\"","trick":false}],"why":"Waiting to be told and leaving the remembering to one parent keep that parent the manager.","relearn":"Lines that wait for instructions or hand all remembering to one parent keep the load lopsided.","persona":"Vikram","source":"who manages"},
  {"id":"ep2-024","cat":"parental-mental-load","type":"branch","persona":"Vikram","source":"lift the weight","hook":"You realise your partner's mind is full of invisible child-admin and yours is not.","steps":[{"prompt":"You want to change that this week. What do you do?","options":[{"text":"Wait for her to tell you what she needs","then":"She says nothing, tired of asking. The week passes."},{"text":"Buy her a treat to say thank you","then":"She smiles, touched. The list in her head is unchanged."},{"text":"Offer to help more with the doing side","then":"She gives you a list. You tick it off, and she still has to think of it all."},{"text":"Ask for whole areas, planning included","then":"She looks at you a moment. \"Really? Take school and the doctor, then.\"","best":true}],"why":"Taking whole areas, planning included, lifts the weight, not only the tasks."},{"prompt":"At the start of term, she sits down to write out the school dates, as she does every year. What do you do?","options":[{"text":"Ask her to text you dates as they come up","then":"She texts you dates for a week, then stops, tired of it."},{"text":"Let her keep writing, since she knows best","then":"The list grows to two pages, and it lives with her."},{"text":"Take her list, and ask her for updates each week","then":"You get her updates each week. She still holds the whole picture in her head."},{"text":"Take the dates once, then run it yourself","then":"She hands you the dates in a folder, then hesitates. \"You'll really track it?\"","best":true}],"why":"Taking the info once and running it yourself moves the tracking to you."},{"prompt":"The school WhatsApp group pings, and she glances at her phone out of habit. What do you do?","options":[{"text":"Say \"I've got this one\" and read it first","then":"She lets the phone lie, looking a little surprised.","best":true},{"text":"Ask her what it says","then":"She reads it out and tells you what to do."},{"text":"Let her read it and tell you later","then":"She reads it and quietly adds it to her list."},{"text":"Read it, then check with her that you understood it","then":"She confirms, and keeps half an eye on the thread."}],"why":"Reading it first, and owning it, lets her actually put the phone down."}],"debrief":"Take over whole areas, planning included, to lift the mental load, not just do more tasks.","relearn":"Take whole areas, planning and all, to truly lighten your partner's load."},
  {"id":"ep2-025","cat":"parental-mental-load","type":"reflect","hook":"Lensy: the parent who never has to remember is the one who isn't carrying the load. Worth noticing?","prompt":"What's your take?","options":["Worth it","I'll notice","True"],"affirm":"If you never have to remember the child-admin, you're not carrying the mental load; noticing that is the start of change.","relearn":"The parent who never has to remember isn't carrying the mental load; noticing that starts the fix.","persona":"any","source":"who remembers"},
  {"id":"ep2-026","cat":"parental-mental-load","type":"match","hook":"Match a sign of an unequal mental load to the fair fix.","pairs":[{"left":"One parent is everyone's reminder service","right":"Each owns their own domains"},{"left":"One always 'just knows' the schedule","right":"Both keep the shared calendar"},{"left":"One worries alone at night","right":"Share the worrying out loud"},{"left":"One spots every problem first","right":"Both watch their own areas"},{"left":"One holds all the passwords and forms","right":"Split who-owns-what admin"}],"relearn":"Unequal load shows in who reminds, knows, worries, spots and holds it all; fair fixes share each of those.","persona":"Divya","source":"fair fixes"},
  {"id":"ep2-027","cat":"parental-mental-load","type":"branch","persona":"Vikram","source":"remove the managing","hook":"Your partner is worn out by the invisible load of the kids' week.","steps":[{"prompt":"Your first instinct is to say \"just tell me what to do.\" What do you say instead?","options":[{"text":"Ask her to make you a list and then wait","then":"She sighs and starts the list, on top of everything else."},{"text":"Say you'll do whatever she asks, whenever she asks","then":"She sighs. \"That's what I do all day. I ask.\""},{"text":"Tell her to rest tonight and you will manage","then":"She rests. Tomorrow the list in her head is the same."},{"text":"Offer to own areas so she stops managing you","then":"She goes still. \"You mean I wouldn't have to tell you at all?\"","best":true}],"why":"Owning an area means she no longer manages you, and that is the weight lifted."},{"prompt":"She says she doesn't even know where to start handing things over. What do you do?","options":[{"text":"Say you'll figure it out on your own, somehow","then":"You guess at the week. She watches, half relieved, half worried."},{"text":"Ask her to write it all out for you tonight","then":"She sits up late with the list, on top of everything else."},{"text":"Say it can wait until things calm down a bit","then":"She nods. Things don't calm down, and the list waits."},{"text":"Write your own version of the week, then compare","then":"She reads yours, laughs at what you missed, and starts adding.","best":true}],"why":"Starting from your own picture saves her the effort of explaining it all."},{"prompt":"Two weeks later, the kids' dentist visit is due, and she starts to remind you. What do you do?","options":[{"text":"Say \"That's mine. I've got it\" and book it","then":"She stops mid-sentence, then nods. \"Okay. I'll let it go.\"","best":true},{"text":"Thank her and ask what to do","then":"She tells you, and the appointment is still hers to remember."},{"text":"Say you had it on your list, when you didn't","then":"She believes you, then finds the slot missing later."},{"text":"Joke that she can't help herself","then":"She smiles thinly. Later, she keeps the reminders to herself."}],"why":"Saying \"that's mine\" and acting on it takes the thought off her head."}],"debrief":"Offer to own areas so your partner stops managing you; a list keeps the load on them.","relearn":"Take ownership instead of asking for a list; the managing is the load to lift."},
  {"id":"ep2-028","cat":"involved-dads","type":"strike-rewrite","hook":"\"A father looking after his own child is 'babysitting' or 'helping mum'.\"","myth":{"un":"A father looking after his own child is 'babysitting' or 'helping mum'.","re":"It's just parenting; caregiving is a father's own responsibility, not help he gives the mother.","why":"You don't help with, or babysit, your own kid."},"relearn":"A father caring for his child is parenting, his own responsibility, not babysitting or helping mum.","persona":"Vikram","source":"not babysitting"},
  {"id":"ep2-029","cat":"involved-dads","type":"strike-rewrite","hook":"\"Fathers are providers; nurturing just isn't a man's role.\"","myth":{"un":"Fathers are providers; nurturing just isn't a man's role.","re":"Men can nurture fully; involved, hands-on, emotionally present fathers are good for children and for fathers themselves.","why":"Tenderness isn't unmanly; it's good fathering."},"relearn":"Nurturing is fully a father's role; involved, emotionally present fathers are good for kids and for themselves.","persona":"Vikram","source":"men nurture"},
  {"id":"ep2-030","cat":"involved-dads","type":"strike-rewrite","hook":"\"Kids only really need their mother in the early years.\"","myth":{"un":"Kids only really need their mother in the early years.","re":"Infants attach to both parents from birth, and involved fathers boost children's development, confidence and behaviour.","why":"Both parents matter from day one."},"relearn":"Children need both parents from the start; involved fathers boost development, confidence and behaviour.","persona":"Vikram","source":"both from birth"},
  {"id":"ep2-031","cat":"involved-dads","type":"branch","persona":"Vikram","source":"lean in","hook":"You want to be close to your new baby, but old ideas about being manly nag at you.","steps":[{"prompt":"Your baby is fussing and your partner is in the shower. What do you do?","options":[{"text":"Pick her up and soothe her yourself","then":"She is stiff at first, then slowly settles on your chest.","best":true},{"text":"Wait a few minutes for your partner to come out","then":"The crying grows. You stand there, unsure."},{"text":"Ask a relative to come and hold her","then":"A relative arrives and takes her easily. You watch from the doorway."},{"text":"Turn on the TV and hope she settles","then":"She cries louder. The show plays on."}],"why":"Trying yourself is how you build the bond."},{"prompt":"At a family function, an uncle smirks as you rock the baby. What do you do?","options":[{"text":"Smile, keep holding her, and say you love it","then":"He shrugs. The baby's fist closes around your finger.","best":true},{"text":"Pass her to the nearest aunty","then":"Aunty takes her. The uncle nods as if that settles it."},{"text":"Joke that it's only until her mother is back","then":"Everyone laughs. You feel a little smaller."},{"text":"Put her down and hold a glass to look busy","then":"Now you have nothing in your arms."}],"why":"Holding her openly shows what a father can be."},{"prompt":"Your partner asks how you'd like to share baths and settling from now on. What do you say?","options":[{"text":"Baths and settling. I'll learn her.","then":"She grins. \"You'll be a pro before I know it.\"","best":true},{"text":"Only baths. It's a small job","then":"She nods. Nights stay entirely hers."},{"text":"Weekends only, when work is quiet","then":"Weekends go well. Weekdays stay all hers."},{"text":"Whenever she's calm enough for me","then":"She is rarely calm at the right time."}],"why":"Owning a regular slot builds the skill and the trust."},{"prompt":"Your partner is back at work, and you have the baby alone for a full day. What do you do?","options":[{"text":"Plan the day yourself, feeds, naps and an outing","then":"You get through it. The day ends with a nap on your chest.","best":true},{"text":"Call your mother to come and help you all day","then":"Your mother arrives. You watch her do it all."},{"text":"Keep the baby busy with videos until she's back","then":"The baby is fed, and you both feel flat."},{"text":"Message your partner every hour for advice","then":"She answers between meetings, and the day is hers too."}],"why":"A full day alone builds the confidence that tenderness needs."}],"debrief":"Be a hands-on, tender father. That is good fathering and a fuller manhood, not a weakness.","relearn":"Lean into tender fathering; the old 'manly distance' costs you and your child."},
  {"id":"ep2-032","cat":"involved-dads","type":"role-play","persona":"Vikram","source":"own it proudly","hook":"Your family has noticed how much of the baby's care you do.","setup":"At a gathering, your uncle raises his voice so the room can hear.","steps":[{"prompt":"Your uncle says with a laugh: \"Nappies and night feeds? Like a woman!\"","options":[{"text":"\"This is just being a dad. I wouldn't miss it.\"","then":"The room chuckles, and a cousin says quietly, \"Fair enough.\"","best":true},{"text":"\"Haha, yes. My wife usually handles that stuff.\"","then":"The uncle nods, pleased. Your wife's smile is tight."},{"text":"\"It's better than doing nothing at all, Uncle.\"","then":"The uncle's face falls. The laughter stops."},{"text":"\"Only when my wife is very tired, Uncle.\"","then":"Someone says, \"Ah, helping.\" The word sticks."}],"why":"Owning it proudly, and simply, models that care is a dad's job."},{"prompt":"Your aunt adds: \"A man should be out earning, not fussing over a baby.\"","options":[{"text":"\"I do both, Aunty. Earning and caring are both my job.\"","then":"She purses her lips. Your wife looks at you with warmth.","best":true},{"text":"\"You're right, Aunty. I'll focus on work now.\"","then":"She beams. Your wife's eyes drop."},{"text":"\"Times are changing, Aunty. You wouldn't get it.\"","then":"She sniffs. \"I raised four children, thank you.\""},{"text":"\"Let's not argue at a function, Aunty.\"","then":"She nods, but keeps looking at you."}],"why":"Providing is part of the job, and hands-on care is part of it too."},{"prompt":"Your teenage cousin asks quietly: \"Does it feel weird, doing all that?\"","options":[{"text":"\"At first. Then it became the best part of my day.\"","then":"He nods slowly. \"Maybe I'll try that one day.\"","best":true},{"text":"\"A bit. I'd rather not, honestly, if I had a choice.\"","then":"He nods. Now he knows what men are supposed to say."},{"text":"\"It's just for a while, until the baby is older.\"","then":"He nods. Care is a phase, not a role."},{"text":"\"Ask your father. He'll tell you what's right.\"","then":"He shrugs. His father doesn't do nappies."}],"why":"Honest warmth shows a younger man that care is worth claiming."}],"relearn":"Owning hands-on fathering proudly shrugs off the teasing and models that caregiving is simply a dad's job."},
  {"id":"ep2-033","cat":"involved-dads","type":"branch","persona":"Vikram","source":"dont hand off","hook":"You realise you instinctively pass the crying baby straight to your partner.","steps":[{"prompt":"Your baby cries in your arms and your partner reaches out. What do you do?","options":[{"text":"Say you've got this and keep soothing him","then":"It takes ten minutes. He finally settles against your shoulder.","best":true},{"text":"Hand him over with a sigh of relief","then":"He quiets in seconds, and you feel sidelined."},{"text":"Say he prefers her, and hand him over","then":"He stays with her. The idea that he prefers her sinks in."},{"text":"Ask her to show you the trick, then hand him back","then":"She shows you the trick. You never try it yourself."}],"why":"Trying yourself is how the crying baby learns to trust you."},{"prompt":"At 3 a.m. he wakes crying, and your partner is fast asleep. What do you do?","options":[{"text":"Get up and soothe him without waking her","then":"He grizzles for twenty minutes, then sleeps. So do you.","best":true},{"text":"Wake her, since she knows what works","then":"She stumbles up, and the night is hers again."},{"text":"Let him cry a little and hope she wakes","then":"He cries harder, and she wakes anyway."},{"text":"Bring him to bed and lay him beside her","then":"She wakes and takes over. It's still her night."}],"why":"Handling the night yourself builds real confidence."},{"prompt":"Your partner asks: \"Could you take the evening settling every day this week?\"","options":[{"text":"Yes. Evenings are mine this week","then":"She smiles. \"I'll take a long bath, then.\"","best":true},{"text":"Sure, but call me if he won't settle","then":"He won't, and you call her within ten minutes."},{"text":"Only on the days he's in a good mood","then":"He is rarely in a good mood at seven."},{"text":"I'd rather keep to weekends","then":"She nods. Weekdays stay hers."}],"why":"A steady daily slot makes you the parent he turns to."}],"debrief":"Practise soothing yourself. Always handing the baby off keeps you a backup parent.","relearn":"Soothe your child yourself rather than handing off; that's how you become their go-to."},
  {"id":"ep2-034","cat":"involved-dads","type":"role-play","persona":"Vikram","source":"ask to be trusted","hook":"Your partner hovers and corrects how you parent, so you've stopped trying.","setup":"Tonight, once the kids are asleep, you decide to say it.","steps":[{"prompt":"She asks: \"You've gone quiet with the kids lately. Is something wrong?\"","options":[{"text":"\"I want to do my share. Can you trust me to do it my way?\"","then":"She pauses. \"I didn't realise you'd stopped because of me.\"","best":true},{"text":"\"Fine. You do it. You clearly think I can't.\"","then":"Her face tightens. \"That's not what I said.\""},{"text":"\"Nothing. I'm just tired from work.\"","then":"She pauses. \"Is it because I keep correcting you?\""},{"text":"\"You're always correcting me, so why bother at all?\"","then":"She stiffens. \"I'm only trying to help.\""}],"why":"Naming it kindly, and asking for trust, opens the door."},{"prompt":"She says: \"I just want it done properly. The kids' routines matter.\"","options":[{"text":"\"They do. Tell me things once, and let me try.\"","then":"She nods slowly. \"Once. I can try that.\"","best":true},{"text":"\"Then maybe you should just do it all yourself.\"","then":"She sighs. \"That's not fair either.\""},{"text":"\"I know how to look after my own children.\"","then":"She goes quiet, hurt."},{"text":"\"Write me a list, and I'll follow it exactly.\"","then":"She writes it. She's the manager, and you're the follower."}],"why":"Agreeing what matters, then trying yourself, builds trust."},{"prompt":"A week on, she corrects how you tie their shoes. What do you say?","options":[{"text":"\"I've got this one. Let me try it my way.\"","then":"She steps back. \"Okay. I'll watch, and not fix.\"","best":true},{"text":"\"Go ahead. You always know best, don't you?\"","then":"She stops. \"I didn't mean it that way.\""},{"text":"\"You did that on purpose to show me up.\"","then":"She looks stung. \"No. I just want it right.\""},{"text":"\"Fine. I'll stay out of the way, then.\"","then":"She stops talking, but the coldness stays."}],"why":"A calm, specific reminder keeps her trust and your space."}],"relearn":"Asking to be trusted to learn your own way addresses gatekeeping so you can become a true equal parent."},
  {"id":"ep2-035","cat":"involved-dads","type":"reflect","hook":"Lensy: 'to be a good father, and to be seen as one' is a worthy goal, and it starts with showing up. Resonate?","prompt":"What do you think?","options":["Resonates","Showing up","That's the goal"],"affirm":"Being a good, hands-on father, and being recognised as one, starts with consistently showing up in the care.","relearn":"Being a good father, and seen as one, starts with showing up in the everyday care.","persona":"Vikram","source":"show up"},
  {"id":"ep2-036","cat":"involved-dads","type":"strike-rewrite","hook":"\"Asking a dad to be fully involved is somehow anti-men.\"","myth":{"un":"Asking a dad to be fully involved is somehow anti-men.","re":"Involved fatherhood is pro-men: it boosts fathers' bonds, confidence and wellbeing, and it's something to claim, not a burden.","why":"Equality here lifts fathers too."},"relearn":"Involved fatherhood isn't anti-men; it lifts fathers' bonds, confidence and wellbeing, and is theirs to claim.","persona":"any","source":"pro-men"},
  {"id":"ep2-037","cat":"involved-dads","type":"sort","hook":"Sort: involved, hands-on fatherhood, or distant 'provider-only' fathering?","items":[{"id":"a","text":"Doing nights, feeds and play"},{"id":"b","text":"Seeing kids only at weekends by choice"},{"id":"c","text":"Knowing your child's daily world"},{"id":"d","text":"Leaving all care to mum and elders"},{"id":"e","text":"Owning the bedtime routine yourself"},{"id":"f","text":"Sending money but rarely being home"}],"bins":[{"id":"involved","label":"Involved","valence":"pos"},{"id":"distant","label":"Distant","valence":"neg"}],"key":{"a":"involved","b":"distant","c":"involved","d":"distant","e":"involved","f":"distant"},"relearn":"Doing nights, knowing your child's world and owning bedtime is involved fathering; weekend-only and absent is distant.","persona":"Vikram","source":"involved vs distant"},
  {"id":"ep2-038","cat":"involved-dads","type":"match","hook":"Match each fathering act to what it gives the child.","pairs":[{"left":"Hands-on daily care","right":"Security and a real bond"},{"left":"Emotional presence","right":"Confidence and resilience"},{"left":"Showing up consistently","right":"Trust they can rely on you"},{"left":"Sharing the load with mum","right":"A calmer home for everyone"},{"left":"Soothing them yourself","right":"A parent they turn to too"}],"relearn":"Daily care, emotional presence, consistency, sharing and soothing are what an involved father gives his child.","persona":"Vikram","source":"what it gives"},
  {"id":"ep2-039","cat":"involved-dads","type":"reflect","hook":"Lensy: the most precious thing a father can give isn't money, it's himself, present and hands-on. Land okay?","prompt":"What's your take?","options":["Lands okay","Himself","Present matters"],"affirm":"A father's presence and hands-on care matter to a child even more than his financial provision.","relearn":"The most precious thing a father gives isn't money, it's himself, present and hands-on.","persona":"Vikram","source":"give himself"},
  {"id":"ep2-040","cat":"involved-dads","type":"spot","hook":"Spot the two lines that make a father a helper, not an equal parent.","scene":[{"id":"a","text":"Owning care without being asked","trick":false},{"id":"b","text":"Waiting to be told what to do","trick":true},{"id":"c","text":"Knowing the child's routines himself","trick":false},{"id":"d","text":"Only doing tasks he's handed","trick":true},{"id":"e","text":"Booking the appointments himself","trick":false}],"why":"Waiting to be told and only doing handed tasks make a helper; an equal parent owns care and knows the routines.","relearn":"An equal-parent father owns care unprompted and knows the routines, rather than waiting to be told.","persona":"Vikram","source":"equal not helper"},
  {"id":"ep2-041","cat":"involved-dads","type":"branch","persona":"Vikram","source":"protect the time","hook":"At your firm, nobody asks about your baby, and long hours are a badge of honour.","steps":[{"prompt":"A 6 p.m. meeting is called on the evening you usually do bedtime. What do you do?","options":[{"text":"Say you leave at six, and offer to catch up in the morning","then":"Your boss raises an eyebrow, then moves the item to the morning.","best":true},{"text":"Stay, and skip bedtime this once","then":"The meeting runs until eight. Your baby is asleep when you reach home."},{"text":"Stay, and text your wife to handle bedtime instead","then":"She replies \"ok\" with no emoji."},{"text":"Leave quietly without telling anyone, and hope no one asks","then":"Someone notices. The whispers start."}],"why":"Saying your limit plainly protects the time and keeps you accountable."},{"prompt":"A colleague says: \"Serious people don't clock out at six.\" What do you do?","options":[{"text":"Say you take work and your child seriously","then":"He shrugs, but doesn't push it.","best":true},{"text":"Laugh, and start staying late","then":"You stay late all week. Bedtime is missed twice."},{"text":"Promise to make up the hours on weekends","then":"You end up working through Saturday and Sunday."},{"text":"Slip out with your bag hidden after that","then":"You leave feeling as if you're doing something wrong."}],"why":"Holding both work and fatherhood stops the culture from deciding for you."},{"prompt":"A new father joins your team and asks how you manage. What do you do?","options":[{"text":"Tell him how to name his limits and ask for them","then":"He writes it down. The next week he leaves at six too.","best":true},{"text":"Tell him to keep his head down and stay late","then":"He stays late every night that month."},{"text":"Tell him it's tough and everyone struggles","then":"He nods. Nothing changes for him."},{"text":"Tell him to ask HR, since that's their job","then":"HR sends a policy link. He still doesn't know how to ask his manager."}],"why":"Showing a new father how to ask for the time makes it easier for him."},{"prompt":"Your firm announces a big project, with late nights for the next month. What do you do?","options":[{"text":"Tell your manager which evenings are fixed","then":"She notes them down. The project goes on around them.","best":true},{"text":"Say yes to everything and hope it works out","then":"You miss most bedtimes that month."},{"text":"Ask your wife to cover the whole month at home","then":"She agrees, and the month becomes hers."},{"text":"Volunteer for extra shifts to look committed","then":"Your boss is pleased. You miss most of your baby's evenings."}],"why":"Fixed evenings, said early, protect the time that matters."}],"debrief":"Protect what parenting time you can against a work culture that erases fatherhood.","relearn":"Guard time to parent against work norms that sideline fathers; don't cede it by default."},
  {"id":"ep2-042","cat":"kids-are-watching","type":"strike-rewrite","hook":"\"Kids don't really notice who does what at home.\"","myth":{"un":"Kids don't really notice who does what at home.","re":"Children learn gender roles largely by watching their parents; what they see at home becomes their normal.","why":"Home is a child's first model of how the world works."},"relearn":"Children notice and absorb who does what at home; it teaches them what's normal for their own future.","persona":"Meena","source":"kids notice"},
  {"id":"ep2-043","cat":"kids-are-watching","type":"strike-rewrite","hook":"\"Telling kids about equality matters more than what they see us do.\"","myth":{"un":"Telling kids about equality matters more than what they see us do.","re":"Children copy what they see far more than what they're told; modelling equality at home is the most powerful lesson.","why":"Actions teach louder than lectures."},"relearn":"Kids learn equality from what they see us do, not what we say; modelling it at home teaches the most.","persona":"Meena","source":"show not tell"},
  {"id":"ep2-044","cat":"kids-are-watching","type":"sort","persona":"Meena","source":"what kids learn","hook":"Sort: what a child learns from a home where parenting is shared, or from one where it isn't?","items":[{"id":"a","text":"Care is everyone's job"},{"id":"b","text":"Caring is only for women"},{"id":"c","text":"Dads are nurturing too"},{"id":"d","text":"Men don't do 'kid stuff'"},{"id":"e","text":"Either parent can run the home"},{"id":"f","text":"A real man only earns, never cares"}],"bins":[{"id":"shared","label":"From a shared home","valence":"pos"},{"id":"unequal","label":"From an unequal one","valence":"neg"}],"key":{"a":"shared","b":"unequal","c":"shared","d":"unequal","e":"shared","f":"unequal"},"relearn":"A shared home teaches that care is everyone's job and dads nurture; an unequal one teaches the old divide."},
  {"id":"ep2-045","cat":"kids-are-watching","type":"branch","persona":"Priya","source":"remodel it","hook":"You fold laundry as usual, and your child says, \"Papa doesn't fold. That's mummy's job.\"","steps":[{"prompt":"Papa is on the sofa, and your child waits for your reaction. What do you do?","options":[{"text":"Say jobs are for everyone, and keep folding alone","then":"Your child nods. Papa stays on the sofa, and the laundry is still yours."},{"text":"Laugh it off as something kids say","then":"Your child grins and repeats it to their grandmother that evening."},{"text":"Tell your child off for saying it","then":"Your child goes quiet, unsure what they did wrong."},{"text":"Call Papa over to fold with you and your child","then":"Papa gets up and folds beside you. Your child watches, then hands over a sock.","best":true}],"why":"Showing both parents at work teaches more than a correction from one."},{"prompt":"A week on, your child watches you cook and says \"Papa never cooks.\" What do you do?","options":[{"text":"Agree a regular cooking night with your partner, and let your child watch","then":"Papa takes Thursdays. By the second week, your child asks what he is making.","best":true},{"text":"Tell your child that anyone can cook","then":"Your child nods politely. Papa still isn't in the kitchen."},{"text":"Say Papa is busy with work","then":"Your child repeats \"Papa is busy\" to the neighbour's kid."},{"text":"Ask Papa to cook once this weekend, then carry on as before","then":"Papa cooks on Sunday. Your child is thrilled, then asks why it isn't every day."}],"why":"A regular turn shows your child that care is Papa's job too, not a treat."},{"prompt":"At a family lunch, a cousin says \"boys don't cook\" and your child looks at you. What do you say?","options":[{"text":"Change the subject to keep the peace","then":"The talk moves on. Your child keeps looking at you, waiting."},{"text":"Tell the cousin off sharply","then":"The cousin's mother stiffens and lunch turns awkward. Your child looks unsettled."},{"text":"Tell your child later that the cousin was wrong","then":"At home your child listens, but the line went unanswered at the table."},{"text":"Say calmly that boys and men cook too","then":"Your child stands taller. An aunt raises her eyebrows, and Papa nods.","best":true}],"why":"Answering calmly on the spot shows your child the cousin's rule isn't true."}],"debrief":"When kids echo a gendered split, change what you model, not just what you say.","relearn":"Reteach equality by changing what kids see you do, not by correcting words."},
  {"id":"ep2-046","cat":"kids-are-watching","type":"reflect","hook":"Lensy: your child's idea of a 'normal' family is being built right now, by watching you two. Powerful?","prompt":"What do you think?","options":["Powerful","Right now","I feel it"],"affirm":"Children build their template of a normal family by watching their parents, so shared parenting shapes their future.","relearn":"Your child's idea of a normal family is built by watching you; shared parenting shapes their future.","persona":"any","source":"building normal"},
  {"id":"ep2-047","cat":"kids-are-watching","type":"reflect","hook":"Lensy: break the cycle, and your kids may raise their kids more equally too. Worth it?","prompt":"What's your take?","options":["Worth it","Break the cycle","For their kids too"],"affirm":"Modelling equality can break an intergenerational cycle, shaping how your children parent their own children.","relearn":"Modelling shared parenting can break the cycle, shaping how your kids parent their own kids one day.","persona":"Meena","source":"break the cycle"},
  {"id":"ep2-048","cat":"kids-are-watching","type":"match","persona":"any","source":"see then expect","hook":"Match what kids see at home to what they grow up expecting.","pairs":[{"left":"Both parents caring and cooking","right":"That care is for everyone"},{"left":"Dad emotionally present","right":"That men can be tender"},{"left":"Decisions made together","right":"That partners are equals"},{"left":"Mum with her own work and rest","right":"That a mother is a whole person"},{"left":"Sons and daughters sharing chores","right":"That housework has no gender"}],"relearn":"What children see, shared care, a present dad, joint decisions, becomes what they expect and give as adults."},
  {"id":"ep2-049","cat":"kids-are-watching","type":"sort","persona":"Priya","source":"models which","hook":"Sort: models equality for kids, or models the old divide?","items":[{"id":"a","text":"A son seeing dad cook and care"},{"id":"b","text":"A daughter told kitchen is her future"},{"id":"c","text":"Both parents at the doctor visit"},{"id":"d","text":"Only mum ever handling the children"},{"id":"e","text":"Parents deciding the home budget together"},{"id":"f","text":"A son excused from chores his sister isn't"}],"bins":[{"id":"equality","label":"Models equality","valence":"pos"},{"id":"divide","label":"Models the divide","valence":"neg"}],"key":{"a":"equality","b":"divide","c":"equality","d":"divide","e":"equality","f":"divide"},"relearn":"A caring dad and both parents sharing model equality; gendered scripts and mum-only care model the old divide."},
  {"id":"ep2-050","cat":"kids-are-watching","type":"strike-rewrite","hook":"\"Raising a son to do 'girl' chores will confuse or weaken him.\"","myth":{"un":"Raising a son to do 'girl' chores will confuse or weaken him.","re":"Teaching all children to cook, clean and care raises capable, respectful adults; chores have no gender.","why":"Life skills aren't gendered, and they strengthen kids."},"relearn":"Teaching sons to cook, clean and care raises capable, respectful adults; chores have no gender.","persona":"Priya","source":"chores no gender"},
  {"id":"ep2-051","cat":"kids-are-watching","type":"spot","persona":"Meena","source":"teaches the wrong lesson","hook":"Spot the two moments that teach a child the opposite of equality at home.","scene":[{"id":"a","text":"Both parents sharing care visibly","trick":false},{"id":"b","text":"Praising dad loudly for rare 'help'","trick":true},{"id":"c","text":"Sons and daughters given the same chores","trick":false},{"id":"d","text":"'That's mum's job,' dad tells the kids","trick":true},{"id":"e","text":"Both parents at the school meeting","trick":false}],"why":"Cheering a dad's rare 'help' and calling care 'mum's job' teach kids care is mum's and a dad's care is extra.","relearn":"Kids learn equality from shared care and same-for-all chores, not from praising a father's rare help."},
  {"id":"ep2-052","cat":"kids-are-watching","type":"branch","persona":"Priya","source":"counter scripting","hook":"It's Diwali at your aunt's, and the kitchen is full of women cooking for everyone.","steps":[{"prompt":"Your aunt calls your daughter in to help and waves your son off to play. What do you do?","options":[{"text":"Say your aunt's ideas are old-fashioned","then":"Your aunt is stung. \"I only asked for a little help,\" she says, and the room goes quiet."},{"text":"Let it pass today and raise it with your husband tonight","then":"Your daughter goes to the kitchen. Later, your husband says he hadn't noticed."},{"text":"Send your daughter in so there is no scene","then":"Your daughter goes quietly while her brother runs off to play cricket."},{"text":"Gently say both kids will help, and call your son in too","then":"Your aunt clicks her tongue but hands your son a bowl of peas.","best":true}],"why":"Gently including both kids counters the script without a fight."},{"prompt":"A few days later, your aunt phones to say your daughter must learn to cook properly now. What do you say?","options":[{"text":"Tell her not to comment on how you raise your kids","then":"She hangs up hurt. The next invitation comes with less warmth."},{"text":"Say your home has its own way and change the subject","then":"She says fine, though she sounds unconvinced. Nothing is settled."},{"text":"Thank her, and say both your kids are learning to cook","then":"She goes quiet, then says, \"Well, times are changing.\" It stays polite.","best":true},{"text":"Agree, and say your son can learn later","then":"She is pleased. Your son overhears and asks why he is excused."}],"why":"A warm, clear answer keeps your aunt close and keeps your example intact."},{"prompt":"At the next function, your son serves tea and an uncle laughs, \"Look, a little girl!\" What do you do?","options":[{"text":"Praise him and say serving guests is for everyone in this house","then":"Your son beams. The uncle shrugs, and your daughter takes a tray too.","best":true},{"text":"Laugh along so your son isn't embarrassed","then":"Your son laughs too but looks down. He doesn't pick up the tray again."},{"text":"Whisper to your son to let the girls serve next time","then":"He nods, relieved. The girls end up carrying every tray."},{"text":"Quietly praise your son at home that night","then":"He is pleased at home. The uncle's laugh at the function goes unanswered."}],"why":"Praising him and naming serving as everyone's job answers the joke in the moment."}],"debrief":"Counter relatives' gendered scripting and keep modelling shared roles; home is the strongest lesson.","relearn":"Gently counter the scripting; your modelled equality at home is the lesson that lasts."},
  {"id":"ep2-053","cat":"kids-are-watching","type":"reflect","hook":"Lensy: the equality you live at home is the curriculum your kids actually absorb. Feel the weight?","prompt":"What's your take?","options":["Feel it","Lived curriculum","It matters"],"affirm":"The equality children absorb is the one their parents actually live at home, not the one they're told about.","relearn":"The equality you live at home is the real curriculum your kids absorb.","persona":"any","source":"lived curriculum"},
  {"id":"ep2-054","cat":"kids-are-watching","type":"match","persona":"any","source":"patterns plant beliefs","hook":"Match a home pattern to the belief it plants in a child.","pairs":[{"left":"Shared, respectful parenting","right":"Partners are equal teammates"},{"left":"Dad doing his fair share","right":"Care is unisex and normal"},{"left":"Mum with her own life too","right":"Women are full people, not just mums"},{"left":"Both parents owning the planning","right":"Remembering kid-stuff isn't only mum's"},{"left":"Sons taught to cook and clean","right":"Home skills belong to every child"}],"relearn":"Each home pattern plants a belief: equal teammates, unisex care, and women as full people."},
  {"id":"ep2-055","cat":"everyone-gains","type":"strike-rewrite","hook":"\"Equal parenting is a sacrifice fathers make for mothers.\"","myth":{"un":"Equal parenting is a sacrifice fathers make for mothers.","re":"Shared parenting is better for everyone: children thrive, mothers are less overloaded, and fathers gain bond, confidence and wellbeing.","why":"It's a win for all three, not a trade."},"relearn":"Equal parenting isn't a sacrifice; it's better for children, mothers and fathers alike.","persona":"Vikram","source":"win for all"},
  {"id":"ep2-056","cat":"everyone-gains","type":"match","hook":"Match each member of the family to what shared parenting gives them.","pairs":[{"left":"The child","right":"Two bonded parents and better development"},{"left":"The mother","right":"Less overload and burnout"},{"left":"The father","right":"A real bond, confidence and wellbeing"},{"left":"The grandparents","right":"A calmer home, not one tired parent to prop up"},{"left":"The marriage","right":"Two teammates instead of a manager and a helper"}],"relearn":"Shared parenting gives the child two bonded parents, the mother relief, and the father a real bond; everyone gains.","persona":"any","source":"everyone gains"},
  {"id":"ep2-057","cat":"everyone-gains","type":"reflect","hook":"Lensy: this isn't about fairness alone; an equal home is happier and healthier for the whole family. Agree?","prompt":"What do you think?","options":["Agree","Happier home","Healthier"],"affirm":"Shared parenting isn't only fair; it makes the whole family happier and healthier, which is why it's worth building.","relearn":"Equal parenting isn't just fair; it makes the whole family happier and healthier.","persona":"any","source":"happier home"},
  {"id":"ep2-058","cat":"everyone-gains","type":"sort","hook":"Sort: a real benefit of shared parenting, or a myth about it?","items":[{"id":"a","text":"Kids bond with both parents"},{"id":"b","text":"It makes fathers 'less manly'"},{"id":"c","text":"Mothers get relief and a life"},{"id":"d","text":"It harms the children"},{"id":"e","text":"Fathers gain confidence and a closer bond"},{"id":"f","text":"Sharing means dad 'loses' his role"}],"bins":[{"id":"benefit","label":"Real benefit","valence":"pos"},{"id":"myth","label":"Myth","valence":"neg"}],"key":{"a":"benefit","b":"myth","c":"benefit","d":"myth","e":"benefit","f":"myth"},"relearn":"Bonding with both parents, relief for mothers and a closer bond for fathers are real; 'less manly', 'harms kids' and 'dad loses out' are myths.","persona":"any","source":"benefit vs myth"},
  {"id":"ep2-059","cat":"everyone-gains","type":"strike-rewrite","hook":"\"A mother who shares the load is a lazy or lesser mother.\"","myth":{"un":"A mother who shares the load is a lazy or lesser mother.","re":"Sharing the load isn't laziness; it lets a mother be a whole person and a less depleted, more present parent.","why":"Support makes a better, not lesser, parent."},"relearn":"A mother who shares the load isn't lazy or lesser; she's a more rested, present and whole parent.","persona":"Divya","source":"not a lesser mum"},
  {"id":"ep2-060","cat":"everyone-gains","type":"branch","persona":"Vikram","source":"reframe as gain","hook":"Weeks into parenthood, you catch yourself calling equal parenting 'giving up' your evenings.","steps":[{"prompt":"Your partner asks you to take bedtime every weekday. What do you do?","options":[{"text":"Say yes, and notice what you get from it for two weeks","then":"The first nights are clumsy. By week two, your daughter settles faster on your chest.","best":true},{"text":"Agree, but keep count of the hours you're giving up","then":"You do bedtime with a tight face. Your partner notices and says nothing."},{"text":"Say you'll start once work calms down","then":"Work never calms down. After a week of pointed looks, you take bedtime anyway."},{"text":"Agree, and ask for Saturday mornings free in exchange","then":"She agrees. Bedtime now feels like a deal, not parenting."}],"why":"Trying it with an open mind lets you find out what you gain."},{"prompt":"A colleague says you look tired and asks why you bother with bedtime. What do you say?","options":[{"text":"Say it's the best part of your day","then":"He raises an eyebrow, then admits he barely knows his kids' routines.","best":true},{"text":"Say it's a sacrifice, but that's parenthood","then":"He nods and laughs. The resentment sits a little heavier."},{"text":"Say you're doing your bit for your wife","then":"He calls that decent of you. It still sounds like a favour."},{"text":"Say you'll ease off when work is heavy","then":"He grins. Skipping starts to sound reasonable."}],"why":"Naming what you get from bedtime keeps you leaning in."},{"prompt":"A month on, your partner asks how the routine feels for you. What do you say?","options":[{"text":"Say some nights are hard, and you wouldn't give it up","then":"She smiles, and admits she worried you were only doing it for her.","best":true},{"text":"Say it's fine, and keep the grumbling to yourself","then":"She senses something is off and stops asking."},{"text":"Say you're doing it for her sake and the baby's","then":"She thanks you, but it still sounds like a favour to her."},{"text":"Say you're keeping track of what you've given up","then":"She goes quiet. The routine begins to feel like a bill."}],"why":"Honest talk about the gain and the effort keeps the sharing warm."}],"debrief":"See equal parenting as gaining a bond and a fuller life, not giving something up.","relearn":"Reframe equal parenting as a gain, a bond and a richer life, not a sacrifice to resent."},
  {"id":"ep2-061","cat":"everyone-gains","type":"match","hook":"Match a worry about equal parenting to the reassuring reality.","pairs":[{"left":"'I'll lose my role as provider'","right":"You gain the role of a real parent"},{"left":"'She won't need me'","right":"Your child will know and need you"},{"left":"'It's all giving things up'","right":"Everyone in the family gains"},{"left":"'I'll have no time left for myself'","right":"A shared load frees time for you both"},{"left":"'People will think I'm henpecked'","right":"A present father is respected, not pitied"}],"relearn":"Each worry about equal parenting has a reassuring reality: a deeper role, a child who needs you, and gains for all.","persona":"Vikram","source":"worry to reality"},
  {"id":"ep2-062","cat":"everyone-gains","type":"reflect","hook":"Lensy: the home where parenting is shared is the home most kids would choose to grow up in. Sit right?","prompt":"What's your take?","options":["Sits right","Kids would choose it","Yes"],"affirm":"A home with shared, equal parenting is the kind of home that's best for children to grow up in.","relearn":"A home where parenting is shared is the one most kids would thrive growing up in.","persona":"any","source":"kids would choose"},
  {"id":"ep2-063","cat":"everyone-gains","type":"sort","hook":"Sort: a sign equal parenting is working for the whole family, or a sign of strain to address?","items":[{"id":"a","text":"Both parents rested enough to enjoy the child"},{"id":"b","text":"One parent always depleted"},{"id":"c","text":"Both bonded with the kids"},{"id":"d","text":"Resentment simmering under the surface"},{"id":"e","text":"Either parent can take a day off, guilt-free"},{"id":"f","text":"One parent keeps a silent mental tally"}],"bins":[{"id":"working","label":"Working for all","valence":"pos"},{"id":"strain","label":"Strain to address","valence":"uhoh"}],"key":{"a":"working","b":"strain","c":"working","d":"strain","e":"working","f":"strain"},"relearn":"Both rested and bonded means it's working; one always depleted or a silent tally is strain to rebalance together.","persona":"any","source":"working vs strain"},
  {"id":"ep2-064","cat":"everyone-gains","type":"strike-rewrite","hook":"\"Once kids arrive, gender equality has to take a back seat.\"","myth":{"un":"Once kids arrive, gender equality has to take a back seat.","re":"Parenthood is exactly when equality matters most; the defaults snap back hardest, so this is the time to hold the line.","why":"Don't surrender equality at the moment it counts most."},"relearn":"Parenthood is when equality matters most, not least; this is the time to hold the line, not surrender it.","persona":"Divya","source":"hold the line"},
  {"id":"ep2-065","cat":"everyone-gains","type":"role-play","persona":"Vikram","source":"make the case","hook":"You've suggested sharing the parenting equally from now on.","setup":"Tonight, once the kids are asleep, she brings it up.","steps":[{"prompt":"Your partner says: \"I'm not sure equal parenting can really work for us.\"","options":[{"text":"\"Let's try it properly. It's better for all of us.\"","then":"She tilts her head. \"Better for me too? How do you mean?\"","best":true},{"text":"\"You're probably right. It's not realistic for us.\"","then":"She sighs. \"Maybe. I'm just so tired of carrying it all.\""},{"text":"\"It works fine for my friends. You're overthinking it.\"","then":"Her face closes. \"I'm not overthinking. I'm tired.\""},{"text":"\"Fine. Tell me what to do and I'll do it.\"","then":"She sighs. \"That's what I'm afraid of. I'd still be running it.\""}],"why":"Naming a gain for all of you invites her to try, not dismiss."},{"prompt":"She asks: \"If we did try, what would you take on? No list of promises.\"","options":[{"text":"\"Bedtime and health, start to finish. Let's check in every Sunday.\"","then":"She almost smiles. \"Health means jabs and forms too?\" \"All of it.\"","best":true},{"text":"\"I'll help with whatever you need. Just ask.\"","then":"She frowns. \"Then I'm still the one deciding what's needed.\""},{"text":"\"We'll figure it out as we go along.\"","then":"\"That's how it usually ends up with me,\" she says."},{"text":"\"I'll do exactly half of everything, and we'll tally it weekly.\"","then":"She laughs, unsure. \"A weekly tally sounds like more work.\""}],"why":"Owning whole areas is a real offer, and not a promise to help."},{"prompt":"Weeks later she says: \"I felt guilty leaving you alone with the kids on Saturday.\"","options":[{"text":"\"Don't feel guilty. They're mine too, and I'm glad you rested.\"","then":"She smiles. \"I did feel lighter. Thank you for saying that.\"","best":true},{"text":"\"You're right. It was a lot. Maybe don't next time.\"","then":"She goes quiet. \"Right. I won't, then.\""},{"text":"\"Feel guilty if you want. I'll just manage.\"","then":"She hears the sigh in your voice, and the guilt doubles."},{"text":"\"No problem. Happy to help out anytime.\"","then":"Her smile fades. \"Help. Right.\""}],"why":"Her rest is good for all of you, and the kids are yours too."}],"relearn":"Framing equal parenting as a win for the whole family invites your partner to try it rather than dismiss it."},
  {"id":"ep2-066","cat":"everyone-gains","type":"role-play","persona":"Vikram","source":"reframe for friend","hook":"Your friend Karan became a father last month, and you meet him for chai.","setup":"He stirs his tea for a while before he speaks.","steps":[{"prompt":"Karan says: \"If I do nappies and bedtime, people will think I've lost my standing.\"","options":[{"text":"\"It's the best thing I do. You gain more than you give.\"","then":"He raises an eyebrow. \"Really? What do you actually get?\"","best":true},{"text":"\"Yeah, enjoy your freedom while it lasts, I guess.\"","then":"He laughs. \"Freedom first.\" Then he goes quiet, unsure."},{"text":"\"Don't worry. Nobody at the office will ever notice.\"","then":"\"So I hide it? That feels odd too,\" he says."},{"text":"\"You're right. Some things are better left to mothers.\"","then":"He nods, relieved, but he doesn't look convinced."}],"why":"Sharing what you gain shows him a real reason to lean in."},{"prompt":"He asks: \"Honestly, what does a baby get from his dad doing all this?\"","options":[{"text":"\"He learns you're someone he can turn to. That lasts.\"","then":"He looks at his phone photo of the baby for a moment.","best":true},{"text":"\"Probably nothing yet. He's only a baby.\"","then":"\"So it can wait,\" he says. \"Fine.\""},{"text":"\"A very tired father, honestly. But it's worth it.\"","then":"He laughs, but you see him back off."},{"text":"\"Ask your wife. She reads all about this.\"","then":"\"So she'll tell me what to do,\" he says."}],"why":"Babies bond with both parents from birth, so it never waits."},{"prompt":"As you get up to leave, he adds: \"My father-in-law laughs when I hold the baby. What do I say?\"","options":[{"text":"\"Try: I'm his dad. This is my job.\"","then":"He says it aloud and grins. \"That's easier than I thought.\"","best":true},{"text":"\"Say your wife insisted on it.\"","then":"He grins. It sounds like he's under orders."},{"text":"\"Hand the baby over whenever he's around.\"","then":"\"Hide it, then. Got it,\" he says."},{"text":"\"Argue until he backs down. He'll respect that.\"","then":"\"That's a fight at every family dinner,\" he says."}],"why":"Calling it your job as a dad settles the teasing calmly."}],"relearn":"Sharing that involved fatherhood is rewarding, not a loss, helps a friend lean in rather than hold back."},
  {"id":"ep2-067","cat":"everyone-gains","type":"spot","hook":"Spot the two lies about who benefits from shared parenting.","scene":[{"id":"a","text":"Children, mothers and fathers all gain","trick":false},{"id":"b","text":"Only mothers benefit, at fathers' cost","trick":true},{"id":"c","text":"Whole families are happier and healthier","trick":false},{"id":"d","text":"A father gains a real bond with his kids","trick":false},{"id":"e","text":"It's a loss for men so women can win","trick":true}],"why":"Shared parenting benefits children, mothers and fathers; 'only mum benefits at dad's cost' and 'men lose so women win' are both false.","relearn":"Shared parenting is a whole-family gain, not a benefit to mothers at fathers' expense.","persona":"any","source":"who benefits"},
  {"id":"ep2-068","cat":"tools-and-help","type":"branch","persona":"Vikram","source":"make a plan","hook":"You want parenting to be truly equal, not just an intention.","steps":[{"prompt":"On Sunday night your wife suggests you both try to be fairer. What do you do?","options":[{"text":"List every task and worry, then divide them","then":"The list runs to two pages. Your wife adds items you had never noticed.","best":true},{"text":"Ask her to tell you what needs doing","then":"She lists a few things. She is still deciding what matters."},{"text":"Split the visible jobs like feeds and nappies","then":"It looks fair on paper. The planning and remembering stay with her."},{"text":"Promise to try to be fairer","then":"She smiles. A month later nothing has really moved."}],"why":"A written map shows the whole load, so nothing stays hidden."},{"prompt":"Your wife says the hardest part is the remembering: jabs, school dates, what's running out. What do you do?","options":[{"text":"Say the small stuff isn't really work","then":"She goes quiet. She keeps carrying all of it."},{"text":"Let her keep those since she is good at them","then":"She is good at them because she has done them for years."},{"text":"Take some of the remembering as fully yours","then":"She looks relieved. \"Nobody has ever taken those off me before.\"","best":true},{"text":"Agree to remember whatever she reminds you about","then":"She reminds you. She is still the one remembering."}],"why":"Remembering and worrying are real work, so they need an owner too."},{"prompt":"Later you sit down to divide the jobs. Your wife says she'll take whatever is left. What do you do?","options":[{"text":"Each pick whole areas and talk over the rest","then":"She picks school and you pick health. You talk through what's left.","best":true},{"text":"Split every task down the middle across all areas","then":"Each area now needs two people to track it. It gets confusing."},{"text":"Ask her to choose for both of you","then":"She chooses carefully for you both. She is managing again."},{"text":"Choose the easy tasks and leave her the rest","then":"She ends up with the harder and messier jobs."}],"why":"Whole areas mean each of you notices, plans and decides."},{"prompt":"Two weeks in, you forget a task that is yours. What do you do?","options":[{"text":"Say the plan is too complicated","then":"She looks at the plan. \"We made it together.\""},{"text":"Fix it, tell her, and add a check to your routine","then":"She nods, glad it's handled. The reminder now sits on your phone.","best":true},{"text":"Let it slide since it was small","then":"The small task becomes two. Your area feels like nobody's."},{"text":"Ask her to cover it just this once","then":"She covers it. The area slides back to her a little."}],"why":"Fixing and adjusting your own area keeps the plan alive."}],"debrief":"Make parenting equal with a real plan: map the tasks and mental load and each own a fair share.","relearn":"Turn fair-parenting intentions into a real map of owned tasks and load; vague promises don't."},
  {"id":"ep2-069","type":"match","persona":"any","source":"the toolkit","hook":"Match each tool to the job it does.","pairs":[{"left":"The task-and-load map","right":"See and split everything fairly"},{"left":"A shared family calendar","right":"Both hold the schedule"},{"left":"A weekly parenting check-in","right":"Rebalance as life changes"},{"left":"Owning a whole domain","right":"Carry the noticing, not just tasks"},{"left":"Routing real burnout to help","right":"Reach Tele-MANAS 14416"}],"relearn":"The task-and-load map, a shared calendar, a check-in, owned domains and routing burnout are the core tools of equal parenting.","cat":"tools-and-help"},
  {"id":"ep2-070","cat":"tools-and-help","type":"branch","persona":"Divya","source":"rebalance over time","hook":"Your fair split worked at first, but it has quietly drifted back to you.","steps":[{"prompt":"You notice you are doing most of the bedtimes and school work again. What do you do?","options":[{"text":"Take over quietly since it's faster","then":"It is faster. The imbalance grows without anyone naming it."},{"text":"Ask your partner to do more without saying what","then":"They say okay and do the dishes. The rest stays the same."},{"text":"Wait for your partner to notice on their own","then":"Days pass. Your partner has not noticed anything."},{"text":"Note what has shifted and ask for a talk","then":"You jot down three things. Your partner agrees to talk on Sunday.","best":true}],"why":"Noting what has drifted gives you something specific to talk about."},{"prompt":"Days later, your partner mentions they thought the split was still working. What do you do?","options":[{"text":"Agree it works and hope they do more","then":"They nod. Nothing gets said and nothing changes."},{"text":"Say they have slacked off since the early months","then":"They bristle. \"That's not fair. I try.\""},{"text":"Say you're probably just tired this week","then":"They relax. The drift continues."},{"text":"Show them a recent week and ask what changed for them","then":"They read it slowly. \"I didn't realise the mornings had slid.\"","best":true}],"why":"Showing a real week beats an argument about who feels what."},{"prompt":"A week later, your partner admits a new shift at work has made mornings hard. What do you do?","options":[{"text":"Say work is not a reason to do less","then":"They go quiet. The mornings still don't work."},{"text":"Re-trade areas to fit their new schedule","then":"You swap mornings for evenings. Both of you feel it fits better.","best":true},{"text":"Take the mornings yourself so they can focus","then":"It works, but you are back at doing most of it."},{"text":"Keep the split as it is since it worked before","then":"They try. The mornings keep falling apart."}],"why":"Life changes, so the areas change with it."},{"prompt":"A relative says that once a split is set, you shouldn't keep changing it. What do you do?","options":[{"text":"Agree it is too much fuss to keep changing it","then":"She's pleased. Your partner hears you agree with her."},{"text":"Explain that kids and jobs keep changing","then":"She thinks. \"Hmm. I suppose nobody's work stays the same.\"","best":true},{"text":"Say nothing and let the comment pass","then":"She takes your silence for agreement and mentions it again."},{"text":"Tell her firmly it is not her business","then":"She is offended. The dinner goes cold and quiet."}],"why":"A calm reason helps family see fairness as something you keep up."},{"prompt":"Three months later a new school term starts. What do you do?","options":[{"text":"Fix it alone with a new chart","then":"The chart looks tidy. Your partner is handed a plan, not asked."},{"text":"Assume the last change will carry you through","then":"It holds for a term. Then the same slide begins."},{"text":"Set a check-in to revisit it each term","then":"You put it in the calendar. Both of you show up with notes.","best":true},{"text":"Wait until it drifts again to talk","then":"It drifts again. The next talk starts with a complaint."}],"why":"A regular check-in catches drift before it hardens."}],"debrief":"Equal parenting needs regular rebalancing; defaults creep back, so revisit the split as life changes.","relearn":"Rebalance regularly; an equal split set once drifts back to one parent over time."},
  {"id":"ep2-071","cat":"tools-and-help","type":"reflect","hook":"Lensy: equality at home is maintained, not declared once; small regular check-ins keep it true. Make sense?","prompt":"What do you think?","options":["Makes sense","Maintained","Regular check-ins"],"affirm":"Equal parenting is maintained through small regular check-ins, not settled by a single declaration.","relearn":"Equality at home is maintained with regular check-ins, not declared once and forgotten.","persona":"any","source":"maintained"},
  {"id":"ep2-072","cat":"tools-and-help","type":"branch","persona":"Divya","source":"burnout is real","hook":"Despite your best efforts, the parenting load has left you running on empty.","steps":[{"prompt":"After a small argument about dinner, you feel completely drained. What do you do?","options":[{"text":"Take a weekend off and go back to the same routine","then":"The weekend helps. By Wednesday you are drained again."},{"text":"Push on and rest once the kids are older","then":"You push on. The tiredness follows you into every day."},{"text":"Tell yourself it is just tiredness","then":"You have a strong tea and carry on. The heaviness stays."},{"text":"Tell your partner you are burning out","then":"Your partner goes still. \"Burning out? Since when?\"","best":true}],"why":"Burnout is real, not weakness, and it means the load needs to change."},{"prompt":"Days later, your partner notices how tired you look and offers to help. What do you do?","options":[{"text":"Say it's fine and that you'll cope alone","then":"They accept it. You are back where you started."},{"text":"Ask for a break on weekends only, nothing more","then":"They agree. Weekdays stay just as heavy."},{"text":"List everything they have missed until now","then":"The list is long and true. They get defensive instead of helping."},{"text":"Ask them to own whole areas from this week","then":"They pick school and health. \"Show me what's involved.\"","best":true}],"why":"Handing over whole areas lightens the load itself, not just the weekends."},{"prompt":"Weeks later you still feel flat and tearful most days. What do you do?","options":[{"text":"Reach out to Looking After You or Tele-MANAS 14416","then":"You call and someone listens. You do not feel you have failed.","best":true},{"text":"Tell yourself that others have it far worse","then":"You feel guilty for being tired. It doesn't go away."},{"text":"Stay a few days at your mother's and rest well","then":"You sleep well. You come home to the same load."},{"text":"Wait a few more weeks for it to pass on its own","then":"Weeks pass. The flat feeling stays."}],"why":"Persistent depletion deserves support, and asking is never weakness."},{"prompt":"A neighbour says a good parent would cope without help. What do you do?","options":[{"text":"Agree with her and feel guilty afterwards","then":"You smile. You carry the guilt into the evening."},{"text":"Wonder if you are just not cut out for this","then":"You go quiet and replay her words. The doubt follows you home."},{"text":"Argue until she finally admits she is wrong","then":"She gets upset. You end up drained again."},{"text":"Say burnout is real and needs support","then":"She looks surprised. \"Oh. My sister had that.\"","best":true}],"why":"Burnout is not weakness or your fault, and asking for help is part of good parenting."}],"debrief":"Take parental burnout seriously: rebalance the load and reach for support (see Looking After You).","relearn":"Treat parental burnout as real: rebalance, and reach Looking After You or Tele-MANAS 14416."},
  {"id":"ep2-073","cat":"tools-and-help","type":"strike-rewrite","hook":"\"If equal parenting is hard to keep up, it's just not for our family.\"","myth":{"un":"If equal parenting is hard to keep up, it's just not for our family.","re":"It takes ongoing effort for everyone; the difficulty is normal and workable with tools and check-ins, not a reason to quit.","why":"Hard to maintain isn't impossible."},"relearn":"Equal parenting being hard to keep up is normal and workable with tools and check-ins, not a reason to give up.","persona":"any","source":"workable not quit"},
  {"id":"ep2-074","cat":"tools-and-help","type":"role-play","persona":"Vikram","source":"set the tone","hook":"You want to set the tone with your wife for how you'll parent as a team.","setup":"You open the talk warmly over chai.","steps":[{"prompt":"Your wife says: \"You want to talk about parenting now? We haven't even started.\"","options":[{"text":"\"Let's see who turns out better at what.\"","then":"She frowns. \"So we'll find out by trying?\""},{"text":"\"I'll earn and you'll handle the baby.\"","then":"She goes quiet. \"Is that the plan?\""},{"text":"\"Let's parent as equals. Share the worry too.\"","then":"She smiles slowly. \"The worry too? Nobody says that part.\"","best":true},{"text":"\"Let's just see how it goes and sort it later.\"","then":"She nods. \"Sure.\" Later is a long way off."}],"why":"Saying equals out loud sets the tone before defaults do it for you."},{"prompt":"Your wife says: \"My sister ended up doing everything after her baby came. How do we stop that happening to us?\"","options":[{"text":"\"We'll just try harder.\"","then":"She sighs. \"That's what they said too.\""},{"text":"\"We'll sort it out when someone gets angry.\"","then":"She laughs uneasily. \"That's not a plan.\""},{"text":"\"You tell me if it drifts.\"","then":"She frowns. \"So I'm the one watching for it.\""},{"text":"\"Let's check in often and re-trade when needed.\"","then":"She relaxes. \"Okay. How often?\"","best":true}],"why":"Regular check-ins keep fairness from depending on anyone's mood."},{"prompt":"Your wife says: \"What if it stops working once the baby comes?\"","options":[{"text":"\"Then I'll do more whenever I possibly can.\"","then":"She nods slowly. \"When you can.\""},{"text":"\"Then we talk and change it. That's the plan.\"","then":"She lets out a breath. \"Okay. That's the plan.\"","best":true},{"text":"\"It will all work out. Please don't worry.\"","then":"She smiles. She is still worried."},{"text":"\"Then we'll go back to how things were.\"","then":"She stiffens. \"How things were?\""}],"why":"Agreeing to talk and adjust makes the plan strong enough to survive change."}],"relearn":"Setting an explicit equal-team tone with regular check-ins keeps parenting fair instead of drifting to default."},
  {"id":"ep2-075","type":"sort","persona":"any","source":"support vs undermine","hook":"Sort: a healthy support for equal parenting, or a habit that undermines it?","items":[{"id":"a","text":"Regular check-ins and rebalancing"},{"id":"b","text":"Maternal gatekeeping of the dad"},{"id":"c","text":"Both owning the mental load"},{"id":"d","text":"Praising dad for the bare minimum"},{"id":"e","text":"One shared calendar you both keep"},{"id":"f","text":"Waiting to be told every task"}],"bins":[{"id":"support","label":"Supports equality","valence":"pos"},{"id":"undermine","label":"Undermines it","valence":"neg"}],"key":{"a":"support","c":"support","e":"support","b":"undermine","d":"undermine","f":"undermine"},"relearn":"Check-ins, shared load and a shared calendar support equal parenting; gatekeeping, bare-minimum praise and waiting undermine it.","cat":"tools-and-help"},
  {"id":"ep2-076","type":"spot","persona":"any","source":"sustainable path","hook":"Spot the two moves that aren't a sustainable path to equal parenting.","scene":[{"id":"a","text":"Small regular rebalancing","trick":false},{"id":"b","text":"One grand promise, never revisited","trick":true},{"id":"c","text":"Both owning load and care over time","trick":false},{"id":"d","text":"Set it once and never look again","trick":true},{"id":"e","text":"A check-in when life changes","trick":false}],"why":"A one-off promise and set-and-forget both let the default return; regular rebalancing and shared ownership last.","relearn":"Equal parenting lasts through regular rebalancing and shared ownership, not a single grand promise left unrevisited.","cat":"tools-and-help"},
  {"id":"ep2-077","cat":"tools-and-help","type":"reflect","hook":"Lensy: two parents, one team. Share the care, split the load, model it for the kids, and rebalance as life shifts. Feel set up to parent as equals?","prompt":"Where do you land?","options":["Set up for it","Still finding our balance","We'll keep adjusting"],"affirm":"Splitting care and load, modelling equality for the kids, and rebalancing as life shifts is what lets a couple parent as a real team.","relearn":"The plan is simple: share care, split the load, model it for the kids, and rebalance as things change.","persona":"any","source":"equipped"},
  {"id":"ep2-078","cat":"tools-and-help","type":"branch","persona":"Vikram","source":"the one principle","hook":"You want one principle to carry through all the years of raising your kids.","steps":[{"prompt":"A friend asks what your parenting rule is. What do you say?","options":[{"text":"We both fully parent, and we show it","then":"Your friend nods slowly. \"Both? That's a big promise.\"","best":true},{"text":"I provide and she runs the home","then":"Your friend smiles and agrees. Your wife is not asked."},{"text":"We split the chores fairly","then":"Your friend is impressed. The worrying and planning don't come up."},{"text":"Whoever is home does it","then":"Your friend nods. That will usually mean your wife."},{"text":"We try to be fair when we can","then":"Your friend laughs. \"When you can\" leaves plenty of room."}],"why":"One clear rule covers the doing, the worrying and the example you set."},{"prompt":"A week later your child falls ill during your busiest week at work. What do you do?","options":[{"text":"Check calendars with your wife and split the days","then":"You take Tuesday and she takes Wednesday. Both of you tell your offices.","best":true},{"text":"Let her handle it since you have deadlines","then":"She cancels her meetings again. Your deadlines stay safe."},{"text":"Take one day and expect her to cover the rest","then":"You take Monday. She takes the other four."},{"text":"Ask your mother to take over","then":"Ma arrives gladly. Neither parent is with the child."}],"why":"Splitting the days means the career cost and the care are both shared."},{"prompt":"Your son says cooking is for girls after watching a cartoon. What do you do?","options":[{"text":"Say nothing since he'll grow out of it","then":"He doesn't grow out of it by himself. He repeats it at school."},{"text":"Tell him off for saying it","then":"He goes quiet. He still thinks it, just silently."},{"text":"Cook with him and say cooking is for everyone","then":"He stirs the dal proudly. \"I made it, Papa!\"","best":true},{"text":"Ask your wife to explain it to him","then":"She explains it warmly. He sees only her in the kitchen."}],"why":"Kids learn what they see, so let them see cooking as everyone's job."},{"prompt":"Years later the routine has drifted as the kids grew. What do you do?","options":[{"text":"Say the kids are busy so it doesn't matter now","then":"Your teenage daughter notices who still does the planning."},{"text":"Rebalance only the school jobs","then":"School is fixed. Health and meals stay with her."},{"text":"Sit down together and rebalance it all","then":"You both map the load again and see where it slipped.","best":true},{"text":"Let whoever carries most keep going","then":"She keeps going. The kids see who is doing most."}],"why":"Rebalancing together as kids grow keeps both of you fully parenting."}],"debrief":"One principle carries it: both fully parent, share the load and worry, and model equality.","relearn":"Lead with both fully parenting and sharing the load; the default rebuilds the gap."},
  {"id":"ep2-079","type":"spot","persona":"any","source":"fair over years","hook":"Spot the two moves that fail to keep parenting fair as the years go on.","scene":[{"id":"a","text":"Revisiting the split as kids grow","trick":false},{"id":"b","text":"Assuming the first arrangement is forever","trick":true},{"id":"c","text":"Both staying hands-on and informed","trick":false},{"id":"d","text":"Letting the default quietly take over","trick":true},{"id":"e","text":"Re-trading domains at each new stage","trick":false}],"why":"Assuming the first split is forever and letting the default take over both unbalance it; revisiting and staying hands-on keep it fair.","relearn":"Keep parenting fair over the years by revisiting the split and both staying hands-on, not set-and-forget.","cat":"tools-and-help"},
  {"id":"ep2-080","cat":"parental-mental-load","type":"role-play","persona":"Vikram","source":"take a domain","hook":"Your partner is stretched thin by the invisible child-admin, and you want to genuinely take some.","setup":"Tonight she puts the kids' schedule down and sighs.","steps":[{"prompt":"Your partner says: \"I'm holding everything in my head. I can't switch off.\"","options":[{"text":"\"Tell me what to do today, and I'll do it.\"","then":"She lists five things, then thinks of a sixth."},{"text":"\"Let me fully run health and school. All of it.\"","then":"She looks up. \"All of it? Even the forms?\" You nod.","best":true},{"text":"\"Just remind me whenever something's due.\"","then":"She nods wearily. \"So I'll still be the one who remembers.\""},{"text":"\"I know. You do so much. I'm sorry.\"","then":"She squeezes your hand. \"Thanks. But what do we do?\""}],"why":"Fully running whole areas lifts the managing off her, not just the tasks."},{"prompt":"The next evening she says: \"I'd love to let go of some of this, but I'm scared you'll forget.\"","options":[{"text":"\"I might slip. I'll fix it, and you needn't check.\"","then":"She lets out a breath. \"Okay. Try it for a month.\"","best":true},{"text":"\"Fine, take it back then.\"","then":"She stares. \"That's not what I meant.\""},{"text":"\"I won't forget. You worry too much.\"","then":"She flinches. \"That's not fair.\""},{"text":"\"Then keep checking my work, just in case.\"","then":"She nods, relieved, and keeps the spreadsheet open."}],"why":"Admitting you may slip, and promising to fix it, is what makes it truly yours."},{"prompt":"Your partner says: \"The clinic called about the jab. Should I ring back?\"","options":[{"text":"\"What did they say? Then I'll decide.\"","then":"She repeats the message, and you choose. The call is still hers."},{"text":"\"Sure, ring back. You know the number.\"","then":"She rings. The clinic is hers again."},{"text":"\"Tell me what to say, and I'll call.\"","then":"She dictates it word for word."},{"text":"\"No, it's mine. I'll call them back now.\"","then":"She smiles, hands over the number, and picks up her tea.","best":true}],"why":"Taking the call yourself shows her the domain is really off her plate."},{"prompt":"Your partner says: \"I forgot to check the school app tonight. Habit.\"","options":[{"text":"\"I checked it. Nothing due. Go and rest.\"","then":"She lets out a laugh. \"I really can stop, can't I?\"","best":true},{"text":"\"Oh no. Can you check it now?\"","then":"She checks it, tired, and reports back."},{"text":"\"You should've checked. That's how things slip.\"","then":"Her face falls. \"I'm trying to stop. It's hard.\""},{"text":"\"It's okay. It's your area really.\"","then":"She laughs uneasily. \"I thought it was yours now.\""}],"why":"Checking it yourself is how she learns she can finally stop."}],"relearn":"Offering to fully run whole domains lifts the managing, not just the tasks, off your partner's mind."},
  {"id":"ep2-081","cat":"kids-are-watching","type":"role-play","persona":"Priya","source":"reframe for child","hook":"Your young child has a firm idea about who looks after babies, and you want to reframe it gently.","setup":"It is a quiet evening, and your child is tucking a doll into bed.","steps":[{"prompt":"Your child says: \"Caring for babies is only for mummies.\"","options":[{"text":"\"Yes, mummies are best at it, beta. It's how they are.\"","then":"Your child beams and repeats it to Papa at dinner."},{"text":"\"Who told you that? Was it at school or at home?\"","then":"Your child shrugs. \"Nobody. I just see it.\""},{"text":"\"Caring is for everyone. Papa feeds and cuddles you too.\"","then":"Your child thinks. \"Papa does, doesn't he?\" and hugs the doll.","best":true},{"text":"\"You'll understand when you're older.\"","then":"Your child frowns. \"But I want to know now.\""}],"why":"Naming Papa's own care in the moment your child is learning changes what feels normal."},{"prompt":"Papa sits down, and your child says: \"You hold the doll wrong. Only Mummy knows how.\"","options":[{"text":"\"Papa, maybe just let Mummy show you.\"","then":"Papa hands over the doll with a shrug. \"You're the expert.\""},{"text":"\"You're right, beta. Mummy knows best.\"","then":"Your child grins. Papa quietly puts the doll down."},{"text":"\"Papa is learning too. Let's give him a turn later.\"","then":"Your child nods and the doll stays with you. Later never comes."},{"text":"\"Papa learned by doing it, same as I did. Show him your way.\"","then":"Your child hands over the doll. \"Hold the head like this.\"","best":true}],"why":"Care is learned by doing, and Papa gets better each time he tries."},{"prompt":"Later, Grandma tells your child: \"Babies need their mummy, dear. Men can't manage them.\"","options":[{"text":"\"Grandma's right, beta. Babies need their mummy.\"","then":"Your child nods at Grandma, and Papa looks away."},{"text":"\"Let's not argue, Amma. It's a small thing.\"","then":"She nods, satisfied, and your child has heard every word."},{"text":"\"Amma, please don't say that in front of the little one.\"","then":"She purses her lips. \"I only said what everyone knows.\""},{"text":"\"Papa rocked this one to sleep every night, Amma.\"","then":"Grandma looks at Papa, who shrugs and smiles. \"Hm. He did,\" she admits.","best":true}],"why":"Naming what Papa really did answers Grandma kindly and shows your child that men manage babies."}],"relearn":"Showing a child that caring is for everyone, with dad doing it, reteaches them in the moment they're learning."},
  {"id":"ep2-082","cat":"everyone-gains","type":"role-play","persona":"Vikram","source":"set praise straight","hook":"Your wife Neha's aunt has firm ideas about who does what with children.","setup":"At a family gathering, Aunty catches you both by the tea table.","steps":[{"prompt":"Aunty says: \"Poor Neha does so much. You're so good to help sometimes.\"","options":[{"text":"\"We share it as equals, Aunty. I'm the lucky one.\"","then":"Aunty blinks. \"Equals? Hm. Well, that's new.\"","best":true},{"text":"\"Yes, she's a saint. I don't know how she does it.\"","then":"Aunty nods happily. Neha's smile stays fixed."},{"text":"\"Aunty, please don't talk about my home like that.\"","then":"Aunty stiffens. \"I was only being kind.\""},{"text":"\"I help as much as I can. I'm trying.\"","then":"\"Very good, beta,\" she says, patting your arm."}],"why":"Saying you share as equals corrects the praise, warmly."},{"prompt":"Aunty asks: \"Tell me, who takes the children to the doctor, and to school?\"","options":[{"text":"\"Both of us. Health is mine, and school is hers.\"","then":"Aunty raises her brows. \"Both? Hm. Interesting.\"","best":true},{"text":"\"Mostly her, but I'm learning.\"","then":"Aunty smiles. \"Of course. That's natural.\""},{"text":"\"That's her area. I earn and she runs the home.\"","then":"\"Exactly as it should be,\" Aunty says."},{"text":"\"Why ask me? Ask her.\"","then":"Aunty turns to Neha, who has to explain herself."}],"why":"Saying who owns what shows sharing as real, not just kind words."},{"prompt":"Later, Aunty tells Neha in front of you: \"Let him rest. He works so hard.\"","options":[{"text":"\"We both work hard, Aunty. Rest is for both of us.\"","then":"Neha looks at you gratefully. Aunty says nothing more.","best":true},{"text":"\"She's right. I could really do with a proper break.\"","then":"Aunty nods. Neha picks up the plates."},{"text":"Laugh, and say nothing at all.","then":"Aunty takes your laugh as a yes."},{"text":"\"Let's talk about this another day, Aunty.\"","then":"The moment passes. Neha is left holding the plates."}],"why":"Naming shared rest ends the lopsided praise in the room."}],"relearn":"Naming that you share as equals, and that involvement is a gift to you, corrects the lopsided praise."},
  {"id":"ep2-083","cat":"tools-and-help","type":"role-play","persona":"Vikram","source":"fair from day one","hook":"You and your wife are starting out as parents and want to agree how to keep it fair from day one.","setup":"It is the first night you're home with the baby.","steps":[{"prompt":"Your wife says: \"He's finally asleep. So how do we do this?\"","options":[{"text":"\"We'll figure it out as we go along.\"","then":"She frowns. \"As we go? I'd rather agree something tonight.\""},{"text":"\"Let's split it once we're both less tired.\"","then":"She shakes her head. \"We won't be less tired for months. Let's do it now.\""},{"text":"\"You know more so you lead and I'll help.\"","then":"She swallows. \"I'm learning too. But okay.\""},{"text":"\"Let's both own real shares from the start.\"","then":"She looks relieved. \"Real shares. I like the sound of that.\"","best":true}],"why":"Agreeing shares early makes fair the starting point, not a fight."},{"prompt":"Your wife asks: \"So which parts are mine, and which are yours?\"","options":[{"text":"\"Let's each take whole areas. I'll start with health.\"","then":"She smiles. \"Then I'll take sleep routines and feeding plans.\"","best":true},{"text":"\"You do the days and I'll do the paperwork.\"","then":"She does days and evenings. You do a form now and then."},{"text":"\"You do the feeds and I'll do whatever's left.\"","then":"She nods slowly. She keeps the biggest part of the day."},{"text":"\"I'll do whatever you tell me to do.\"","then":"She thinks. \"Then I have to tell you everything.\""}],"why":"Owning whole areas beats waiting for a task list."},{"prompt":"Your wife says: \"And how will we know it stays fair?\"","options":[{"text":"\"Let's keep a chart of who does what.\"","then":"She raises an eyebrow. \"A chart to count everything?\""},{"text":"\"You tell me if it's not fair.\"","then":"She sighs. \"So I'm the one watching for it.\""},{"text":"\"Let's check in for ten minutes every week.\"","then":"She smiles. \"Weekly? Sunday morning, then.\"","best":true},{"text":"\"We'll know if someone is unhappy.\"","then":"She laughs. \"By the time we know, it's too late.\""}],"why":"A short weekly check-in keeps fairness a shared job."},{"prompt":"Your mother says: \"Why all these plans? A mother just knows what to do.\"","options":[{"text":"\"You're right, Ma. She'll lead.\"","then":"Ma smiles. Your wife hears the plan change."},{"text":"\"Ma, please don't worry. She'll manage.\"","then":"Ma is satisfied. Your wife looks at you, tired."},{"text":"\"Ma, let's talk about this later.\"","then":"Ma frowns. Later, the same comment returns."},{"text":"\"Ma, we both learn. That's why we plan.\"","then":"Ma sniffs. \"Hmm. We didn't plan.\" She sounds a little less certain.","best":true}],"why":"Plans work because parents learn together, not because someone just knows."}],"relearn":"Agreeing owned shares and a weekly check-in from day one makes fairness the default instead of a constant fight."},
  {"id":"ep2-084","type":"spot","persona":"any","source":"keep load shared","hook":"Spot the two moves that quietly keep the mental load on one parent.","scene":[{"id":"a","text":"Both owning whole domains end-to-end","trick":false},{"id":"b","text":"One parent assigning tasks to the other","trick":true},{"id":"c","text":"A weekly check-in to rebalance","trick":false},{"id":"d","text":"One parent keeping all the lists","trick":true},{"id":"e","text":"Each tracking their own domain","trick":false}],"why":"Assigning tasks and keeping all the lists leave one parent the manager doing the tracking; owned domains share the load.","relearn":"Keep the mental load shared by both owning whole domains and checking in, not by one assigning tasks or holding the lists.","cat":"tools-and-help"},
  {"id":"ep2-1260","cat":"everyone-gains","type":"strike-rewrite","hook":"\"A father who does half the parenting has 'gone soft'.\"","myth":{"un":"A father who does half the parenting has 'gone soft'.","re":"A father who does half is a fuller parent and partner; involvement is strength, not softness.","why":"Showing up for your kids takes more, not less, of a man."},"relearn":"A hands-on father hasn't gone soft; he's claimed a fuller, stronger role at home.","persona":"Vikram","source":"not gone soft"},
  {"id":"ep2-1261","cat":"everyone-gains","type":"strike-rewrite","hook":"\"Equality at home is a women's issue that costs men.\"","myth":{"un":"Equality at home is a women's issue that costs men.","re":"Equal parenting is pro-men too: fathers gain bond, confidence and wellbeing, not a bill to pay.","why":"It lifts all three of you, never men losing so women win."},"relearn":"Equality at home isn't men's loss; it's a gain for fathers as much as for mothers and kids.","persona":"any","source":"pro-men gain"},
  {"id":"ep2-1262","cat":"everyone-gains","type":"strike-rewrite","hook":"\"The most a father gives his kids is a good income.\"","myth":{"un":"The most a father gives his kids is a good income.","re":"Income matters, but your presence and bond shape your child far more than your pay slip ever can.","why":"Kids remember a father who showed up, not his salary."},"relearn":"A father's biggest gift isn't his income; it's his presence and the bond it builds.","persona":"Vikram","source":"more than income"},
  {"id":"ep2-1263","cat":"everyone-gains","type":"strike-rewrite","hook":"\"A wife who shares the parenting is letting her husband do her job.\"","myth":{"un":"A wife who shares the parenting is letting her husband do her job.","re":"Parenting was never one parent's job; sharing it means two owners, not a wife offloading work.","why":"It's their child together, so the care is theirs together."},"relearn":"Sharing the parenting isn't a wife shirking; it's two parents owning what was always shared.","persona":"any","source":"never one job"},
  {"id":"ep2-1264","cat":"everyone-gains","type":"strike-rewrite","hook":"\"Splitting parenting fairly just leaves both parents exhausted.\"","myth":{"un":"Splitting parenting fairly just leaves both parents exhausted.","re":"A fair split spreads the load so neither parent burns out; that's the whole point, less depletion, not more.","why":"Two carrying half beats one carrying it all."},"relearn":"A fair split doesn't tire both out; it stops one parent carrying everything alone.","persona":"any","source":"less depletion"},
  {"id":"ep2-1265","cat":"everyone-gains","type":"strike-rewrite","hook":"\"A mother who travels for work is putting the family second.\"","myth":{"un":"A mother who travels for work is putting the family second.","re":"When the other parent owns the home in turn, her work and the kids both thrive; it's not a family she abandoned.","why":"Two capable parents means neither is chained to the door."},"relearn":"A working mother isn't sidelining the family; a shared home lets both her career and her kids flourish.","persona":"Divya","source":"both thrive"},
  {"id":"ep2-1266","cat":"everyone-gains","type":"strike-rewrite","hook":"\"Once you have kids, the marriage just has to take a back seat.\"","myth":{"un":"Once you have kids, the marriage just has to take a back seat.","re":"Sharing the load as teammates protects the marriage too; partners who share stay closer, not further apart.","why":"A manager and a helper drift; two teammates pull together."},"relearn":"Kids needn't sink the marriage; sharing the load keeps you teammates, not a manager and a helper.","persona":"any","source":"marriage gains too"},
  {"id":"ep2-1267","cat":"everyone-gains","type":"strike-rewrite","hook":"\"A father bonding deeply with a baby is unusual and a bit much.\"","myth":{"un":"A father bonding deeply with a baby is unusual and a bit much.","re":"Babies attach to fathers from birth; a deeply bonded dad is exactly how it's meant to be, and a gift to them both.","why":"That early bond shapes the child and lifts the father for life."},"relearn":"A father bonding deeply with a baby isn't 'too much'; it's natural, and good for them both.","persona":"Vikram","source":"bond is meant to be"},
  {"id":"ep2-1268","cat":"everyone-gains","type":"strike-rewrite","hook":"\"If I share parenting, my kids will respect me less as the man of the house.\"","myth":{"un":"If I share parenting, my kids will respect me less as the man of the house.","re":"Kids respect a father they actually know; the dad who feeds, plays and listens earns more respect, not less.","why":"Presence builds the bond that respect grows from."},"relearn":"Sharing the care doesn't cost a father respect; being present is what earns it.","persona":"Vikram","source":"respect from presence"},
  {"id":"ep2-1269","cat":"everyone-gains","type":"strike-rewrite","hook":"\"A less-stressed mother is just a mother who's stopped trying so hard.\"","myth":{"un":"A less-stressed mother is just a mother who's stopped trying so hard.","re":"A mother with the load shared isn't trying less; she's a rested, whole person and a more present parent for it.","why":"Support makes a better parent, not a slacker."},"relearn":"A less-stressed mother hasn't given up; sharing the load lets her be present and whole.","persona":"Divya","source":"rested not slacking"},
  {"id":"ep2-1270","cat":"everyone-gains","type":"strike-rewrite","hook":"\"Holding out for equal parenting will just wreck the peace at home.\"","myth":{"un":"Holding out for equal parenting will just wreck the peace at home.","re":"Naming an unfair split kindly and rebalancing it builds real peace; the buried resentment is what wrecks it.","why":"Quiet fairness lasts; silent imbalance corrodes."},"relearn":"Asking for a fair split needn't break the peace; the unspoken imbalance is what does.","persona":"any","source":"real peace"},
  {"id":"ep2-1271","cat":"everyone-gains","type":"match","hook":"Match each person to one real thing they gain from shared parenting.","pairs":[{"left":"A toddler","right":"Comfort from either parent, not just one"},{"left":"A new mother","right":"Sleep and her own self back"},{"left":"A father","right":"The closeness he'd otherwise have missed"},{"left":"An older child","right":"A model of how partners treat each other"},{"left":"The whole household","right":"Less tension, more steadiness"}],"relearn":"Every person in a home gains from shared parenting: the kids, both parents and the household itself.","persona":"any","source":"each one gains"},
  {"id":"ep2-1272","cat":"everyone-gains","type":"match","hook":"Match the 'sacrifice' fear to the gain that's actually waiting.","pairs":[{"left":"'I'll lose my evenings'","right":"You gain bedtime stories you'll never forget"},{"left":"'I'll lose my freedom'","right":"You gain a teammate to share it back"},{"left":"'I'll lose my edge at work'","right":"You gain a calmer home to come back to"},{"left":"'I'll lose face with friends'","right":"You gain kids who actually know you"},{"left":"'I'll lose the easy life'","right":"You gain a richer one"}],"relearn":"Each fear of sacrifice in shared parenting hides a real gain; it's a trade up, not a loss.","persona":"Vikram","source":"fear to gain"},
  {"id":"ep2-1273","cat":"everyone-gains","type":"match","hook":"Match the lopsided home to the shared home it could become.","pairs":[{"left":"One parent runs on empty","right":"Both rested enough to enjoy the kids"},{"left":"Dad is the 'fun visitor'","right":"Dad is a parent the kids rely on"},{"left":"Mum tracks every detail alone","right":"Each owns whole domains end to end"},{"left":"Resentment goes unspoken","right":"Check-ins keep it fair over time"},{"left":"Kids see one carer","right":"Kids see two equal parents"}],"relearn":"A lopsided home can become a shared one; naming it and rebalancing turns strain into a gain for all.","persona":"any","source":"lopsided to shared"},
  {"id":"ep2-1274","cat":"everyone-gains","type":"match","hook":"Match each family member to how a shared home shows up for them.","pairs":[{"left":"The daughter","right":"Sees a father who cooks and cares"},{"left":"The son","right":"Learns care is his to give too"},{"left":"The mother","right":"Is a person, not just a service"},{"left":"The father","right":"Is missed when he's away, not just obeyed"},{"left":"The couple","right":"Are partners, not boss and assistant"}],"relearn":"A shared home shows up well for everyone, shaping how each child and parent sees their place.","persona":"Priya","source":"shows up for each"},
  {"id":"ep2-1275","cat":"everyone-gains","type":"match","hook":"Match the myth about equal parenting to the truth that beats it.","pairs":[{"left":"'It's a loss for men'","right":"It's a gain in bond and wellbeing"},{"left":"'Mum is the lesser if she shares'","right":"She's a fuller, present parent"},{"left":"'Kids only need one carer'","right":"Kids thrive with two bonded parents"},{"left":"'Equality fades once kids come'","right":"It matters most once kids come"},{"left":"'It's a trade-off'","right":"It's a win for all three"}],"relearn":"Every myth about equal parenting has a truth that beats it; sharing is a whole-family win, not a trade.","persona":"any","source":"myth beaten"},
  {"id":"ep2-1276","cat":"everyone-gains","type":"match","hook":"Match each gain of shared parenting to who feels it most.","pairs":[{"left":"A deeper bond from the start","right":"The father"},{"left":"Room to breathe and rebuild herself","right":"The mother"},{"left":"Two safe laps to climb into","right":"The child"},{"left":"A calmer, less-stretched house","right":"The grandparents"},{"left":"Two pulling together, not apart","right":"The marriage"}],"relearn":"Each gain of shared parenting lands somewhere real; the father, mother, child, elders and the marriage all benefit.","persona":"any","source":"who feels it"},
  {"id":"ep2-1277","cat":"everyone-gains","type":"match","hook":"Match the comment relatives make to the calm reframe that holds.","pairs":[{"left":"'Poor thing, doing it all alone?'","right":"'We share it, so neither of us is alone'"},{"left":"'You're so good to help her'","right":"'It's my child too, not helping'"},{"left":"'Won't this spoil the kids?'","right":"'Two bonded parents is good for them'"},{"left":"'A man shouldn't be in the kitchen'","right":"'My kids see both of us cook'"},{"left":"'She's lucky to have you'","right":"'We're lucky to have each other'"}],"relearn":"A calm reframe meets each relative's comment, naming the home as shared without picking a fight.","persona":"any","source":"relative reframe"},
  {"id":"ep2-1278","cat":"everyone-gains","type":"match","hook":"Match each parent's old story to the gain hiding inside it.","pairs":[{"left":"'I gave up my career edge'","right":"You gained kids who know you"},{"left":"'I gave up being the boss at home'","right":"You gained a real partner"},{"left":"'I gave up my Sundays'","right":"You gained being missed when away"},{"left":"'I gave up the quiet life'","right":"You gained a fuller one"},{"left":"'I gave up doing it my way'","right":"You gained doing it together"}],"relearn":"Inside each 'I gave up' is a real gain; shared parenting trades a thinner life for a richer one.","persona":"Vikram","source":"old story flipped"},
  {"id":"ep2-1279","cat":"everyone-gains","type":"reflect","hook":"Lensy: when a father is fully in, he doesn't just give his kids more; he gets a whole side of life he'd have missed. True for you?","prompt":"What's your sense?","options":["True for me","He gains a lot","Worth claiming"],"affirm":"A father who's fully in gains a bond and a side of life he'd otherwise miss; the gain runs both ways.","relearn":"Involved fatherhood isn't only a gift to the kids; the father gains just as much.","persona":"Vikram","source":"gains both ways"},
  {"id":"ep2-1280","cat":"everyone-gains","type":"reflect","hook":"Lensy: a home where the load is shared tends to be a calmer, warmer home for everyone in it. Ring true?","prompt":"What do you think?","options":["Rings true","Calmer home","Warmer too"],"affirm":"When the load is shared, the whole home runs calmer and warmer; that's a gain everyone living there feels.","relearn":"Sharing the load makes the whole home calmer and warmer, not just fairer.","persona":"any","source":"calmer warmer"},
  {"id":"ep2-1281","cat":"everyone-gains","type":"reflect","hook":"Lensy: a mother getting a full night's sleep and a bit of her own life back isn't a luxury; it's good for the whole family. Agree?","prompt":"Your take?","options":["Agree","Good for all","Not a luxury"],"affirm":"A rested mother with a little of herself back is a more present parent; the family gains, it's not a luxury.","relearn":"A mother's rest and space aren't a luxury; they make her a more present parent and the family gains.","persona":"Divya","source":"rest helps all"},
  {"id":"ep2-1282","cat":"everyone-gains","type":"reflect","hook":"Lensy: equality at home isn't about keeping score; it's about both of you ending the week less stretched. Sit right?","prompt":"What's your view?","options":["Sits right","Less stretched","Not a scoreboard"],"affirm":"Equality at home is two people less stretched, not a scoreboard; the aim is a lighter load for both.","relearn":"Equality at home isn't a scoreboard; it's both parents ending up less stretched.","persona":"any","source":"not a scoreboard"},
  {"id":"ep2-1283","cat":"everyone-gains","type":"reflect","hook":"Lensy: of all the times to keep equality alive, the years with young kids may matter most. How does that land?","prompt":"What do you feel?","options":["Lands true","Matters most now","Hold the line"],"affirm":"The young-kid years are exactly when equality matters most; holding the line then sets the tone for years.","relearn":"Equality matters most in the early-kid years, when defaults snap back hardest; that's the time to hold it.","persona":"any","source":"matters most now"},
  {"id":"ep2-1284","cat":"everyone-gains","type":"reflect","hook":"Lensy: when both parents are bonded and steady, a child gets two safe places to land instead of one. Worth it?","prompt":"What's your sense?","options":["Worth it","Two safe places","Good for the child"],"affirm":"Two bonded parents give a child two safe places to land; the child's wellbeing is right at the centre of this.","relearn":"Shared parenting centres the child too; two bonded parents give them two safe places to land.","persona":"Priya","source":"two safe places"},
  {"id":"ep2-1285","cat":"everyone-gains","type":"reflect","hook":"Lensy: nobody chooses the perfect split overnight; the win is just both of you a little less alone in it. Fair?","prompt":"Your take?","options":["Fair","Less alone","Step by step"],"affirm":"The win isn't a perfect overnight split; it's both parents a little less alone in the work, built step by step.","relearn":"The gain isn't a flawless split; it's both parents feeling less alone, rebalanced over time.","persona":"any","source":"less alone"},
  {"id":"ep2-1286","cat":"everyone-gains","type":"reflect","hook":"Lensy: a son who grows up seeing his dad care learns that caring is his too; that's a quiet gift to his future family. Agree?","prompt":"What do you think?","options":["Agree","A quiet gift","Good for him"],"affirm":"A son who sees his dad care learns it's his to give too; that's a gain for him and the family he'll one day build.","relearn":"Watching a caring father teaches a son that care is his too; the gain reaches the next generation.","persona":"Priya","source":"gift to his future"},
  {"id":"ep2-1287","cat":"everyone-gains","type":"sort","hook":"Sort: who is a winner when parenting is truly shared?","items":[{"id":"a","text":"The child, with two bonded parents"},{"id":"b","text":"Nobody; someone always loses"},{"id":"c","text":"The mother, less depleted"},{"id":"d","text":"The father, more confident and close"},{"id":"e","text":"Only the mother, never the father"},{"id":"f","text":"The marriage, two teammates"}],"bins":[{"id":"win","label":"A real winner","valence":"pos"},{"id":"false","label":"False framing","valence":"neg"}],"key":{"a":"win","b":"false","c":"win","d":"win","e":"false","f":"win"},"relearn":"Shared parenting has many winners: the child, the mother, the father and the marriage; 'someone loses' is false.","persona":"any","source":"who wins"},
  {"id":"ep2-1288","cat":"everyone-gains","type":"sort","hook":"Sort: a gain a father gets from being fully involved, or a loss he was warned he'd suffer?","items":[{"id":"a","text":"A close, lasting bond with his kids"},{"id":"b","text":"More confidence as a parent"},{"id":"c","text":"Losing his place as head of the house"},{"id":"d","text":"Being 'demoted' from provider"},{"id":"e","text":"Better wellbeing and less regret later"},{"id":"f","text":"Looking weak in front of others"}],"bins":[{"id":"gain","label":"A real gain","valence":"pos"},{"id":"warned","label":"A warned-of 'loss'","valence":"neg"}],"key":{"a":"gain","b":"gain","c":"warned","d":"warned","e":"gain","f":"warned"},"relearn":"Involved fathers gain a bond, confidence and wellbeing; the 'losses' they're warned of, weakness or demotion, are myths.","persona":"Vikram","source":"gain vs warned loss"},
  {"id":"ep2-1289","cat":"everyone-gains","type":"sort","hook":"Sort: a whole-family gain of equal parenting, or a zero-sum trade where one wins and one loses?","items":[{"id":"a","text":"Mum rests; dad bonds; kids thrive"},{"id":"b","text":"Dad gives up time so mum can rest"},{"id":"c","text":"Both parents less burnt out"},{"id":"d","text":"Mum wins only if dad loses"},{"id":"e","text":"The kids get more of both parents"},{"id":"f","text":"One parent's gain is the other's cost"}],"bins":[{"id":"whole","label":"Whole-family gain","valence":"pos"},{"id":"zero","label":"Zero-sum myth","valence":"neg"}],"key":{"a":"whole","b":"zero","c":"whole","d":"zero","e":"whole","f":"zero"},"relearn":"Equal parenting is a whole-family gain; the zero-sum 'one wins, one loses' framing is a myth.","persona":"any","source":"gain vs zero-sum"},
  {"id":"ep2-1290","cat":"everyone-gains","type":"sort","hook":"Sort: a sign a couple reframed parenting as a shared gain, or a sign it's still seen as one person's burden?","items":[{"id":"a","text":"'We' language about the kids"},{"id":"b","text":"'I'm helping her out today'"},{"id":"c","text":"Either parent plans the week"},{"id":"d","text":"'Ask your mother, she handles that'"},{"id":"e","text":"Both proud of the bond they've built"},{"id":"f","text":"One keeps score of who did more"}],"bins":[{"id":"shared","label":"Shared gain","valence":"pos"},{"id":"burden","label":"One's burden","valence":"uhoh"}],"key":{"a":"shared","b":"burden","c":"shared","d":"burden","e":"shared","f":"burden"},"relearn":"'We' language and shared planning signal a shared gain; 'helping her out' or keeping score signals one person's burden.","persona":"any","source":"shared vs burden"},
  {"id":"ep2-1291","cat":"everyone-gains","type":"sort","hook":"Sort: a true reason equality matters most once kids arrive, or a false reason to let it slide then?","items":[{"id":"a","text":"Defaults snap back hardest now"},{"id":"b","text":"Kids learn from what they watch"},{"id":"c","text":"'Survival mode means roles must split'"},{"id":"d","text":"Both are stretched, so share more"},{"id":"e","text":"'No time for fairness with a baby'"},{"id":"f","text":"'One of us must be the default carer'"}],"bins":[{"id":"true","label":"True: hold the line","valence":"pos"},{"id":"slide","label":"False: let it slide","valence":"neg"}],"key":{"a":"true","b":"true","c":"slide","d":"true","e":"slide","f":"slide"},"relearn":"Kids arriving is the reason to hold the line, not let it slide; defaults snap back hardest just as kids start watching.","persona":"any","source":"hold vs slide"},
  {"id":"ep2-1292","cat":"everyone-gains","type":"sort","hook":"Sort: a real upside of a shared home for the kids, or a worry that simply doesn't hold?","items":[{"id":"a","text":"They can turn to either parent"},{"id":"b","text":"'They'll be confused by two carers'"},{"id":"c","text":"They see partners as a team"},{"id":"d","text":"'A boy needs only his father's example'"},{"id":"e","text":"They learn care has no gender"},{"id":"f","text":"'Dad's care will make them soft'"}],"bins":[{"id":"upside","label":"Real upside","valence":"pos"},{"id":"worry","label":"Worry that fails","valence":"neg"}],"key":{"a":"upside","b":"worry","c":"upside","d":"worry","e":"upside","f":"worry"},"relearn":"Kids gain from two carers and a team to watch; 'confused', 'too soft' or 'only dad's example' are worries that don't hold.","persona":"Priya","source":"upside vs worry"},
  {"id":"ep2-1293","cat":"everyone-gains","type":"sort","hook":"Sort: a healthy way to keep equal parenting going, or depletion creeping in that needs support?","items":[{"id":"a","text":"A monthly check-in on who carries what"},{"id":"b","text":"One parent crying from sheer tiredness"},{"id":"c","text":"Swapping domains when one's stretched"},{"id":"d","text":"Persistent emptiness for weeks"},{"id":"e","text":"Both naming what they need out loud"},{"id":"f","text":"Snapping at the kids, feeling numb"}],"bins":[{"id":"healthy","label":"Healthy upkeep","valence":"pos"},{"id":"depleted","label":"Depletion to support","valence":"uhoh"}],"key":{"a":"healthy","b":"depleted","c":"healthy","d":"depleted","e":"healthy","f":"depleted"},"relearn":"Check-ins and swapping domains keep it healthy; weeks of emptiness is burnout, reach Tele-MANAS 14416.","persona":"any","source":"healthy vs depleted"},
  {"id":"ep2-1294","cat":"everyone-gains","type":"sort","hook":"Sort: a genuine gain for the mother when the load is shared, or a slur thrown at her for sharing it?","items":[{"id":"a","text":"Time to be a whole person again"},{"id":"b","text":"'She's lazy for not doing it all'"},{"id":"c","text":"Less burnout, more patience with kids"},{"id":"d","text":"'A real mother manages alone'"},{"id":"e","text":"A career and motherhood, both alive"},{"id":"f","text":"'She's a lesser mum now'"}],"bins":[{"id":"gain","label":"Her real gain","valence":"pos"},{"id":"slur","label":"Unfair slur","valence":"neg"}],"key":{"a":"gain","b":"slur","c":"gain","d":"slur","e":"gain","f":"slur"},"relearn":"A mother who shares gains rest, patience and her whole self; 'lazy' or 'lesser mum' are unfair slurs, not truths.","persona":"Divya","source":"gain vs slur"},
  {"id":"ep2-1295","cat":"everyone-gains","type":"branch","persona":"Vikram","source":"show the gain","hook":"A friend says he earns while his wife does the kids, and everyone's happy.","steps":[{"prompt":"He asks why you left the office early for your daughter's checkup. What do you say?","options":[{"text":"Tell him what you gain by being hands-on","then":"He looks curious. \"Gain? I thought it was just a chore.\"","best":true},{"text":"Say your boss is flexible, so it's easy for you to slip away","then":"He nods. \"Lucky you. Mine would never allow it.\""},{"text":"Tell him he's missing out and should feel ashamed of it","then":"He stiffens. \"I provide for them. Don't lecture me.\""},{"text":"Say it works for you and leave it there for today","then":"He shrugs. The talk moves on to cricket."}],"why":"Sharing what you gain gives him a reason to be curious."},{"prompt":"Over lunch a few days later, he says his kids only cling to their mother anyway. How do you reply?","options":[{"text":"Say your daughter reached for you once you did the daily bits","then":"He goes quiet, then asks what you actually do with her.","best":true},{"text":"Agree that little kids just prefer their mothers anyway","then":"He nods, satisfied. The idea goes unchallenged."},{"text":"Warn him that his kids will resent him when they grow up","then":"He frowns and says you're being dramatic."},{"text":"Offer to lend him a good parenting book you read","then":"He takes it and never opens it."}],"why":"Your own story shows the bond comes from doing the care."},{"prompt":"A week later he texts that his son cried for his mother again. What do you reply?","options":[{"text":"Say it took you time too, and offer to show what helped","then":"He sends a thumbs up, then: \"Saturday?\"","best":true},{"text":"Say he should be around more, and that it's his own doing","then":"He mutes the chat for a few days."},{"text":"Send a sympathetic emoji and nothing more than that","then":"He sends one back. Nothing changes."},{"text":"Suggest his wife should hand the baby over to him more","then":"He says she never would. Then he stops replying."}],"why":"Sharing your own learning curve invites him in without blame."}],"debrief":"Naming the bond he stands to gain invites a father in; shame just makes him defend the old split.","relearn":"Reach a provider-only father by showing what he gains by leaning in, not by shaming him."},
  {"id":"ep2-1296","cat":"everyone-gains","type":"branch","persona":"any","source":"don't let it harden","hook":"Exhausted with a newborn, you both find a split of nights for her and money for you tempting.","steps":[{"prompt":"At 2 a.m. the baby cries again and your partner is grey with tiredness. What do you do?","options":[{"text":"Get up, settle the baby, and plan a nights rota tomorrow","then":"She hands the baby over with a tired smile. Over chai you both sketch a rota.","best":true},{"text":"Stay in bed, since you have an early meeting tomorrow morning","then":"She gets up alone. You sleep, and feel a little guilty."},{"text":"Offer to take over the nights just for this one week","then":"She's relieved. The offer quietly ends on Sunday."},{"text":"Tell her to nap tomorrow while you're away at work","then":"She nods. Her days and nights are both full now."}],"why":"Sharing nights early stops the default from setting."},{"prompt":"Your mother visits and says the mother handles nights while the father sleeps. What do you say?","options":[{"text":"Thank her, and say nights are for both of you from now on","then":"She purses her lips, then admits her own back ached for years.","best":true},{"text":"Nod politely and change the subject to the weather and food","then":"She takes it as agreement and repeats it at dinner."},{"text":"Tell her firmly to stay out of how you run your own home","then":"The room chills. She leaves early."},{"text":"Say you share the nights whenever you can manage it","then":"She smiles. \"When you can\" becomes the rule."}],"why":"Saying it plainly, with warmth, keeps both parents central."},{"prompt":"Two months on, sleep is easier and she asks what you two should keep. What do you say?","options":[{"text":"Share nights, and each own an area like health or supplies","then":"You sketch it on a whiteboard. She laughs at how easy that felt.","best":true},{"text":"Settle back into the old split now that things are easier","then":"Nights drift to her. By spring she's the default again."},{"text":"Say you'll pitch in whenever she asks you to, of course","then":"She becomes the one who has to ask, again."},{"text":"Wait until the baby sleeps through the night, then decide","then":"Nothing gets decided, and the habits set."}],"why":"Owned areas, kept up over time, make the fair split last."},{"prompt":"Six months on, a work trip lands in a rough patch of night wakings. What do you do?","options":[{"text":"Plan it with her, and take extra nights before you go","then":"She gets full nights of sleep, and you leave on good terms.","best":true},{"text":"Leave her the nights and say sorry for the trip","then":"She nods, tired. The nights are hers, again."},{"text":"Ask your mother to cover the nights while you're away","then":"Your mother agrees. The load quietly shifts to her."},{"text":"Ask her to cope on her own this once, since it's work","then":"She copes. It becomes the reason she copes next time too."}],"why":"Planning ahead keeps nights fair when work moves."}],"debrief":"The newborn fog is when defaults set. Sharing nights now keeps the gain alive for everyone.","relearn":"In the newborn haze, share nights and domains rather than letting the default harden."},
  {"id":"ep2-1297","cat":"everyone-gains","type":"branch","persona":"Vikram","source":"back her return","hook":"Your wife wants to return to work, and your mother says the kids will suffer.","steps":[{"prompt":"Over tea, your mother repeats it while your wife is in the room. What do you do?","options":[{"text":"Say you decided together and you'll own your half","then":"Your mother goes quiet. Your wife's shoulders drop.","best":true},{"text":"Promise your mother the kids won't suffer, since your wife will manage both","then":"Your mother relaxes. Your wife's jaw tightens."},{"text":"Tell your mother she's being old-fashioned about all of this","then":"She stands up, hurt. The tea goes cold."},{"text":"Suggest your wife waits a year or two before going back","then":"Your mother beams. Your wife studies her cup."}],"why":"Backing her openly, and owning your half, settles the doubt."},{"prompt":"A month later, your wife has a job offer with a start date. What do you do?","options":[{"text":"Sit down together and list which parts of child care you'll own","then":"You take school mornings and health. She adds her share. The list goes on the fridge.","best":true},{"text":"Congratulate her and ask how she plans to manage the mornings","then":"She says she'll figure it out. She usually does."},{"text":"Suggest hiring some help for everything else at home","then":"Help arrives, but the planning still lands on your wife."},{"text":"Say you'll pitch in whenever work allows it, and leave it","then":"She nods. \"When work allows\" turns into \"rarely\"."}],"why":"Owning whole domains makes her return a shared plan."},{"prompt":"In her first week, your son runs a fever on the day of her big meeting. What do you do?","options":[{"text":"Take the day yourself and handle the doctor too","then":"She goes to her meeting calm. You book the visit and note the medicine.","best":true},{"text":"Ask your mother to look after him while you both work","then":"Your mother agrees, then adds a remark about working mothers."},{"text":"Message your wife to ask her what needs to be done","then":"She sends dosage and doctor details between agenda points."},{"text":"Ask your wife to stay home with him just this once","then":"She stays. The job starts with an apology."}],"why":"Taking the day, and the details, shows her work counts as much as yours."},{"prompt":"Months later, she is offered a promotion that means some travel. What do you do?","options":[{"text":"Ask what she wants, then rework who owns what","then":"She lights up. You sit down and redraw the list together.","best":true},{"text":"Suggest she waits until the kids are older","then":"She shelves the offer. The kids are still the reason."},{"text":"Say yes, and expect your mother to fill in the gaps","then":"Your mother agrees. The gaps are hers, not yours."},{"text":"Say you'll manage, but ask for less travel","then":"She negotiates hard. The offer shrinks, and so does her joy."}],"why":"Reworking who owns what lets her grow while you both share."}],"debrief":"Backing her return and carrying your share is a gain for her, you and the kids, not a risk.","relearn":"Supporting a partner's return to work and owning your half is a win for the children."},
  {"id":"ep2-1298","cat":"everyone-gains","type":"branch","persona":"any","source":"not allowing","hook":"At a family dinner, an uncle praises you for 'allowing' your wife her job.","steps":[{"prompt":"Uncle raises his glass to you in front of the kids. What do you do?","options":[{"text":"Say it's her right, and a gain for all of you","then":"Uncle blinks, then says \"Of course.\" Your wife's eyes soften.","best":true},{"text":"Smile and accept the praise for being modern","then":"Uncle beams. Your daughter glances at her mother, who studies her plate."},{"text":"Joke that she'd never listen to you anyway, so why not","then":"The table laughs. Your wife's smile is thin."},{"text":"Tell your wife later that you didn't like the remark","then":"She thanks you, then asks why you didn't say it at the table."}],"why":"Answering on the spot shows the kids whose right it is."},{"prompt":"At bedtime your daughter asks if mummy needs your permission to work. What do you say?","options":[{"text":"Say no, mummy decides for herself","then":"She thinks. \"Like you decide for you.\" You nod.","best":true},{"text":"Say it's a grown-up matter and change the subject","then":"She frowns, and keeps wondering."},{"text":"Say mummy asks because you're a kind papa","then":"She nods. She's learned that dads give permission."},{"text":"Say you'll get mummy to explain it in the morning","then":"Mummy tells you later she wishes you'd answered."}],"why":"A plain answer teaches her that her mother's work is her own."},{"prompt":"At the next function, uncle says your wife is lucky to have you. What do you do?","options":[{"text":"Say you're the lucky one, since you're partners","then":"Uncle laughs a little stiffly. Your son repeats it to a cousin later.","best":true},{"text":"Let it pass to keep the peace","then":"The evening stays smooth. Your wife says nothing."},{"text":"Ask your wife to answer him herself","then":"She answers, calm and tired. Correcting him is her job again."},{"text":"Tell him in front of everyone that he's out of date","then":"He goes red. The room falls silent."}],"why":"Naming your partnership out loud, kindly, keeps modelling it."},{"prompt":"Your daughter says at bedtime she wants to be a pilot. What do you say?","options":[{"text":"Say she can do any job, and have a fair home if she wants","then":"She beams. \"Like you and mummy?\" \"Just like us.\"","best":true},{"text":"Say she should pick a job that leaves time for family","then":"She nods slowly. The sky gets a little smaller."},{"text":"Say pilots are mostly men, so it may be hard","then":"She frowns. \"Then I'll be one of them.\""},{"text":"Say you'll talk about it when she's older","then":"She nods. The dream waits."}],"why":"Backing her dream as you back mummy's work shows her it in action."}],"debrief":"Correcting 'allowing' in front of the kids models that a mother's work is hers by right.","relearn":"How you answer 'allowing her to work' teaches the kids who decides; name it as her right."},
  {"id":"ep2-1299","cat":"everyone-gains","type":"branch","persona":"Vikram","source":"own it warmly","hook":"Now that you do real parenting, a mate teases that you're 'whipped'.","steps":[{"prompt":"At the tea stall, he says it again in front of the others. What do you do?","options":[{"text":"Say it's the best thing you do, and your kids know you","then":"A couple of the others go quiet. One says his own father never did that.","best":true},{"text":"Laugh it off and change the subject to cricket again","then":"They laugh. The jibe comes back next week."},{"text":"Snap that he's hardly a great father himself either","then":"He goes silent. The tea turns bitter."},{"text":"Joke that you only do it because she's the boss","then":"They roar. You become the henpecked-husband story."}],"why":"Owning it warmly, without a fight, shows the gain."},{"prompt":"Your mates invite you out on the night you usually do bath and stories. What do you do?","options":[{"text":"Say you'll join after bedtime, or another night","then":"They grumble. One says he might try bedtime himself.","best":true},{"text":"Go out. The routine can wait","then":"Your daughter waits by the door and sleeps asking for mummy."},{"text":"Ask your wife to cover bedtime just for tonight","then":"She does, tired. You feel a little small the next day."},{"text":"Say you're busy and keep the reason vague","then":"They guess, and the joke grows."}],"why":"Keeping the ritual, and the friends, shows you can do both."},{"prompt":"Alone, that friend asks how you manage with the baby, since his wife is exhausted. What do you say?","options":[{"text":"Tell him what you do and what you get from it","then":"He listens. \"Maybe I'll try bath time this weekend.\"","best":true},{"text":"Say your wife is patient, so it's easier for you","then":"He decides his home is just different."},{"text":"Tell him he should have started earlier","then":"He goes defensive. \"Easy for you to say.\""},{"text":"Suggest he asks his wife what to do","then":"He asks. She says she's too tired to plan his change."}],"why":"Sharing what you do and gain invites him in."}],"debrief":"Naming involved fatherhood as the best thing you do shrugs off the jibe and protects the bond.","relearn":"Teased for being a hands-on dad, own it as a gain; don't trade the bond back to look 'tough'."},
  {"id":"ep2-1300","cat":"everyone-gains","type":"branch","persona":"any","source":"rebalance not quit","hook":"Both of you are stretched thin, and keeping parenting equal feels too hard.","steps":[{"prompt":"After a rough week, your partner says the split feels like too much. What do you do?","options":[{"text":"Sit down and map who carries what","then":"The list is longer than either guessed. Some jobs sit with the wrong person.","best":true},{"text":"Let it slide back to the old default for now","then":"The week eases. Nights drift toward one of you."},{"text":"Say your partner's long hours are the real problem","then":"You both get defensive. Nothing changes."},{"text":"Hire more help and stop talking about it","then":"Help takes some chores. The tension stays."}],"why":"Mapping the load shows what to rebalance, instead of quitting."},{"prompt":"Two weeks on, a school form and a vaccine date are both missed. What do you do?","options":[{"text":"Agree who owns school and who owns health","then":"Each of you takes a whole area. The next deadline goes on one shared calendar.","best":true},{"text":"Agree to remind each other more often","then":"Reminders pile up. One of you is still the reminder."},{"text":"Blame whoever usually handled it","then":"They apologise, hurt. It doesn't touch the cause."},{"text":"Decide you both just need to try harder","then":"You try. By Friday you're both flat."}],"why":"Owning whole areas beats scattered reminders."},{"prompt":"A month later, one of you is burnt out and snaps at dinner. What do you do?","options":[{"text":"Pause, say it plainly, and set a check-in to rebalance","then":"You pick a Sunday check-in, and agree to call Tele-MANAS 14416 if it lasts.","best":true},{"text":"Say it proves equal parenting doesn't work","then":"The idea goes quiet. Old habits move back in."},{"text":"Push on and say you'll cope","then":"You cope, silently, until the next snap."},{"text":"Give the tired one a week off, then carry on as before","then":"They rest. The old pattern returns on Monday."}],"why":"Burnout is real, not a weakness or anyone's fault. A check-in, and help if it lasts, keeps you both going."},{"prompt":"At the start of a new school term, the routine changes completely. What do you do?","options":[{"text":"Hold a fresh check-in and redraw who owns what","then":"The old split is out of date. The new one takes an hour.","best":true},{"text":"Keep the old split and see what breaks","then":"Things break by the second Tuesday."},{"text":"Let whoever is less busy this term take everything","then":"The less busy one takes everything, and the term is a slog."},{"text":"Ask the school to send all messages to one parent","then":"One parent's phone buzzes all day, and the other stays blind."}],"why":"Fresh check-ins keep a fair split alive over the years."}],"debrief":"When it feels too hard, that's the cue to remap and rebalance, not to quit. Difficulty is workable.","relearn":"Equal parenting feeling hard is normal; remap and rebalance rather than sliding back to one carrier."},
  {"id":"ep2-1301","cat":"everyone-gains","type":"branch","persona":"Vikram","source":"more than fun bits","hook":"You've slipped into being the 'fun parent' while your partner carries the rest.","steps":[{"prompt":"On Sunday you plan a park trip while your partner sorts laundry and meals. What do you do?","options":[{"text":"Tell her you'll take one whole area, dull parts included","then":"She looks up, surprised. \"Which one?\" \"Health, start to finish.\"","best":true},{"text":"Keep the park trips and call that your fair share of parenting","then":"She smiles thinly. The laundry pile grows."},{"text":"Ask her to list what she needs help with","then":"She sighs. Writing the list is one more job."},{"text":"Do the dishes tonight and count it as done","then":"The dishes are clean. Nothing else has moved."}],"why":"Taking a whole area, dull bits too, ends the visitor role."},{"prompt":"Your daughter has a school form due, an appointment to book and a lunchbox to plan. What do you do?","options":[{"text":"Take all three and plan them together this Sunday","then":"You block Sunday for the week's plan and book the appointment. Nothing gets missed.","best":true},{"text":"Take the lunchbox, since it's the easy and quick part","then":"Lunch is sorted. The form and booking stay with her."},{"text":"Ask your wife to remind you about deadlines","then":"She sets the reminders. She's still the one tracking."},{"text":"Wait to be told what's urgent","then":"She tells you. Then she tells you again."}],"why":"Owning the noticing as well as the doing makes it shared."},{"prompt":"Your son says you're the fun parent and mummy is the boring one. What do you say?","options":[{"text":"Say dull bits are parenting too, and you'll do more of them","then":"He wrinkles his nose, then asks to help pack lunches.","best":true},{"text":"Laugh and say fun is your department, and mummy's is the rest","then":"He grins. The roles stay put."},{"text":"Say mummy likes the boring bits","then":"He believes you, and files it away."},{"text":"Tell him to be nicer to mummy","then":"He says sorry to his mother, confused."}],"why":"Your son learns from seeing you share the dull parts."},{"prompt":"A month on, your partner has a bad flu for a week. What do you do?","options":[{"text":"Run the house and the kids, planning included","then":"She rests. You find the week is easier than you feared.","best":true},{"text":"Call your mother in to take over everything","then":"Your mother arrives. You go back to being a visitor."},{"text":"Stick to your usual jobs and let the rest slide","then":"Your usual jobs run fine. Everything else piles up by Friday."},{"text":"Ask her to leave you notes from her bed","then":"She writes notes through the fever. She's the manager, again."}],"why":"Running the whole home shows you can own more than the fun parts."}],"debrief":"Claiming a whole domain, dull parts and all, turns the fun visitor into an equal parent.","relearn":"Being the 'fun parent' isn't sharing; own a full domain to become an equal parent."},
  {"id":"ep2-1302","cat":"everyone-gains","type":"role-play","persona":"Vikram","source":"free her guilt","hook":"Your wife has a weekend away with friends planned, and she's wavering.","setup":"She stands over her half-packed bag, looking at you.","steps":[{"prompt":"She says: \"I feel terrible leaving the kids for a whole weekend.\"","options":[{"text":"\"Go. It's good for all of us. Come back rested.\"","then":"She lets out a breath. \"Are you sure? Bedtimes and meals too?\"","best":true},{"text":"\"I'll manage somehow, if you really have to go.\"","then":"Her shoulders sag. \"I want to go. I just need it to feel okay.\""},{"text":"\"Maybe next month, when the kids are a bit older.\"","then":"She stops packing. \"Next month will feel just the same.\""},{"text":"\"Sure. Just leave me a list of everything.\"","then":"She sits and starts writing, and the trip feels less like a break."}],"why":"Telling her the break helps everyone frees her of the guilt."},{"prompt":"She asks: \"Your mother will say I'm a bad mother. What then?\"","options":[{"text":"\"I'll talk to her. Your break is your call.\"","then":"She squeezes your hand. \"Thank you.\"","best":true},{"text":"\"Ignore her. She says things like this about everyone.\"","then":"\"Easy to say. I'm the one she says it to,\" she replies."},{"text":"\"Let's not tell her you're away.\"","then":"\"So I hide it, as if it's wrong,\" she says."},{"text":"\"Maybe she has a point about mothers.\"","then":"She goes quiet. \"Right,\" she says."}],"why":"Handling your mother yourself keeps the pressure off her."},{"prompt":"On Sunday evening she rings and asks: \"How are the kids? Is everything okay?\"","options":[{"text":"\"All good. Bath done and homework checked. Enjoy.\"","then":"She laughs, relaxed. \"That's the best thing you could say.\"","best":true},{"text":"\"A bit chaotic. When are you back?\"","then":"\"Oh. Should I come back early?\" she asks."},{"text":"\"Where do we keep the kids' medicines again?\"","then":"She spends her evening talking you through the cupboard."},{"text":"\"It's been hard, but you owe me one.\"","then":"Her laughter dies. \"Owe you? For our own kids?\""}],"why":"Running the weekend yourself makes her rest a real rest."},{"prompt":"A month later she says: \"A friend has invited me out again. Is that okay?\"","options":[{"text":"\"Of course, it's your call. Tell me the dates and I'll plan around them.\"","then":"She smiles. \"I'll put it on the calendar.\"","best":true},{"text":"\"Again? Maybe wait a few months first.\"","then":"She nods. The invitation goes unanswered."},{"text":"\"If you must. But who will help with the kids?\"","then":"She goes quiet. \"You will. They're yours too.\""},{"text":"\"Ask your mother if she can help out.\"","then":"She asks. Her mother says yes, with a sigh."}],"why":"Her time is her own, and the kids are yours to care for."}],"relearn":"Telling a partner her rest is good for the whole family frees her guilt and makes the break a shared gain."},
  {"id":"ep2-1303","cat":"everyone-gains","type":"role-play","persona":"Vikram","source":"leave is worth it","hook":"You've applied for parental leave after your baby's birth.","setup":"At the pantry, a colleague grins as you mention your dates.","steps":[{"prompt":"He says with a laugh: \"Parental leave? That'll kill your career, you know.\"","options":[{"text":"\"This time with my kids is the best call I've made.\"","then":"He shrugs, a little surprised. \"Bold. What does your boss say?\"","best":true},{"text":"\"Yeah, maybe you're right. I should be careful.\"","then":"He nods, pleased. \"Nobody takes leave and gets promoted.\""},{"text":"\"Don't worry. I'll answer emails from home.\"","then":"He laughs. \"So it's not even a proper leave.\""},{"text":"\"At least I'm not chained to my desk like you.\"","then":"His grin drops. \"Wow. Okay.\""}],"why":"Naming leave as a gain, calmly, turns a joke into a real answer."},{"prompt":"Your manager asks: \"Are you sure about the full leave? We're busy this quarter.\"","options":[{"text":"\"Yes. Here's my handover plan for the busy weeks.\"","then":"She reads it and nods. \"This is thorough. I'll approve it.\"","best":true},{"text":"\"Maybe I can cut it to a week or so.\"","then":"She looks relieved. \"That would help us a lot.\""},{"text":"\"I'll decide once the baby is actually here.\"","then":"\"Then I can't plan around you,\" she says."},{"text":"\"My wife wants me to, so I have no choice.\"","then":"She nods. \"Understood, if it's family pressure.\""}],"why":"A clear plan claims the leave without apologising."},{"prompt":"On your first day back, the same colleague asks: \"So, was it worth it?\"","options":[{"text":"\"Every day of it. I'd do it again.\"","then":"He says nothing for a moment. \"My wife keeps asking me about leave.\"","best":true},{"text":"\"Honestly? I missed a lot at work.\"","then":"He smirks. \"Told you.\""},{"text":"\"It was fine. I'm just glad to be back.\"","then":"He nods. \"Good. Back to normal.\""},{"text":"\"I'm not sure. Ask me after the appraisal.\"","then":"\"Fair,\" he says. \"The appraisal will tell us.\""}],"why":"Saying it plainly shows leave is worth claiming."}],"relearn":"Naming involved fatherhood as a gain, not a career risk, models that leave is worth claiming, not apologising for."},
  {"id":"ep2-1304","cat":"everyone-gains","type":"role-play","persona":"Vikram","source":"why you share","hook":"Your teenager has noticed that you cook half of the family meals.","setup":"She's helping you chop onions when she asks.","steps":[{"prompt":"She asks: \"Why do you cook so much? Other dads don't.\"","options":[{"text":"\"It's our home. I'd hate to miss caring for you all.\"","then":"She stops chopping. \"Huh. I never thought of it that way.\"","best":true},{"text":"\"Your mother made me. That's just how it is here.\"","then":"She smirks. \"So you'd stop if she didn't?\""},{"text":"\"Other dads are missing out. That's their loss.\"","then":"She rolls her eyes. \"You sound like you're judging them.\""},{"text":"\"Because I enjoy cooking. It's my hobby.\"","then":"She nods. \"So it's just for fun, not a chore.\""}],"why":"Naming it as a gain you'd hate to miss teaches care is shared."},{"prompt":"She says: \"My friends' brothers never cook. Why should my brother?\"","options":[{"text":"\"Everyone in a home should know how to care for it.\"","then":"She thinks about it. \"So it's a life skill, not a girl thing.\"","best":true},{"text":"\"He doesn't have to. You're the one who's good at it.\"","then":"She frowns. \"So it is a girl thing?\""},{"text":"\"You're right. Let's not push him on it.\"","then":"She shrugs. \"Fine by me. He'd only make a mess anyway.\""},{"text":"\"Because I said so, and it's not up for debate.\"","then":"She goes quiet, and doesn't ask again."}],"why":"Cooking and care are for everyone, sons included."},{"prompt":"Her brother wanders in and asks: \"Papa, can you teach me to make rotis too?\"","options":[{"text":"\"Yes. Wash your hands and start with the dough.\"","then":"He grins and rolls up his sleeves. His sister laughs at his first lopsided roti.","best":true},{"text":"\"Sure, but only on weekends when you're free.\"","then":"He nods. It becomes a hobby, not a habit."},{"text":"\"Ask your sister to show you.\"","then":"She sighs and rolls her eyes. She's the teacher again."},{"text":"\"Ask mummy. She makes the best rotis.\"","then":"He wanders off, and the dough stays in the bowl."}],"why":"Teaching your son yourself shows him care is a man's work too."}],"relearn":"Framing your share as something you'd hate to miss teaches a child that care is a gain a father claims, not a chore imposed."},
  {"id":"ep2-1305","cat":"everyone-gains","type":"role-play","persona":"any","source":"get yourself back","hook":"Your partner has had almost no time of her own since the baby arrived.","setup":"Tonight, as the house goes quiet, she speaks.","steps":[{"prompt":"She says quietly: \"Sometimes I feel I've lost myself in being a mum.\"","options":[{"text":"\"I'm glad you told me. What would help you most?\"","then":"She takes a breath. \"Time that's mine. Even just a bit.\"","best":true},{"text":"\"That's just what being a mum is, isn't it?\"","then":"She looks down. \"I suppose so.\""},{"text":"\"You have so much to be grateful for.\"","then":"Her eyes fill. \"I know. That's why I feel worse.\""},{"text":"\"Should I ask your mother to come and stay?\"","then":"\"No. I don't want another person deciding for me.\""}],"why":"Listening first shows her it's real, not weakness. If the low lasts, Tele-MANAS 14416 can help too."},{"prompt":"She says: \"I don't even know what I like anymore.\"","options":[{"text":"\"Let's fix a weekly slot for you. I've got the kids.\"","then":"She almost laughs. \"Every week? Really?\" \"Every week.\"","best":true},{"text":"\"You'll feel better once the baby's older.\"","then":"She nods, but the light in her face fades."},{"text":"\"Take a break whenever you want to. Just tell me.\"","then":"She shrugs. \"I'd have to ask. And plan it.\""},{"text":"\"Try a class, and I'll help if I can.\"","then":"\"If you can,\" she says. \"Right.\""}],"why":"A fixed slot she doesn't have to ask for gives her real time back."},{"prompt":"A week later she says: \"I went out for two hours and felt guilty the whole time.\"","options":[{"text":"\"Next time go longer. It's good for all of us.\"","then":"She smiles, a little shy. \"I think I will.\"","best":true},{"text":"\"Then maybe it's not worth going.\"","then":"She nods. The next slot goes unused."},{"text":"\"Did the kids cry for you while you were away?\"","then":"Her guilt returns. \"A little. Yes.\""},{"text":"\"You can go, but keep your phone on.\"","then":"She checks it every ten minutes on her next outing."}],"why":"Her rest is good for the whole family, and it isn't hers to earn."},{"prompt":"Two months on, she says: \"I want to take up a course. I'm finding myself again.\"","options":[{"text":"\"Lovely. Which evenings? I'll take the kids.\"","then":"She hugs you. \"Tuesdays and Thursdays.\"","best":true},{"text":"\"A course? What about the kids' homework?\"","then":"She sighs. \"Homework again.\""},{"text":"\"Sure, if it doesn't cost too much.\"","then":"She nods. She's already counting the fee."},{"text":"\"Maybe next year. This year is heavy.\"","then":"She nods. The course waits."}],"why":"Taking the kids for her evenings lets her rebuild her own life."}],"relearn":"Offering to hold the kids so a partner reclaims herself turns her depletion into a shared, fixable gain, not a fate."},
  {"id":"ep2-1306","cat":"everyone-gains","type":"role-play","persona":"Priya","source":"cooking is for boys too","hook":"Your young son loves helping in the kitchen, and a visiting relative has noticed.","setup":"She watches him stir the dal, and then she speaks.","steps":[{"prompt":"Your relative says to him: \"Helping mummy cook isn't for boys, beta.\"","options":[{"text":"\"In our home everyone cooks, Mausi. It's a life skill.\"","then":"Mausi raises her brows. Your son keeps stirring.","best":true},{"text":"\"Hmm, maybe. Let's not make a fuss about it now.\"","then":"Your son slowly puts the spoon down."},{"text":"\"Beta, go and play. Mausi doesn't mean it.\"","then":"He runs off. The spoon stays on the counter."},{"text":"\"He only helps because he's little. It'll pass.\"","then":"Mausi smiles. \"Yes. Boys grow out of it.\""}],"why":"Saying it plainly protects your son's right to care."},{"prompt":"Later he asks: \"Mummy, why did Mausi say that?\"","options":[{"text":"\"Some people think that. In our home we all cook.\"","then":"He nods. \"So I can still help?\" \"Yes.\"","best":true},{"text":"\"Don't mind her. She's just from another time.\"","then":"He nods, but he still doesn't know why."},{"text":"\"Ask your father. He'll explain.\"","then":"He goes to papa. Papa says, \"Ask mummy.\""},{"text":"\"Never mind. Go and wash your hands.\"","then":"He goes, and the question stays with him."}],"why":"A calm answer tells him care is a strength and not an odd thing."},{"prompt":"After a classmate laughs, he says: \"I don't want to tell anyone I cook now.\"","options":[{"text":"\"Cooking is a skill. You can be proud of it.\"","then":"He shrugs. Later he asks to cook rice for the family.","best":true},{"text":"\"Then don't tell anyone, if it upsets you.\"","then":"He nods. The apron goes to the back of the cupboard."},{"text":"\"Tell him girls play cricket too.\"","then":"He looks confused. \"What has that got to do with it?\""},{"text":"\"I'll talk to that boy's mother about it.\"","then":"He winces. \"Please don't.\""}],"why":"Pride in a skill answers the teasing better than hiding it."}],"relearn":"Standing up for a son's right to care teaches him it's a strength to gain, and corrects the relative without a row."},
  {"id":"ep2-1307","cat":"everyone-gains","type":"role-play","persona":"Vikram","source":"not spoiling her","hook":"Your father is staying with you for a week, and he notices everything.","setup":"One morning he watches you fold the kids' clothes.","steps":[{"prompt":"Your father says: \"You're spoiling your wife, doing the housework and the kids.\"","options":[{"text":"\"We're partners, Papa. Sharing keeps us both well.\"","then":"He grunts. \"In my day...\" but he stays in the room.","best":true},{"text":"\"You're right, Papa. I'm probably being too soft.\"","then":"He nods, satisfied. Your wife, in the doorway, turns away."},{"text":"\"Papa, times have changed. You wouldn't understand.\"","then":"His jaw sets. \"I understand plenty.\""},{"text":"\"I'll do it when you're not around, Papa.\"","then":"He chuckles. \"Good. Keep it private.\""}],"why":"Calling it partnership holds your ground without disrespect."},{"prompt":"Papa says: \"A man's work is outside. Who will respect you like this?\"","options":[{"text":"\"My kids do. I'm a better father for it, Papa.\"","then":"He looks at your daughter on your lap and says nothing.","best":true},{"text":"\"Respect isn't the point. Please stop, Papa.\"","then":"He frowns. \"You never used to talk to me like this.\""},{"text":"\"Let's not discuss it, Papa. Have your tea.\"","then":"He sips in silence, but you can tell he isn't done."},{"text":"\"Your generation had it easy, Papa.\"","then":"He says gruffly, \"Easy? I worked my whole life.\""}],"why":"Naming what you gain answers him with respect."},{"prompt":"Before he leaves, Papa says: \"Your mother did everything for us. Was that wrong?\"","options":[{"text":"\"She gave us everything. My kids should see us both give.\"","then":"He is quiet, then pats your shoulder. \"Hm. Fair.\"","best":true},{"text":"\"No, Papa. It worked for your time.\"","then":"He nods. The talk is over, and nothing has moved."},{"text":"\"Yes. Mummy deserved a great deal more help from you.\"","then":"He goes quiet and hurt, and leaves early."},{"text":"\"Let's not judge the past, Papa.\"","then":"He nods, relieved to drop it."}],"why":"Honouring the past while modelling sharing keeps both parents central."}],"relearn":"Naming the sharing as partnership and a gain for you both holds your ground with elders without disrespect."},
  {"id":"ep2-1308","cat":"everyone-gains","type":"role-play","persona":"Vikram","source":"not helping, owning","hook":"You've been doing more with the kids lately, and your partner has noticed.","setup":"After the kids are in bed, she squeezes your hand.","steps":[{"prompt":"She says warmly: \"Thank you for helping so much with the kids.\"","options":[{"text":"\"You don't have to thank me. They're mine too.\"","then":"She pauses. \"You're right. It just feels new to hear.\"","best":true},{"text":"\"No problem. Happy to pitch in whenever you need.\"","then":"She smiles. She'll have to ask again tomorrow."},{"text":"\"It's the least I can do for you.\"","then":"She nods. \"You're a good man.\" It sits oddly."},{"text":"\"I do more than most fathers I know.\"","then":"She goes quiet. \"Maybe. But I don't want to compare.\""}],"why":"Calling them yours makes you an owner, not a helper."},{"prompt":"She says: \"I still think of it as my job. It's hard to let go.\"","options":[{"text":"\"Let me own some jobs outright. Which one first?\"","then":"She thinks. \"School lunches and the doctor.\" \"Done.\"","best":true},{"text":"\"Then let me help with whatever you point out.\"","then":"\"I'd still be the one pointing,\" she says."},{"text":"\"Don't worry. You'll get used to it.\"","then":"She smiles, unconvinced. Nothing is handed over."},{"text":"\"It is your job, really. I just like helping.\"","then":"She looks at you, confused and a little tired."}],"why":"Owning whole jobs lifts the noticing off her, not only the doing."},{"prompt":"A few weeks later she asks: \"Do you ever resent doing this much?\"","options":[{"text":"\"No. I'd hate to miss it. It's mine too.\"","then":"She smiles, and her shoulders relax.","best":true},{"text":"\"Sometimes, honestly. But I'm managing.\"","then":"She nods, and starts hiding how often she needs you."},{"text":"\"Only when you criticise how I do it.\"","then":"She winces. \"Was I doing that?\""},{"text":"\"I'd rather not think about it.\"","then":"She lets it go, but the question stays in the room."}],"why":"Saying it's a gain for you removes her fear of resentment."}],"relearn":"Declining the 'thanks for helping' frame names you as an equal owner, not a helper, and claims the gain as yours too."},
  {"id":"ep2-1309","cat":"everyone-gains","type":"role-play","persona":"Vikram","source":"learned by doing","hook":"You're at a new parents' meeting, one of only a few fathers there.","setup":"At the tea break, the father beside you speaks up.","steps":[{"prompt":"He says: \"Fathers aren't built for baby stuff. It's a mother's thing.\"","options":[{"text":"\"I wasn't sure either. We learn it by doing.\"","then":"He blinks. \"Really? You learned it?\"","best":true},{"text":"\"True, it really is more of a mother's thing.\"","then":"He nods, pleased. The other fathers murmur agreement."},{"text":"\"That's nonsense, and you know it.\"","then":"He bristles. \"No need to be rude.\""},{"text":"\"Some fathers manage, but I'm the exception.\"","then":"He shrugs. \"Then you're lucky.\""}],"why":"Saying you learned it by doing shows care isn't a matter of birth."},{"prompt":"Another father says: \"My wife always knows what the baby needs. I don't.\"","options":[{"text":"\"It's practice. Own one whole job and you'll know.\"","then":"He looks thoughtful. \"Like the night feeds?\"","best":true},{"text":"\"That's because she's the mother. It's instinct.\"","then":"He nods. \"Yes. Instinct.\""},{"text":"\"Ask her to write down what to do.\"","then":"\"A list, yes,\" he says. \"I'll ask her.\""},{"text":"\"Try to pay closer attention.\"","then":"He shrugs. \"I do try.\""}],"why":"Knowing what a baby needs is practice, so it can be built."},{"prompt":"After the meeting, he asks quietly: \"What if I'm bad at it and the baby cries?\"","options":[{"text":"\"Everyone is at first. Stay, and he'll learn you.\"","then":"He nods slowly. \"I'll try this weekend.\"","best":true},{"text":"\"Then hand him back. No harm done. Try again later.\"","then":"He nods, relieved. He also steps out of it."},{"text":"\"Watch a video first so you don't fail.\"","then":"He watches one, then decides he's still not ready."},{"text":"\"Keep your wife nearby, just in case.\"","then":"He does. The baby looks past him to her."}],"why":"Staying with a crying baby is how a father learns and bonds."}],"relearn":"Saying you learned care by doing, and love it, busts 'not built for it' and shows other fathers the gain on offer."},
  {"id":"ep2-1310","cat":"everyone-gains","type":"role-play","persona":"any","source":"let them talk","hook":"Your partner is about to go back to work, and she's uneasy about the neighbours.","setup":"She stops at the window, watching the lane below.","steps":[{"prompt":"She says: \"The neighbours will talk when they see me leave every morning.\"","options":[{"text":"\"Let them talk. Our kids will be proud of us both.\"","then":"She lets out a breath. \"Two parents they're proud of. I like that.\"","best":true},{"text":"\"Maybe wait a bit. You know how people gossip here.\"","then":"She nods, and puts off telling her boss she's ready."},{"text":"\"I'll tell them you're only doing it for the money.\"","then":"She stiffens. \"I'm doing it because I want to.\""},{"text":"\"Ignore them. It's not worth thinking about.\"","then":"She shrugs. \"Easy for you. They talk about me.\""}],"why":"Naming two proud parents as the win steadies her."},{"prompt":"She says: \"And what if the kids miss me?\"","options":[{"text":"\"Sometimes, yes. I'm here, and you're back by evening.\"","then":"She smiles. \"You will be there. That helps.\"","best":true},{"text":"\"They'll be fine. Children adjust to anything.\"","then":"She nods, but the worry stays."},{"text":"\"Maybe we should ask your mother to take over.\"","then":"She frowns. \"So my mother does my part?\""},{"text":"\"Then part-time is safer for them.\"","then":"She sighs. \"Safer for whom?\""}],"why":"Being present yourself answers her worry honestly."},{"prompt":"On her first morning, a neighbour calls out: \"Off to work again, beta? Poor kids.\"","options":[{"text":"\"Yes, Aunty! And I'm doing the school run today.\"","then":"Aunty blinks. \"You are? Well.\" Your wife squeezes your arm.","best":true},{"text":"\"Ignore her. Just keep walking.\"","then":"She hurries on, and the remark follows her all day."},{"text":"\"Don't mind, Aunty. She's only trying it out.\"","then":"The neighbour smiles. \"Yes, only trying.\""},{"text":"\"Aunty, please mind your own family.\"","then":"The lane goes quiet. Your wife hurries away."}],"why":"Showing a shared home answers the gossip better than arguing."},{"prompt":"A month on, she says: \"My boss offered me a late shift. Should I take it?\"","options":[{"text":"\"Let's look at the week. I'll cover your late evenings.\"","then":"She smiles. \"You already have a plan.\"","best":true},{"text":"\"Better not. The neighbours will talk more.\"","then":"She nods. The shift goes to someone else."},{"text":"\"Take it, if you can sort the kids out yourself.\"","then":"She nods. The kids are hers to sort."},{"text":"\"Ask your mother if she'd mind the evenings.\"","then":"Her mother agrees. It's the same job, done by someone else."}],"why":"Planning the evenings together keeps her job and your evenings with the kids on track."}],"relearn":"Backing a partner against the gossip names two proud, present parents as the real win and keeps equality on track."},
  {"id":"ep2-1311","cat":"everyone-gains","type":"role-play","persona":"Vikram","source":"not babysitting","hook":"Your wife is away for the day, and your kids have a word for your time with them.","setup":"Breakfast is half-made when your daughter looks up.","steps":[{"prompt":"Your daughter asks: \"Papa, are you babysitting us today?\"","options":[{"text":"\"It's not babysitting. I'm just being your dad.\"","then":"She giggles. \"Okay, Papa.\" Your son copies you, \"Just Papa!\"","best":true},{"text":"\"Yes, babysitting duty today. Lucky me!\"","then":"She giggles. Your son repeats, \"Babysitting!\""},{"text":"\"Call it what you like. Eat your breakfast.\"","then":"She shrugs. The word stays."},{"text":"\"Mummy asked me to look after you, so yes.\"","then":"She nods. \"Mummy's the boss of us, then.\""}],"why":"Correcting the word, lightly, tells them it's your job."},{"prompt":"Your son says: \"Mummy always leaves a list for you when she goes.\"","options":[{"text":"\"True. Today I'll plan it myself. Let's see.\"","then":"He grins. \"You're the boss today, then.\" \"For every day.\"","best":true},{"text":"\"That's because she likes being organised.\"","then":"He nods. Lists must be what mothers do."},{"text":"\"I wish she wouldn't. I'd manage fine.\"","then":"He looks unsure. \"Are you cross with mummy?\""},{"text":"\"Get her list, and we'll follow it.\"","then":"He fetches the list. You follow it line by line."}],"why":"Planning the day yourself shows the kids you own it, not just follow."},{"prompt":"That evening your wife calls and asks: \"Did you manage okay today?\"","options":[{"text":"\"A normal day with my kids. Lunch, bath, story.\"","then":"She laughs, relieved. \"Normal. I like hearing that.\"","best":true},{"text":"\"Barely. I don't know how you do it every day.\"","then":"She laughs, tired. Her load goes unseen again."},{"text":"\"I did it all. Don't ask me to do it again.\"","then":"She goes quiet. \"I wasn't going to ask. I just wondered.\""},{"text":"\"Yes, but what do they usually eat at four?\"","then":"She spends ten minutes explaining everything on the phone."}],"why":"Calling it a normal day shows it is yours, and never a rescue."}],"relearn":"Correcting 'babysitting' even in a joke teaches kids a father's care is his job and his gain, not a favour."},
  {"id":"ep2-1312","cat":"everyone-gains","type":"role-play","persona":"Vikram","source":"a gift to me too","hook":"You've offered to take on more of the kids' care, and your partner seems uneasy.","setup":"She says it into the dark, after the light is off.","steps":[{"prompt":"She says softly: \"If you share more, will you end up resenting me?\"","options":[{"text":"\"I won't. I'd resent missing out on the kids more.\"","then":"She turns to face you. \"You mean that?\" \"I do.\"","best":true},{"text":"\"I'll try not to mind too much, for your sake.\"","then":"She turns over. \"That's exactly what I'm afraid of.\""},{"text":"\"Only if you keep a count of everything.\"","then":"She goes quiet. \"I'll try not to.\""},{"text":"\"Let's not talk about this at night.\"","then":"She's quiet, then says: \"I can't sleep until we do.\""}],"why":"Naming the sharing as your own gain answers her fear."},{"prompt":"She says: \"But you work long hours. What if it's too much?\"","options":[{"text":"\"Then we'll change it together, and not go back.\"","then":"She nods. \"So it's a plan, not a test.\"","best":true},{"text":"\"Then you'll have to take back the rest.\"","then":"She nods slowly. The default comes back home."},{"text":"\"I'll manage. Don't worry about my long hours at work.\"","then":"She sighs. \"You always say that.\""},{"text":"\"We'll see how it goes.\"","then":"She waits for more. There's nothing more."}],"why":"Adjusting together, not retreating, keeps the sharing fair."},{"prompt":"A month later she says: \"I keep waiting for you to say you're fed up.\"","options":[{"text":"\"I'm not. If I ever am, I'll say so. It's mine too.\"","then":"She laughs softly. \"Then I'll stop waiting.\"","best":true},{"text":"\"Then stop waiting. It won't happen.\"","then":"She smiles, but the worry stays."},{"text":"\"Not fed up. Though you do owe me a few lie-ins by now.\"","then":"She laughs, unsure. \"So you are keeping count.\""},{"text":"\"Just say if you'd like me to do less.\"","then":"She stares. \"You'd go back to the old way?\""}],"why":"Promising honesty, and owning it, lets her stop bracing."}],"relearn":"Telling a partner the sharing is a gift, not a grudge, frees her fear and names the gain as mutual."},
  {"id":"ep2-1313","cat":"everyone-gains","type":"spot","hook":"Spot the two lines that frame equal parenting as men losing out.","scene":[{"id":"a","text":"'I get a real bond with my kids out of this'","trick":false},{"id":"b","text":"'Every hour I parent is an hour I lose'","trick":true},{"id":"c","text":"'We're both less burnt out this way'","trick":false},{"id":"d","text":"'She gains, so I must be losing'","trick":true},{"id":"e","text":"'Our home is calmer for all of us'","trick":false}],"why":"'Every hour I lose' and 'she gains so I lose' are zero-sum lies; shared parenting is a gain for fathers too, not a loss.","relearn":"Equal parenting isn't men losing out; the 'every hour is a loss' and 'she gains so I lose' framings are false.","persona":"Vikram","source":"men-lose lines"},
  {"id":"ep2-1314","cat":"everyone-gains","type":"spot","hook":"Spot the two comments that treat a sharing mother as a lesser mum.","scene":[{"id":"a","text":"'She's a whole person and a present parent'","trick":false},{"id":"b","text":"'A good mother wouldn't need help'","trick":true},{"id":"c","text":"'Rested, she has more patience for the kids'","trick":false},{"id":"d","text":"'She's gone lazy since he started helping'","trick":true},{"id":"e","text":"'Sharing lets her keep her own life too'","trick":false}],"why":"'A good mother wouldn't need help' and 'she's gone lazy' shame a sharing mother; sharing makes her more present, not lesser.","relearn":"A mother who shares isn't lazy or lesser; the comments calling her so are myths, not truths.","persona":"Divya","source":"lesser-mum comments"},
  {"id":"ep2-1315","cat":"everyone-gains","type":"spot","hook":"Spot the two excuses for letting equality slide once the baby arrives.","scene":[{"id":"a","text":"'Defaults snap back now, so hold the line'","trick":false},{"id":"b","text":"'No time for fairness with a newborn'","trick":true},{"id":"c","text":"'Sharing nights keeps us both standing'","trick":false},{"id":"d","text":"'Someone has to be the default carer'","trick":true},{"id":"e","text":"'The kids watch how we split this'","trick":false}],"why":"'No time for fairness' and 'someone must default' are excuses; the newborn stage is when equality matters most.","relearn":"A new baby is the reason to hold the line, not drop it; 'no time' and 'someone must default' are myths.","persona":"any","source":"slide excuses"},
  {"id":"ep2-1316","cat":"everyone-gains","type":"spot","hook":"Spot the two lines that frame a father's care as a favour, not his own job.","scene":[{"id":"a","text":"'These are my kids; caring for them is mine to do'","trick":false},{"id":"b","text":"'I helped her out with the baby today'","trick":true},{"id":"c","text":"'I own bedtime end to end'","trick":false},{"id":"d","text":"'I babysat so she could rest'","trick":true},{"id":"e","text":"'I'd hate to miss this part of their lives'","trick":false}],"why":"'Helped her out' and 'babysat' frame a father's own parenting as a favour to mum; it's his job and his gain, not a favour.","relearn":"A father caring for his child isn't 'helping' or 'babysitting'; the lines that say so miss that it's his own role.","persona":"Vikram","source":"favour lines"},
  {"id":"ep2-1317","cat":"everyone-gains","type":"spot","hook":"Spot the two worries about shared parenting that simply don't hold for the kids.","scene":[{"id":"a","text":"'Two bonded parents help them thrive'","trick":false},{"id":"b","text":"'Dad's care will make our son soft'","trick":true},{"id":"c","text":"'They learn partners can be a team'","trick":false},{"id":"d","text":"'Kids only really need mum early on'","trick":true},{"id":"e","text":"'They get comfort from either of us'","trick":false}],"why":"'Dad's care makes him soft' and 'kids only need mum early' are false; children thrive bonded to both parents from birth.","relearn":"Shared parenting is good for kids; 'it'll make him soft' and 'they only need mum early' are worries that don't hold.","persona":"Priya","source":"kid worries"},
  {"id":"ep2-1318","cat":"everyone-gains","type":"spot","hook":"Spot the two lines that sell equal parenting as a sacrifice instead of a gain.","scene":[{"id":"a","text":"'I gained kids who actually know me'","trick":false},{"id":"b","text":"'I gave up my whole life for this'","trick":true},{"id":"c","text":"'We're both less stretched now'","trick":false},{"id":"d","text":"'It's a price I pay so she's happy'","trick":true},{"id":"e","text":"'Best decision our family ever made'","trick":false}],"why":"'I gave up my whole life' and 'a price I pay for her' frame sharing as sacrifice; it's a gain for the whole family, not a cost.","relearn":"Equal parenting isn't a sacrifice you pay; the 'I gave up everything' and 'a price for her' lines miss the shared gain.","persona":"Vikram","source":"sacrifice lines"},
  {"id":"ep2-1319","cat":"everyone-gains","type":"spot","hook":"Spot the two replies that quietly undermine a co-parent instead of backing them.","scene":[{"id":"a","text":"'You've got this; do it your way'","trick":false},{"id":"b","text":"'You're doing it wrong, let me'","trick":true},{"id":"c","text":"'I trust how you handle bedtime'","trick":false},{"id":"d","text":"'Just leave it, I'll redo it'","trick":true},{"id":"e","text":"'Thanks for owning that, it helps'","trick":false}],"why":"'You're doing it wrong' and 'I'll redo it' undermine a co-parent; backing each other is what makes sharing work.","relearn":"Partners gain when they back, not undermine, each other; 'you're doing it wrong' quietly pushes a co-parent out.","persona":"any","source":"undermine replies"},
  {"id":"ep2-1080","cat":"involved-dads","type":"strike-rewrite","hook":"\"A good dad's main job is to earn; the hands-on stuff is the mother's department.\"","myth":{"un":"A good dad's main job is to earn; the hands-on stuff is the mother's department.","re":"Earning is part of the job, not all of it; your child also needs your hands, time and presence.","why":"A salary can't bathe, feed or comfort a child."},"relearn":"Providing is part of fathering, not the whole of it; kids need your hands-on care and presence too.","persona":"Vikram","source":"provide and present"},
  {"id":"ep2-1081","cat":"involved-dads","type":"strike-rewrite","hook":"\"He gives the baby a bottle sometimes, so he's basically doing half the parenting.\"","myth":{"un":"Doing a few visible tasks sometimes means he's doing half the parenting.","re":"Quality and ownership matter more than the odd task; a present father carries his share day in, day out.","why":"A bottle on Sunday isn't a shared load."},"relearn":"Quality of engagement matters more than the odd task; a present father owns his share daily, not occasionally.","persona":"Vikram","source":"quality over tokens"},
  {"id":"ep2-1082","cat":"involved-dads","type":"strike-rewrite","hook":"\"Men just aren't wired to soothe a crying baby; that's mum's instinct.\"","myth":{"un":"Men aren't wired to soothe a crying baby; that's a mother's instinct.","re":"Soothing is a learned skill, not an instinct; a father who practises becomes just as good at it.","why":"Whoever does the soothing gets practised at it."},"relearn":"Soothing is learned by practice, not a maternal instinct; fathers who do it get just as skilled.","persona":"Vikram","source":"soothing is learned"},
  {"id":"ep2-1083","cat":"involved-dads","type":"strike-rewrite","hook":"\"Taking paternity leave looks like he's not serious about his career.\"","myth":{"un":"Taking paternity leave makes a man look unserious about his career.","re":"Taking the leave you're owed to bond with your newborn is claiming good fatherhood, not slacking.","why":"Being there at the start is a strength, not a lapse."},"relearn":"Using paternity leave to bond is claiming good fatherhood; it's a strength, not a sign of being unserious.","persona":"Vikram","source":"claim the leave"},
  {"id":"ep2-1142","cat":"involved-dads","type":"strike-rewrite","hook":"\"Real fathers stay strict and distant; getting tender confuses the kids.\"","myth":{"un":"Real fathers stay strict and distant; being tender confuses the kids.","re":"Warmth and tenderness build trust and security; a child gains, not loses, from a gentle father.","why":"Tenderness is good fathering, not weakness."},"relearn":"A warm, tender father builds his child's trust and security; distance isn't strength, it's a missed bond.","persona":"Vikram","source":"tender not distant"},
  {"id":"ep2-1084","cat":"involved-dads","type":"strike-rewrite","hook":"\"He works all day, so it's fair he does none of the nights or mornings.\"","myth":{"un":"He earns all day, so it's only fair he does none of the nights or mornings.","re":"Care work is real work too; both parents are tired, and both can own a share of nights and mornings.","why":"One paid job doesn't cancel the unpaid one."},"relearn":"Earning doesn't exempt a father from nights and mornings; care is real work both parents can own.","persona":"Vikram","source":"both are tired"},
  {"id":"ep2-1085","cat":"involved-dads","type":"strike-rewrite","hook":"\"Let the grandparents handle the baby; a father would just get in the way.\"","myth":{"un":"Leave the baby to the grandparents; a father would only get in the way.","re":"Grandparents are a gift, but your child still needs you hands-on; you're a parent, not a spare.","why":"Loving help doesn't replace a present father."},"relearn":"Grandparents help, but a father is still central; their care doesn't replace his own hands-on presence.","persona":"Vikram","source":"not a spare"},
  {"id":"ep2-1086","cat":"involved-dads","type":"strike-rewrite","hook":"\"Changing nappies and wiping noses is below a man; that's not a father's job.\"","myth":{"un":"Nappies and wiping noses are beneath a man; not a father's job.","re":"Nothing about care is beneath a father; the small, messy tasks are exactly how a bond is built.","why":"Bonds grow in the ordinary, messy moments."},"relearn":"No care task is beneath a father; the small, messy jobs are where a real bond with his child is built.","persona":"Vikram","source":"nothing beneath"},
  {"id":"ep2-1087","cat":"involved-dads","type":"strike-rewrite","hook":"\"As long as I show up for the fun bits on Sunday, I'm an involved dad.\"","myth":{"un":"Showing up for the fun bits on Sunday makes me an involved dad.","re":"Involvement is the dull, daily care too, not just the outings; quality of engagement beats mere contact.","why":"Sundays alone don't make a present father."},"relearn":"Real involvement is the daily, unglamorous care, not just weekend fun; engagement matters more than contact.","persona":"Vikram","source":"daily not sunday"},
  {"id":"ep2-1088","cat":"involved-dads","type":"strike-rewrite","hook":"\"A father bonds later; in the first months a baby only really wants its mother.\"","myth":{"un":"A father bonds later; in the first months a baby only really wants its mother.","re":"Infants attach to both parents from birth; the more you hold and soothe early, the deeper the bond.","why":"Attachment starts on day one, for both of you."},"relearn":"Infants attach to both parents from birth; early holding and soothing build a father's bond, not delay it.","persona":"Vikram","source":"bond from birth"},
  {"id":"ep2-1089","cat":"involved-dads","type":"strike-rewrite","hook":"\"If a dad does the cooking and care, the neighbours will say he's under his wife's thumb.\"","myth":{"un":"A dad who cooks and cares will be seen as under his wife's thumb.","re":"Sharing the home is partnership, not being ruled; what others gossip is no measure of a good father.","why":"A strong father isn't scared of a ladle."},"relearn":"Sharing home and care is partnership, not being controlled; neighbours' gossip doesn't define a good father.","persona":"any","source":"not under the thumb"},
  {"id":"ep2-1090","cat":"involved-dads","type":"strike-rewrite","hook":"\"Knowing the kid's shoe size or doctor's name is mum-stuff; dads don't track that.\"","myth":{"un":"Knowing shoe sizes and the doctor's name is mum-stuff; dads don't track that.","re":"Carrying the details of your child's life is part of fathering; either parent can hold that map.","why":"Knowing your child's world isn't gendered."},"relearn":"Tracking a child's details is part of fathering, not just mum-stuff; either parent can carry that map.","persona":"Vikram","source":"dads track too"},
  {"id":"ep2-1091","cat":"involved-dads","type":"strike-rewrite","hook":"\"He's a great dad, he never raises his voice and leaves all the discipline and care to her.\"","myth":{"un":"Being the easy-going parent who leaves all the work to her makes him a great dad.","re":"Being the fun one while she carries everything isn't great fathering; share the hard parts too.","why":"Fun is easy when someone else does the load."},"relearn":"Being only the fun parent while she carries the work isn't great fathering; an involved dad shares the hard parts.","persona":"Vikram","source":"more than the fun one"},
  {"id":"ep2-1092","cat":"involved-dads","type":"strike-rewrite","hook":"\"He helps so much with the kids,\" people say of an involved father.","myth":{"un":"A father who looks after his own kids is 'helping' with them.","re":"He's not helping; he's parenting his own children, the same responsibility as their mother.","why":"You don't 'help' with your own job."},"relearn":"A father caring for his own children is parenting, not helping; it's his responsibility, equal to hers.","persona":"any","source":"not helping"},
  {"id":"ep2-1093","cat":"involved-dads","type":"strike-rewrite","hook":"\"Wanting fathers more involved is just one more way modern life puts men down.\"","myth":{"un":"Asking fathers to be more involved is one more way modern life puts men down.","re":"Inviting fathers into full care lifts them; the bond, confidence and joy of it are a gain for men.","why":"More fatherhood is more for fathers, not less."},"relearn":"Inviting fathers into full care isn't anti-men; the bond, confidence and joy it brings is a gain for them.","persona":"any","source":"a gain for men"},
  {"id":"ep2-1094","cat":"involved-dads","type":"branch","persona":"Vikram","source":"safe arms","hook":"Your toddler falls in the garden while your wife is out.","steps":[{"prompt":"She cries and reaches for the door, calling \"Mama\". What do you do?","options":[{"text":"Pick her up and comfort her until she settles","then":"She sobs into your shirt for a while, then goes quiet.","best":true},{"text":"Call your wife and wait for her to come back","then":"Your wife says she's on her way. The crying goes on for twenty minutes."},{"text":"Distract her with a biscuit and a toy","then":"She stops for a moment, then cries again."},{"text":"Tell her mama is coming and stand by her","then":"She keeps looking at the door."}],"why":"Comforting her yourself shows her you're a safe pair of arms."},{"prompt":"The next evening she scrapes her knee and looks at both of you. What do you do?","options":[{"text":"Kneel, open your arms and clean the knee","then":"She hesitates, then walks into your arms.","best":true},{"text":"Wait to see if she goes to mummy","then":"She goes to mummy, as before."},{"text":"Call out for mummy to bring the plaster","then":"Mummy comes, and holds her while it goes on."},{"text":"Fetch the plaster and let mummy put it on","then":"She holds mummy's hand. You hold the plaster."}],"why":"Being the one who comforts is how she learns to turn to you."},{"prompt":"A week later your mother-in-law says: \"She only wants her mother. It's natural.\" What do you say?","options":[{"text":"Say she'll learn you're safe too, if you keep showing up","then":"Your mother-in-law softens. \"Hm. Perhaps she will.\"","best":true},{"text":"Agree that it's natural","then":"She nods. The idea gets a little stronger."},{"text":"Say you keep trying, but it's hard","then":"She pats your arm. \"Mothers know best.\""},{"text":"Ask her not to say that in front of the child","then":"She goes quiet, offended."}],"why":"Children learn who is safe from who shows up, not from who gave birth."}],"debrief":"Comfort her yourself. Being the parent who soothes is how a child learns to turn to you too.","relearn":"Soothe your child yourself instead of deferring to mum; that's how you become a safe pair of arms."},
  {"id":"ep2-1095","cat":"involved-dads","type":"branch","persona":"Vikram","source":"take the leave","hook":"Your firm offers two weeks of paternity leave, and colleagues hint that serious men skip it.","steps":[{"prompt":"Your manager asks if you'll use the leave. What do you do?","options":[{"text":"Say yes, and give her the dates and a handover plan","then":"She notes the dates, then asks who will cover your client.","best":true},{"text":"Say you may take just a few days","then":"She says that's convenient, and asks no more. You take four days."},{"text":"Say you'll skip it and work a little from home","then":"She smiles, and your inbox stays open on day one."},{"text":"Say you'll skip it to look committed","then":"\"I appreciate that,\" she says. You feel a small pang."}],"why":"Using the leave you're owed shows you take both jobs seriously."},{"prompt":"On day three after the birth, your team chat lights up with an urgent request. What do you do?","options":[{"text":"Say you're unavailable today, and name who to ask","then":"A colleague says \"on it.\" The chat goes quiet.","best":true},{"text":"Fix it quickly, just this once","then":"It takes two hours, and more requests arrive."},{"text":"Ignore it, then feel guilty all day","then":"Your phone buzzes on the sofa while you hold the baby."},{"text":"Hand the baby to your wife while you deal with it","then":"She takes him, and the leave becomes hers again."}],"why":"Naming who covers protects the leave for its purpose."},{"prompt":"In week two your partner asks how you two will share things once you're fully back at work. What do you say?","options":[{"text":"Propose you own mornings and health from now on","then":"She writes it down. \"Good. Let's try it for a month.\"","best":true},{"text":"Say you'll help in the evenings","then":"She asks, \"Which evenings?\" You don't know."},{"text":"Say work will be heavy, so she should plan","then":"She nods. The planning is hers again."},{"text":"Say you'll see once you're back at work","then":"Weeks pass, and nothing has been decided."}],"why":"Owning whole areas before leave ends keeps the early bond going."}],"debrief":"Take the leave. The early weeks come once, and being there builds a bond office optics never will.","relearn":"Use the paternity leave you're owed; the newborn weeks come once and the bond outlasts any office optics."},
  {"id":"ep2-1096","cat":"involved-dads","type":"branch","persona":"Vikram","source":"name it kindly","hook":"At a family lunch, an uncle teases you about 'babysitting' your own kids.","steps":[{"prompt":"He says loudly: \"Look, our babysitter, while madam relaxes!\" What do you do?","options":[{"text":"Gently say it's parenting, not babysitting","then":"He blinks. \"Parenting? Okay, okay.\" A cousin smiles.","best":true},{"text":"Laugh along to keep the peace","then":"The table laughs. Your daughter wonders what's funny."},{"text":"Say she deserves a rest, so you're helping today","then":"He nods. \"Good husband.\" It sounds like a favour."},{"text":"Snap that he's never changed a nappy himself","then":"The table goes quiet. Your aunt tuts."}],"why":"Naming it kindly resets the family's word for your care."},{"prompt":"Later your teenage niece whispers that she doesn't get why uncle says that. What do you say?","options":[{"text":"Say care is a parent's job, not only a mother's","then":"She nods. \"I'd like a partner like that someday.\"","best":true},{"text":"Say uncle is old-fashioned and she should ignore him","then":"She shrugs. She's still unsure why."},{"text":"Say it's just his sense of humour","then":"She smiles. Jokes like that stay on the table."},{"text":"Say you'll speak to him later","then":"She waits. The talk never happens."}],"why":"A plain answer tells the young ones what care really is."},{"prompt":"At the next lunch he starts the same joke again. What do you do?","options":[{"text":"Smile and say it's parenting, and you love it","then":"He laughs, waves it off, and drops the joke.","best":true},{"text":"Ignore it, since jokes like this fade on their own","then":"The joke comes back every time."},{"text":"Leave the table","then":"Your wife looks at you across the room."},{"text":"Ask your wife to handle him","then":"She sighs and does. It's her job again."}],"why":"Saying it again, kindly, makes the new word stick."}],"debrief":"Name it kindly. A father minding his own children is parenting, not babysitting, and worth saying out loud.","relearn":"Gently correct 'babysitting'; minding your own kids is parenting, and naming it resets the family frame."},
  {"id":"ep2-1097","cat":"involved-dads","type":"branch","persona":"Vikram","source":"own the routine","hook":"You've never done the school run alone, and the bags, snacks and timings feel unfamiliar.","steps":[{"prompt":"Your wife has an early meeting on Monday, so the school run is yours. What do you do?","options":[{"text":"Learn the timetable and pack the bags on Sunday","then":"You find the timetable and pack the bags. You only forget the water bottle.","best":true},{"text":"Ask your wife to write a list for the morning","then":"She writes a list at 11 p.m., before her early meeting."},{"text":"Ask your wife to pack the bags the night before","then":"She packs them. You just carry."},{"text":"Ask your mother to do the run with you","then":"Your mother knows the routine. You follow her."}],"why":"Learning it yourself is what makes the routine yours."},{"prompt":"Midweek, the school sends a note about a dress-up day. What do you do?","options":[{"text":"Read it, note it and sort the costume","then":"The costume is rough, and your daughter loves it.","best":true},{"text":"Show it to your wife and ask what to do","then":"She sorts it that evening. It's her job again."},{"text":"Skip it, since it's only dress-up","then":"Your daughter is the only one in uniform."},{"text":"Ask another parent what to send","then":"The parent replies, and you send a similar costume. You never read the note."}],"why":"Owning the notices is part of owning the routine."},{"prompt":"Two weeks on, your wife offers to take the run back for a day. What do you say?","options":[{"text":"Say you've got it, and offer her an easy morning","then":"She grins. \"Then I'll sleep in.\"","best":true},{"text":"Give it back to her for good, since it's tiring","then":"She takes it back. By Friday, the run is hers every day."},{"text":"Say yes, and ask her to keep the list ready","then":"She keeps a list on the fridge. She updates it, and you follow it."},{"text":"Say you'll keep it but call her when in doubt","then":"She gets a call at 8:05 most mornings."}],"why":"Keeping the whole routine means she can truly step away."},{"prompt":"Your daughter starts an after-school class that needs pick-ups. What do you do?","options":[{"text":"Take the pick-up days and diarise them","then":"You show up twice a week. The teacher learns your name.","best":true},{"text":"Ask your wife which days suit her","then":"She picks the days. The planning is hers again."},{"text":"Ask the class to call your wife about changes","then":"The calls go to her phone."},{"text":"Say you'll pick up whenever you're free","then":"You're free on two days out of eight."}],"why":"Owning fixed days turns a favour into a routine."}],"debrief":"Take the school run on fully and learn it. Owning the routine beats being handed a list each morning.","relearn":"Own the school run and learn its details yourself; a daily list keeps you the helper, not an equal parent."},
  {"id":"ep2-1098","cat":"involved-dads","type":"branch","persona":"Vikram","source":"ask for room","hook":"Your partner keeps redoing how you dress and feed the baby, so you've begun stepping back.","steps":[{"prompt":"She re-buttons the baby's suit right after you finish. What do you do?","options":[{"text":"Say kindly you'd like room to do it your way","then":"She stops, a little startled. \"Oh. Did I do that a lot?\"","best":true},{"text":"Say nothing and step back from the whole thing","then":"She takes over, and you leave the room."},{"text":"Say she clearly doesn't trust you with him","then":"Her face tightens. \"That's not fair.\""},{"text":"Ask her to show you the right way again","then":"She shows you. It's still her way."}],"why":"Naming it kindly keeps you in the care."},{"prompt":"That evening she says: \"I know I redo things. I just worry he'll be uncomfortable.\" What do you say?","options":[{"text":"Say you understand, and ask her to let you learn","then":"She sighs. \"I'll try. It's hard for me to watch.\"","best":true},{"text":"Say fine and let her keep doing it","then":"She nods. The baby is hers again."},{"text":"Say she's being controlling about it","then":"Her eyes flash. \"Controlling? I'm being careful.\""},{"text":"Say you'll do it when she's out of the room","then":"She wonders what happens when she's out."}],"why":"Asking for room while understanding her worry keeps trust."},{"prompt":"A week later she hovers again while you feed him. What do you do?","options":[{"text":"Gently ask for room, and offer her a tea break","then":"She nods and steps out. You hear her exhale.","best":true},{"text":"Give up and hand him over to her right away","then":"She takes him. It's how it was before."},{"text":"Snap that she's doing it again, in front of him","then":"She goes red. The bottle is cold by the time he feeds."},{"text":"Let her hover and stay silent","then":"She hovers. You feel watched the whole time."}],"why":"A gentle ask, with a break for her, keeps you both learning."}],"debrief":"Name the gatekeeping kindly and ask for room to learn. Stepping back parks you as a backup parent.","relearn":"Address gatekeeping and ask for room to learn, rather than retreating and handing the load back."},
  {"id":"ep2-1099","cat":"involved-dads","type":"branch","persona":"Vikram","source":"protect bedtime","hook":"A late-night work group chat keeps you online while your child's bedtime happens without you.","steps":[{"prompt":"It's 8 p.m. and the chat is busy. Your child is calling for you. What do you do?","options":[{"text":"Put the phone away and do bedtime, then check messages","then":"Story, teeth, lights. Twelve messages wait, and none are urgent.","best":true},{"text":"Reply to two more messages first, then go and see her","then":"Twenty minutes pass. Your child is already asleep with her mother."},{"text":"Send your child to your wife for the story","then":"Your wife takes over and says nothing."},{"text":"Take the phone into the room and keep replying","then":"She notices the glow on the wall and asks you to put it away."}],"why":"Doing bedtime first keeps the ritual, and work can wait a bit."},{"prompt":"The group's admin says everyone should be reachable until 10 p.m. What do you do?","options":[{"text":"Tell the group you're offline 7 to 8:30 each evening","then":"Two colleagues say \"same here.\" One says nothing.","best":true},{"text":"Say nothing and stay online all evening, as before","then":"Your phone buzzes through dinner."},{"text":"Mute the group and check later, secretly","then":"You miss one message and hear about it the next day."},{"text":"Leave the group entirely","then":"You miss a real deadline. Your manager frowns."}],"why":"Naming a protected window keeps you reachable and present."},{"prompt":"One night an urgent message arrives during bedtime. What do you do?","options":[{"text":"Check if it can wait, then finish the story first","then":"It can wait. You finish the story, and your child holds your hand.","best":true},{"text":"Drop the story and start working on it right away","then":"Your child watches you leave the room."},{"text":"Ask your wife to finish the story","then":"She finishes it. Your child asks where you went."},{"text":"Tell your child you need five minutes","then":"Five minutes turns into thirty."}],"why":"Checking first protects the ritual and still respects real urgency."},{"prompt":"You're travelling for work, and your child asks if you'll call at bedtime. What do you say?","options":[{"text":"Say yes, and read her a story over the phone","then":"She giggles at the phone on the pillow. You don't miss the ritual.","best":true},{"text":"Say you'll call when you can","then":"You call at nine. She's asleep."},{"text":"Say mummy will do the story tonight","then":"She nods. The ritual passes to mummy."},{"text":"Say you'll send a voice note in the morning","then":"She listens on the bus. Bedtime is still empty."}],"why":"Keeping the ritual by phone shows the bond travels with you."}],"debrief":"Protect bedtime most nights. A daily ritual builds a bond that always-on work quietly erodes.","relearn":"Guard bedtime as protected time; letting work win each evening makes you a stranger to it."},
  {"id":"ep2-1100","cat":"involved-dads","type":"branch","persona":"Vikram","source":"he watches you","hook":"Your son says he wants to be just like papa, and you realise he never sees you do any care.","steps":[{"prompt":"Your son says it again at dinner. What do you do?","options":[{"text":"Start doing bath and dinner where he can see you","then":"He watches, then asks to hold the towel.","best":true},{"text":"Tell him what a good dad does","then":"He listens, nods, and goes back to his toys."},{"text":"Do the care after he's asleep, so it stays private","then":"He still doesn't see it. Nothing changes."},{"text":"Say you'll do more once he's older","then":"He shrugs. \"Okay, Papa.\""}],"why":"Care he can see becomes what he learns fathers do."},{"prompt":"You're cooking on Saturday when a neighbour's son says his own papa never cooks. What do you do?","options":[{"text":"Say cooking is for everyone, and keep stirring","then":"The boys look at each other. Your son grabs a spoon to help.","best":true},{"text":"Laugh and say it's just a hobby you happen to enjoy","then":"The boys nod. Cooking is a hobby, not a job."},{"text":"Send the boys outside to play","then":"They run out. The moment passes."},{"text":"Say your wife is busy today","then":"Your son hears that cooking is what dads do when mums can't."}],"why":"Saying it plainly, while doing it, tells the boys care has no gender."},{"prompt":"Your son asks if he can help wash the dishes like you. What do you do?","options":[{"text":"Say yes, and show him how, side by side","then":"He rolls up his sleeves, soaks his shirt, and beams.","best":true},{"text":"Say he's too small, maybe later","then":"He nods. It's easier to stay small."},{"text":"Give him a job and leave to do something else","then":"He does the job. No one shows him how."},{"text":"Say thanks, but let him play","then":"He plays. The dishes stay yours."}],"why":"Working side by side teaches him care is his work too."}],"debrief":"Let your son see you do care. What he watches at home becomes his idea of what fathers do.","relearn":"Do care visibly so your son sees it as a man's work too; what he watches becomes his normal."},
  {"id":"ep2-1101","cat":"involved-dads","type":"branch","persona":"Vikram","source":"own a domain","hook":"Your partner is going back to work after time at home with the kids.","steps":[{"prompt":"In her first week back, she says she assumes you'll help when you can. What do you do?","options":[{"text":"Say you'd rather own whole areas, and suggest which","then":"She looks surprised, then relieved. \"Really? Start to finish?\"","best":true},{"text":"Say you'll gladly help whenever you can manage it","then":"She smiles. \"When you can\" leaves gaps that she covers."},{"text":"Say you'll help, and she can just message you anytime","then":"She messages and you reply, and she's the manager again."},{"text":"Say you're busy too, so it can't be every single day","then":"She nods, stiffly. The gaps will be hers."}],"why":"Offering whole areas turns helping into owning."},{"prompt":"A week later the school calls: your daughter has a fever and you both have meetings. What do you do?","options":[{"text":"Say you'll go, and handle the doctor too","then":"She is grateful. You note the medicine dose yourself.","best":true},{"text":"Ask her to go, since her office is closer","then":"She goes. Her meeting gets moved, again."},{"text":"Say you'll go, but ask which pharmacy she uses","then":"She types a long answer in the middle of her meeting."},{"text":"Offer to go once your own meeting ends","then":"That's two hours after the call. She goes anyway."}],"why":"Taking the whole task, doctor included, is ownership."},{"prompt":"Three weeks in, she asks whether the new arrangement feels fair. What do you say?","options":[{"text":"Name what's uneven, and suggest a monthly check-in","then":"She agrees. \"First Sunday of the month.\"","best":true},{"text":"Say it's fine, and that you'll keep helping","then":"She smiles. The old default lingers."},{"text":"Say she should tell you if anything drops","then":"She notes that she's still the one watching."},{"text":"Say you're tired too, so leave it as it is","then":"She nods, and the conversation ends there."}],"why":"A regular check-in keeps the sharing fair over time."}],"debrief":"Own whole domains rather than 'helping when you can'. Ownership is what makes you a real co-parent.","relearn":"Take ownership of whole domains instead of helping ad hoc; helping leaves her managing all the rest."},
  {"id":"ep2-1102","cat":"involved-dads","type":"branch","persona":"Vikram","source":"answer yourself","hook":"At the baby's clinic visit, the nurse directs every question to your wife, not you.","steps":[{"prompt":"The nurse asks your wife how the baby has been sleeping. What do you do?","options":[{"text":"Step in and say what you know of his sleep","then":"The nurse turns to you and notes what you say.","best":true},{"text":"Let your wife answer, as usual, and stay quiet","then":"She answers. The nurse writes nothing about you."},{"text":"Nudge your wife to answer, in case you get it wrong","then":"She fills in the details. The nurse nods to her."},{"text":"Say you'll check with her and answer later","then":"The nurse smiles. \"Fine, then.\""}],"why":"Answering shows you know your child, so the nurse asks you too."},{"prompt":"The nurse says the baby's jabs are due next month. What do you do?","options":[{"text":"Ask for the date and note it in your phone","then":"The nurse gives you the schedule card, and you photograph it.","best":true},{"text":"Trust your wife to remember it, as she always does","then":"She nods, and adds it to her mental list."},{"text":"Ask the nurse to message your wife about the date","then":"The nurse types her number. The reminders go to her."},{"text":"Say you'll ask your wife about it tonight","then":"Your wife tells you the date, and asks you to remember."}],"why":"Noting the date yourself takes the tracking off her."},{"prompt":"On the way home, your wife says clinics always seem to talk only to her. What do you say?","options":[{"text":"Say you noticed too, and you'll speak up next time","then":"She smiles. \"It's tiring being the only one they see.\"","best":true},{"text":"Say it's just how clinics are, and not worth minding","then":"She shrugs. It stays as it is."},{"text":"Say you'd rather she handles the clinic visits, anyway","then":"She sighs. It's hers again."},{"text":"Say she should tell the nurse to include you next time","then":"She agrees, and has one more task."}],"why":"Speaking up yourself shows you're an equal, informed parent."},{"prompt":"The baby's next clinic visit falls when your wife is away. What do you do?","options":[{"text":"Book it, take the card, and ask the questions","then":"The nurse talks to you. You write down what she says.","best":true},{"text":"Reschedule until your wife is back","then":"The visit slips a fortnight. She hears about it."},{"text":"Ask her mother to take him","then":"Her mother goes. Nobody tells you what was said."},{"text":"Go, but call your wife with every question","then":"She answers during her trip. It's still her job."}],"why":"Handling the visit yourself makes you the informed parent."}],"debrief":"Answer the clinic's questions yourself. Knowing your child's details marks you as an equal, informed parent.","relearn":"Step in and answer questions about your child; deferring every time keeps you the parent who doesn't know."},
  {"id":"ep2-1103","cat":"involved-dads","type":"branch","persona":"Vikram","source":"share the hard weeks","hook":"Friends invite you on a long weekend away, when your partner would be alone with the newborn.","steps":[{"prompt":"The trip is booked for two weeks from now. What do you do?","options":[{"text":"Shorten it to one night, so you share the early weeks","then":"Your friends groan. You agree to join them for one night only.","best":true},{"text":"Go for the full trip, since she has her mother","then":"You tell her the plan. She calls her mother, and goes quiet."},{"text":"Ask her if she minds, and go if she says okay","then":"She says okay, and starts planning the weekend alone."},{"text":"Go, and phone her every evening from the road","then":"You promise daily calls. She nods, and looks at the baby."}],"why":"Being there for the hardest weeks shares them."},{"prompt":"Days before the trip, your partner says: \"Go. I'll manage.\" What do you do?","options":[{"text":"Ask what she needs, and plan around it","then":"She thinks. \"Some sleep. And you here at night.\"","best":true},{"text":"Go, and promise to make it up with nights later","then":"She agrees. The promise doesn't help at 3 a.m."},{"text":"Say you'll go, and ask her mother to stay","then":"Her mother stays. The nights are still hers alone."},{"text":"Stay, but grumble about missing the trip","then":"She hears it. The whole weekend feels heavy."}],"why":"Asking what she needs beats asking whether she minds."},{"prompt":"A few months later your friends plan another weekend away. What do you say?","options":[{"text":"Say yes, once she has a weekend too","then":"Your friends laugh. You mark both weekends on the calendar.","best":true},{"text":"Say no, to be on the safe side","then":"Your friends stop asking, and no one gets a break."},{"text":"Say yes, and settle the rest later","then":"You settle it the night before, and not well."},{"text":"Say you'll see how the baby is nearer the time","then":"The weekend comes and goes without a decision."}],"why":"Time away can happen when both parents get a fair turn."}],"debrief":"Share the newborn weeks rather than opting out. Being present when it's hardest is real fathering.","relearn":"Stay and share the hard newborn weeks; opting out leaves the whole early load on her."},
  {"id":"ep2-1104","cat":"involved-dads","type":"branch","persona":"Vikram","source":"own health","hook":"You realise you've never taken your child to the doctor or known which jabs are due.","steps":[{"prompt":"The next check-up is coming up. What do you do?","options":[{"text":"Tell your wife you're taking health on","then":"She hands you the card, a little stunned. \"All of it?\" \"All of it.\"","best":true},{"text":"Ask your wife to tell you when the check-up is","then":"She tells you. She's still the tracker."},{"text":"Go along, but let her do all the talking there","then":"The doctor speaks to her. You sit by the door."},{"text":"Leave it to her, since she just knows that stuff","then":"She books it, as always. You go along, only to drive."}],"why":"Taking health end to end moves the tracking to you."},{"prompt":"At the check-up, the doctor asks about allergies and past illnesses. What do you do?","options":[{"text":"Answer what you can, and ask about the next jab","then":"The doctor writes it down and nods.","best":true},{"text":"Look at your wife to answer, as you normally would","then":"She answers. You watch."},{"text":"Say you'll check at home and call back later","then":"The doctor waits, then moves on."},{"text":"Say you're not sure, since mothers know these things","then":"The doctor smiles. The habit gets stronger."}],"why":"Knowing the details is practice you can build."},{"prompt":"A jab is due next Tuesday, and your wife has a big deadline. What do you do?","options":[{"text":"Book the slot, block the time, and take her yourself","then":"You handle it. She only hears about it afterwards.","best":true},{"text":"Remind her about it, in case she forgets it again","then":"She says \"I know,\" and it goes on her list too."},{"text":"Ask a relative to take the child instead","then":"An aunty takes her. Nobody has the details."},{"text":"Ask her which day is best for her","then":"She picks a day, and has to plan it as well."}],"why":"Owning the booking and the visit is what sharing the load means."},{"prompt":"Your daughter runs a fever at 2 a.m. What do you do?","options":[{"text":"Take her temperature, settle her, and call if it's high","then":"You have the doctor's number ready. Your wife sleeps on.","best":true},{"text":"Wake your wife to decide what to do","then":"She gets up, checks, and decides. You hold the torch."},{"text":"Ask your mother by phone what to give her at this hour","then":"Your mother gives advice from memory. You still have no plan."},{"text":"Search online, and hope it's nothing","then":"You scroll worst cases until dawn, more scared than before."}],"why":"Knowing what to do at 2 a.m. is what owning health looks like."}],"debrief":"Own a domain like health end to end. 'She just knows' is practice you can build, not a fixed truth.","relearn":"Take a whole domain such as health; she 'just knows' from practice you can build, not from instinct."},
  {"id":"ep2-1105","cat":"involved-dads","type":"role-play","persona":"Vikram","source":"not helping line","hook":"At a family function, you've spent the afternoon looking after the kids.","setup":"At the tea table, Aunty smiles at your wife, then at you.","steps":[{"prompt":"Aunty says: \"You're so lucky, beta. She lets you help so much.\"","options":[{"text":"\"They're my kids too, Aunty. It's not helping. It's being their dad.\"","then":"Aunty blinks. Your wife's shoulders drop.","best":true},{"text":"\"Ha, yes. She's kind to let me pitch in sometimes.\"","then":"Aunty nods happily. Your wife's smile slips."},{"text":"\"It's nothing, Aunty. I'm just doing my bit.\"","then":"Aunty pats your arm. \"Very good, beta.\""},{"text":"\"Aunty, please. That's a rude thing to say.\"","then":"Aunty looks stung. The tea goes cold."}],"why":"Saying they're your kids too resets care as your own job."},{"prompt":"Aunty says: \"But mothers do it better. It's in their nature.\"","options":[{"text":"\"It's practice, Aunty. I'm learning by doing it.\"","then":"Aunty raises her brows. \"Hm. Perhaps.\"","best":true},{"text":"\"You may be right, Aunty. She's a natural, of course.\"","then":"Aunty smiles. Your wife studies her cup."},{"text":"\"Nature has nothing to do with it, Aunty.\"","then":"Aunty frowns. \"You young ones know everything.\""},{"text":"\"Let's not argue, Aunty. Have another biscuit.\"","then":"She takes the biscuit. The idea stays on the table."}],"why":"Care is learned by doing it, and not inherited."},{"prompt":"Later your wife says quietly: \"I felt awkward when she said that.\"","options":[{"text":"\"So did I. Next time, let's answer her together.\"","then":"She smiles. \"I'd like that.\"","best":true},{"text":"\"Aunty didn't mean it. Don't take it to heart.\"","then":"She nods, and swallows it."},{"text":"\"Well, you did let me help, didn't you?\"","then":"She stares. \"Let you?\""},{"text":"\"Ignore it. She's like that with everyone she meets.\"","then":"She shrugs, but it stays with her."}],"why":"Answering together keeps the two of you on the same side."}],"relearn":"Saying 'it's not helping. It's being their dad' resets care as your own job, not a favour to your wife."},
  {"id":"ep2-1106","cat":"involved-dads","type":"role-play","persona":"Vikram","source":"claim the meeting","hook":"Your child's parent-teacher meeting is on Thursday afternoon.","setup":"Your boss stops by your desk with the meeting roster.","steps":[{"prompt":"He says: \"Thursday's review is at four. Your wife handles school things, so you're free.\"","options":[{"text":"\"I'll take that hour. I go to my child's meetings.\"","then":"He pauses. \"Fine. Send me your points before you go.\"","best":true},{"text":"\"You're right. My wife will go. No need for me there.\"","then":"He nods, satisfied. Your wife adjusts her Thursday."},{"text":"\"I'll try to make both. Let's see how it goes.\"","then":"He says, \"Fine.\" You'll likely miss one of them."},{"text":"\"That's a very old-fashioned assumption, if I may say.\"","then":"He bristles. \"I'm only planning.\""}],"why":"Claiming the hour calmly shows fathering is part of your life."},{"prompt":"A colleague says quietly: \"Men who put school things first get passed over here.\"","options":[{"text":"\"Maybe. But I want to be there. I'd hate to miss these years.\"","then":"He nods slowly. \"Fair enough. I never go to mine.\"","best":true},{"text":"\"You're right. I'll cut back on school things.\"","then":"He nods. You feel uneasy."},{"text":"\"My wife covers most school things anyway, so it's fine.\"","then":"He nods. \"Lucky you.\""},{"text":"\"I'll make up the hours on weekends. Don't worry.\"","then":"He nods. You lose Saturday too."}],"why":"Being honest about the pressure, and still choosing your child, holds the line."},{"prompt":"When you collect your child one afternoon, the teacher hands you a form: \"Please give this to the mother.\"","options":[{"text":"\"I'm his parent too. Please note my number as well.\"","then":"The teacher smiles, a bit embarrassed. \"Of course. I'll add it.\"","best":true},{"text":"\"Of course. I'll fill it in tonight and hand it back.\"","then":"The teacher thanks you. Next month's notice goes to her number again."},{"text":"\"Why does everything always go to the mothers here?\"","then":"The teacher stammers. \"It's just habit, sir.\""},{"text":"\"Sure. My wife handles the school forms anyway.\"","then":"The teacher writes down her number only."}],"why":"Giving your number changes how the school reaches you."}],"relearn":"Claiming the hour for your child's meeting shows fathering is part of your life, not the mother's job alone."},
  {"id":"ep2-1107","cat":"involved-dads","type":"role-play","persona":"Vikram","source":"not soft","hook":"Your father is staying for the weekend, and evenings are your time with the baby.","setup":"He watches from the sofa as you rock her to sleep.","steps":[{"prompt":"Your father says: \"You'll make yourself soft, holding the baby all evening.\"","options":[{"text":"\"Holding her isn't soft, Papa. It's the best part of my day.\"","then":"He grunts. \"Hm.\" He doesn't look away from the baby.","best":true},{"text":"\"Maybe you're right. I should leave the cuddling to her.\"","then":"He nods. Your wife, across the room, watches quietly."},{"text":"\"You didn't hold me much, and I turned out fine.\"","then":"His face darkens. \"I did my duty.\""},{"text":"\"Fair enough, Papa. I'll put her down now.\"","then":"He smiles, satisfied. She wakes as soon as you set her down."}],"why":"Claiming tenderness as good fathering holds your ground kindly."},{"prompt":"He says: \"A man must be firm. Children need firmness, not cuddles.\"","options":[{"text":"\"They need both, Papa. She feels safe with me.\"","then":"He watches her yawn on your shoulder. \"Hm. Perhaps.\"","best":true},{"text":"\"I'll be firm with her, Papa. Don't you worry.\"","then":"He grunts, satisfied. The baby giggles anyway."},{"text":"\"That's the old way of thinking, Papa.\"","then":"He frowns. \"The old ways raised you.\""},{"text":"\"Let's talk later, Papa. She's nearly asleep now.\"","then":"He waves a hand. The point stays open."}],"why":"Safe attachment to a father is good for a child's growth."},{"prompt":"Papa asks quietly: \"Did I miss something, not holding you more?\"","options":[{"text":"\"Maybe a little, Papa. I'm glad I get to hold her.\"","then":"He is silent. Then he reaches out and touches her hand.","best":true},{"text":"\"Yes. I wish you had, Papa.\"","then":"He goes quiet, and leaves the room."},{"text":"\"No, Papa. It's fine, really. Don't think about it.\"","then":"He nods, but doesn't look at you."},{"text":"\"You worked hard, Papa. That's what mattered most.\"","then":"He nods slowly, and the moment closes."}],"why":"Honest, gentle words open a door between generations."}],"relearn":"Saying holding your child isn't 'soft' but the best part of your day claims tenderness as good fathering."},
  {"id":"ep2-1108","cat":"involved-dads","type":"role-play","persona":"Vikram","source":"i'll own those","hook":"Your partner is worn out by the baby's endless jobs, and you want to own a part.","setup":"She counts the tasks off on her fingers.","steps":[{"prompt":"She says: \"Feeds, laundry, doctor visits, night wakings, shopping. I can't do it all.\"","options":[{"text":"\"Night wakings and doctor visits are mine. All of it.\"","then":"She looks up, a bit stunned. \"All of it? Really?\"","best":true},{"text":"\"Just tell me what to do, and I'll do it when you ask.\"","then":"She sighs. \"Then I still have to remember it all.\""},{"text":"\"I'll do whatever is left over at the end of each day.\"","then":"She nods. \"But I still decide what's left.\""},{"text":"\"Which one is the easiest? I'll start there, then.\"","then":"She hands you the laundry. The rest stays hers."}],"why":"Taking whole jobs, and not scraps, lifts the noticing off her."},{"prompt":"She asks: \"What about nights when one of us is just too tired?\"","options":[{"text":"\"Night wakings are mine. On a bad night, we swap.\"","then":"She almost laughs. \"So it isn't all or nothing.\"","best":true},{"text":"\"Then you'll do it. You're used to it by now.\"","then":"She looks at you. \"Used to it. Yes.\""},{"text":"\"I won't be too tired. Don't worry about that.\"","then":"She doesn't quite believe you."},{"text":"\"I'll try my best to manage it somehow.\"","then":"She says, \"Okay,\" and doesn't sleep well."}],"why":"Flexing for each other, and owning it, keeps the split fair."},{"prompt":"A month later she asks: \"Is the baby's doctor visit this week sorted?\"","options":[{"text":"\"Booked it Monday, and I'm taking him. You needn't track it.\"","then":"She lets out a breath. \"You held it. I didn't have to think.\"","best":true},{"text":"\"Not yet. It's easier if you book it.\"","then":"She books it. The visit stays hers."},{"text":"\"Not yet. Remind me next week, and I'll do it then.\"","then":"She reminds you. Then she reminds you again."},{"text":"\"Not yet. Can you book it this once? Work is mad.\"","then":"She sighs and does it, tired."}],"why":"Holding the noticing as well as the booking makes it truly yours."}],"relearn":"Offering to own night wakings and doctor visits fully makes you a co-parent, not a helper waiting for tasks."},
  {"id":"ep2-1109","cat":"involved-dads","type":"role-play","persona":"Vikram","source":"priority not weakness","hook":"You leave work on time most days so you can do your kids' bath time.","setup":"It's half past five, and a colleague watches you pack your bag.","steps":[{"prompt":"He says with a grin: \"Bath time again? You've gone soft on us, yaar.\"","options":[{"text":"\"I leave on time to be a dad. That's a priority.\"","then":"He blinks. \"Huh. Never thought of it like that.\"","best":true},{"text":"\"Yeah, I know. I really should stay later like the rest of you.\"","then":"He nods. \"Exactly. Stay later.\""},{"text":"\"You'd do the same if you had kids, wouldn't you?\"","then":"He shrugs. \"I have kids. My wife handles it.\""},{"text":"\"Ha, my wife insists on it. What can I do?\"","then":"He laughs. \"Poor you.\""}],"why":"Naming it as a priority you own settles the jokes."},{"prompt":"He adds: \"Just so you know, the boss notices who stays late.\"","options":[{"text":"\"I get my work done, and I stay late when needed.\"","then":"He shrugs. \"Well, it works for you, I guess.\"","best":true},{"text":"\"Then I'll stay late twice a week to be safe.\"","then":"He nods. Two bath times go missing."},{"text":"\"The boss should notice results, not hours.\"","then":"He rolls his eyes. \"Try telling him that.\""},{"text":"\"I'll worry about that when it happens.\"","then":"He shrugs. He doesn't look convinced."}],"why":"Delivering well while keeping the boundary makes it credible."},{"prompt":"A younger colleague asks quietly: \"Does leaving on time hurt at appraisal time?\"","options":[{"text":"\"It hasn't so far. I'm clear about what I deliver.\"","then":"He nods, thinking. \"I might try it too.\"","best":true},{"text":"\"Yes, a bit. Don't do what I do.\"","then":"He nods. Now he thinks it's a risk."},{"text":"\"Only if you're not good at your job.\"","then":"He nods, less sure of himself."},{"text":"\"Ask HR. That's what they're there for.\"","then":"He nods. He never asks."}],"why":"Sharing how it works makes it easier for other fathers."}],"relearn":"Saying you leave on time to be a dad frames present fatherhood as a priority you own, not a weakness."},
  {"id":"ep2-1110","cat":"involved-dads","type":"role-play","persona":"Vikram","source":"my own way","hook":"Your wife hovers and corrects how you swaddle the baby.","setup":"The baby is fussy, and she's standing at your shoulder.","steps":[{"prompt":"She says: \"No, not like that. Tuck the arms in tighter.\"","options":[{"text":"\"Let me find my way with him. Give me a little space.\"","then":"She hesitates, then steps back a pace. \"Okay. I'll try.\"","best":true},{"text":"\"Fine. You do it. Clearly I can't get anything right.\"","then":"She takes him. Her face is torn between guilt and relief."},{"text":"\"Why do you always have to do this to me?\"","then":"She stiffens. \"I'm only trying to help.\""},{"text":"\"Okay, show me again, then. Slowly this time.\"","then":"She shows you. You feel more like an assistant than a parent."}],"why":"Asking for room, calmly, lets you build real confidence."},{"prompt":"She says: \"I just don't want him uncomfortable. He's so tiny.\"","options":[{"text":"\"I get it. Watch for a minute, then let me try.\"","then":"She watches. He settles, and she lets out a breath.","best":true},{"text":"\"You worry too much. He's completely fine, really.\"","then":"She frowns. \"You don't know that.\""},{"text":"\"Then take over. I'll get out of your way.\"","then":"She swaddles him. You leave the room."},{"text":"\"Fine, you're the expert. I'll follow your lead.\"","then":"She nods. She's the manager, again."}],"why":"Hearing her worry and asking for a trial builds trust for both."},{"prompt":"Next morning she reaches for the fussy baby and says: \"Here, let me.\"","options":[{"text":"\"I've got him. Go and have your tea while it's hot.\"","then":"She hesitates, then goes. You hear the kettle click.","best":true},{"text":"\"Okay, take him. You're better at this.\"","then":"She takes him. You're the backup again."},{"text":"\"Stop hovering, please. It's really getting to me.\"","then":"She steps back, hurt."},{"text":"\"Tell me if I'm doing it wrong.\"","then":"She corrects three things in a minute."}],"why":"Holding your ground gently, and giving her a break, keeps the peace."}],"relearn":"Asking for space to find your own way addresses gatekeeping so you can build real confidence as a parent."},
  {"id":"ep2-1111","cat":"involved-dads","type":"role-play","persona":"Vikram","source":"stay with him","hook":"At a wedding, the men gather away from the babies.","setup":"Your child is fussing in your arms as the men call you over.","steps":[{"prompt":"A cousin calls: \"Come, leave him with the women. We're all over here.\"","options":[{"text":"\"I'll stay with him. Settling him is my job too.\"","then":"He shrugs. The baby's cries turn to hiccups in your arms.","best":true},{"text":"\"I'll hand him to an aunty and catch you all later.\"","then":"You hand him to an aunty. He cries until you take him back."},{"text":"\"Five minutes, then I'll come and join you all.\"","then":"Five minutes pass. He's still fussing, so you stay with him after all."},{"text":"\"He's fine. Let him cry a bit. He'll settle.\"","then":"He doesn't settle. You end up holding him anyway, as the aunties frown."}],"why":"Staying with him tells him and the men that care is a father's job."},{"prompt":"An aunty says: \"Give him to me, beta. This isn't a man's job.\"","options":[{"text":"\"Thanks, Aunty. Let me try first. I'll ask if I need you.\"","then":"She nods, surprised. Ten minutes later he's asleep on your shoulder.","best":true},{"text":"\"Yes, please. You're so much better at this than me.\"","then":"She takes him. You stand aside with empty arms and watch."},{"text":"\"No, Aunty. It's fine, really, thank you.\"","then":"She sniffs, and keeps watching from her chair."},{"text":"\"Only for a minute, Aunty. Then give him back.\"","then":"A minute becomes an hour. She keeps him and you hover close by."}],"why":"Trying first, politely, lets you learn him and keeps the elders on side."},{"prompt":"On the drive home, your wife asks: \"The men kept calling you over. Do you wish you'd gone?\"","options":[{"text":"\"No. Time with him matters more to me than that.\"","then":"She smiles, and takes your hand.","best":true},{"text":"\"Honestly, yes. But it was worth the sacrifice.\"","then":"She frowns. \"So it's a sacrifice.\""},{"text":"\"They made me feel like an outsider over there, to be honest.\"","then":"She nods. \"They'll get used to it.\" You both go quiet."},{"text":"\"Yes. Next time I'll join them and leave him with you.\"","then":"She smiles thinly, and the baby is hers again."}],"why":"Seeing care as a gain, and never a sacrifice, keeps you close to your child."}],"relearn":"Staying to settle your child instead of handing him off shows care is a father's job in any room."},
  {"id":"ep2-1112","cat":"involved-dads","type":"role-play","persona":"Vikram","source":"teach me","hook":"Your teenage daughter has started noticing what her friends' fathers do at home.","setup":"She's tying her hair for school and looks at you in the mirror.","steps":[{"prompt":"She says: \"Other dads plait their daughters' hair now. Why don't you?\"","options":[{"text":"\"You're right. Teach me. I want to be that dad.\"","then":"She smiles, surprised. \"Really? Sit down, then.\"","best":true},{"text":"\"That's really more your mother's thing, beta.\"","then":"She shrugs, and picks up the comb herself."},{"text":"\"I never learned. It's too late for me now, beta.\"","then":"She looks disappointed. \"Okay.\""},{"text":"\"Ask your mother to teach you both how, beta.\"","then":"She goes to her mother. You watch from the door."}],"why":"Saying you'll learn shows it is never too late to be hands-on."},{"prompt":"A few days later, she holds out her comb and asks: \"Want to try a plait, Papa? It's hard.\"","options":[{"text":"\"Yes. We'll go slowly. Show me the first part.\"","then":"She lifts a section. \"Like this, then over.\"","best":true},{"text":"\"Maybe I'll just watch how mummy does it.\"","then":"She sighs. Watching isn't the same as doing."},{"text":"\"I'll try it another day, when it's calmer.\"","then":"She nods, but that day doesn't come."},{"text":"\"Let me watch a video first. We'll try tomorrow.\"","then":"Tomorrow comes, and she runs to school unplaited."}],"why":"Doing the first step together turns wanting into learning."},{"prompt":"A few weeks on, before a school function, she says: \"Papa, can you do my hair today? It needs patience.\"","options":[{"text":"\"Yes. Sit down, and we'll do it together.\"","then":"She giggles at the wobbly parting. \"It's lopsided, but I like it.\"","best":true},{"text":"\"Not today. It's too important to get wrong.\"","then":"She nods, and her mother does it. You watch from the door."},{"text":"\"Sure, but don't blame me if it goes wrong.\"","then":"She sits stiffly. The plait comes out tight and uneven."},{"text":"\"Ask your mother. She'll do it faster.\"","then":"She goes to her mother. You stay out of it."}],"why":"Doing it together shows her that learning is part of loving."}],"relearn":"Telling your child you'll learn their care shows it's never too late to become a more hands-on father."},
  {"id":"ep2-1113","cat":"involved-dads","type":"reflect","hook":"Lensy: the bond you build by being hands-on is yours to keep for life. Does that land?","prompt":"What's your take?","options":["It lands","Mine to keep","Worth the time"],"affirm":"The bond a father builds through daily, hands-on care is his own, lifelong, and no one can do it for him.","relearn":"The bond built through hands-on care is a father's own and lifelong; it's claimed by showing up, not delegated.","persona":"Vikram","source":"bond to keep"},
  {"id":"ep2-1114","cat":"involved-dads","type":"reflect","hook":"Lensy: 'helping' makes care sound like her job you assist with. Sit with that word a moment?","prompt":"What do you think?","options":["I see it","Just my word","It's my job too"],"affirm":"When a father 'helps', care still belongs to her; when he owns it, it's simply his job as a parent.","relearn":"Calling care 'helping' keeps it her job; owning it makes care a father's own equal responsibility.","persona":"any","source":"the word helping"},
  {"id":"ep2-1115","cat":"involved-dads","type":"reflect","hook":"Lensy: being there isn't only about money; your time and attention are gifts too. Resonate?","prompt":"How does that sit?","options":["Resonates","Time counts","Not only money"],"affirm":"A father's time, attention and presence are gifts to a child that no amount of provision can replace.","relearn":"A father's presence and attention are gifts money can't replace; providing is part of the job, not all of it.","persona":"Vikram","source":"presence is a gift"},
  {"id":"ep2-1116","cat":"involved-dads","type":"reflect","hook":"Lensy: getting better at care comes from doing it, not from being born for it. Land okay?","prompt":"What's your view?","options":["Lands okay","Practice, not birth","I can learn"],"affirm":"Fathers get good at care the same way anyone does, by practising; it was never a skill reserved for mothers.","relearn":"Skill at care comes from practice, not from being born to it; a father can learn it as well as anyone.","persona":"Vikram","source":"practice not birth"},
  {"id":"ep2-1117","cat":"involved-dads","type":"reflect","hook":"Lensy: every father starts unsure; the first nappy is clumsy for everyone. Comforting?","prompt":"What do you feel?","options":["Comforting","All start unsure","I'll learn it"],"affirm":"Every parent fumbles at first; a father's early clumsiness is the start of skill, not proof he can't do it.","relearn":"Early fumbling is normal for any parent; a father's clumsy first tries are the start of skill, not a verdict.","persona":"Vikram","source":"all start unsure"},
  {"id":"ep2-1118","cat":"involved-dads","type":"reflect","hook":"Lensy: claiming hands-on fatherhood is something you do for yourself, not just for her. Agree?","prompt":"Your take?","options":["I agree","For me too","A gain, not a chore"],"affirm":"Hands-on fatherhood lifts a father's own bond, confidence and joy; claiming it is a gain, not a sacrifice.","relearn":"Involved fatherhood is pro-men: claiming it lifts a father's own bond, confidence and joy, not just hers.","persona":"any","source":"for me too"},
  {"id":"ep2-1119","cat":"involved-dads","type":"reflect","hook":"Lensy: a child who can turn to either parent is steadier. Does that feel true to you?","prompt":"How does it land?","options":["Feels true","Either parent","Steadier kid"],"affirm":"When a child can turn to both parents, not just one, they feel safer and the load is genuinely shared.","relearn":"A child who can turn to either parent feels safer; building that means a father must be soothing, not just present.","persona":"Vikram","source":"either parent"},
  {"id":"ep2-1120","cat":"involved-dads","type":"reflect","hook":"Lensy: 'fun dad, tired mum' isn't really equal. Worth a pause?","prompt":"What do you notice?","options":["Worth a pause","Not equal","Share the dull bits"],"affirm":"Being only the fun parent while she carries the dull, daily load isn't shared parenting; both halves count.","relearn":"Being the fun parent while she carries the daily grind isn't equal; an involved dad shares the unglamorous half too.","persona":"Vikram","source":"fun dad tired mum"},
  {"id":"ep2-1121","cat":"involved-dads","type":"sort","hook":"Sort each line: owning the parenting, or staying a helper who waits to be told?","items":[{"id":"a","text":"Knowing the jab schedule yourself"},{"id":"b","text":"Waiting for a list before you act"},{"id":"c","text":"Taking the night feed without being asked"},{"id":"d","text":"Only doing tasks she hands you"},{"id":"e","text":"Owning the school run end-to-end"},{"id":"f","text":"Asking 'what should I do?' every time"}],"bins":[{"id":"owner","label":"Owning it","valence":"pos"},{"id":"helper","label":"Just helping","valence":"neg"}],"key":{"a":"owner","b":"helper","c":"owner","d":"helper","e":"owner","f":"helper"},"relearn":"Knowing schedules, taking feeds unasked and owning the school run is owning it; waiting for tasks is just helping.","persona":"Vikram","source":"owner vs helper"},
  {"id":"ep2-1122","cat":"involved-dads","type":"sort","hook":"Sort: present, hands-on fathering, or distant 'provider-only' fathering?","items":[{"id":"a","text":"Doing the bedtime routine nightly"},{"id":"b","text":"Seeing the kids only at weekends by choice"},{"id":"c","text":"Knowing your child's friends and worries"},{"id":"d","text":"Leaving all care to mum and grandparents"},{"id":"e","text":"Taking leave to be there at birth"},{"id":"f","text":"Sending money but rarely being home"}],"bins":[{"id":"present","label":"Present","valence":"pos"},{"id":"distant","label":"Distant","valence":"neg"}],"key":{"a":"present","b":"distant","c":"present","d":"distant","e":"present","f":"distant"},"relearn":"Bedtimes, knowing your child's world and being there at birth is present fathering; weekend-only and absent is distant.","persona":"Vikram","source":"present vs distant"},
  {"id":"ep2-1123","cat":"involved-dads","type":"sort","hook":"Sort each comment: a real myth about dads, or a true thing about involved fathers?","items":[{"id":"a","text":"Men can't soothe babies, it's instinct"},{"id":"b","text":"Fathers bond with newborns from day one"},{"id":"c","text":"Nappies are beneath a real man"},{"id":"d","text":"A present father lifts a child's confidence"},{"id":"e","text":"Care is mum's department, not dad's"},{"id":"f","text":"Soothing is a skill any parent can learn"}],"bins":[{"id":"myth","label":"Myth","valence":"neg"},{"id":"true","label":"True","valence":"pos"}],"key":{"a":"myth","b":"true","c":"myth","d":"true","e":"myth","f":"true"},"relearn":"That men can't soothe or that care is mum's job are myths; bonding from day one and learned soothing are true.","persona":"any","source":"myth vs true"},
  {"id":"ep2-1124","cat":"involved-dads","type":"sort","hook":"Sort: speak up and claim it, or quietly let your fatherhood get sidelined?","items":[{"id":"a","text":"\"They're my kids, not babysitting\""},{"id":"b","text":"Laughing along when called a babysitter"},{"id":"c","text":"\"I'll take the clinic visit myself\""},{"id":"d","text":"Letting the nurse ask only mum"},{"id":"e","text":"\"Leave bedtime to me tonight\""},{"id":"f","text":"Going quiet when told care is her job"}],"bins":[{"id":"claim","label":"Claim it","valence":"tell"},{"id":"sidelined","label":"Sidelined","valence":"uhoh"}],"key":{"a":"claim","b":"sidelined","c":"claim","d":"sidelined","e":"claim","f":"sidelined"},"relearn":"Naming 'not babysitting' and taking visits and bedtime claims your fatherhood; staying quiet lets it get sidelined.","persona":"Vikram","source":"claim vs sidelined"},
  {"id":"ep2-1125","cat":"involved-dads","type":"sort","hook":"Sort each barrier a dad meets: a real obstacle to name, or just an excuse to opt out?","items":[{"id":"a","text":"Workplace gives men no real leave"},{"id":"b","text":"\"I earn, so care isn't my job\""},{"id":"c","text":"Partner redoes everything you try"},{"id":"d","text":"\"Babies just don't want dads\""},{"id":"e","text":"No older men modelled hands-on care"},{"id":"f","text":"\"I'm too clumsy, why bother\""}],"bins":[{"id":"real","label":"Real barrier","valence":"uhoh"},{"id":"excuse","label":"Just an excuse","valence":"neg"}],"key":{"a":"real","b":"excuse","c":"real","d":"excuse","e":"real","f":"excuse"},"relearn":"Thin leave, gatekeeping and no role models are real barriers to name; 'I earn' or 'I'm clumsy' are excuses to opt out.","persona":"any","source":"barrier vs excuse"},
  {"id":"ep2-1126","cat":"involved-dads","type":"sort","hook":"Sort: quality engagement that builds a bond, or mere contact that doesn't?","items":[{"id":"a","text":"Listening to your child's day fully"},{"id":"b","text":"On the phone while 'watching' them"},{"id":"c","text":"Reading and playing together nightly"},{"id":"d","text":"In the room but never looking up"},{"id":"e","text":"Handling a tantrum patiently yourself"},{"id":"f","text":"Sitting beside them, both on screens"}],"bins":[{"id":"quality","label":"Real engagement","valence":"pos"},{"id":"contact","label":"Just contact","valence":"neutral"}],"key":{"a":"quality","b":"contact","c":"quality","d":"contact","e":"quality","f":"contact"},"relearn":"Listening, playing and handling tantrums is real engagement; being in the room on a phone is mere contact.","persona":"Vikram","source":"quality vs contact"},
  {"id":"ep2-1127","cat":"involved-dads","type":"sort","hook":"Sort each line a dad might say: owning his share, or pushing care back onto her?","items":[{"id":"a","text":"\"I've got the night feeds this week\""},{"id":"b","text":"\"You're just better with him than me\""},{"id":"c","text":"\"I booked the dentist for both kids\""},{"id":"d","text":"\"Wake me only if you really need to\""},{"id":"e","text":"\"I'll learn his routine myself\""},{"id":"f","text":"\"That's mother's stuff, you do it\""}],"bins":[{"id":"owns","label":"Owns his share","valence":"pos"},{"id":"pushes","label":"Pushes it back","valence":"neg"}],"key":{"a":"owns","b":"pushes","c":"owns","d":"pushes","e":"owns","f":"pushes"},"relearn":"Taking feeds, booking the dentist and learning the routine owns his share; 'you're better' or 'that's mother's stuff' pushes it back.","persona":"Vikram","source":"owns vs pushes"},
  {"id":"ep2-1128","cat":"involved-dads","type":"match","hook":"Match each involved-dad act to what it gives the child.","pairs":[{"left":"Doing the daily care","right":"A secure, real bond"},{"left":"Being emotionally present","right":"Confidence and resilience"},{"left":"Showing up consistently","right":"Trust they can rely on you"},{"left":"Sharing the load with mum","right":"A calmer, less-stretched home"},{"left":"Modelling care as a man","right":"A wider idea of what men do"}],"relearn":"Daily care, presence, consistency, sharing the load and modelling are what an involved father gives his child.","persona":"Vikram","source":"act to gift"},
  {"id":"ep2-1129","cat":"involved-dads","type":"match","hook":"Match each old myth about dads to the truth that replaces it.","pairs":[{"left":"He's just babysitting his own kids","right":"He's parenting; it's his job too"},{"left":"Nurturing isn't a man's role","right":"Men can nurture fully and well"},{"left":"Babies only want their mother","right":"Infants attach to both from birth"},{"left":"Care is beneath a real man","right":"Care is how a father builds a bond"},{"left":"Asking dads to do more is anti-men","right":"Involved fatherhood is pro-men"}],"relearn":"Babysitting becomes parenting, nurturing is a man's role, babies attach to both, care builds bonds, involvement is pro-men.","persona":"any","source":"myth to truth"},
  {"id":"ep2-1130","cat":"involved-dads","type":"match","hook":"Match each barrier a father faces to a way to meet it without opting out.","pairs":[{"left":"Thin or no paternity leave","right":"Take what you can and guard home time"},{"left":"Partner redoing your efforts","right":"Ask kindly for room to learn"},{"left":"Work that erases fatherhood","right":"Protect a daily ritual you keep"},{"left":"No older men modelled care","right":"Be the model your own kids see"},{"left":"\"It's not manly\" pressure","right":"Claim tenderness as good fathering"}],"relearn":"Thin leave, gatekeeping, greedy work, no role models and 'not manly' pressure are each met by claiming your share, not opting out.","persona":"any","source":"barrier to move"},
  {"id":"ep2-1131","cat":"involved-dads","type":"match","hook":"Match each domain a father can own to what owning it actually means.","pairs":[{"left":"Health","right":"Tracking jabs and booking the doctor"},{"left":"Sleep","right":"Owning the bedtime routine and nights"},{"left":"School","right":"Knowing the bags, timings and meetings"},{"left":"Food","right":"Planning and making the kids' meals"},{"left":"Play","right":"Being the one who reads and plays daily"}],"relearn":"Owning a domain like health, sleep, school, food or play means tracking and doing it end-to-end, not when asked.","persona":"Vikram","source":"domain to meaning"},
  {"id":"ep2-1132","cat":"involved-dads","type":"match","hook":"Match each thing a present father does to the gain it brings him.","pairs":[{"left":"Soothing his baby himself","right":"Confidence he can parent"},{"left":"Sharing nights and feeds","right":"A deeper bond with his child"},{"left":"Knowing his child's world","right":"Closeness as they grow"},{"left":"Modelling care openly","right":"A son who respects care work"},{"left":"Claiming hands-on time","right":"Joy he'd otherwise miss"}],"relearn":"Soothing, sharing nights, knowing his child and modelling care give a father confidence, bond, closeness and joy.","persona":"Vikram","source":"act to dad's gain"},
  {"id":"ep2-1133","cat":"involved-dads","type":"match","hook":"Match each phrase to whether it's an involved-dad move or a stay-distant move.","pairs":[{"left":"\"Leave the doctor visit to me\"","right":"Involved: owning a domain"},{"left":"\"Just tell me what to do\"","right":"Distant: staying a helper"},{"left":"\"I'll learn his routine myself\"","right":"Involved: building real skill"},{"left":"\"You're the natural with him\"","right":"Distant: ducking the load"},{"left":"\"Bedtime's mine tonight\"","right":"Involved: sharing the daily care"}],"relearn":"Taking visits, learning routines and owning bedtime is involved; 'tell me what to do' or 'you're the natural' stays distant.","persona":"Vikram","source":"involved vs distant phrase"},
  {"id":"ep2-1134","cat":"involved-dads","type":"match","hook":"Match each setting to the involved-dad action that fits it.","pairs":[{"left":"Newborn weeks at home","right":"Take leave and share the nights"},{"left":"At the child's clinic","right":"Answer the questions yourself"},{"left":"Family lunch teasing","right":"Name it: parenting, not babysitting"},{"left":"Late work pings at bedtime","right":"Protect the bedtime ritual"},{"left":"Partner hovering as you try","right":"Ask for room to learn your way"}],"relearn":"Newborn weeks, the clinic, teasing, work pings and hovering each have an involved-dad move: show up and own it.","persona":"Vikram","source":"setting to action"},
  {"id":"ep2-1135","cat":"involved-dads","type":"spot","hook":"Spot the two lines that keep a father a helper instead of an equal parent.","scene":[{"id":"a","text":"He knows the kids' routines himself","trick":false},{"id":"b","text":"He waits to be told what to do","trick":true},{"id":"c","text":"He owns bedtime without being asked","trick":false},{"id":"d","text":"He only does tasks she hands him","trick":true},{"id":"e","text":"He books the doctor visits himself","trick":false}],"why":"Waiting to be told and only doing handed tasks keep him a helper; an equal parent owns and notices himself.","relearn":"A father stays a helper when he waits to be told and only does handed tasks; owning care himself makes him equal.","persona":"Vikram","source":"helper red flags"},
  {"id":"ep2-1136","cat":"involved-dads","type":"spot","hook":"Spot the two lines that wrongly treat fathering as not a man's job.","scene":[{"id":"a","text":"\"Holding my baby is the best part of my day\"","trick":false},{"id":"b","text":"\"Nappies are beneath a real man\"","trick":true},{"id":"c","text":"\"I take the kids to the doctor too\"","trick":false},{"id":"d","text":"\"Nurturing just isn't a man's thing\"","trick":true},{"id":"e","text":"\"I'll learn his routine myself\"","trick":false}],"why":"'Nappies are beneath a man' and 'nurturing isn't a man's thing' are the myths; care is fully a father's role.","relearn":"Saying care is beneath a man or not a man's thing are myths to catch; nurturing is fully a father's role.","persona":"any","source":"not-a-mans-job myths"},
  {"id":"ep2-1137","cat":"involved-dads","type":"spot","hook":"Spot the two lines that excuse a father opting out of care.","scene":[{"id":"a","text":"\"Work was hard, but I'll still do bath time\"","trick":false},{"id":"b","text":"\"I earn, so the care isn't my job\"","trick":true},{"id":"c","text":"\"Let me take the night feed tonight\"","trick":false},{"id":"d","text":"\"Babies just don't really want dads\"","trick":true},{"id":"e","text":"\"I'll learn what jabs are due\"","trick":false}],"why":"'I earn, so care isn't my job' and 'babies don't want dads' are excuses to opt out; both parents owe the care.","relearn":"'I earn so care isn't mine' and 'babies don't want dads' are opt-out excuses to catch; care is a father's job too.","persona":"Vikram","source":"opt-out excuses"},
  {"id":"ep2-1138","cat":"involved-dads","type":"spot","hook":"Spot the two replies that quietly let a father's care be called 'babysitting'.","scene":[{"id":"a","text":"\"It's not babysitting, they're my kids\"","trick":false},{"id":"b","text":"\"Ha, yes, I'm on babysitting duty today\"","trick":true},{"id":"c","text":"\"I parent them, same as their mother\"","trick":false},{"id":"d","text":"\"She lets me help out now and then\"","trick":true},{"id":"e","text":"\"Minding my own children is just being dad\"","trick":false}],"why":"Calling it babysitting duty and saying 'she lets me help' both frame care as a favour; it's his own job.","relearn":"Accepting 'babysitting' or 'she lets me help' frames care as a favour to catch; it's a father's own responsibility.","persona":"Vikram","source":"babysitting language"},
  {"id":"ep2-1139","cat":"involved-dads","type":"spot","hook":"Spot the two moves that show 'present' on paper but not real engagement.","scene":[{"id":"a","text":"He listens fully to his child's day","trick":false},{"id":"b","text":"He's on his phone while 'minding' them","trick":true},{"id":"c","text":"He reads and plays with them nightly","trick":false},{"id":"d","text":"He's in the room but never looks up","trick":true},{"id":"e","text":"He handles the tantrum patiently himself","trick":false}],"why":"Being on a phone or never looking up is mere contact, not engagement; quality of attention is what builds a bond.","relearn":"Being physically there on a phone or never looking up is contact, not engagement; real attention builds the bond.","persona":"Vikram","source":"contact not engagement"},
  {"id":"ep2-1140","cat":"involved-dads","type":"spot","hook":"Spot the two lines that pressure a dad to stay distant to seem 'manly'.","scene":[{"id":"a","text":"\"Cuddle him all you like, it's good for him\"","trick":false},{"id":"b","text":"\"Holding the baby will make you soft\"","trick":true},{"id":"c","text":"\"Take the leave, be there at the start\"","trick":false},{"id":"d","text":"\"Real men leave the crying to the wife\"","trick":true},{"id":"e","text":"\"Learn his routine, you'll be glad you did\"","trick":false}],"why":"'Holding makes you soft' and 'real men leave crying to the wife' push distance; tenderness is good fathering.","relearn":"'Cuddling makes you soft' and 'real men leave crying to wives' are the pressure to catch; tenderness is strength.","persona":"Vikram","source":"manly distance"},
  {"id":"ep2-1141","cat":"involved-dads","type":"spot","hook":"Spot the two lines that hand the whole mental load back to the mother.","scene":[{"id":"a","text":"\"I track his jabs and sizes myself\"","trick":false},{"id":"b","text":"\"You just remember that stuff better\"","trick":true},{"id":"c","text":"\"I'll plan the week's meals this time\"","trick":false},{"id":"d","text":"\"Make me a list and I'll do it\"","trick":true},{"id":"e","text":"\"I'll own the school bags and timings\"","trick":false}],"why":"'You remember better' and 'make me a list' keep her the manager who notices; sharing means owning the noticing too.","relearn":"'You remember better' and 'make me a list' keep her the manager to catch; a father shares the noticing, not just tasks.","persona":"Vikram","source":"load handed back"},
  {"id":"ep2-1170","cat":"kids-are-watching","type":"strike-rewrite","persona":"Meena","source":"sons see kitchen","hook":"\"My son seeing me in the kitchen and his dad on the sofa won't shape him.\"","myth":{"un":"My son seeing me cook while his dad relaxes won't shape him.","re":"What a boy watches at home becomes his idea of 'normal'; he learns whose job care is by who does it.","why":"Children build their template from the home they grow up in."},"relearn":"What your son sees you both do at home becomes his idea of whose job care is."},
  {"id":"ep2-1171","cat":"kids-are-watching","type":"strike-rewrite","persona":"Priya","source":"daughter expects","hook":"\"If I do all the home work, my daughter will still aim high at her career.\"","myth":{"un":"Doing all the home work myself won't lower what my daughter expects for herself.","re":"A daughter who only sees mum carry the home learns to expect that load on top of any career she builds.","why":"Kids absorb what a 'wife and mother' does from the one they watch."},"relearn":"A daughter learns what she'll be expected to carry from watching who carries it at home."},
  {"id":"ep2-1172","cat":"kids-are-watching","type":"strike-rewrite","persona":"Meena","source":"praise dad rare","hook":"\"Praising my husband loudly when he changes a nappy teaches our kids he's a great dad.\"","myth":{"un":"Praising my husband loudly for changing one nappy teaches the kids he's a great dad.","re":"Cheering a father for routine care teaches kids it's extra and optional for men, not simply his job too.","why":"Kids read what's normal from what gets treated as a favour."},"relearn":"Treating a dad's everyday care as a favour teaches kids it's optional for men."},
  {"id":"ep2-1173","cat":"kids-are-watching","type":"strike-rewrite","persona":"Priya","source":"too young to notice","hook":"\"My kids are too small to notice who cooks, cleans or earns at home.\"","myth":{"un":"My kids are too small to notice who cooks, cleans or earns at home.","re":"Even young children track who does what; the home roles they watch early become the ones they assume are natural.","why":"The earliest model a child sees is the hardest to unlearn later."},"relearn":"Even small children track who does what, and early home roles feel 'natural' to them for life."},
  {"id":"ep2-1174","cat":"kids-are-watching","type":"strike-rewrite","persona":"Meena","source":"dad fun parent","hook":"\"Dad being the fun playtime parent while I handle the rest is a fine split for the kids.\"","myth":{"un":"Dad as the fun playtime parent while I handle the rest is a fine split for the kids.","re":"When kids only see dad play and mum manage, they learn care-work is mum's and dads just visit the fun bits.","why":"Children copy the division of labour they actually watch."},"relearn":"If kids only see dad play and mum manage, they learn care is mum's job and dads just drop in."},
  {"id":"ep2-1175","cat":"kids-are-watching","type":"strike-rewrite","persona":"Priya","source":"weekend modelling","hook":"\"As long as my husband helps on weekends, the kids see a fair home.\"","myth":{"un":"As long as my husband helps on weekends, the kids see a fair home.","re":"Kids watch the daily pattern, not the weekend cameo; a weekday split that's all mum is what they absorb.","why":"The everyday routine, not the occasional one, sets a child's normal."},"relearn":"Kids absorb the daily routine, not the weekend cameo, so weekday sharing is what models fairness."},
  {"id":"ep2-1176","cat":"kids-are-watching","type":"strike-rewrite","persona":"Meena","source":"sons learn respect","hook":"\"A boy learns to respect women from being told to, not from chores at home.\"","myth":{"un":"A boy learns to respect women from being told to, not from chores at home.","re":"A boy who shares cooking and cleaning at home learns women aren't there to serve him, far more than a lecture can.","why":"Respect is learned in the doing, not the telling."},"relearn":"A boy who shares the home work learns women aren't there to serve him, better than any lecture."},
  {"id":"ep2-1177","cat":"kids-are-watching","type":"strike-rewrite","persona":"Priya","source":"grandparents model","hook":"\"My kids see grandparents in old roles, so what we two do at home barely matters.\"","myth":{"un":"With grandparents in old roles around, what we two do at home barely matters to the kids.","re":"Parents are a child's closest, most-watched model; your shared split stands out even amid older patterns.","why":"Kids weight what their own parents do most heavily."},"relearn":"Your kids watch you two most closely; your shared home stands out even amid older family patterns."},
  {"id":"ep2-1178","cat":"kids-are-watching","type":"strike-rewrite","persona":"Meena","source":"care confuses boys","hook":"\"Letting my son rock the baby or fold clothes will make him soft or confused.\"","myth":{"un":"Letting my son rock the baby or fold clothes will make him soft or confused.","re":"A boy who learns to care and run a home grows up capable and confident; care skills don't weaken him.","why":"Life skills strengthen children; they have no gender."},"relearn":"A boy who learns to care and run a home grows up capable and confident, never weakened."},
  {"id":"ep2-1179","cat":"kids-are-watching","type":"strike-rewrite","persona":"Priya","source":"talk vs do gap","hook":"\"We tell our kids partners are equal, so what they see us do is a smaller detail.\"","myth":{"un":"We tell our kids partners are equal, so what they see us do is a smaller detail.","re":"When the words say equal but the home doesn't, kids believe what they watch; the gap teaches the talk is just talk.","why":"A child trusts the lived example over the spoken one."},"relearn":"When your words say equal but the home doesn't, kids believe what they see, not what they hear."},
  {"id":"ep2-1180","cat":"kids-are-watching","type":"strike-rewrite","persona":"Meena","source":"break my own cycle","hook":"\"I grew up with an unequal home, so my kids are bound to repeat the same pattern.\"","myth":{"un":"I grew up in an unequal home, so my kids are bound to repeat the same pattern.","re":"You can break what you inherited; a shared home this generation gives your kids a new normal to carry forward.","why":"Modelling change is how the intergenerational cycle ends."},"relearn":"You can break what you inherited; a shared home now gives your kids a new normal to carry forward."},
  {"id":"ep2-1181","cat":"kids-are-watching","type":"sort","persona":"Meena","source":"what son absorbs","hook":"Sort: a son watching this home learns care is shared, or learns care isn't his job?","items":[{"id":"a","text":"Papa packs the school tiffin most mornings"},{"id":"b","text":"Only Mummy is ever called for a sick child"},{"id":"c","text":"Both parents wash up after dinner"},{"id":"d","text":"Dad says 'cooking is your mother's department'"},{"id":"e","text":"Papa helps with homework and bedtime"},{"id":"f","text":"Boys excused from chores, girls aren't"}],"bins":[{"id":"shared","label":"Care is shared","valence":"pos"},{"id":"notmine","label":"Care isn't his job","valence":"neg"}],"key":{"a":"shared","b":"notmine","c":"shared","d":"notmine","e":"shared","f":"notmine"},"relearn":"A son learns care is shared from a dad who cooks and parents; he learns it isn't his from mum-only homes."},
  {"id":"ep2-1182","cat":"kids-are-watching","type":"sort","persona":"Priya","source":"models or not","hook":"Sort: does this moment model equality for the kids, or quietly undermine it?","items":[{"id":"a","text":"Parents decide the budget together"},{"id":"b","text":"Dad waits to be 'asked' before he helps"},{"id":"c","text":"Mum has the final say on her own career"},{"id":"d","text":"Kids hear 'real men don't do dishes'"},{"id":"e","text":"Both parents attend the school meeting"},{"id":"f","text":"Daughter told to serve her brother first"}],"bins":[{"id":"models","label":"Models equality","valence":"pos"},{"id":"undermines","label":"Undermines it","valence":"neg"}],"key":{"a":"models","b":"undermines","c":"models","d":"undermines","e":"models","f":"undermines"},"relearn":"Joint decisions and both parents showing up model equality; gendered jabs undermine it."},
  {"id":"ep2-1183","cat":"kids-are-watching","type":"sort","persona":"Meena","source":"daily vs cameo","hook":"Sort: which of these does a child actually watch every day, and which is just an occasional cameo?","items":[{"id":"a","text":"Who gets up for the early school rush daily"},{"id":"b","text":"Who plans the week's meals and groceries"},{"id":"c","text":"Dad's once-a-month trip to the park"},{"id":"d","text":"Who notices when uniforms need washing"},{"id":"e","text":"A grand 'helping out' on a festival day"},{"id":"f","text":"Who keeps track of homework each evening"}],"bins":[{"id":"daily","label":"Watched daily","valence":"neutral"},{"id":"cameo","label":"Occasional cameo","valence":"uhoh"}],"key":{"a":"daily","b":"daily","c":"cameo","d":"daily","e":"cameo","f":"daily"},"relearn":"Kids absorb the daily routine of care, not the occasional cameo, so the everyday split is what they learn."},
  {"id":"ep2-1184","cat":"kids-are-watching","type":"sort","persona":"Priya","source":"chore gendered","hook":"Sort: which teaches kids chores have no gender, and which teaches the old divide?","items":[{"id":"a","text":"Son and daughter both learn to cook dal"},{"id":"b","text":"Only the girl is taught to keep house"},{"id":"c","text":"Brother and sister share the sweeping"},{"id":"d","text":"Boy handed money, girl handed a broom"},{"id":"e","text":"Both kids fold their own clothes"},{"id":"f","text":"Sister serves, brother is served"}],"bins":[{"id":"nogender","label":"Chores have no gender","valence":"pos"},{"id":"olddivide","label":"Teaches the old divide","valence":"neg"}],"key":{"a":"nogender","b":"olddivide","c":"nogender","d":"olddivide","e":"nogender","f":"olddivide"},"relearn":"Same chores for sons and daughters teach care has no gender; splitting by sex teaches the divide."},
  {"id":"ep2-1185","cat":"kids-are-watching","type":"sort","persona":"Meena","source":"present dad","hook":"Sort: which shows a child dads can be tender, and which says dads keep their distance?","items":[{"id":"a","text":"Papa cuddles the toddler when she cries"},{"id":"b","text":"'Go to your mother' when a child is upset"},{"id":"c","text":"Dad sits and listens to a kid's bad day"},{"id":"d","text":"'Ask your mum about feelings,' says dad"},{"id":"e","text":"Papa sings the baby to sleep"},{"id":"f","text":"Dad never does the soothing or soft stuff"}],"bins":[{"id":"tender","label":"Dads can be tender","valence":"pos"},{"id":"distant","label":"Dads keep distance","valence":"neg"}],"key":{"a":"tender","b":"distant","c":"tender","d":"distant","e":"tender","f":"distant"},"relearn":"A dad who soothes shows kids men can be tender; pushing soft stuff to mum teaches distance."},
  {"id":"ep2-1186","cat":"kids-are-watching","type":"sort","persona":"Priya","source":"counter or cede","hook":"Sort: when relatives push old roles on your kids, which keeps your home the lesson?","items":[{"id":"a","text":"Gently say 'in our home, both of us cook'"},{"id":"b","text":"Stay silent so the gendered remark stands"},{"id":"c","text":"Show the kids dad doing it right then"},{"id":"d","text":"Let 'that's girls' work' go unchallenged"},{"id":"e","text":"Repeat your shared split out loud, kindly"},{"id":"f","text":"Agree quietly just to avoid a scene"}],"bins":[{"id":"holds","label":"Keeps home the lesson","valence":"tell"},{"id":"cedes","label":"Lets the script win","valence":"neg"}],"key":{"a":"holds","b":"cedes","c":"holds","d":"cedes","e":"holds","f":"cedes"},"relearn":"Gently naming your shared split keeps home the lesson; silence lets the old script teach instead."},
  {"id":"ep2-1187","cat":"kids-are-watching","type":"sort","persona":"any","source":"belief planted","hook":"Sort: which homes teach a child care is everyone's, and which that care is women's only?","items":[{"id":"a","text":"Both parents on hospital duty when a kid is ill"},{"id":"b","text":"Father has never made a meal at home"},{"id":"c","text":"Both parents do nights with a new baby"},{"id":"d","text":"Mum alone runs every birthday and illness"},{"id":"e","text":"Papa irons the school uniforms"},{"id":"f","text":"Care talk is always aimed at the women"}],"bins":[{"id":"everyone","label":"Care is everyone's","valence":"pos"},{"id":"womenonly","label":"Care is women's only","valence":"neg"}],"key":{"a":"everyone","b":"womenonly","c":"everyone","d":"womenonly","e":"everyone","f":"womenonly"},"relearn":"Kids learn care is everyone's from both parents sharing it, and women's from mum-only homes."},
  {"id":"ep2-1188","cat":"kids-are-watching","type":"sort","persona":"Meena","source":"mental load seen","hook":"Sort: which lets kids see planning is shared, and which hides it as mum's invisible work?","items":[{"id":"a","text":"Both parents fill the family calendar"},{"id":"b","text":"Only mum remembers every vaccine"},{"id":"c","text":"Dad openly tracks fees and supplies"},{"id":"d","text":"Father asks 'what do I buy?' every time"},{"id":"e","text":"Parents plan the school year together"},{"id":"f","text":"Mum carries the to-do list in her head"}],"bins":[{"id":"shared","label":"Planning is shared","valence":"pos"},{"id":"hidden","label":"Mum's invisible work","valence":"uhoh"}],"key":{"a":"shared","b":"hidden","c":"shared","d":"hidden","e":"shared","f":"hidden"},"relearn":"Kids see planning as shared when both parents track it openly; mum-only remembering hides it."},
  {"id":"ep2-1189","cat":"kids-are-watching","type":"branch","persona":"Priya","source":"son refuses chore","hook":"At dinner your son pushes his plate away and says \"that's didi's job.\"","steps":[{"prompt":"Your daughter is already reaching for it, and your husband is watching. What do you do?","options":[{"text":"Let his sister clear it to avoid a scene","then":"The dinner stays calm. Your daughter clears both plates without a word."},{"text":"Ask your husband to explain it to him","then":"Dad tells him plates are for everyone, from the sofa. The plates stay where they are."},{"text":"Say equality matters, then clear it yourself","then":"Your son nods and leaves. You are the one at the sink again."},{"text":"Have him clear it, and say you and Dad clear yours too","then":"He grumbles, carries the plate, and sees Dad stack his own.","best":true}],"why":"He learns it is everyone's job by seeing it, not by hearing it."},{"prompt":"The next evening your son clears his plate but says \"Didi should do the cups.\" What do you do?","options":[{"text":"Put up a rota with names for Dad and you too","then":"The rota goes on the fridge. Dad grins at seeing his name on Wednesday.","best":true},{"text":"Tell him he must do all of it, no arguments","then":"He clears everything, scowling, and says it isn't fair."},{"text":"Let the kids sort it out between themselves","then":"Your daughter says she will do it, and your son happily lets her."},{"text":"Let it go, since he did clear his plate","then":"He takes the win and drifts off. The cups stay with Didi."}],"why":"A shared rota with everyone's name makes fairness the house rule."},{"prompt":"A friend visits, sees your son clearing plates and looks surprised. What do you do?","options":[{"text":"Give his friend a short talk about equality","then":"The boy nods politely and glances at the door."},{"text":"Say casually that everyone here clears, and carry on","then":"The boys shrug and stack plates together. Your son says, \"Everyone does it at ours.\"","best":true},{"text":"Clear for them to spare your son's embarrassment","then":"Your son looks relieved. His friend goes home with the same idea he came with."},{"text":"Say your son is helping today because he's a good boy","then":"Your son puffs up. He starts expecting a reward each time."}],"why":"Treating it as normal, not special, lets both boys see chores as everyone's."}],"debrief":"When a child voices the old divide, change what both parents do, not just what you say.","relearn":"Reteach by having both parents share the job in front of him."},
  {"id":"ep2-1190","cat":"kids-are-watching","type":"branch","persona":"Priya","source":"dad sofa","hook":"Every night you clear up after dinner while your husband and the kids watch TV.","steps":[{"prompt":"Tonight you want the kids to see something fairer. What do you do?","options":[{"text":"Ask the kids to help while their father rests","then":"The kids grumble and help for five minutes. Your husband stays on the sofa."},{"text":"Snap that nobody in this house ever helps you","then":"The TV goes quiet. He mutters that you could just ask."},{"text":"Keep going quietly and hope he notices without being asked","then":"He doesn't. The kids stay glued to the screen."},{"text":"Ask him warmly to split the clean-up with you","then":"He looks up, then gets a cloth. The kids glance at both of you.","best":true}],"why":"Sharing the clean-up where the kids can see it teaches more than doing it alone."},{"prompt":"The next evening he says, \"Just tell me what to do and I'll do it.\" What do you say?","options":[{"text":"Say it's fine and you will manage tonight, as usual","then":"He shrugs, relieved. The kids see you at the sink again."},{"text":"Suggest he own clean-up on alternate nights","then":"He nods. \"Alternate nights, no reminders. Fine.\"","best":true},{"text":"Say he should just know what needs doing by now","then":"He frowns. \"How would I know unless you tell me?\""},{"text":"Give him a list of what to wash and dry tonight","then":"He follows the list and returns to the sofa between items."}],"why":"Owning whole nights means you stop managing him and the thinking moves too."},{"prompt":"Your mother-in-law visits and says clearing up is a wife's job, not a husband's. The kids listen. What do you say?","options":[{"text":"Agree, and clear up yourself to keep the peace","then":"She relaxes. The kids watch you at the sink again."},{"text":"Tell her she is stuck in the past","then":"She is hurt and goes quiet. The kids look from one to the other."},{"text":"Say you will talk about it later, away from the kids","then":"The visit moves on. The kids never hear your side."},{"text":"Say warmly that you both run this home","then":"She sighs, \"Different times.\" Your husband nods and picks up a plate.","best":true}],"why":"Saying it plainly and kindly keeps her close and shows the kids a shared home."},{"prompt":"A month on, your son asks whether the dishes are Mummy's job or Papa's. What do you say?","options":[{"text":"Say it's everyone's job, and everyone takes a turn","then":"Your son nods slowly. \"So do I get a turn too?\"","best":true},{"text":"Say Papa helps Mummy with the dishes","then":"Your son nods. He files it: dishes are Mummy's, with Papa's help."},{"text":"Say it's not for kids to worry about","then":"Your son shrugs and goes back to the TV."},{"text":"Say whoever is less tired does them","then":"Your son thinks. \"But how do we know who is less tired?\""}],"why":"Saying it is everyone's job, in turns, tells him the house rule for good."}],"debrief":"Sharing the clean-up where kids see it teaches more than doing it alone.","relearn":"Splitting the clean-up where kids can see it models shared care."},
  {"id":"ep2-1191","cat":"kids-are-watching","type":"branch","persona":"Meena","source":"daughter quit","hook":"Your daughter says \"I'll stop working when I have kids, like mums do.\"","steps":[{"prompt":"She looks at you, waiting for a reply. What do you say?","options":[{"text":"Tell her how you and Dad both worked and cared","then":"Her eyes widen. \"Papa picked me up from school?\" You nod, and say the choice will be hers.","best":true},{"text":"Agree it's just what mothers do for their families","then":"She nods and folds the idea into her plan for the future."},{"text":"Tell her not to think that way, and move on","then":"She shrugs and says okay, still picturing the same thing."},{"text":"Say every family is different, and leave it there","then":"She nods, and still can't picture how anyone does both."}],"why":"Seeing both parents share care and work shows her a mother's life has room for both, and the choice is hers."},{"prompt":"A month on, she asks who looks after a baby when both parents work. What do you say?","options":[{"text":"Say the mother figures it out somehow","then":"She frowns. \"All by herself?\" You don't have an answer ready."},{"text":"Say grandparents usually step in when both parents work","then":"She nods, and the picture in her mind still leaves out both parents."},{"text":"Say it's too early for her to worry about it","then":"She goes quiet, and the question stays with her."},{"text":"Show her how you and Dad plan it together","then":"She studies the calendar, and you walk her through the Tuesdays and Thursdays.","best":true}],"why":"Showing how parents plan together makes a shared future look ordinary."},{"prompt":"At a family gathering, her aunt says \"Girls should give up jobs for kids.\" Your daughter looks at you. What do you say?","options":[{"text":"Let the remark pass so the mood stays light","then":"The moment passes. Your daughter keeps watching you."},{"text":"Tell your daughter afterwards not to listen to her aunt","then":"Your daughter nods, then asks why you didn't say it to her aunt."},{"text":"Tell her aunt she is wrong in front of everyone","then":"The aunt flushes, the room tenses, and your daughter looks at her shoes."},{"text":"Say that in your family both parents work and care","then":"Your daughter smiles. Dad adds, \"Ask me about school runs.\"","best":true}],"why":"Your own family is the example she will carry into her own life."}],"debrief":"A daughter rethinks the default by watching both parents share care and work.","relearn":"A daughter expects a fair future when both parents share care and their own lives."},
  {"id":"ep2-1192","cat":"kids-are-watching","type":"branch","persona":"Priya","source":"praise dad","hook":"At a family lunch, a relative gushes, \"What a husband! He even feeds the baby!\"","steps":[{"prompt":"Your kids are listening and your husband smiles awkwardly. What do you say?","options":[{"text":"Say nothing and pass the dal round the table","then":"The talk moves on. Your husband's smile stiffens slightly."},{"text":"Smile and agree that he is being very helpful today","then":"The relative beams. Your children hear \"helpful\" one more time."},{"text":"Smile and say feeding his own baby is just his job","then":"Your relative laughs, surprised. Your husband nods, and your daughter looks up.","best":true},{"text":"Thank her and say you are lucky to have such a husband","then":"She pats your hand. \"Very lucky,\" she says, and the kids nod along."}],"why":"Feeding his own baby is a father's job, and the kids hear that said kindly."},{"prompt":"After lunch your daughter says, \"Papa helps you so much, Mummy.\" What do you say?","options":[{"text":"Say yes, Papa really does help us a great deal","then":"She repeats it at bedtime, \"Papa helps a lot,\" as if it were a treat."},{"text":"Say it's a grown-ups' matter and not for kids to ask","then":"She shrugs and goes to play, and the question goes unanswered."},{"text":"Say Papa is parenting his own children, not helping","then":"She thinks. \"So it's Papa's job too?\" \"Yes,\" you say.","best":true},{"text":"Say Papa does it because he loves all of you dearly","then":"She smiles. \"So he does it when he loves us?\" she asks."}],"why":"Naming it as his own job teaches kids that care is a duty, not a favour."},{"prompt":"Another relative praises his \"help\" while he is in the room. What do you do?","options":[{"text":"Quietly ask your husband to correct her himself","then":"He fumbles and says it's fine. The chance passes."},{"text":"Laugh and say you've trained him well","then":"She laughs. The kids hear \"trained\", as if care were a favour you taught him."},{"text":"Say nothing, and let the remark pass","then":"The relative carries on. Your husband looks at you, hoping you'll speak."},{"text":"Say you both parent, and invite him to say so too","then":"He says it is his job too. The relative blinks, then laughs.","best":true}],"why":"Saying it together, with his voice in it, makes shared parenting the norm."},{"prompt":"Your daughter brings home a drawing titled \"Mummy cooks, Papa helps.\" What do you do?","options":[{"text":"Praise it and put it on the fridge","then":"She beams. The picture goes up, and so does the idea."},{"text":"Sit with her and draw the family cooking together","then":"She draws you, Papa and herself with spoons. Papa hangs it on the fridge.","best":true},{"text":"Ask her to redraw it without saying why","then":"She crumples the paper and says nothing."},{"text":"Tell her the drawing is wrong","then":"She looks crestfallen. \"But Aunty said it.\""}],"why":"Drawing the shared version with her lets her see it, not just hear it."}],"debrief":"Reframing a dad's care as his own job, not a favour, corrects what kids just heard.","relearn":"Naming a dad's care as his own duty teaches kids care is shared, not a favour."},
  {"id":"ep2-1193","cat":"kids-are-watching","type":"branch","persona":"Meena","source":"play house","hook":"Your kids play house with the boy \"at office\" and the girl \"cooking.\"","steps":[{"prompt":"They invite you into the game as the guest. What do you do?","options":[{"text":"Join in and let the \"dad\" cook while the \"mum\" works","then":"Your son tries the pan with delight. Your daughter announces an important meeting.","best":true},{"text":"Ask your daughter why she is always the one cooking","then":"Your daughter shrugs, embarrassed. \"That's how it is,\" says your son."},{"text":"Stop the game and explain why it isn't fair","then":"They sit still, then wander off. The game ends."},{"text":"Find it cute and play along with the roles as they are","then":"They giggle, thrilled with your attention. The roles stay put."}],"why":"Play copies the home they watch, so joining in and widening it is how they learn."},{"prompt":"A week later they play house with a doll. Your son says, \"Baby's crying. Mummy will fix it.\" What do you do?","options":[{"text":"Tell him boys can hold babies when they're older","then":"Your son puts his hands behind his back and waits."},{"text":"Let your daughter take the doll, since she loves it","then":"Your daughter picks up the doll and your son goes back to his toy phone."},{"text":"Tell them Papa soothes babies too, then step away for tea","then":"They nod politely and keep the game as it was."},{"text":"Hand him the doll and say Papa can cuddle babies too","then":"Your son rocks the doll awkwardly, then hums a lullaby.","best":true}],"why":"Handing him the doll lets him try it, which teaches more than telling."},{"prompt":"Their grandmother watches and says, \"Look how naturally the girl takes to the kitchen.\" What do you say?","options":[{"text":"Say warmly that in this house everyone cooks","then":"Grandma laughs. \"Even the little chef?\" Your son grins and holds out a toy plate.","best":true},{"text":"Tell the kids later that Grandma is old-fashioned","then":"The kids giggle and start calling Grandma old-fashioned."},{"text":"Smile and say nothing at all, then pour the tea","then":"Grandma takes the smile for a yes and says it again, louder."},{"text":"Agree that girls just take to it naturally","then":"Grandma is delighted. Your daughter beams, and your son slips away."}],"why":"Welcoming Grandma while saying everyone cooks keeps the family close and fair."}],"debrief":"Kids' play mirrors the home they watch; widen it by joining in and sharing the real work at home.","relearn":"Children's play copies the home they watch; widen it by joining in and sharing the real work at home."},
  {"id":"ep2-1194","cat":"kids-are-watching","type":"branch","persona":"Priya","source":"dad distance","hook":"Your child runs to you crying. Your husband says, \"Go to mama. I'm no good at it.\"","steps":[{"prompt":"Your child clings to your leg. What do you do?","options":[{"text":"Gently turn your child back to Dad, and stay nearby","then":"Dad kneels, clumsy at first. The crying slows as he hums.","best":true},{"text":"Snap that he must learn, in front of your child","then":"He stiffens, and your child cries harder between you."},{"text":"Pick your child up yourself, since it's quicker","then":"Your child calms quickly. Dad relaxes on the sofa."},{"text":"Ask him to try, but take over when the crying grows","then":"The crying grows and you step in. He hands over gratefully."}],"why":"Letting Dad comfort, even clumsily, is how fathers get good at it."},{"prompt":"A week later, your child falls at the park and looks at both of you. What do you do?","options":[{"text":"Rush over first, as always","then":"Your child sobs into your shoulder while Dad holds the water bottle."},{"text":"Say Dad can take the next one, and comfort them now","then":"Your child gets your hug. \"Next time\" comes and goes."},{"text":"Walk over with Dad to check on the knee too","then":"You both reach your child. You end up doing the comforting."},{"text":"Stay put and let him kneel and check the knee","then":"Dad checks the knee and lets your child choose the plaster.","best":true}],"why":"Staying back lets your child turn to Dad and lets Dad practise."},{"prompt":"At 2am your child cries out and you both wake. What do you do?","options":[{"text":"Say \"Your turn tonight. I'll take the next one\" and roll over","then":"He groans and goes. Twenty minutes later he comes back, pleased.","best":true},{"text":"Wait to see if he wakes up on his own","then":"He sleeps on. You give in after ten minutes and get up."},{"text":"Go yourself, since you're already awake","then":"You settle your child quickly. Dad is asleep before you're back."},{"text":"Nudge him, then follow to supervise","then":"He soothes your child while you hover. His hands fumble under your gaze."}],"why":"Taking turns at night builds his skill and lets you both rest."},{"prompt":"At bedtime, a month on, your child wakes from a bad dream and calls out \"Mama!\" Dad is right there. What do you do?","options":[{"text":"Let Dad go in first, and wait at the door","then":"Dad sits on the bed and rubs your child's back. The sobs slow, and your child leans into him.","best":true},{"text":"Go in first, since it's your name being called","then":"Your child settles in your arms. Dad stands in the doorway, unsure what to do."},{"text":"Send Dad in, but call advice from the hallway","then":"He goes in, but your calls make him second-guess himself. Your child stays restless."},{"text":"Go in together and let your child choose who to hold","then":"Your child reaches for you, and Dad steps back to the doorway."}],"why":"When your child sees Dad comfort, tenderness becomes something fathers do."}],"debrief":"Letting dad comfort, even clumsily, teaches kids that fathers are tender too.","relearn":"When kids watch dad soothe, they learn tenderness is for fathers too."},
  {"id":"ep2-1195","cat":"kids-are-watching","type":"branch","persona":"Meena","source":"mocks dad","hook":"Papa is washing up after lunch, and your son finds it very funny.","steps":[{"prompt":"Your son giggles and calls his cousins to watch. What do you do?","options":[{"text":"Scold him sharply for laughing","then":"Your son stops, red-faced. The kitchen turns tense."},{"text":"Wave the kids out so Papa isn't embarrassed","then":"The kids run out, still laughing, and Papa goes on washing alone."},{"text":"Say calmly that both parents run the home","then":"Your son stops giggling. \"Both?\" Papa nods, hands deep in the suds.","best":true},{"text":"Laugh along so it stays a joke","then":"Your son laughs harder. Papa's smile turns thin."}],"why":"Saying it is normal, not funny, resets what your son thinks is ordinary."},{"prompt":"Later your son wonders aloud whether other papas do washing too. What do you say?","options":[{"text":"Ask him why he wants to know","then":"He shrugs. \"Just.\" The question hangs in the room."},{"text":"Say it doesn't matter what other papas do","then":"He shrugs, still unsure whether Papa is odd or not."},{"text":"Say some do, but most don't","then":"He nods. \"So Papa is unusual.\""},{"text":"Say many do, and name a few you know","then":"He counts on his fingers. \"Chintu's papa cooks too.\"","best":true}],"why":"Showing he is one of many makes a caring dad feel ordinary."},{"prompt":"A classmate visits, sees Papa at the sink and says he has never seen a dad do dishes. What do you do?","options":[{"text":"Say Papa is just helping today","then":"The classmate nods. Your son says nothing."},{"text":"Tell the classmate that isn't polite","then":"The classmate flushes. Your son shrinks a little."},{"text":"Send both boys off to play","then":"They run off, and the remark goes unanswered."},{"text":"Say lightly that everyone here does dishes","then":"The classmate shrugs. \"Cool.\" Your son picks up a towel.","best":true}],"why":"Saying it lightly, as a fact of your home, lets both boys hear it as normal."},{"prompt":"Your son asks if he can wash up with Papa tonight. What do you do?","options":[{"text":"Say yes and leave them to it","then":"Your son and Papa argue about soap. The plates come out fine.","best":true},{"text":"Say tonight is homework night, so not yet","then":"He nods and goes to his books. The offer is not repeated."},{"text":"Say he can watch Papa but not touch the plates","then":"He watches from a stool, bored, and drifts away."},{"text":"Say yes, then redo the plates once he's gone","then":"They look clean to him. You rewash three plates while he sleeps."}],"why":"Letting him do it his way makes shared work feel like his own, not a favour."}],"debrief":"Treating a caring dad as ordinary, not a punchline, resets what your son thinks is normal.","relearn":"Naming a dad's care as completely normal stops a child filing it as funny."},
  {"id":"ep2-1196","cat":"kids-are-watching","type":"branch","persona":"Priya","source":"women serve","hook":"Guests arrive, and your kids watch the women rush to serve while the men sit.","steps":[{"prompt":"Your husband is among the men seated. What do you do?","options":[{"text":"Ask your husband to serve with you","then":"He stands. An uncle raises an eyebrow, and the kids see Papa carrying tea.","best":true},{"text":"Let the old pattern run to keep the peace","then":"The women stay on their feet, and the kids watch it all."},{"text":"Send your daughter to help serve, not your son","then":"Your daughter carries plates. Your son stays with the uncles."},{"text":"Serve everyone yourself, then join the guests","then":"Everyone is fed by you. You sit down to cold tea."}],"why":"Hosting together in front of the kids rewrites the scene they are learning from."},{"prompt":"Later, your son picks up a tray, and your mother-in-law whispers, \"Boys don't serve. Let him sit.\" What do you say?","options":[{"text":"Say warmly that in your home everyone hosts","then":"She frowns but lets him carry the tray, and says nothing more.","best":true},{"text":"Say you'll talk later, and let her take the tray","then":"She sends your son back to the sofa. Your kids saw you agree."},{"text":"Whisper back that she is old-fashioned","then":"She stiffens and goes to the kitchen alone."},{"text":"Say okay, just for today, to keep her happy","then":"She nods, pleased. Your son puts the tray down and sits."}],"why":"Saying it warmly keeps her close and shows the kids your home rule."},{"prompt":"At the next gathering, the kids are told to help serve. Your son heads for the sofa. What do you do?","options":[{"text":"Call both kids to take a tray each","then":"Your son groans, then takes a tray. Your daughter smiles.","best":true},{"text":"Let your daughter go and let your son sit, since it's easier","then":"Your daughter serves alone, and her brother watches cricket."},{"text":"Promise him sweets if he helps","then":"He carries one tray, collects the sweets and expects them next time."},{"text":"Ask your son once, then let it go if he refuses","then":"He refuses. Your daughter picks up his tray as well."}],"why":"Giving both kids the same job, without a bargain, makes serving everyone's duty."}],"debrief":"Sharing the hosting before the kids, men included, rewrites the gendered scene.","relearn":"When kids watch both parents host and serve, they learn hosting has no gender."},
  {"id":"ep2-1197","cat":"kids-are-watching","type":"reflect","persona":"any","source":"first textbook","hook":"Lensy: your home is the first 'textbook' on men and women your child ever reads. Sit with that?","prompt":"What comes up for you?","options":["It lands","First textbook","I'll be mindful"],"affirm":"A child's first lesson on what men and women do comes from the home they watch, long before any school.","relearn":"Home is a child's first textbook on gender roles; what they watch there is read as the truth."},
  {"id":"ep2-1198","cat":"kids-are-watching","type":"reflect","persona":"Priya","source":"son future wife","hook":"Lensy: the way your son sees his dad treat you is the blueprint he'll carry into his own home. Feel it?","prompt":"What's your take?","options":["I feel it","A blueprint","Worth getting right"],"affirm":"A son watches how his father shares and respects at home, and carries that blueprint into his own family.","relearn":"How a son watches his dad share and respect at home becomes the blueprint for his own future family."},
  {"id":"ep2-1199","cat":"kids-are-watching","type":"reflect","persona":"any","source":"silence teaches too","hook":"Lensy: even on a quiet day, who does what at home is teaching your kids something. Notice that?","prompt":"What do you think?","options":["I notice","Always teaching","Even quietly"],"affirm":"There's no neutral day; the everyday split of care your kids watch is teaching them, whether you mean it or not.","relearn":"There is no off day; the daily split of care your kids watch is always teaching them what's normal."},
  {"id":"ep2-1200","cat":"kids-are-watching","type":"reflect","persona":"Meena","source":"daughter whole person","hook":"Lensy: your daughter learns whether a mum can be a whole person, with her own work and rest, by watching you. Big?","prompt":"What's your take?","options":["Big","A whole person","She's watching"],"affirm":"A daughter learns a mother can have her own work, rest and dreams by watching one who keeps them.","relearn":"A daughter learns a mum can be a whole person, with her own life, by watching one who keeps hers."},
  {"id":"ep2-1201","cat":"kids-are-watching","type":"reflect","persona":"any","source":"copy not comply","hook":"Lensy: your kids will copy what they see you both do, not what you tell them to do. Sit with that?","prompt":"What comes up?","options":["It's true","Copy, not comply","Noted"],"affirm":"Children copy the example they watch far more reliably than they follow the instructions they're given.","relearn":"Kids copy what they watch you do far more than they obey what they're told; the example is the lesson."},
  {"id":"ep2-1202","cat":"kids-are-watching","type":"reflect","persona":"any","source":"both parents capable","hook":"Lensy: when kids see both parents handle a fever, a tantrum and a tiffin, they learn either parent can. Worth it?","prompt":"What's your take?","options":["Worth it","Either parent can","Good lesson"],"affirm":"When kids watch both parents handle the messy, hard care, they learn competence in care isn't a gender.","relearn":"Kids who watch both parents handle the hard care learn either parent is capable; care isn't a gender."},
  {"id":"ep2-1203","cat":"kids-are-watching","type":"reflect","persona":"Priya","source":"new family normal","hook":"Lensy: you get to decide what 'a normal family' looks like to your kids, starting with today. Powerful?","prompt":"What do you feel?","options":["Powerful","Starting today","It's ours to set"],"affirm":"What 'normal' looks like to your children is being set by what they watch at home, and you help shape it.","relearn":"You help set what 'a normal family' means to your kids by what they watch you both do at home."},
  {"id":"ep2-1204","cat":"kids-are-watching","type":"reflect","persona":"Meena","source":"chain ends here","hook":"Lensy: the unequal split you may have grown up in can stop with you, so your kids start fresh. Sit with it?","prompt":"What's your take?","options":["It can stop here","A fresh start","I'll try"],"affirm":"The home pattern you inherited can end with your generation; a shared home gives your kids a new starting point.","relearn":"An inherited unequal split can stop with you; a shared home hands your kids a fresh starting point."},
  {"id":"ep2-1205","cat":"kids-are-watching","type":"reflect","persona":"any","source":"small eyes watching","hook":"Lensy: the small eyes in your home clock who's tired, who rests, who's always 'on'. Did you realise?","prompt":"What comes up?","options":["I realise now","Small eyes","They clock it"],"affirm":"Children quietly notice who is always 'on' and who gets to rest, and they learn whose comfort counts.","relearn":"Kids quietly notice who's always 'on' and who rests, learning whose comfort and time are treated as theirs."},
  {"id":"ep2-1206","cat":"kids-are-watching","type":"reflect","persona":"any","source":"sons gain too","hook":"Lensy: a boy who learns to cook, care and clean grows up able to run his own life, not just lucky to find a wife. Yes?","prompt":"What's your take?","options":["Yes","He gains too","A gift to him"],"affirm":"Teaching a son to cook, care and keep house is a gift to him; he grows up able to run his own life.","relearn":"A son taught to cook, care and clean gains independence; the skills serve him, they don't weaken him."},
  {"id":"ep2-1207","cat":"kids-are-watching","type":"reflect","persona":"Priya","source":"watch then expect","hook":"Lensy: the home your kids watch today quietly sets what they'll expect from a partner tomorrow. Big thought?","prompt":"What do you feel?","options":["Big thought","Watch then expect","Long reach"],"affirm":"What children watch at home becomes the standard they'll expect from, and bring to, their own partnerships.","relearn":"The home kids watch now sets what they'll expect from a partner, and what they'll offer, as adults."},
  {"id":"ep2-1208","cat":"kids-are-watching","type":"match","persona":"any","source":"home to belief","hook":"Match a home a child watches to the belief it quietly plants.","pairs":[{"left":"Papa cooks dinner on weeknights","right":"A kitchen belongs to everyone"},{"left":"Both parents at the doctor visit","right":"Caring for a sick child is a shared duty"},{"left":"Mum keeps her own job and rest","right":"A mother is a full person too"},{"left":"Dad comforts a crying toddler","right":"Fathers can be gentle and present"},{"left":"Decisions made by both together","right":"Partners are equals, not boss and helper"}],"relearn":"Each home pattern a child watches plants a belief about who cooks, who cares, and who counts as an equal."},
  {"id":"ep2-1209","cat":"kids-are-watching","type":"match","persona":"any","source":"unequal to lesson","hook":"Match an unequal home pattern to the lesson a watching child takes from it.","pairs":[{"left":"Only mum ever cooks and cleans","right":"Housework is a woman's job"},{"left":"Dad never changes a nappy","right":"Babies are not a father's concern"},{"left":"Sister serves, brother is served","right":"Girls exist to wait on boys"},{"left":"Dad praised loudly for any care","right":"A father's care is a rare favour"},{"left":"Mum's needs always come last","right":"A mother's own comfort doesn't matter"}],"relearn":"Each unequal pattern a child watches teaches a lesson about whose work care is and whose needs come last."},
  {"id":"ep2-1210","cat":"kids-are-watching","type":"match","persona":"Priya","source":"who does, who learns","hook":"Match what a child sees a parent do to who they grow up believing should do it.","pairs":[{"left":"Papa packs school bags each morning","right":"Either parent can run the school routine"},{"left":"Both parents track fees and forms","right":"Remembering kid-stuff isn't only mum's"},{"left":"Dad nurses a sick child overnight","right":"Nights with kids are a shared job"},{"left":"Parents split the festival cooking","right":"Feeding the family isn't gendered"},{"left":"Both attend sports day","right":"Showing up for kids is for both"}],"relearn":"What a child watches a parent do becomes who they believe should do it."},
  {"id":"ep2-1211","cat":"kids-are-watching","type":"match","persona":"any","source":"reframe lines","hook":"Match a thing your child says to the reframe that reteaches them in the moment.","pairs":[{"left":"'Cooking is only for mummies'","right":"'See? Papa cooks for us too'"},{"left":"'Boys don't cry'","right":"'Everyone has big feelings, even Papa'"},{"left":"'Cleaning is a girl's job'","right":"'In our home, all of us tidy up'"},{"left":"'Babies need only their mum'","right":"'Papa feeds and rocks you as well'"},{"left":"'Dad earns, mum does the rest'","right":"'We both earn and we both care'"}],"relearn":"A gentle reframe in the moment, backed by what the child sees you do, reteaches what they just assumed."},
  {"id":"ep2-1212","cat":"kids-are-watching","type":"match","persona":"any","source":"shared home gains","hook":"Match a shared-home habit to the strength it builds in a watching child.","pairs":[{"left":"A son taught to cook and clean","right":"Grows up able to run his own home"},{"left":"A daughter who sees mum work","right":"Aims high without guilt"},{"left":"Kids watching parents share","right":"Expect equality in their own homes"},{"left":"A boy watching dad be tender","right":"Learns to name his feelings safely"},{"left":"Children seeing joint decisions","right":"Learn to listen and decide fairly"}],"relearn":"Every shared-home habit a child watches builds a real strength they carry into adulthood."},
  {"id":"ep2-1213","cat":"kids-are-watching","type":"match","persona":"Meena","source":"cycle break","hook":"Match a thing you change at home to the cycle it helps your kids break.","pairs":[{"left":"Dad starts owning the night feeds","right":"Care won't skip the next men"},{"left":"Sons given the same chores as girls","right":"The chore divide ends with your kids"},{"left":"Mum stops carrying the load alone","right":"Daughters won't assume it's theirs"},{"left":"Both parents plan the week openly","right":"The mental load stops being invisible"},{"left":"You name a relative's old script","right":"Kids see the old norm can be questioned"}],"relearn":"Each thing you change at home helps your kids break a piece of the inherited cycle."},
  {"id":"ep2-1214","cat":"kids-are-watching","type":"match","persona":"any","source":"see vs hear","hook":"Match what parents often say to kids with what those kids learn from watching.","pairs":[{"left":"'We treat each other as equals'","right":"Learned only if the home shows it"},{"left":"'Respect women, beta'","right":"Sunk in when dad shares the work"},{"left":"'Your father loves you'","right":"Believed when dad is present, not just earning"},{"left":"'Help your mother out'","right":"Heard as 'it's her job, you assist'"},{"left":"'Both parents matter equally'","right":"Real when both show up, not just one"}],"relearn":"Children learn from the home they watch, not the lines they're told; words land only if the example backs them."},
  {"id":"ep2-1215","cat":"kids-are-watching","type":"match","persona":"any","source":"task to shared owner","hook":"Match a daily care task to how a shared home teaches kids it gets owned.","pairs":[{"left":"The morning school rush","right":"Whoever's free leads it, not always mum"},{"left":"A child's doctor appointment","right":"Either parent books and takes them"},{"left":"Helping with homework","right":"Both parents take turns through the week"},{"left":"Soothing a midnight nightmare","right":"Whichever parent the child reaches for"},{"left":"Remembering a friend's birthday gift","right":"Tracked by both, not one parent's head"}],"relearn":"A shared home shows kids each care task is owned by whoever's free, not defaulted to one parent."},
  {"id":"ep2-1216","cat":"kids-are-watching","type":"spot","persona":"Meena","source":"two old-divide signals","hook":"Spot the two moments that quietly teach your kids the old gender divide.","scene":[{"id":"a","text":"Both parents wash up together after dinner","trick":false},{"id":"b","text":"Daughter told to serve her brother first","trick":true},{"id":"c","text":"Papa helps with homework at the table","trick":false},{"id":"d","text":"'Cooking is your mother's job,' dad tells the son","trick":true},{"id":"e","text":"Mum and dad plan the school week jointly","trick":false}],"why":"Telling a daughter to serve her brother and calling cooking 'mum's job' teach kids the old, gendered divide.","relearn":"Kids learn the old divide from gendered serving rules and 'that's mum's job' lines, not from shared care."},
  {"id":"ep2-1217","cat":"kids-are-watching","type":"spot","persona":"Priya","source":"two helper-frame slips","hook":"Spot the two lines that teach kids a dad's care is just 'helping mum', not his own job.","scene":[{"id":"a","text":"'Papa, can you babysit while I cook?'","trick":true},{"id":"b","text":"'Papa's taking you to the doctor today'","trick":false},{"id":"c","text":"'Look how he helps me out with the kids!'","trick":true},{"id":"d","text":"'Both of us are putting you to bed tonight'","trick":false},{"id":"e","text":"'Papa packed your tiffin this morning'","trick":false}],"why":"Calling a dad's time with his own kids 'babysitting' or 'helping me' teaches kids care is mum's, dad just assists.","relearn":"'Babysitting' and 'helping me' frame a dad's care as a favour; kids learn it's optional for men."},
  {"id":"ep2-1218","cat":"kids-are-watching","type":"spot","persona":"Meena","source":"two distance signals","hook":"Spot the two moments that teach kids fathers keep an emotional distance.","scene":[{"id":"a","text":"Papa hugs the toddler after a fall","trick":false},{"id":"b","text":"'Go cry to your mother, I can't deal with this'","trick":true},{"id":"c","text":"Dad sits and hears out a kid's hard day","trick":false},{"id":"d","text":"'Feelings are a mum thing, ask her,' says dad","trick":true},{"id":"e","text":"Papa sings the baby back to sleep","trick":false}],"why":"Pushing every upset and feeling to mum teaches kids that fathers stay distant from the soft, tender side of care.","relearn":"Sending all comfort and feelings to mum teaches kids dads keep distant; a soothing dad teaches the opposite."},
  {"id":"ep2-1219","cat":"kids-are-watching","type":"spot","persona":"Priya","source":"two gendered chore slips","hook":"Spot the two moments that teach kids chores come with a gender.","scene":[{"id":"a","text":"Son and daughter both learn to make tea","trick":false},{"id":"b","text":"Boy handed pocket money, girl handed a broom","trick":true},{"id":"c","text":"Both kids fold their own clothes","trick":false},{"id":"d","text":"'Sweeping isn't for boys,' the son is told","trick":true},{"id":"e","text":"Brother and sister share the washing-up","trick":false}],"why":"Handing the broom to the girl and excusing the boy from sweeping teach kids that chores are split by gender.","relearn":"Splitting chores by sex teaches kids housework has a gender; the same tasks for all teach it doesn't."},
  {"id":"ep2-1220","cat":"kids-are-watching","type":"spot","persona":"any","source":"two undermining lines","hook":"Spot the two remarks that quietly undermine the equality your kids are watching for.","scene":[{"id":"a","text":"'We decided the budget together, kids'","trick":false},{"id":"b","text":"'Real men don't do dishes,' jokes dad","trick":true},{"id":"c","text":"'Both of us will be at your match'","trick":false},{"id":"d","text":"'Your mum's the boss of all this kid stuff'","trick":true},{"id":"e","text":"'Papa and I both cooked tonight'","trick":false}],"why":"'Real men don't do dishes' and 'mum's the boss of kid stuff' teach kids care is women's and men opt out.","relearn":"Throwaway lines that brand care as women's work undermine the equality kids are watching you live."},
  {"id":"ep2-1221","cat":"kids-are-watching","type":"spot","persona":"Priya","source":"two daughter-limiting","hook":"Spot the two moments that teach a daughter to shrink her own future.","scene":[{"id":"a","text":"Mum keeps her job and her hobbies","trick":false},{"id":"b","text":"'Learn to cook, that's what a wife needs'","trick":true},{"id":"c","text":"Parents cheer her science project","trick":false},{"id":"d","text":"'No point studying too much, you'll marry'","trick":true},{"id":"e","text":"Dad helps her with her maths homework","trick":false}],"why":"Telling a girl her future is cooking and that study is pointless once she marries teaches her to shrink her own life.","relearn":"Lines that reduce a daughter's future to marriage and housework teach her to expect less; her watching takes it in."},
  {"id":"ep2-1222","cat":"kids-are-watching","type":"spot","persona":"Meena","source":"two invisible-load signals","hook":"Spot the two moments that teach kids the planning is mum's invisible job, not shared.","scene":[{"id":"a","text":"Both parents fill the family calendar","trick":false},{"id":"b","text":"'Ask your mother, she knows the schedule'","trick":true},{"id":"c","text":"Dad openly tracks the kids' vaccines","trick":false},{"id":"d","text":"'Papa, what do I need to buy?' every time","trick":true},{"id":"e","text":"Parents plan the school year together","trick":false}],"why":"Defaulting every plan and reminder to mum teaches kids the remembering is hers alone, an unshared load.","relearn":"When dad always sends kids to mum for plans, they learn the mental load is mum's invisible job."},
  {"id":"ep2-1223","cat":"kids-are-watching","type":"role-play","persona":"Priya","source":"son cooking is girls","hook":"At dinner your young son has a new idea about who cooks, and his little sister listens.","setup":"Papa is passing the rice at the other end of the table.","steps":[{"prompt":"Your son says: \"Cooking is for girls, Mummy.\"","options":[{"text":"\"Don't say silly things.\" Then you change the topic and pass the dal.","then":"Your son goes quiet. \"It's not silly,\" he mutters into his plate."},{"text":"\"Girls are often good at it, beta. It suits them well.\"","then":"Your son nods, pleased. His sister looks at her plate."},{"text":"\"Let's not talk about that at the table, beta.\"","then":"Your son shrugs. \"Okay, Mummy.\" His sister looks up at you."},{"text":"\"Cooking's for everyone. Papa makes the best omelette.\"","then":"Your son looks at Papa. \"Omelette? Can I crack the eggs?\"","best":true}],"why":"Naming the dad who cooks, in the moment, shows both kids that cooking has no gender."},{"prompt":"The next evening, your son asks: \"Why does Anya always help you cook, and not me?\"","options":[{"text":"\"Fair point. You and Anya will take turns.\"","then":"Your son groans, then grins. \"Can I do the eggs?\"","best":true},{"text":"\"Because girls learn it early, beta. It's normal.\"","then":"Your son nods, satisfied. His sister says nothing."},{"text":"\"She likes it. You can go and play instead.\"","then":"Your son runs off. His sister carries the plates alone."},{"text":"\"Ask Papa. He will explain it to you properly.\"","then":"Papa says, \"Well, ask your mother.\" Your son stays confused."}],"why":"Turns for both kids make the fairness real, not just a saying."},{"prompt":"Your daughter says quietly: \"Bhaiya says I'll have to cook for him when we're big.\"","options":[{"text":"\"Nobody owes anyone cooking. You both learn, and take turns.\"","then":"Her shoulders drop. \"Even Bhaiya?\" \"Even Bhaiya,\" you say.","best":true},{"text":"\"Well, you might want to one day. Cooking is a joy.\"","then":"She looks uncertain. The idea stays with her."},{"text":"\"Don't listen to him, sweetheart. He's just a boy.\"","then":"She giggles, but \"just a boy\" makes her brother scowl."},{"text":"\"Tell him you'll cook only if he does the washing up.\"","then":"She grins and runs to strike the deal. The cooking is still hers."}],"why":"Saying that everyone looks after themselves frees her from a job she never chose."}],"relearn":"Naming a dad who cooks, in the moment your son assumes otherwise, reteaches both kids that cooking has no gender."},
  {"id":"ep2-1224","cat":"kids-are-watching","type":"role-play","persona":"Meena","source":"daughter quit work","hook":"Your daughter has been wondering what happens to mothers' jobs.","setup":"She asks while you plait her hair.","steps":[{"prompt":"Your daughter asks: \"Mums stop working once they have a baby, na?\"","options":[{"text":"\"Every family is different, beta. Now sit still for me.\"","then":"She sits still, but can't picture what \"different\" looks like."},{"text":"\"Some mums do and some don't. Papa and I both worked. You'll choose.\"","then":"Her eyes go round. \"Both? Who looked after me?\" You smile.","best":true},{"text":"\"Yes, that's how it usually goes for mothers, beta.\"","then":"She nods slowly, frowning a little."},{"text":"\"Why do you ask? Are you worried about something?\"","then":"She shrugs. \"Nothing.\" A moment later, she tries again."}],"why":"Sharing your own story, and leaving her the choice, shows her a mother's life can hold work and care."},{"prompt":"Your daughter asks: \"Who feeds a baby if its mother goes to work?\"","options":[{"text":"\"That's a lot to think about. Let's finish your hair.\"","then":"She sighs and lets the question go."},{"text":"\"Papa, Nani and I took turns. We planned it together.\"","then":"She counts on her fingers. \"Three people?\" \"Sometimes four,\" you say.","best":true},{"text":"\"Nani helps. Mothers can always ask their mothers.\"","then":"She nods. Nani's part is clear, and Papa's isn't mentioned."},{"text":"\"The mother rushes home to do it herself.\"","then":"Her forehead creases. \"That sounds tiring.\""}],"why":"Saying who shared the care shows her it is a team job, not a mother's alone."},{"prompt":"Your daughter asks: \"Will I have to quit my job for my baby, one day?\"","options":[{"text":"\"Mothers always find a way, beta. You'll manage.\"","then":"She nods, but \"manage\" sounds like doing it all alone."},{"text":"\"Maybe, but it will feel worth it in the end.\"","then":"She goes quiet, as if it is already decided."},{"text":"\"Nobody has to. You and your partner decide together.\"","then":"She nods. \"Like you and Papa.\" \"Exactly like that,\" you say.","best":true},{"text":"\"It depends on your husband's job and his hours.\"","then":"She frowns. \"Why his job and not mine?\""}],"why":"Deciding together, as equals, keeps her future open to both work and care."},{"prompt":"Your daughter says: \"When I grow up I'll work, and my husband can look after the baby.\"","options":[{"text":"\"Let's not plan that far ahead, beta.\"","then":"She shrugs. The question stays in the air."},{"text":"\"Husbands don't usually like that, beta.\"","then":"She thinks. \"Then I'll find one who does.\""},{"text":"\"That sounds nice, but a baby needs its mother.\"","then":"She frowns. \"Why does the baby only need its mother?\""},{"text":"\"That can work. So can sharing it, beta.\"","then":"She grins. \"Like you and Papa did.\" \"Like that,\" you say.","best":true}],"why":"Affirming her plan and offering sharing keeps the choice hers."}],"relearn":"Showing a daughter that both parents worked and cared widens what she believes a mother's life can hold."},
  {"id":"ep2-1225","cat":"kids-are-watching","type":"role-play","persona":"Priya","source":"son mocks dad washing","hook":"Your son is at the age where he notices who does which job at home.","setup":"Papa is pegging shirts on the line while you sit with the kids.","steps":[{"prompt":"Your son laughs: \"That's a funny job for Papa!\"","options":[{"text":"\"Ha, yes! Your dad is quite the housewife!\"","then":"Your son roars with laughter. Papa's smile fades a little."},{"text":"\"Nothing funny. Running our home is both our job.\"","then":"Your son stops laughing. \"Both?\" Papa nods, pegging a shirt.","best":true},{"text":"\"Papa is just helping me out today, beta.\"","then":"Your son nods. \"So Papa is a helper.\""},{"text":"\"Shh, don't laugh at Papa. That isn't nice, beta.\"","then":"Your son goes quiet, unsure why it was wrong."}],"why":"Calling it normal, not funny, keeps a caring dad from becoming a joke."},{"prompt":"Your son asks: \"Does Papa do it because you told him to?\"","options":[{"text":"\"No. We share the work. Papa does his part unasked.\"","then":"Your son thinks. \"Like you do.\" Papa grins from the line.","best":true},{"text":"\"Yes, I asked, and he was kind enough to agree.\"","then":"Your son nods. \"So Papa does it as a favour.\""},{"text":"\"Ask Papa, beta. That is between him and me.\"","then":"Papa laughs and shrugs. Your son looks confused again."},{"text":"\"Sometimes I remind him, and sometimes he remembers.\"","then":"Your son smirks. \"So Papa forgets.\""}],"why":"Sharing without reminders shows him a dad who owns his part."},{"prompt":"Your son's friend says: \"My papa says laundry is for mummies.\"","options":[{"text":"\"Please don't say that here. Be polite, beta.\"","then":"The friend flushes and goes quiet. Your son looks uneasy."},{"text":"\"Yes, mostly. Papa is just being kind today.\"","then":"Your son looks at Papa, then at his friend, and says nothing."},{"text":"\"In our house it's whoever's turn. Try pinning a shirt.\"","then":"The boys pin socks together and argue over whose is straighter.","best":true},{"text":"\"Every house is different, beta. Come and have juice.\"","then":"The boys run off. The friend's idea goes home with him."}],"why":"Letting kids try it themselves shows that laundry has no gender."}],"relearn":"Naming home-running as normal for both parents stops a child filing a caring dad as funny or unusual."},
  {"id":"ep2-1226","cat":"kids-are-watching","type":"role-play","persona":"Meena","source":"son wont help sister can","hook":"Your son refuses a small chore, and both kids are watching how you respond.","setup":"The table still needs wiping after dinner.","steps":[{"prompt":"Your son says: \"Let Didi wipe it. That's girls' work.\"","options":[{"text":"\"Stop saying that. Go to your room right now.\"","then":"He stomps off. The table stays wet and your daughter goes silent."},{"text":"\"Please, beta, just do it for Mummy's sake.\"","then":"He wipes one corner and hands you the cloth."},{"text":"\"Fine, your sister can do it this once, beta.\"","then":"Your daughter sighs and reaches for the cloth. Her brother sits down."},{"text":"\"Whoever's turn it is wipes it. Papa did yesterday. It's yours.\"","then":"He scowls, takes the cloth, and wipes with big, slow strokes.","best":true}],"why":"A fair turn, with Papa's turn named, tells both kids the chore has no gender."},{"prompt":"Your daughter says quietly: \"I don't mind wiping it, Mummy.\"","options":[{"text":"\"Thank you, beta. You are such a good girl.\"","then":"She beams and wipes the whole table while her brother watches."},{"text":"\"I know. It's not only yours. We take turns.\"","then":"She smiles a little. \"Okay. Then he can do the cups too.\"","best":true},{"text":"\"Then let him off tonight, since he's tired.\"","then":"Her brother slips away. She wipes the table on her own."},{"text":"\"All right, but tell me if it ever bothers you.\"","then":"She nods. She says nothing the next night either."}],"why":"Saying it isn't only hers frees her from a job nobody asked her to keep."},{"prompt":"The next night, your son grumbles: \"Papa never does it at Dadi's house.\"","options":[{"text":"\"True. Let's not fuss at Dadi's. Only here.\"","then":"He shrugs. \"So it's only a home rule.\""},{"text":"\"Papa's turn counts there too. Turns, always.\"","then":"He huffs, then nods. \"So Papa wipes at Dadi's too?\" \"When it's his turn,\" you say.","best":true},{"text":"\"Don't compare us with Dadi. Just do it, beta.\"","then":"He mutters something and bangs the chair in."},{"text":"\"True. Papa is a guest there, so he rests.\"","then":"He nods, pleased. \"So guests don't work?\""}],"why":"Naming Papa's turn wherever you are shows him fairness travels with you."}],"relearn":"Holding a son to a fair turn, and naming dad's turn too, teaches both kids chores aren't a girl's job."},
  {"id":"ep2-1227","cat":"kids-are-watching","type":"role-play","persona":"Priya","source":"relative dad helps so much","hook":"A relative makes a remark to your kids about how much their papa does.","setup":"Everyone is having tea after the function.","steps":[{"prompt":"A relative tells your kids: \"You're lucky. Your papa helps your mummy so much!\"","options":[{"text":"\"He isn't helping me. He's parenting his own kids.\"","then":"The relative blinks, then laughs. Your kids look at Papa.","best":true},{"text":"\"Yes, we're so lucky he pitches in when he can.\"","then":"The relative beams, and your kids nod along."},{"text":"\"Thank you, Aunty. That's kind of you to say.\"","then":"She pats your cheek. The remark stands, and your kids heard it."},{"text":"\"Let's not talk about that now, Aunty, please.\"","then":"She looks puzzled. \"I was only being nice.\""}],"why":"Papa is parenting, not helping, and the kids hear it said kindly."},{"prompt":"The relative adds: \"Of course, it's the mother who really takes care.\"","options":[{"text":"\"We both do. Feeds, fevers, school. All shared here.\"","then":"She blinks. \"Both? Hm. Times have changed.\"","best":true},{"text":"\"Of course. A mother always knows best.\"","then":"She smiles, happy. Your kids watch you say it."},{"text":"\"Well, it depends on the day, Aunty.\"","then":"She nods, unconvinced. \"Mostly the mother, I'd say.\""},{"text":"\"Papa earns and I do the rest. That's how we manage.\"","then":"\"Wonderful,\" she says. Your kids listen without a word."}],"why":"Saying it is shared, with examples, answers her without a debate."},{"prompt":"The relative tells Papa: \"In our day, men never set foot in the kitchen, beta.\"","options":[{"text":"\"And now they do, Aunty. We share the kitchen and the kids.\"","then":"Papa laughs. \"True, Aunty. My dal is famous.\"","best":true},{"text":"\"Papa, tell her yourself. I'll stay out of it.\"","then":"Papa mumbles something about work. The moment slips by."},{"text":"\"Aunty, he only cooks because I ask him nicely.\"","then":"She nods, satisfied. Papa's smile freezes."},{"text":"\"Ha ha, you know how it is, Aunty.\"","then":"She winks at Papa. He looks down at his tea."}],"why":"Saying plainly that you share it lets Papa join in, as an owner and not a helper."}],"relearn":"Reframing 'helping mum' as a dad parenting his own kids teaches them care is shared, not a man's favour."},
  {"id":"ep2-1228","cat":"kids-are-watching","type":"role-play","persona":"Meena","source":"son boys dont cry","hook":"Your son has passed a rule about feelings to his younger brother.","setup":"You overhear them in the bedroom before bed.","steps":[{"prompt":"Your son tells his brother: \"Boys don't cry. Only girls do.\"","options":[{"text":"\"Stop teasing your brother right now, both of you.\"","then":"The older one sulks. \"I was only telling him the rule.\""},{"text":"\"Well, try to be a brave boy anyway, my dear.\"","then":"He wipes his eyes hard and stares at the floor."},{"text":"\"Everyone cries, beta, even Papa and me. It's normal.\"","then":"Your younger son sniffles. \"Even Papa cries?\" \"Even Papa,\" you say.","best":true},{"text":"\"He's little. He'll learn to stop soon enough.\"","then":"The younger one gulps. The rule still stands in the room."}],"why":"Saying everyone cries, Papa too, takes the gender out of feelings."},{"prompt":"Your older son says: \"Papa never cries. I've never seen it.\"","options":[{"text":"\"Some people cry less. Never mind, go to sleep.\"","then":"They lie down, and the question is left in the dark."},{"text":"\"Papa is strong. That's why he doesn't.\"","then":"He nods, proud. His brother wipes his face quickly."},{"text":"\"Papa's a grown-up, and grown-ups don't need to.\"","then":"He nods. \"So I'll stop when I'm big.\""},{"text":"\"Papa cries too, sometimes. Ask him about it tonight.\"","then":"\"Really? I'll ask.\" He looks at the door, curious.","best":true}],"why":"Inviting him to ask Papa lets him see a father with feelings."},{"prompt":"Next day your younger son sniffles: \"My friend says I'm a girl because I cried.\"","options":[{"text":"\"Ignore him, beta. He's just teasing you.\"","then":"He sniffs. \"But it still feels bad, Mummy.\""},{"text":"\"Then don't cry in front of your friends.\"","then":"He nods, wipes his face, and learns to hide it."},{"text":"\"Let's go and tell your friend's mother about this.\"","then":"He shrinks back. \"No, Mummy. It'll be worse.\""},{"text":"\"Crying means big feelings. Come here and tell me.\"","then":"He climbs into your lap and tells you all of it, hiccuping.","best":true}],"why":"Listening first tells him big feelings are fine for a boy, and he stays open to you."}],"relearn":"Naming that everyone, dad included, has big feelings reteaches kids that emotions aren't split by gender."},
  {"id":"ep2-1229","cat":"kids-are-watching","type":"role-play","persona":"Priya","source":"daughter serve brother","hook":"At a family meal your child has noticed a habit and asks about it.","setup":"Didi has just served bhaiya's plate again.","steps":[{"prompt":"Your child asks: \"Why does didi always serve bhaiya?\"","options":[{"text":"\"Didi, do you mind? Tell your brother yourself.\"","then":"Didi shrugs. \"It's fine.\" Her smile is too tight."},{"text":"\"Because she's older, beta. Eat your food now.\"","then":"Didi keeps serving. Bhaiya doesn't look up."},{"text":"\"That's just how it's always been done, beta.\"","then":"Your child frowns. \"But why?\""},{"text":"\"Good question. From now we all take turns serving.\"","then":"Bhaiya looks up, surprised. Didi's shoulders relax.","best":true}],"why":"Naming it and sharing the serving tells kids that nobody exists to wait on another."},{"prompt":"Bhaiya says: \"But Nani says a good girl serves the men first.\"","options":[{"text":"\"Nani knows best, Bhaiya. Let's not argue with her.\"","then":"Bhaiya smirks, and Didi picks up the ladle again."},{"text":"\"Nobody said Didi is bad. Sit down and eat.\"","then":"Bhaiya sits. The question stays unanswered."},{"text":"\"Nani grew up with that. In our house, everyone serves everyone.\"","then":"Nani says nothing but hands Bhaiya a plate to pass.","best":true},{"text":"\"We'll talk about Nani's rules later, in private.\"","then":"The meal carries on, and the kids have heard only Nani's side."}],"why":"Respecting Nani while stating your house rule keeps the family close and fair."},{"prompt":"Didi says quietly: \"Mummy, can I stop serving now?\"","options":[{"text":"\"Of course, beta. But do it gently around Nani.\"","then":"Didi nods. Later she serves Nani quietly anyway."},{"text":"\"Yes. We each serve ourselves from now, you too, Bhaiya.\"","then":"Bhaiya groans, then fills his own plate.","best":true},{"text":"\"Just for tonight. Nani might be upset.\"","then":"Didi nods and picks up the ladle again at the next meal."},{"text":"\"Tell Bhaiya yourself. It's between the two of you.\"","then":"Didi looks at her plate. Bhaiya keeps holding his out."}],"why":"Backing her fully, and asking Bhaiya to share, ends the habit for good."}],"relearn":"Naming the unfair serving habit and sharing it out reteaches kids that no child exists to wait on another."},
  {"id":"ep2-990","cat":"parental-mental-load","type":"strike-rewrite","hook":"\"I help a lot, so the planning side is naturally hers to hold.\"","myth":{"un":"I help a lot, so the planning side is naturally hers to hold.","re":"The planning isn't naturally anyone's; whoever ends up holding it just got handed it, and either parent can own it.","why":"Defaults feel natural but are just habits."},"relearn":"The planning isn't naturally one parent's; it got defaulted to them, and either parent can take a real share.","persona":"Vikram","source":"not naturally hers"},
  {"id":"ep2-991","cat":"parental-mental-load","type":"strike-rewrite","hook":"\"If nothing's been forgotten, the load must be fairly shared.\"","myth":{"un":"If nothing's been forgotten, the load must be fairly shared.","re":"Nothing being forgotten often means one parent is silently carrying all the tracking; smooth doesn't mean shared.","why":"A smooth home can hide one exhausted manager."},"relearn":"A home where nothing slips can still rest on one parent carrying all the tracking; smooth isn't the same as shared.","persona":"Divya","source":"smooth not shared"},
  {"id":"ep2-992","cat":"parental-mental-load","type":"strike-rewrite","hook":"\"Worrying about the kids at 2am is just a mother thing.\"","myth":{"un":"Worrying about the kids at 2am is just a mother thing.","re":"The worrying is part of the mental load, not a gender trait; a father can carry his share of the lying-awake too.","why":"Worry follows who owns the tracking, not gender."},"relearn":"Night-worry about the kids is part of the mental load both parents can carry, not a built-in mother thing.","persona":"any","source":"worry isn't gendered"},
  {"id":"ep2-993","cat":"parental-mental-load","type":"strike-rewrite","hook":"\"A shared family calendar means we've split the mental load.\"","myth":{"un":"A shared family calendar means we've split the mental load.","re":"A calendar only helps if both put things on it and act on it; if one parent fills and checks it, they still carry the load.","why":"A tool only shares load if both actually use it."},"relearn":"A shared calendar splits the load only if both parents add to it and act on it, not just one keeping it updated.","persona":"any","source":"calendar isn't sharing"},
  {"id":"ep2-994","cat":"parental-mental-load","type":"strike-rewrite","hook":"\"She just notices these things faster, so it makes sense she tracks them.\"","myth":{"un":"She just notices these things faster, so it makes sense she tracks them.","re":"She notices faster because she's been doing the tracking; let a father own a domain and he gets just as quick.","why":"Noticing is a practised skill, not an instinct."},"relearn":"One parent notices faster because they practise the tracking; owning a domain builds the same speed in either parent.","persona":"Vikram","source":"noticing is practised"},
  {"id":"ep2-995","cat":"parental-mental-load","type":"strike-rewrite","hook":"\"Once the kids are in school, the mental load basically disappears.\"","myth":{"un":"Once the kids are in school, the mental load basically disappears.","re":"School just swaps the load: fees, forms, projects, fittings and timetables are a whole new tracking job to share.","why":"The load changes shape; it doesn't go away."},"relearn":"School doesn't end the mental load; fees, forms, projects and timetables become a new tracking job to share.","persona":"Meena","source":"school load"},
  {"id":"ep2-996","cat":"parental-mental-load","type":"strike-rewrite","hook":"\"Telling my partner I'm tired of all the remembering would just sound like nagging.\"","myth":{"un":"Telling my partner I'm tired of all the remembering would just sound like nagging.","re":"Naming an invisible load you carry isn't nagging; it's the only way the work can be seen and then genuinely split.","why":"You can't share what's never named out loud."},"relearn":"Naming the invisible load you carry isn't nagging; it's how it gets seen and finally split between both parents.","persona":"Divya","source":"naming isn't nagging"},
  {"id":"ep2-997","cat":"parental-mental-load","type":"strike-rewrite","hook":"\"Grandparents help so much that there's no real mental load left to share.\"","myth":{"un":"Grandparents help so much that there's no real mental load left to share.","re":"Grandparents lighten the doing, but one parent usually still tracks and decides; that planning is the load to share.","why":"Helpers do tasks; the tracking still sits somewhere."},"relearn":"Grandparents help with tasks, but the tracking and deciding still sits with a parent; that mental load is yours to share.","persona":"any","source":"grandparents help"},
  {"id":"ep2-998","cat":"parental-mental-load","type":"strike-rewrite","hook":"\"I earn for the family, so the day-to-day kid-tracking fairly falls to her.\"","myth":{"un":"I earn for the family, so the day-to-day kid-tracking fairly falls to her.","re":"Earning is part of the job, not the whole of it; the kid-tracking is real work too and can be genuinely shared.","why":"Providing money doesn't cancel the planning work."},"relearn":"Earning is part of parenting, not all of it; the day-to-day kid-tracking is real work that can be shared too.","persona":"Vikram","source":"earning isn't enough"},
  {"id":"ep2-999","cat":"parental-mental-load","type":"strike-rewrite","hook":"\"Keeping a list on my phone of everything the kids need means I'm on top of it together.\"","myth":{"un":"Keeping a list on my phone of everything the kids need means I'm on top of it together.","re":"If only one of you keeps and acts on the list, you're not sharing; you're the sole manager with a neat list.","why":"Being organised alone is still carrying it alone."},"relearn":"Holding the whole list yourself is being a tidy sole manager, not sharing; the load lifts when both own parts of it.","persona":"Divya","source":"list isn't sharing"},
  {"id":"ep2-1000","cat":"parental-mental-load","type":"sort","hook":"Sort: someone owning a whole domain, or just doing scattered tasks on request?","items":[{"id":"a","text":"\"I run all of health, start to finish\""},{"id":"b","text":"\"I gave the baby a bath when asked\""},{"id":"c","text":"\"School is mine: fees, forms, the lot\""},{"id":"d","text":"\"I dropped him today because she told me to\""},{"id":"e","text":"\"I own meals and the grocery planning\""},{"id":"f","text":"\"I changed a nappy when she handed me one\""}],"bins":[{"id":"own","label":"Owns a domain","valence":"pos"},{"id":"task","label":"Task on request","valence":"uhoh"}],"key":{"a":"own","b":"task","c":"own","d":"task","e":"own","f":"task"},"relearn":"Running health, school or meals end-to-end is owning a domain; doing single tasks when asked is not.","persona":"Vikram","source":"own vs task"},
  {"id":"ep2-1001","cat":"parental-mental-load","type":"sort","hook":"Sort: this genuinely lifts the mental load, or it just adds to the manager's job?","items":[{"id":"a","text":"\"I'll fully own the doctor visits\""},{"id":"b","text":"\"Make me a list and I'll work through it\""},{"id":"c","text":"\"I'll track the school dates myself\""},{"id":"d","text":"\"Just remind me each time something's due\""},{"id":"e","text":"\"I'll plan and pack for the trip\""},{"id":"f","text":"\"Tell me exactly what to buy and I'll get it\""}],"bins":[{"id":"lifts","label":"Lifts the load","valence":"pos"},{"id":"adds","label":"Adds to it","valence":"neg"}],"key":{"a":"lifts","b":"adds","c":"lifts","d":"adds","e":"lifts","f":"adds"},"relearn":"Owning and tracking lifts the load; asking for lists and reminders keeps your partner managing you.","persona":"Vikram","source":"lifts or adds"},
  {"id":"ep2-1002","cat":"parental-mental-load","type":"sort","hook":"Sort: a real chunk of mental load, or a one-off five-minute task?","items":[{"id":"a","text":"Owning all the school admin for the year"},{"id":"b","text":"Signing one form she put in front of you"},{"id":"c","text":"Tracking the child's whole medical history"},{"id":"d","text":"Posting one courier when asked"},{"id":"e","text":"Knowing every birthday and gift to plan"},{"id":"f","text":"Buying one item off a sent list"}],"bins":[{"id":"load","label":"Real mental load","valence":"tell"},{"id":"oneoff","label":"One-off task","valence":"neutral"}],"key":{"a":"load","b":"oneoff","c":"load","d":"oneoff","e":"load","f":"oneoff"},"relearn":"Owning the year's admin, the medical history or the social calendar is mental load; one signed form is a task.","persona":"any","source":"load vs one-off"},
  {"id":"ep2-1003","cat":"parental-mental-load","type":"sort","hook":"Sort: a fair way to split the load, or a tidier way to keep one manager?","items":[{"id":"a","text":"Each parent owns whole domains, fully"},{"id":"b","text":"One makes the other a daily to-do list"},{"id":"c","text":"Both check and update the same calendar"},{"id":"d","text":"One is the family's single reminder app"},{"id":"e","text":"You swap who owns what every few months"},{"id":"f","text":"One keeps all the info and delegates pieces"}],"bins":[{"id":"fair","label":"Fairly split","valence":"pos"},{"id":"manager","label":"One stays manager","valence":"uhoh"}],"key":{"a":"fair","b":"manager","c":"fair","d":"manager","e":"fair","f":"manager"},"relearn":"Owning domains, sharing the calendar and swapping is fair; lists and delegating keep one as manager.","persona":"Divya","source":"fair or manager"},
  {"id":"ep2-1004","cat":"parental-mental-load","type":"sort","hook":"Sort: visible care, or the invisible mental load behind it?","items":[{"id":"a","text":"Cooking the child's dinner"},{"id":"b","text":"Knowing what they will and won't eat"},{"id":"c","text":"Dropping them at tuition"},{"id":"d","text":"Choosing the tuition and tracking fees"},{"id":"e","text":"Giving the medicine"},{"id":"f","text":"Remembering the dose, timing and refill"}],"bins":[{"id":"visible","label":"Visible care","valence":"neutral"},{"id":"mental","label":"Mental load","valence":"tell"}],"key":{"a":"visible","b":"mental","c":"visible","d":"mental","e":"visible","f":"mental"},"relearn":"Cooking, dropping and dosing are visible; knowing preferences, choosing tuition and remembering refills is the load.","persona":"any","source":"care vs load"},
  {"id":"ep2-1005","cat":"parental-mental-load","type":"sort","hook":"Sort: which belong to the parental mental load, and which don't?","items":[{"id":"a","text":"Tracking when the next jab is due"},{"id":"b","text":"Watching a cartoon with the child"},{"id":"c","text":"Planning the week's meals and supplies"},{"id":"d","text":"Carrying the child to bed once"},{"id":"e","text":"Holding every deadline and form in your head"},{"id":"f","text":"Pushing the swing at the park"}],"bins":[{"id":"load","label":"Mental load","valence":"tell"},{"id":"notload","label":"Not the load","valence":"neutral"}],"key":{"a":"load","b":"notload","c":"load","d":"notload","e":"load","f":"notload"},"relearn":"Tracking jabs, planning meals and holding deadlines is mental load; watching cartoons or pushing a swing isn't.","persona":"any","source":"load or not"},
  {"id":"ep2-1006","cat":"parental-mental-load","type":"sort","hook":"Sort: a remark that sees the mental load, or one that keeps it invisible?","items":[{"id":"a","text":"\"You're holding a lot in your head; let me own some\""},{"id":"b","text":"\"But the house runs fine, what load?\""},{"id":"c","text":"\"I'll take over remembering the medical stuff\""},{"id":"d","text":"\"You never even mentioned you were tired\""},{"id":"e","text":"\"Let's name everything you track and split it\""},{"id":"f","text":"\"You make it look easy, so it must be easy\""}],"bins":[{"id":"sees","label":"Sees the load","valence":"pos"},{"id":"hides","label":"Keeps it invisible","valence":"neg"}],"key":{"a":"sees","b":"hides","c":"sees","d":"hides","e":"sees","f":"hides"},"relearn":"Naming what a partner tracks and offering to own some sees the load; 'it looks easy' keeps it invisible.","persona":"Vikram","source":"sees or hides"},
  {"id":"ep2-1007","cat":"parental-mental-load","type":"sort","hook":"Sort: a real sign the load is shared, or only a sign it looks shared?","items":[{"id":"a","text":"Either parent knows when the next checkup is"},{"id":"b","text":"He helps a lot but always asks her what's next"},{"id":"c","text":"Both feel the worry, not just one"},{"id":"d","text":"She still 'manages' him through every task"},{"id":"e","text":"Either can run a sick day solo, start to end"},{"id":"f","text":"He does loads but she's the only planner"}],"bins":[{"id":"shared","label":"Really shared","valence":"pos"},{"id":"looks","label":"Only looks shared","valence":"uhoh"}],"key":{"a":"shared","b":"looks","c":"shared","d":"looks","e":"shared","f":"looks"},"relearn":"Either parent knowing, worrying and running a day solo is shared; doing tasks while one plans only looks shared.","persona":"Divya","source":"shared or looks"},
  {"id":"ep2-1008","cat":"parental-mental-load","type":"branch","persona":"Vikram","source":"share the worry","hook":"Your partner lies awake tracking the kids' week while you sleep fine.","steps":[{"prompt":"She sighs beside you at midnight. What do you do?","options":[{"text":"Reassure her it will be fine and roll over","then":"She goes quiet. Ten minutes later she is still staring at the ceiling."},{"text":"Take a whole domain so half the tracking is yours","then":"She turns to you. \"Which one?\" You say school, and she breathes out.","best":true},{"text":"Get up and make her tea, then go back to bed","then":"She smiles, grateful. The tracking is still all hers."},{"text":"Tell her she should switch off and sleep","then":"She bristles. \"If I stop, who will remember?\""}],"why":"Owning a whole domain moves the worry too, not just the sympathy."},{"prompt":"Over breakfast she lists the week's tasks from memory. What do you do?","options":[{"text":"Say you don't know how she does it","then":"She smiles tiredly. \"Practice, and nobody else doing it.\""},{"text":"Own a whole area, with its dates on a shared calendar","then":"You take school. Its dates appear on a shared calendar while she watches.","best":true},{"text":"Say you'll do whatever is on the list","then":"You do the tasks. She still thinks of every one of them first."},{"text":"Thank her and ask her to remind you nearer the day","then":"She agrees, and the reminder becomes one more thing on her list."}],"why":"A whole domain on a shared calendar moves the tracking, not just the tasks."},{"prompt":"A week on, she stirs at 2am again and you hear her. What do you do?","options":[{"text":"Say you'll look at it in the morning","then":"The morning gets busy. Whatever woke her stays unsaid."},{"text":"Ask what is worrying her, and say which part is yours","then":"She says the fee is due Friday. \"That's mine,\" you say. She breathes out.","best":true},{"text":"Tell her to write it down and leave it till morning","then":"She writes it down. In the morning it is still her list."},{"text":"Stay awake beside her without saying anything","then":"She feels you there, but the worry is still hers."}],"why":"Naming what is yours in the moment lets her put it down."},{"prompt":"Three weeks on, the next school notice pings both your phones. What do you do?","options":[{"text":"Leave it for her, since she always sees them","then":"She reads it at midnight and adds it to her list."},{"text":"Deal with it, and tell her she needn't open it","then":"She puts her phone down. Later she says, \"I didn't check the school app once.\"","best":true},{"text":"Read it, and ask her what you should do","then":"She tells you, and the thinking is hers again."},{"text":"Deal with it, then ask her to double-check you","then":"She checks quietly, and a little of the worry creeps back."}],"why":"Handling it without being asked, and saying so, is what lets her stop tracking school."},{"prompt":"Two months on, a work trip clashes with the kids' school sports day. What do you do?","options":[{"text":"Tell her early, and offer a swap for another day","then":"She thinks. \"Yes. I'll go if you take next week's parents' meeting.\"","best":true},{"text":"Skip sports day and hope no one minds","then":"Your child looks for you in the crowd, and tells her about it that night."},{"text":"Assume she'll cover it, and say nothing","then":"She finds out at the school gate, and covers it."},{"text":"Ask her to sort it, since it's just this once","then":"She sorts it, and \"just this once\" starts to repeat."}],"why":"Telling her early and offering a swap is how two owners flex for each other."}],"debrief":"Take a whole domain so the worry is yours too, not just sympathised with.","relearn":"Sharing night-worry means owning some tracking, not only offering reassurance."},
  {"id":"ep2-1009","cat":"parental-mental-load","type":"branch","persona":"Vikram","source":"learn the routine","hook":"You take the kids to your parents' for two days, and realise only your partner knows their full routine.","steps":[{"prompt":"She texts you a long list of reminders from home. What do you do?","options":[{"text":"Use it now, and learn it all properly once home","then":"She sends a heart. \"Okay. Next weekend, all of it.\"","best":true},{"text":"Ask her to write detailed notes for your next trip","then":"She types notes late that night, on top of everything else."},{"text":"Say you'll manage and call only if you're stuck","then":"She reads it twice, and doesn't quite believe you."},{"text":"Reply thanks and treat the list as your guide","then":"You follow the list. The plan lives in her head and her phone."}],"why":"Learning it yourself means two of you hold the routine, not one memory."},{"prompt":"Back home, the kids ask why Papa doesn't know their bus times. What do you do?","options":[{"text":"Say Papa is busy, and change the subject","then":"They shrug. The question is not asked again."},{"text":"Say Mummy knows it all, so ask Mummy","then":"They go to her. She answers without looking up, and the routine stays hers."},{"text":"Say you're learning, and ask them to show you","then":"They show you eagerly. Your daughter corrects you on the swimming day.","best":true},{"text":"Say you'll check with Mummy a bit later","then":"Later you ask her, and she rattles it off from memory."}],"why":"Asking the kids too shows them a dad who wants to know their week."},{"prompt":"A weekend later, she offers to write the routine on the fridge. What do you do?","options":[{"text":"Tell her the fridge list is enough","then":"She writes it out late at night. You glance at it and go back to your phone."},{"text":"Run a whole day alone while she is out","then":"She goes to a friend's with her phone off. You manage drop-offs, lunch and a meltdown.","best":true},{"text":"Ask her to stay near in case you need her","then":"She hovers, answering every question before you ask."},{"text":"Ask her to text you when things come up","then":"She texts all afternoon. She is still the one who knows."}],"why":"Running a whole day alone is how the routine moves out of her head."}],"debrief":"Learn the routine so two of you hold it, not stay dependent on one memory.","relearn":"The load lifts when a second parent truly knows the routine, not when one writes it down."},
  {"id":"ep2-1010","cat":"parental-mental-load","type":"branch","persona":"Vikram","source":"not better by nature","hook":"At lunch a relative says your wife is just better at keeping track of the kids.","steps":[{"prompt":"Your wife smiles awkwardly. What do you say?","options":[{"text":"Say she is a natural, and you are lucky","then":"Your wife says nothing. The idea sits at the table."},{"text":"Say it's practice, and you're learning too","then":"The relative looks surprised. Your wife glances at you and smiles.","best":true},{"text":"Laugh and agree to keep the peace","then":"The relative nods, pleased. Your wife's smile fades."},{"text":"Tell the relative that is an outdated idea","then":"The relative stiffens. \"I only said something nice.\""}],"why":"Calling tracking a shared, learnable skill pushes back on the myth kindly."},{"prompt":"Later your wife says she is tired of being \"the organised one.\" What do you do?","options":[{"text":"Ask which part to take over first","then":"She thinks, then hands you the school calendar.","best":true},{"text":"Ask her to teach you her system","then":"She spends an evening on it. Afterwards she is still the one who runs it."},{"text":"Say you'll try to remember more","then":"She nods. The remembering is still hers to check."},{"text":"Say being the organised one is a compliment","then":"She goes quiet. \"It doesn't feel like one at 2am.\""}],"why":"Taking over a part is how it stops being her label."},{"prompt":"At the next lunch, the relative says again that your wife just knows these things. What do you do?","options":[{"text":"Say she just does more of it, and you're catching up","then":"The relative blinks. \"You?\" Your wife adds, \"He's learning.\"","best":true},{"text":"Let it go, since it's only lunch talk","then":"The relative carries on. Your wife looks down."},{"text":"Ask your wife to answer, as she knows best","then":"She answers politely. The idea gets stronger."},{"text":"Say you'll learn the dates, given time","then":"The relative nods, and \"given time\" is remembered."}],"why":"Saying calmly that you're catching up shifts the story the family tells."}],"debrief":"Name tracking as a learnable, shared skill, not 'she's just better'.","relearn":"Tracking is practice, not instinct; naming that resists the default that it's the mother's."},
  {"id":"ep2-1011","cat":"parental-mental-load","type":"branch","persona":"Divya","source":"hand over noticing","hook":"You keep being the one who notices when the kids run out of socks and snacks, while your husband rarely has to.","steps":[{"prompt":"Tonight you notice the snack tin is empty again. What do you do?","options":[{"text":"Give him full ownership of supplies now","then":"He nods. \"Supplies are mine. What do we need?\" You leave it there.","best":true},{"text":"Buy it yourself, since it's quicker","then":"The tin is full in ten minutes, and the noticing stays yours."},{"text":"Mention it out loud so he might notice","then":"He says \"Hm\" and scrolls his phone."},{"text":"Text him each item to buy","then":"He buys them, thanking you. You did the noticing again."}],"why":"Handing over the whole domain moves the noticing, not just the shop trip."},{"prompt":"The kids need new socks, and he says he'll buy them whenever you say. What do you do?","options":[{"text":"Tell him the sizes and the shop","then":"He goes to the shop. The sizes came from you."},{"text":"Say never mind and do it yourself","then":"He shrugs, relieved. The drawers are yours again."},{"text":"Say supplies are his, drawers included","then":"He looks at you, then at the drawers. \"Okay. Every Sunday.\"","best":true},{"text":"Send him a photo of the empty drawer","then":"He replies with a thumbs up. You spotted it, again."}],"why":"Checking the drawers himself is what makes noticing his."},{"prompt":"Two weeks on, the snack tin is empty and the kids complain to you. What do you do?","options":[{"text":"Tell everyone supplies are Papa's now, and stay out","then":"Papa scrambles, then returns with biscuits and a list for next time.","best":true},{"text":"Tell him off in front of the kids","then":"He goes red. The kids stare at both of you."},{"text":"Text him a reminder for tomorrow","then":"He replies with a thumbs up. You are managing again."},{"text":"Quietly buy the snacks yourself","then":"The kids are happy. He never finds out the tin was empty."}],"why":"Saying it's Papa's job, and staying out, makes supplies really his."},{"prompt":"A month on, he spots low stock before you do. What do you do?","options":[{"text":"Say thank you, and resist checking the shelf","then":"He fills the tin, pleased. Your head feels a little lighter.","best":true},{"text":"Check the shelf anyway, just to be sure","then":"He notices you checking, and slows down."},{"text":"Take over again when he's busy","then":"He goes back to waiting for your cue."},{"text":"Tell him he should have caught it sooner","then":"His pride drops. Next week he waits for you again."}],"why":"Trusting him fully lets the noticing stay with him."}],"debrief":"Give a whole domain over so the noticing moves too, not just the shop trip.","relearn":"Handing over the buying isn't enough; the load lifts only when the noticing becomes theirs."},
  {"id":"ep2-1012","cat":"parental-mental-load","type":"branch","persona":"Divya","source":"stop managing","hook":"The planning for the kids sits entirely in your head, and you are tired of carrying it.","steps":[{"prompt":"Your partner says, \"Just tell me what to do and I'll happily do it.\" What do you say?","options":[{"text":"Start making him a daily list of tasks","then":"He follows the list well. You spend every morning writing it."},{"text":"Suggest he pick a domain to fully own","then":"He thinks. \"School, then. Forms, fees, everything.\"","best":true},{"text":"Say it's fine and you will manage it yourself","then":"He shrugs, relieved. The kids' week stays in your head."},{"text":"Give him one big task for the weekend","then":"He does it well, and asks what is next on Monday."}],"why":"Owning a domain moves the planning out of your head, not just the tasks."},{"prompt":"A school notice arrives, and he looks at you. What do you do?","options":[{"text":"Read it aloud and tell him what to do","then":"He does exactly what you say, and waits for the next notice."},{"text":"Say you'll check later that he did it right","then":"He does it, and then waits for your check."},{"text":"Handle it quickly, since it's due today","then":"It's done in a minute. He goes back to his phone."},{"text":"Say it's his area now, and step away","then":"He reads it twice, then adds the date to his phone.","best":true}],"why":"Stepping away is what lets him become the one who notices."},{"prompt":"Weeks later, he handles a task his own way, and it looks different from yours. What do you do?","options":[{"text":"Tell him how you would have done it","then":"He nods stiffly, and next time he asks before acting."},{"text":"Let it be, as long as the kids are cared for","then":"He notices you didn't comment, and grins. \"Worked, didn't it?\"","best":true},{"text":"Redo it your way when he's out","then":"It looks right. He finds out, and goes quiet for weeks."},{"text":"Give him a checklist of your way","then":"He follows it, and the thinking is yours again."}],"why":"Trusting his way lets him own the job, and lets you put it down."},{"prompt":"Three months on, he asks if he can take over a whole area of the planning. What do you say?","options":[{"text":"Say you'll think about it","then":"He waits. A month later, he doesn't ask again."},{"text":"Say you'd rather keep it. It's easier that way","then":"He shrugs. The planning stays in your head."},{"text":"Say yes, but write out what he has to do","then":"He follows the list, and the planning is still yours."},{"text":"Say yes, and hand it over without notes or checks","then":"He grins and takes it, and you sleep better that week.","best":true}],"why":"Handing over freely shares the planning, and keeps it shared."}],"debrief":"Invite him to own a domain so the planning leaves your head, not list-manage him.","relearn":"'Tell me what to do' keeps one parent the manager; owning a domain moves the thinking."},
  {"id":"ep2-1013","cat":"parental-mental-load","type":"branch","persona":"Vikram","source":"take clothing","hook":"You have never once had to think about the kids' clothes because your partner handles it.","steps":[{"prompt":"Winter is starting, and the kids have outgrown their clothes. What do you do?","options":[{"text":"Suggest she picks and you pay","then":"She shops, and you pay. The list is still hers."},{"text":"Take clothing fully: sizes, seasons, restocking","then":"She hands over the outgrown pile with relief. \"They're yours now.\"","best":true},{"text":"Offer to buy clothes when she tells you sizes","then":"She gives you sizes and a list. The thinking is still hers."},{"text":"Say you'll help when the kids need something","then":"She says fine. The noticing stays with her."}],"why":"Taking a whole domain, tracking included, lifts it from her head for good."},{"prompt":"Weeks later, you spot school shoes on sale and realise you don't know the kids' shoe sizes. What do you do?","options":[{"text":"Call your partner and ask her the sizes","then":"She answers instantly, and the sizes are still in her head."},{"text":"Check their old shoes, and note the sizes","then":"That evening you read the sizes off their shoes and save them in your phone.","best":true},{"text":"Leave the sale, and ask her to buy them later","then":"She buys them that evening, on top of everything else."},{"text":"Text her a photo of the shoes so she can choose","then":"She picks from the photo. The choosing was hers again."}],"why":"Finding the sizes yourself, and noting them, builds your own record of the kids."},{"prompt":"A month later, a cold night hits and the sweaters are still packed away. What do you do?","options":[{"text":"Wait until she notices the cold too","then":"She notices, and the sweaters come out by her hand."},{"text":"Get the sweaters out and fix a storage spot","then":"You find them in a suitcase and note where they will live now.","best":true},{"text":"Ask her where she packed them","then":"She tells you, and adds a reminder for the next winter."},{"text":"Buy new sweaters and leave the boxes","then":"The kids have new sweaters. The old ones stay lost."}],"why":"Solving it and keeping a system keeps the tracking with you."}],"debrief":"Absorb the whole clothing domain, tracking included, not just act on her cues.","relearn":"Truly taking a domain means owning its tracking and timing, not just shopping when told."},
  {"id":"ep2-1014","cat":"parental-mental-load","type":"branch","persona":"any","source":"map and split","hook":"You and your partner are both worn out and snapping over forgotten kid-admin.","steps":[{"prompt":"A missed school form sparks another sharp exchange. What do you do?","options":[{"text":"Agree to stop talking about it tonight","then":"The room calms. The forms are still nobody's."},{"text":"Suggest listing what each of you tracks","then":"You write side by side. One list runs to a second page, and you both go quiet.","best":true},{"text":"Say it's their turn to be more organised","then":"They snap back, and the argument moves to who does more."},{"text":"Promise to both try harder to remember","then":"You both try. Two days later a different form is missed."}],"why":"Naming the hidden work is the first step, and it eases the snapping."},{"prompt":"The next evening you sit down to split the kid-admin. How do you divide it?","options":[{"text":"Give it to whoever has more free time","then":"That parent carries most of it, and resentment returns within a month."},{"text":"Split it task by task, half each","then":"The lists are equal on paper. The remembering still lands on one of you."},{"text":"Give each parent whole areas, start to finish","then":"You choose health and school. They take meals and clothes.","best":true},{"text":"Take turns being in charge each week","then":"Week one goes well. In week two, nobody remembers whose week it is."}],"why":"Whole domains with clear owners end the guessing about who tracks what."},{"prompt":"A month on, one of you drops a ball in your own area. What do you do?","options":[{"text":"Say it's fixable, and ask what would help","then":"They catch their breath. \"A reminder on my phone would help.\"","best":true},{"text":"Take the task back to be safe","then":"It's done at once. They stop trying to hold it."},{"text":"Let it go and hope it doesn't happen again","then":"It happens again a fortnight later."},{"text":"Point out the slip in front of the kids","then":"They flush. The kids stare at both of you."}],"why":"Helping the slip get fixed keeps ownership, and trust, with its owner."},{"prompt":"Three months on, you sit down again. What do you do?","options":[{"text":"Point out what has slipped in the other's area","then":"They defend themselves, and the check-in becomes a scorecard."},{"text":"Reopen the whole split from scratch","then":"It takes three evenings, and both of you end up tired."},{"text":"Do a quick check-in, and adjust the domains","then":"You swap meals and clothes. Both of you sleep a little better.","best":true},{"text":"Skip it, since it seems to be working","then":"A month later, one of you is quietly overloaded again."}],"why":"A regular check-in keeps a fair split fair as the kids grow."},{"prompt":"A year on, a new school term brings twice the forms. What do you do?","options":[{"text":"Let one of you absorb it, then switch later","then":"One of you sinks for a month before switching."},{"text":"Divide the new forms into your areas, then check the split","then":"You add them to health and school. The balance still feels fair.","best":true},{"text":"Divide the forms by a coin toss","then":"The coin splits them. Nobody owns the whole pile."},{"text":"Ignore the pile until the forms are late","then":"Two forms are late, and both of you snap."}],"why":"Fitting new work into owned areas keeps the split fair year after year."}],"debrief":"Map and reassign whole domains, not each strain to hold more in your head.","relearn":"When both are fried, naming and splitting the tracking beats trying to remember more."},
  {"id":"ep2-1015","cat":"parental-mental-load","type":"branch","persona":"Vikram","source":"naming to action","hook":"Your partner finally lists out loud all the kid-admin she silently carries.","steps":[{"prompt":"She finishes, tearful and tired. What do you do?","options":[{"text":"Ask her to send you the list to review","then":"She emails it. You read it, and nothing else changes."},{"text":"Tell her you had no idea and feel bad","then":"She comforts you. The list stays with her."},{"text":"Promise to do more from now on","then":"She nods, hopeful. \"More\" is not a domain, and nothing changes by Friday."},{"text":"Thank her, and pick domains to own this week","then":"She wipes her eyes. \"Really? Which ones?\" You choose school and health.","best":true}],"why":"Naming it becomes real relief only when you take ownership of real domains."},{"prompt":"A week later, a child gets a fever at school while she is on a work call. What do you do?","options":[{"text":"Ask her which clinic to go to","then":"She answers between calls, and the clinic choice was hers again."},{"text":"Call her to double-check, then act","then":"She steps out of her call. Her focus is gone for the hour."},{"text":"Collect the child and book the doctor yourself","then":"You take the day off, and she stays on her call, knowing the fever is handled.","best":true},{"text":"Tell the school to call her, since she knows","then":"The school calls her. She leaves her meeting."}],"why":"Taking the whole health job, without a call, is what makes it yours."},{"prompt":"She hands you the health file with names, dates and allergies. What do you do?","options":[{"text":"File it away, and look when it's needed","then":"Two weeks later, a jab is a week overdue."},{"text":"Ask her to keep reminding you of the dates","then":"She agrees, and the dates stay on her mind as well as yours."},{"text":"Read it tonight, and set your own reminders","then":"You set three reminders. She watches them go off and lets go.","best":true},{"text":"Ask her to summarise it on one page","then":"She writes it up late. The summary lives in her head."}],"why":"Learning the file yourself is how the health domain leaves her head."}],"debrief":"Turn her naming into you owning real domains, not just sympathy and guilt.","relearn":"Once the hidden load is named, the fix is real ownership, not stopping at feeling bad."},
  {"id":"ep2-1016","cat":"parental-mental-load","type":"branch","persona":"Vikram","source":"own bedtime","hook":"Your partner asked you to own bedtime, but you keep checking in with her about it.","steps":[{"prompt":"Tonight bedtime is yours and she is in the next room. What do you do?","options":[{"text":"Ask her to stay close in case you need help","then":"She hovers, answering before you ask. It's still her bedtime."},{"text":"Run it fully and don't ask her a thing","then":"Baths, stories and lights out go your way. Her room stays quiet.","best":true},{"text":"Do bedtime, then text her a summary to check","then":"She replies with three tips and a thumbs up. She is still managing."},{"text":"Start, then hand over to her when it gets hard","then":"She soothes your child in five minutes. You go to bed."}],"why":"Owning bedtime end to end takes it off her mind for good."},{"prompt":"The next night, your child protests: \"Mama does the story differently.\" What do you do?","options":[{"text":"Say tonight's story is Papa's way, and carry on","then":"Your child grumbles, then asks for the ending twice.","best":true},{"text":"Call your partner in to show you","then":"She comes in and tells the story. Bedtime is hers again."},{"text":"Do it her way to avoid the fuss","then":"Your child settles. You are her assistant now."},{"text":"Tell your child that Mama's way is better anyway","then":"Your child looks at you, puzzled. Then they ask for Mama."}],"why":"Doing it your own way makes bedtime yours and lets your child accept it."},{"prompt":"A fortnight on, your child cries at 9pm and your partner half-rises. What do you do?","options":[{"text":"Say \"I've got it\" and go","then":"She sits back. You find the right lullaby on the third try.","best":true},{"text":"Ask her to come just this once","then":"She comes, and bedtime is hers again."},{"text":"Tell her to go, since it's quicker","then":"She goes, and does it in five minutes."},{"text":"Go, but call questions to her from the room","then":"She answers each one. She is still managing."}],"why":"Saying \"I've got it\" is what lets her truly switch off."},{"prompt":"Your partner is away for the night, and your child wants Mama to do bedtime. What do you do?","options":[{"text":"Let your child stay up until Mama's back","then":"Your child is overtired and grumpy by nine."},{"text":"Skip the story, since your child is upset","then":"Your child settles, and learns that a fuss ends the story."},{"text":"Video-call Mama to do the story","then":"Mama reads over the phone. Bedtime is still hers, from afar."},{"text":"Say tonight is Papa's night, and do the full routine","then":"Your child sulks through the bath, then falls asleep on your arm.","best":true}],"why":"Doing the full routine, even with a protest, makes bedtime yours."}],"debrief":"Own bedtime end-to-end so it leaves her head, not do it while she oversees.","relearn":"Owning a domain means carrying it without check-ins, so it leaves your partner's mind."},
  {"id":"ep2-1017","cat":"parental-mental-load","type":"branch","persona":"Vikram","source":"push through","hook":"You have taken over health admin but keep forgetting things in the early weeks.","steps":[{"prompt":"You missed a check-up date, and she noticed. What do you do?","options":[{"text":"Own it, fix the date and build your own system","then":"You book the slot for tomorrow and set a monthly reminder on your phone.","best":true},{"text":"Apologise a lot and promise to be better","then":"She waves it away. The slot is still unbooked."},{"text":"Ask her to remind you before every date","then":"She promises, and the reminders become another chore for her."},{"text":"Hand it back, saying she is clearly better at it","then":"She sighs. \"Give it one more month,\" she says, and hands it back to you."}],"why":"Fixing it and building a system is how you get practised, and it stays yours."},{"prompt":"A month later she starts to say, \"Let me just check the health calendar.\" What do you do?","options":[{"text":"Get defensive and say you're fine","then":"She backs off, hurt. The calendar sits between you."},{"text":"Say she can do it, since she is faster","then":"She checks it, and quietly starts tracking health again alongside you."},{"text":"Let her check it, just this once","then":"She checks, and she checks the next time too."},{"text":"Show her your system, and ask her to let go of it","then":"She scrolls through it, surprised. \"Okay. That's clear.\"","best":true}],"why":"Showing your system is what lets her trust you, and stop tracking."},{"prompt":"Three months on, a jab falls on the day of your work trip. What do you do?","options":[{"text":"Ask her to sort it out, since you're away","then":"She rebooks it herself. The health job is half hers again."},{"text":"Rebook an on-time slot yourself, and tell her","then":"The clinic has a slot two days later, still on time. She nods. \"You handled that.\"","best":true},{"text":"Ask her to pick a new day that works for her","then":"She picks a day. The scheduling stays hers."},{"text":"Skip the jab this time, and catch up later","then":"The catch-up slips. She notices, and books it herself."}],"why":"Rebooking it on time yourself keeps the jab on schedule and proves the domain is truly yours."}],"debrief":"Push through the clumsy weeks so the skill, and the load, become yours.","relearn":"You get good at tracking by practising; giving up early hands the load back unchanged."},
  {"id":"ep2-1018","cat":"parental-mental-load","type":"branch","persona":"any","source":"let go to lift","hook":"Your partner keeps redoing the kid-admin you took on, \"just to be sure.\"","steps":[{"prompt":"You notice they have re-checked a form you filled in. What do you do?","options":[{"text":"Say nothing, since it's only a quick look","then":"The re-checking becomes a habit, and the form stays on their mind."},{"text":"Snap that they don't trust you","then":"They stiffen. \"I just want it right.\""},{"text":"Ask them to re-check only the important ones","then":"They re-check the important ones. What counts is still their call."},{"text":"Ask them to hand it over and trust your way","then":"They pause. \"Okay. It's yours. I'll try not to look.\"","best":true}],"why":"Handing over means trusting a different way of doing it."},{"prompt":"A few days later, they hover while you book a doctor's slot. What do you do?","options":[{"text":"Say kindly that you've got it and they can go","then":"They hesitate, then leave the room.","best":true},{"text":"Send them the confirmation afterwards","then":"They read it and reply. They are still in the loop."},{"text":"Let them take the phone and do it","then":"It's booked in a minute. You are the assistant again."},{"text":"Let them watch and give tips","then":"They give tips. The slot is booked, and the booking is still theirs."}],"why":"Saying you have got it gives them permission to stop watching."},{"prompt":"A month on, they ask whether you really got the vaccination slot booked. What do you do?","options":[{"text":"Get annoyed and say they never trust you","then":"They go quiet, and the checking moves out of sight."},{"text":"Say it's booked, and they can stop tracking it","then":"They exhale. \"Okay. I believe you.\"","best":true},{"text":"Show them the confirmation each time","then":"They look at it each time, and start to expect it."},{"text":"Say you'll double-check it yourself first","then":"You double-check, and tell them it's fine. They double-check too."}],"why":"Trusting that it is done lets both of you drop it."}],"debrief":"For the load to lift, your partner has to let go and trust your handling.","relearn":"Sharing the load needs the other parent to truly hand over, not silently re-track the work."},
  {"id":"ep2-1019","cat":"parental-mental-load","type":"reflect","hook":"Lensy: the parent who can take a holiday and the home keeps running is usually not the one carrying the load. Notice that?","prompt":"What's your take?","options":["I notice that","Worth a look","True for us"],"affirm":"If you can step away and nothing wobbles, you're likely not the one holding the tracking; noticing that is the start.","relearn":"Being able to switch off while the home runs often means the other parent is silently carrying the mental load.","persona":"any","source":"who can switch off"},
  {"id":"ep2-1020","cat":"parental-mental-load","type":"reflect","hook":"Lensy: try this; for one week, notice every time you ask your partner 'where is...' or 'when is...'. Worth trying?","prompt":"How does that sit?","options":["Worth trying","I'll notice","Good idea"],"affirm":"Each 'where is' or 'when is' is a moment your partner is holding info you could be holding too; noticing it is step one.","relearn":"Counting how often you ask your partner for kid-info reveals how much tracking quietly sits with them.","persona":"Vikram","source":"count the asks"},
  {"id":"ep2-1021","cat":"parental-mental-load","type":"reflect","hook":"Lensy: 'I do half the tasks' and 'I carry half the thinking' are very different claims. Sit with that?","prompt":"What do you think?","options":["I'll sit with it","Fair point","Different, yes"],"affirm":"Doing half the tasks is real, but carrying half the thinking is the harder, invisible half worth aiming for too.","relearn":"Splitting the doing isn't the same as splitting the thinking; the mental load is that second, invisible half.","persona":"any","source":"tasks vs thinking"},
  {"id":"ep2-1022","cat":"parental-mental-load","type":"reflect","hook":"Lensy: if you both vanished for a day, would the other parent know the kids' full routine, or only one of you? Wonder about it?","prompt":"What's your honest answer?","options":["Only one of us","Worth checking","Both, I hope"],"affirm":"If only one of you holds the full routine, that's the mental load made visible; sharing it means both knowing.","relearn":"When only one parent holds the whole routine, the load is on them; sharing it means both can run the day.","persona":"any","source":"who holds the routine"},
  {"id":"ep2-1023","cat":"parental-mental-load","type":"reflect","hook":"Lensy: owning a domain isn't 'helping with it', it's it never crossing the other parent's mind again. Ring true?","prompt":"What's your take?","options":["Rings true","I get it","Yes, that"],"affirm":"You've owned something when your partner can fully forget it exists; that's the load genuinely lifting.","relearn":"True ownership means a whole area leaves your partner's mind for good, not that you assist with it.","persona":"Vikram","source":"owning vs helping"},
  {"id":"ep2-1024","cat":"parental-mental-load","type":"reflect","hook":"Lensy: the tiredness from constant tracking is real, even when nobody can see you doing anything. Worth honouring?","prompt":"How does that land?","options":["Worth honouring","I feel that","It's real"],"affirm":"Holding a hundred small kid-things in your head is genuinely tiring work; it counts, even when it's invisible.","relearn":"The fatigue of always tracking is real cognitive work, not nothing, even though no one sees it happening.","persona":"Divya","source":"invisible tiredness"},
  {"id":"ep2-1025","cat":"parental-mental-load","type":"reflect","hook":"Lensy: when one parent always 'just knows', the other rarely learns. Worth thinking about?","prompt":"What do you think?","options":["Worth thinking about","I see that","Makes sense"],"affirm":"If one parent always knows, the other never has to learn; swapping who tracks lets both build the skill.","relearn":"One parent always knowing keeps the other from learning; sharing the tracking lets both get practised.","persona":"any","source":"both can learn"},
  {"id":"ep2-1026","cat":"parental-mental-load","type":"reflect","hook":"Lensy: 'managing my partner through tasks' can quietly become its own full-time job. Recognise it?","prompt":"What's your take?","options":["I recognise it","Hits home","Yes"],"affirm":"Reminding, checking and delegating is itself work; the fix is owned domains so there's nobody to manage.","relearn":"Managing your partner through tasks is its own load; owned domains remove the managing altogether.","persona":"Divya","source":"managing is work"},
  {"id":"ep2-1027","cat":"parental-mental-load","type":"spot","hook":"Spot the two lines that keep the mental load on one parent.","scene":[{"id":"a","text":"\"You're the one who remembers, so you handle the doctor.\"","trick":true},{"id":"b","text":"\"I'll own all the medical tracking from now on.\"","trick":false},{"id":"c","text":"\"Make me a list and I'll get to it.\"","trick":true},{"id":"d","text":"\"Let's each take whole areas, planning included.\"","trick":false},{"id":"e","text":"\"I'll learn the routine so I can run it solo.\"","trick":false}],"why":"Leaving the remembering to one parent and asking for a list keep that parent the planner.","relearn":"Lines that assign remembering to one parent or wait for a list keep the load lopsided.","persona":"Vikram","source":"keeps the load"},
  {"id":"ep2-1028","cat":"parental-mental-load","type":"spot","hook":"Spot the two phrases that treat the mental load as not-real-work.","scene":[{"id":"a","text":"\"It's all in your head, that's hardly work.\"","trick":true},{"id":"b","text":"\"Tracking the kids' week is real, tiring work.\"","trick":false},{"id":"c","text":"\"You didn't do anything, you just remembered.\"","trick":true},{"id":"d","text":"\"Holding all those dates deserves sharing.\"","trick":false},{"id":"e","text":"\"Worrying and planning counts; let me carry some.\"","trick":false}],"why":"Calling remembering 'hardly work' or 'not doing anything' denies that tracking is real labour.","relearn":"The mental load is real, tiring work; calling it 'nothing' erases the labour of tracking.","persona":"Divya","source":"load is real"},
  {"id":"ep2-1029","cat":"parental-mental-load","type":"spot","hook":"Spot the two moves that look like sharing but keep one parent as manager.","scene":[{"id":"a","text":"He texts to ask what to cook every single night","trick":true},{"id":"b","text":"He fully owns dinners, menu and shopping","trick":false},{"id":"c","text":"She writes him a detailed list each morning","trick":true},{"id":"d","text":"They split domains and stop checking each other","trick":false},{"id":"e","text":"Either of them can run a sick day alone","trick":false}],"why":"Asking what to cook nightly and writing daily lists keep the planning on one parent.","relearn":"Nightly 'what should I do' and daily lists leave one parent planning; owned domains don't.","persona":"Vikram","source":"looks like sharing"},
  {"id":"ep2-1030","cat":"parental-mental-load","type":"spot","hook":"Spot the two beliefs that wrongly tie the mental load to being a mother.","scene":[{"id":"a","text":"\"A mother just naturally remembers all of it.\"","trick":true},{"id":"b","text":"\"Whoever tracks it gets practised at it.\"","trick":false},{"id":"c","text":"\"Worrying about the kids is a mum thing.\"","trick":true},{"id":"d","text":"\"A father can carry his full share of planning.\"","trick":false},{"id":"e","text":"\"The load is learned by doing, not by gender.\"","trick":false}],"why":"'Mothers naturally remember' and 'worry is a mum thing' tie the load to gender; it's practice, not biology.","relearn":"The mental load isn't a mother's instinct; it's a learned, practised skill either parent can carry.","persona":"any","source":"not a mum thing"},
  {"id":"ep2-1031","cat":"parental-mental-load","type":"spot","hook":"Spot the two lines that hand over tasks but keep the tracking.","scene":[{"id":"a","text":"\"Buy these three things I've listed on your way home.\"","trick":true},{"id":"b","text":"\"I'll own groceries: noticing what's low and restocking.\"","trick":false},{"id":"c","text":"\"Remind me and I'll book the appointment.\"","trick":true},{"id":"d","text":"\"I'll watch our health needs and book them myself.\"","trick":false},{"id":"e","text":"\"School admin is mine; I'll catch the dates myself.\"","trick":false}],"why":"A ready-made list and 'remind me' move the doing but keep the noticing on one parent.","relearn":"Handing over tasks while keeping the noticing isn't sharing; owning the noticing is.","persona":"Divya","source":"task not tracking"},
  {"id":"ep2-1032","cat":"parental-mental-load","type":"spot","hook":"Spot the two responses that dodge owning a share of the load.","scene":[{"id":"a","text":"\"You're just better at this stuff than me.\"","trick":true},{"id":"b","text":"\"I'll take a domain and get practised at it.\"","trick":false},{"id":"c","text":"\"I'd only do it wrong, so you keep it.\"","trick":true},{"id":"d","text":"\"I'll learn the routine so it's genuinely mine.\"","trick":false},{"id":"e","text":"\"Let's split the tracking, not just the tasks.\"","trick":false}],"why":"'You're better at it' and 'I'd do it wrong' use skill-gaps as reasons to keep the load on one parent.","relearn":"'You're better' and 'I'd mess it up' dodge ownership; the skill comes from practising your share.","persona":"Vikram","source":"dodge ownership"},
  {"id":"ep2-1033","cat":"parental-mental-load","type":"spot","hook":"Spot the two replies that quietly make 'remembering' her permanent job.","scene":[{"id":"a","text":"\"You've got such a good memory, you keep all the dates.\"","trick":true},{"id":"b","text":"\"Let's both put dates in the shared calendar.\"","trick":false},{"id":"c","text":"\"Your brain is the family diary, it works for us.\"","trick":true},{"id":"d","text":"\"I'll own and track the school calendar myself.\"","trick":false},{"id":"e","text":"\"We can swap who tracks what every few months.\"","trick":false}],"why":"Praising her memory as 'the family diary' assigns all remembering to her for good.","relearn":"Praising one parent's memory to keep them the diary entrenches the load; sharing lifts it.","persona":"Vikram","source":"her permanent job"},
  {"id":"ep2-1034","cat":"parental-mental-load","type":"role-play","persona":"Vikram","source":"own domains","hook":"Your partner is wiped out from holding the kids' whole week in her head.","setup":"You put a cup of tea down beside her.","steps":[{"prompt":"Your partner says: \"I don't even know when I last sat down.\"","options":[{"text":"\"Tell me what to do today, and I'll handle it.\"","then":"She thinks. \"Buy vegetables, sign the form...\" and the list begins."},{"text":"\"You should rest more. I'll handle a bit.\"","then":"She smiles tiredly. \"How much is a bit?\""},{"text":"\"Let me fully own school and meals, tracking too.\"","then":"She stares at you. \"Tracking and all?\" \"All of it,\" you say.","best":true},{"text":"\"You're so good at all this. I couldn't manage.\"","then":"She sighs. \"I wasn't born good at it, you know.\""}],"why":"Owning school and meals takes the tracking off her head, not just the tasks."},{"prompt":"The next day she asks: \"So who plans the meals and what we're out of this week?\"","options":[{"text":"\"I'll cook whatever you decide each night.\"","then":"She sighs and plans the menu, as she always does."},{"text":"\"We'll order out more, so nobody has to plan.\"","then":"She smiles wearily. The takeaways pile up, and the questions stay."},{"text":"\"I do. Menu, shopping and what we're out of.\"","then":"She writes nothing down for the first time in a year.","best":true},{"text":"\"Leave me a note on the fridge each week.\"","then":"She writes the note, and the planning stays hers."}],"why":"Owning the whole plan means she is not the manager any more."},{"prompt":"She glances at the fridge and says: \"There's nothing planned for Sunday.\"","options":[{"text":"\"Sorry. What do you feel like?\"","then":"She tells you, and plans the rest as she talks."},{"text":"\"I'll sort it. Just tell me what we need.\"","then":"She names five items. The list is still hers."},{"text":"\"Can you plan it this once? I'm swamped.\"","then":"She plans it, tired. \"This once\" becomes most weeks."},{"text":"\"Sunday's mine. I'm shopping tomorrow.\"","then":"She lets out a breath. \"Really? Sunday's sorted?\" \"Sorted.\"","best":true}],"why":"Having the plan ready shows her the domain is truly off her mind."}],"relearn":"Offering to fully own whole domains, tracking included, lifts the planning off your partner, not just the tasks."},
  {"id":"ep2-1035","cat":"parental-mental-load","type":"role-play","persona":"Divya","source":"ask for ownership","hook":"You are the parent silently carrying all the kid-admin, and you want your partner to truly share it.","setup":"You find him alone in the kitchen tonight.","steps":[{"prompt":"Your partner asks: \"You seem tired. Anything I can do?\"","options":[{"text":"\"I'm tracking it all. Can you own health and clothes?\"","then":"He pauses. \"Fully own? Tell me what that means.\"","best":true},{"text":"\"No, it's fine. I'm only a bit tired tonight.\"","then":"He nods and goes back to his phone."},{"text":"\"Could you maybe help out a bit more when I ask?\"","then":"He nods. \"Sure. Just ask.\" You are already tired of asking."},{"text":"\"Do you really not see all I do?\"","then":"He stiffens. \"That's not fair. Tell me what you mean.\""}],"why":"Asking him to own whole domains shares the tracking, not just the tasks."},{"prompt":"A few days later he says: \"I'd like to take on more, but you know all the details. I'll get it wrong.\"","options":[{"text":"\"Just ask me whenever you're unsure.\"","then":"He agrees. He will ask, and you will answer, all week."},{"text":"\"Fine, get it wrong then. See if I care.\"","then":"He goes quiet. \"That isn't fair.\""},{"text":"\"You're right. It's quicker if I do it.\"","then":"He nods. \"Okay. Still, I want to try one thing.\""},{"text":"\"I learned by doing it. You will too.\"","then":"He looks at you. \"Okay. Show me once, then.\"","best":true}],"why":"Learning by doing, even clumsily, is how he becomes capable."},{"prompt":"A week later he says: \"I made a health folder for the kids. Want to check it?\"","options":[{"text":"\"Yes, let me have a quick look.\"","then":"You check it. He watches your face, waiting for a verdict."},{"text":"\"Great. I'll fill in whatever's missing.\"","then":"He slides it across. \"Oh. Sure.\" The folder is half yours again."},{"text":"\"Send me photos of the pages.\"","then":"You get the photos, and find yourself checking them at night."},{"text":"\"No. It's yours. I'll ask if I need it.\"","then":"He grins, and closes the folder like it's his own.","best":true}],"why":"Trusting him fully lets the health folder leave your head."},{"prompt":"He says: \"My mum says fathers shouldn't bother with kid-admin.\"","options":[{"text":"\"Tell her to mind her own business, please.\"","then":"He winces. \"I can't say that to my mother.\""},{"text":"\"Then just don't tell her what you're doing.\"","then":"He nods, and keeps his part out of her sight."},{"text":"\"Your mum's world was different. This is ours.\"","then":"He nods slowly. \"I'll tell her that. Gently.\"","best":true},{"text":"\"Maybe she's right. Let's not upset her just now.\"","then":"He looks relieved. The admin drifts back to you."}],"why":"Standing together on your own rule keeps his role, and his mum, close."}],"relearn":"Asking a partner to fully own domains shares the tracking; asking for 'help when I ask' keeps you the manager."},
  {"id":"ep2-1036","cat":"parental-mental-load","type":"role-play","persona":"Vikram","source":"learned not natural","hook":"Family is over for tea, and talk turns to who tracks the kids' school and doctor dates.","setup":"Your wife is pouring tea when your uncle turns to you.","steps":[{"prompt":"Your uncle says: \"She's just naturally better at all that kid-admin.\"","options":[{"text":"\"She's had years of practice. Give me time.\"","then":"He chuckles. \"Of course.\" You are still waiting."},{"text":"\"Ha, we all have our strengths, Uncle.\"","then":"He nods, satisfied. The remark stays put."},{"text":"\"It's practice, not nature. I'm learning my half too.\"","then":"Your uncle blinks. Your wife glances at you and smiles.","best":true},{"text":"\"Yeah, she's the organised one. I just pitch in.\"","then":"He laughs. \"Good man.\" Your wife looks at her tea."}],"why":"Calling it practice keeps the myth from sticking, and you own your half."},{"prompt":"Your uncle adds: \"A mother worries more, anyway. It's how they are.\"","options":[{"text":"\"Times are changing, Uncle. Let's leave it there.\"","then":"He grunts. Nothing is settled."},{"text":"\"Whoever does the tracking worries. I'm taking half.\"","then":"He raises an eyebrow. \"Half?\" Your wife looks up, surprised.","best":true},{"text":"\"True, Uncle. Mothers do worry more.\"","then":"He nods, pleased. Your wife stays silent."},{"text":"\"Maybe. Let's not argue about it, Uncle.\"","then":"He shrugs. The subject moves on."}],"why":"Naming who does the tracking shows worry follows the work, not the sex."},{"prompt":"Later your wife says quietly: \"What Uncle said at tea stayed with me.\"","options":[{"text":"\"It's true. You are just better at it.\"","then":"She frowns. \"That's what I'm trying to get away from.\""},{"text":"\"Sorry. I didn't want a fight at the table.\"","then":"She nods. It sounds like a favour, not a change."},{"text":"\"I hear you. Which part can I take on next?\"","then":"She thinks. \"The dentist and school forms, maybe?\"","best":true},{"text":"\"Don't take it to heart. Uncle means well.\"","then":"She smiles thinly. The load stays where it is."}],"why":"Following words with action shows her you mean it."}],"relearn":"Naming tracking as learned, shareable practice resists 'she's naturally better' and models owning your half."},
  {"id":"ep2-1037","cat":"parental-mental-load","type":"role-play","persona":"Vikram","source":"let her let go","hook":"Your partner keeps double-checking the kid-admin you have taken on, and you want her to let it go.","setup":"You catch her opening the health folder again.","steps":[{"prompt":"Your partner says: \"I'm just making sure the jab dates are right.\"","options":[{"text":"\"Fine, check. But I hate being watched.\"","then":"She stiffens. \"I'm not watching. I care.\""},{"text":"\"Do what you like.\"","then":"She flips a page, hurt. The folder stays open."},{"text":"\"I've got health now. You can let it go.\"","then":"She closes the folder slowly. \"It's hard. I've done it so long.\"","best":true},{"text":"\"Keep checking my work, just in case.\"","then":"She nods, relieved, and keeps reading."}],"why":"Asking her to let go openly is the only way it stops being double-tracked."},{"prompt":"She says: \"What if you miss something? I'd never forgive myself.\"","options":[{"text":"\"Then I'll fix it, and tell you. Let me try.\"","then":"She takes a breath. \"Okay. I'll try to stay out of it.\"","best":true},{"text":"\"It'll be fine. Don't think about it.\"","then":"She nods, and thinks about it anyway."},{"text":"\"Nothing has gone wrong so far. Relax.\"","then":"She tenses. \"That's not the point.\""},{"text":"\"You're right. Check the next few dates.\"","then":"She checks the next few. Then the ones after that."}],"why":"Promising to fix any slip helps her trust you enough to step back."},{"prompt":"Your partner says: \"I made a note of the next jab, just in case.\"","options":[{"text":"\"It's in my calendar. You can drop the note.\"","then":"She hesitates, then tears up the note.","best":true},{"text":"\"Please stop. It makes me feel useless.\"","then":"She recoils. \"I'm only trying to help.\""},{"text":"\"Great, keep the note as a backup.\"","then":"She keeps it. She keeps tracking it, too."},{"text":"\"That's kind. I'll take a look.\"","then":"You look at it. She is still in the loop."}],"why":"Showing your own calendar lets her put the note down, kindly."}],"relearn":"For the load to lift, a partner has to truly let go and stop re-tracking; double-checking keeps it on her."},
  {"id":"ep2-1038","cat":"parental-mental-load","type":"role-play","persona":"Vikram","source":"no list","hook":"You catch yourself about to ask your partner to just make you a list, and want to take real ownership instead.","setup":"She is already planning the week over her tea.","steps":[{"prompt":"Your partner asks: \"Can you do groceries this week? I'll write down what we need.\"","options":[{"text":"\"Write down everything you need and I'll work through it.\"","then":"She writes a two-page list, and still holds the plan in her head."},{"text":"\"Sure. Just text me whenever something runs out.\"","then":"She texts whenever something runs out, and keeps noticing."},{"text":"\"Okay. Anything special this week?\"","then":"She lists a few things. The rest is still hers to think of."},{"text":"\"Don't write it. Meals and groceries are mine now.\"","then":"She blinks. \"All of it? Even what's running low?\"","best":true}],"why":"Owning meals and groceries takes the planning off her, not just the shopping."},{"prompt":"Your partner asks: \"And the kids' fussy eating? That's a whole list of its own.\"","options":[{"text":"\"Write me the dislikes list and I'll follow it.\"","then":"She writes a long list. You follow it, and she thinks of more."},{"text":"\"I'll learn it. Show me once, and I'll keep the notes.\"","then":"She shows you, and you write it on your phone.","best":true},{"text":"\"They'll eat what I make.\"","then":"She looks doubtful. The dinner is half eaten."},{"text":"\"You know it best. You be the guide.\"","then":"She nods. She is the guide, and the manager, again."}],"why":"Learning their tastes yourself is what really moves the knowledge."},{"prompt":"She glances at the fridge and says: \"The milk's low. I'm trying not to say anything.\"","options":[{"text":"\"Please tell me when things run low.\"","then":"She nods. She is the one noticing again."},{"text":"\"I've seen it, and it's on the order.\"","then":"She stares. \"You noticed? Without being asked?\"","best":true},{"text":"\"Thanks. What else is low?\"","then":"She lists three things. The noticing was hers."},{"text":"\"Go ahead and say it. I'll do it then.\"","then":"She says it. The reminder is hers."}],"why":"Noticing it yourself is the proof the domain has really moved."},{"prompt":"A month on, she says: \"That was a lovely dinner. Thank you for tonight.\"","options":[{"text":"\"It's my job now, not a favour. I enjoyed it.\"","then":"She smiles. \"I'm keeping you.\"","best":true},{"text":"\"It was easy. Anyone could do it.\"","then":"She raises an eyebrow. \"It wasn't easy for me.\""},{"text":"\"Happy to help you out a bit.\"","then":"She nods, but \"help\" sits oddly between you."},{"text":"\"Good. Now don't nag me about the budget.\"","then":"She laughs, then goes quiet."}],"why":"Calling it your job, not a favour, keeps it truly yours."}],"relearn":"Owning a domain and its planning lifts the load; asking for a list keeps your partner doing the thinking."},
  {"id":"ep2-1039","cat":"parental-mental-load","type":"role-play","persona":"Vikram","source":"learn it yourself","hook":"Your partner leaves on a two-day work trip tomorrow, and only she knows the kids' full routine.","setup":"She is packing her bag and checking tomorrow's bus times.","steps":[{"prompt":"Your partner says: \"Don't worry. I'll write you notes on the kids' routine tonight.\"","options":[{"text":"\"Teach me the whole routine, so I carry it too.\"","then":"She looks up. \"All of it? Tonight?\" She reaches for a pen.","best":true},{"text":"\"Great, notes are perfect. Thanks.\"","then":"She writes until late. The routine is still hers."},{"text":"\"It's only two days. We'll be fine.\"","then":"She raises an eyebrow. \"I hope so.\""},{"text":"\"Just text me each morning with what to do.\"","then":"She smiles tiredly. \"I'll text every hour, then.\""}],"why":"Learning it yourself means two of you carry the routine, not one memory."},{"prompt":"She says: \"It's a lot. Bus times, meds, homework and Tuesday's swim.\"","options":[{"text":"\"Walk me through a normal day, slowly.\"","then":"She sits with you and goes through it, hour by hour.","best":true},{"text":"\"Just tell me the big ones.\"","then":"She picks the big ones. The small ones stay hers."},{"text":"\"Put it all on one page for me.\"","then":"She writes it up on one page. It comes out of her head, not yours."},{"text":"\"Skip the details. I'll ring you if stuck.\"","then":"She sighs. \"I'll keep my phone on.\""}],"why":"A slow walk-through moves the knowledge into your head, not onto a page."},{"prompt":"Back from her trip, your partner asks: \"Do I still need to be on standby for the routine?\"","options":[{"text":"\"No. I've got the routine. Take a day for yourself.\"","then":"She looks stunned, then laughs. \"A whole day?\"","best":true},{"text":"\"Not really, but keep your phone on.\"","then":"She keeps it on. She keeps watching, too."},{"text":"\"I'll check with you before changing anything.\"","then":"She nods, and you check often. She is still the manager."},{"text":"\"Yes, please. Just for the first month.\"","then":"She nods. The standby feels endless."}],"why":"Telling her you have it lets her stand down for real."}],"relearn":"Learning the routine so two parents hold it shares the load; staying dependent on one parent's memory doesn't."},
  {"id":"ep2-1040","cat":"parental-mental-load","type":"role-play","persona":"any","source":"split the holding","hook":"At bedtime your partner is still rattling off what you both need to remember tomorrow.","setup":"You are both tired, and the list keeps growing.","steps":[{"prompt":"Your partner says: \"Don't forget the form, the shoes and the vaccine appointment.\"","options":[{"text":"\"Let's write it on the fridge and go to sleep.\"","then":"You write it up. By morning, your partner is the one keeping it updated."},{"text":"\"I'll remember the shoes. You do the rest.\"","then":"Your partner smiles thinly. The shoes are covered, and the rest is theirs."},{"text":"\"Let's each own whole areas, not the whole list.\"","then":"Your partner stops. \"Whole areas? Like what?\"","best":true},{"text":"\"You track it. Just tell me my bits in the morning.\"","then":"Your partner nods wearily, still the one who holds it all."}],"why":"Owning whole areas stops one of you holding the entire list."},{"prompt":"The next night your partner asks: \"If we did split it up, how would we choose who takes what?\"","options":[{"text":"\"Toss a coin for each item on the list.\"","then":"The coin splits the list. Next week nobody knows who has what."},{"text":"\"Whoever has more free time should take more.\"","then":"It sounds fair, but the free time shifts each week, and so does who owns what."},{"text":"\"Two pairs: health and school, home and meals. Each picks one.\"","then":"Your partner nods. \"Then let's each pick a pair tonight.\"","best":true},{"text":"\"You pick first and I'll take the rest.\"","then":"Your partner picks first, and you are left with whatever remains."}],"why":"Splitting into pairs of whole areas makes each owner clear."},{"prompt":"A month on, your partner says: \"I dropped one of my jobs this week. I feel awful.\"","options":[{"text":"\"It happens. What would help next time?\"","then":"Your partner thinks. \"A reminder on my phone, I think.\"","best":true},{"text":"\"That's what I was afraid of.\"","then":"Your partner stiffens. \"I'm trying.\""},{"text":"\"I'll take it back for you.\"","then":"Your partner lets it go, and the area is yours again."},{"text":"\"Don't worry. I'll cover it just this once.\"","then":"Your partner thanks you, and the pattern starts again."}],"why":"Helping without taking it back keeps ownership with its owner."},{"prompt":"Your partner says: \"Work has changed for me lately. Can we look at the split again?\"","options":[{"text":"\"Yes. Let's rearrange it for a term and recheck.\"","then":"Your partner smiles. \"Thank you. A term sounds fair.\"","best":true},{"text":"\"Let's not fiddle. It's been working.\"","then":"Your partner swallows it. It has not been working for them."},{"text":"\"Fine. I'll just take all of it then.\"","then":"Your partner relaxes. You are overloaded within a month."},{"text":"\"No, we agreed. Stick with it for now.\"","then":"Your partner sighs. The heaviness remains."}],"why":"Adjusting the split over time keeps it fair for both of you."}],"relearn":"Splitting into owned domains stops one parent holding the whole list; being told your bits keeps them the planner."},
  {"id":"ep2-1041","cat":"parental-mental-load","type":"strike-rewrite","hook":"\"I take the kids out every weekend, so I'm clearly carrying my half.\"","myth":{"un":"I take the kids out every weekend, so I'm clearly carrying my half.","re":"Fun outings are great, but the invisible planning, tracking and worrying runs all week; that's the half to share too.","why":"Weekends are the easy, visible part of the load."},"relearn":"Weekend outings are real, but the week-long tracking and planning is the invisible half that also needs sharing.","persona":"Vikram","source":"weekend isn't half"},
  {"id":"ep2-1042","cat":"parental-mental-load","type":"match","hook":"Match the everyday moment to the hidden tracking behind it.","pairs":[{"left":"The lunchbox is packed","right":"Knowing what they'll eat and what's low"},{"left":"Clean uniform on time","right":"Tracking laundry, sizes and spares"},{"left":"Fees paid by the deadline","right":"Holding every due date in your head"},{"left":"Medicine given on schedule","right":"Remembering the dose, timing and refill"},{"left":"Party gift ready to go","right":"Knowing whose birthday and what they'd like"}],"relearn":"Behind each smooth daily moment sits invisible tracking; naming it is how it gets shared.","persona":"any","source":"moment to tracking"},
  {"id":"ep2-1043","cat":"parental-mental-load","type":"match","hook":"Match the 'I'll help' offer to the fuller 'I'll own it' version.","pairs":[{"left":"\"Tell me which doctor, I'll drive\"","right":"\"I'll run all the health visits\""},{"left":"\"Send a list and I'll shop\"","right":"\"I'll own groceries and what's low\""},{"left":"\"Remind me about the form\"","right":"\"I'll watch all the school dates\""},{"left":"\"Wake me if the baby cries\"","right":"\"I'll take the night shifts as mine\""},{"left":"\"Ask me when you need a hand\"","right":"\"I'll carry two whole domains\""}],"relearn":"Each 'help when asked' offer has an 'own it' version that moves the tracking, not just the task.","persona":"Vikram","source":"help to own"},
  {"id":"ep2-900","cat":"share-the-care","type":"strike-rewrite","hook":"\"I'm just babysitting my own kids while she's at the temple.\"","myth":{"un":"I'm just babysitting my own kids today.","re":"A father caring for his own child is parenting, not babysitting; it's your job, not a favour you do.","why":"You don't babysit your own children."},"relearn":"Caring for your own child is parenting, never babysitting.","persona":"Vikram","source":"not babysitting"},
  {"id":"ep2-901","cat":"share-the-care","type":"strike-rewrite","hook":"\"A baby just needs its mother in the first year; I'll get involved later.\"","myth":{"un":"A baby just needs its mother in the first year.","re":"Babies bond with both parents from birth; feeds, nappies and soothing are yours to own from day one.","why":"Bonding starts at birth, for both parents."},"relearn":"Infants attach to both parents from birth; start owning care from day one.","persona":"Vikram","source":"from day one"},
  {"id":"ep2-902","cat":"share-the-care","type":"strike-rewrite","hook":"\"Men's hands are too clumsy for nappies and tiny clothes.\"","myth":{"un":"Men's hands are too clumsy for nappies and tiny clothes.","re":"Nappies and dressing are learned by repetition; any parent who practises gets quick and confident.","why":"It's practice, not biology."},"relearn":"Care skills come from practice, not from being a mother.","persona":"any","source":"learned by doing"},
  {"id":"ep2-903","cat":"share-the-care","type":"strike-rewrite","hook":"\"I earn the money, so the night feeds are fair to leave to her.\"","myth":{"un":"I earn the money, so the nights are fairly hers.","re":"Providing is part of the job, not all of it; children need your hands-on nights and presence too.","why":"A pay-cheque isn't a pass on care."},"relearn":"Providing financially doesn't buy out your share of hands-on care.","persona":"Vikram","source":"more than the wage"},
  {"id":"ep2-904","cat":"share-the-care","type":"strike-rewrite","hook":"\"I help out a lot at home, so the care is basically shared.\"","myth":{"un":"I help out a lot, so care is basically shared.","re":"'Helping' still makes her the manager who notices and asks; sharing means owning whole tasks yourself.","why":"A helper waits to be told."},"relearn":"Owning tasks is sharing; 'helping when asked' leaves one parent in charge.","persona":"Vikram","source":"own not help"},
  {"id":"ep2-905","cat":"share-the-care","type":"strike-rewrite","hook":"\"Taking the baby to the doctor is really a mother's errand.\"","myth":{"un":"Doctor visits are really a mother's errand.","re":"Either parent can book, attend and ask the questions at check-ups; it's a task to own, not a gendered errand.","why":"Appointments aren't mother-only."},"relearn":"Appointments are a job either parent can fully own.","persona":"any","source":"appointments shared"},
  {"id":"ep2-906","cat":"share-the-care","type":"strike-rewrite","hook":"\"I can't do the school-run; I wouldn't know the routine.\"","myth":{"un":"I can't do the school-run; I don't know the routine.","re":"You learn the routine the same way she did, by doing it a few times; not-knowing is a head-start gap, not a rule.","why":"Routines are learnable, fast."},"relearn":"Not knowing a routine is fixed by doing it, not a reason to opt out.","persona":"Vikram","source":"learn the run"},
  {"id":"ep2-907","cat":"share-the-care","type":"strike-rewrite","hook":"\"Weekend dad is enough; she handles the weekdays.\"","myth":{"un":"Being the weekend dad is enough.","re":"Daily feeds, baths and bedtimes are where bonds grow; presence across the week beats a Sunday cameo.","why":"Quality care is daily, not occasional."},"relearn":"Everyday presence builds the bond; weekend-only isn't a fair share.","persona":"Vikram","source":"daily not sunday"},
  {"id":"ep2-908","cat":"share-the-care","type":"strike-rewrite","hook":"\"My father never changed a nappy and we turned out fine.\"","myth":{"un":"My father never did nappies and we turned out fine.","re":"The old default isn't a target to copy; sharing care now is better for your kids and for you.","why":"You can break the pattern you grew up with."},"relearn":"Inheriting an unequal split isn't a reason to repeat it.","persona":"Vikram","source":"break the pattern"},
  {"id":"ep2-909","cat":"share-the-care","type":"strike-rewrite","hook":"\"Sharing care fairly means I track every nappy I do versus her.\"","myth":{"un":"Sharing fairly means tracking every nappy each of us does.","re":"Fair sharing is owning whole domains and flexing for each other, not tallying a scorecard.","why":"Ownership and flexibility beat counting."},"relearn":"Fairness is owned domains plus flexibility, not a nappy scoreboard.","persona":"any","source":"no scorecard"},
  {"id":"ep2-910","cat":"share-the-care","type":"strike-rewrite","hook":"\"She breastfeeds, so naturally everything baby-related falls to her.\"","myth":{"un":"She breastfeeds, so all baby tasks fall to her.","re":"Only breastfeeding is mother-specific; burping, winding, changing and settling are all yours to take.","why":"One task is hers; the rest aren't."},"relearn":"Only feeding at the breast is mother-only; the rest you can own.","persona":"Divya","source":"only breastfeeding"},
  {"id":"ep2-911","cat":"share-the-care","type":"sort","hook":"Sort: a task only the breastfeeding mother can do, or one either parent can own?","items":[{"id":"a","text":"Feeding milk at the breast"},{"id":"b","text":"Winding the baby after a feed"},{"id":"c","text":"Bathing and dressing"},{"id":"d","text":"Rocking back to sleep at 2am"},{"id":"e","text":"Sterilising and prepping bottles"},{"id":"f","text":"Clipping tiny nails"}],"bins":[{"id":"either","label":"Either parent","valence":"pos"},{"id":"mum","label":"Mother-specific","valence":"neutral"}],"key":{"a":"mum","b":"either","c":"either","d":"either","e":"either","f":"either"},"relearn":"Only feeding at the breast is mother-specific; winding, bathing, settling and prepping are jobs either parent owns.","persona":"any","source":"either or mum"},
  {"id":"ep2-912","cat":"share-the-care","type":"sort","hook":"Sort: genuinely shared care, or lopsided dressed up as sharing?","items":[{"id":"a","text":"Each owns whole care domains"},{"id":"b","text":"One does it all, one 'helps' sometimes"},{"id":"c","text":"Nights alternated between you"},{"id":"d","text":"One is always the default backup"},{"id":"e","text":"Both can run a day solo"},{"id":"f","text":"She must remind you of every task"}],"bins":[{"id":"fair","label":"Genuinely shared","valence":"pos"},{"id":"lop","label":"Lopsided","valence":"neg"}],"key":{"a":"fair","b":"lop","c":"fair","d":"lop","e":"fair","f":"lop"},"relearn":"Owning domains, alternating nights and both running solo is shared; one doing it all while the other 'helps' is lopsided.","persona":"Vikram","source":"fair vs lopsided"},
  {"id":"ep2-913","cat":"share-the-care","type":"sort","hook":"Sort: builds both parents' competence, or keeps one parent the only 'expert'?","items":[{"id":"a","text":"Both do solo stretches with the baby"},{"id":"b","text":"One always supervises the other"},{"id":"c","text":"Both learn the full bedtime routine"},{"id":"d","text":"Treating one as the only 'expert'"},{"id":"e","text":"Swapping who does the early start"},{"id":"f","text":"Redoing his work 'properly' after"}],"bins":[{"id":"both","label":"Builds both","valence":"pos"},{"id":"one","label":"Keeps it one-sided","valence":"neg"}],"key":{"a":"both","b":"one","c":"both","d":"one","e":"both","f":"one"},"relearn":"Solo time, shared routines and swapping starts build both; constant supervision, a single 'expert' and redoing his work keep it one-sided.","persona":"any","source":"both vs one-sided"},
  {"id":"ep2-914","cat":"share-the-care","type":"sort","hook":"Sort each daily care job: clearly owned by one of you, or floating with no owner?","items":[{"id":"a","text":"Morning bath: Dad owns it"},{"id":"b","text":"Whoever notices does the nappy"},{"id":"c","text":"Bedtime story: Mum owns it"},{"id":"d","text":"'Someone' should book the jab"},{"id":"e","text":"School-run: Dad owns Mon-Wed"},{"id":"f","text":"Sick days: 'we'll figure it out'"}],"bins":[{"id":"owned","label":"Clearly owned","valence":"pos"},{"id":"float","label":"No owner","valence":"uhoh"}],"key":{"a":"owned","b":"float","c":"owned","d":"float","e":"owned","f":"float"},"relearn":"Named owners keep care reliable; 'whoever notices' and 'someone should' float onto whoever cracks first.","persona":"Meena","source":"owned vs floating"},
  {"id":"ep2-915","cat":"share-the-care","type":"sort","hook":"Sort: a fair way to split a recurring duty, or a way that quietly reloads one parent?","items":[{"id":"a","text":"Alternate night wake-ups by turn"},{"id":"b","text":"'You're better at it, you do it'"},{"id":"c","text":"Each owns some appointments"},{"id":"d","text":"Wait to be asked before helping"},{"id":"e","text":"Split the school week in half"},{"id":"f","text":"One stays the permanent backup"}],"bins":[{"id":"fair","label":"Fair split","valence":"pos"},{"id":"reload","label":"Reloads one parent","valence":"neg"}],"key":{"a":"fair","b":"reload","c":"fair","d":"reload","e":"fair","f":"reload"},"relearn":"Turns, owned appointments and a split week share the duty; 'you're better at it' and 'wait to be asked' reload one parent.","persona":"any","source":"split vs reload"},
  {"id":"ep2-916","cat":"share-the-care","type":"sort","hook":"Sort each line: owning your share, or handing it back to her?","items":[{"id":"a","text":"'I've got bath and bed tonight'"},{"id":"b","text":"'Just tell me what to do'"},{"id":"c","text":"'I booked the dentist for Friday'"},{"id":"d","text":"'Ask your mother, she'll know'"},{"id":"e","text":"'I'll take the early shift this week'"},{"id":"f","text":"'I helped a lot today, didn't I?'"}],"bins":[{"id":"own","label":"Owning it","valence":"pos"},{"id":"back","label":"Handing it back","valence":"neg"}],"key":{"a":"own","b":"back","c":"own","d":"back","e":"own","f":"back"},"relearn":"Naming what you've got and booking it yourself is owning; 'tell me what to do' and 'didn't I help?' hand it back.","persona":"Vikram","source":"own vs hand back"},
  {"id":"ep2-917","cat":"share-the-care","type":"sort","hook":"Sort: part of hands-on parenting, or only the providing half of the job?","items":[{"id":"a","text":"Paying school fees on time"},{"id":"b","text":"Doing the bedtime routine"},{"id":"c","text":"Earning the household income"},{"id":"d","text":"Sitting up with a feverish child"},{"id":"e","text":"Buying the formula and nappies"},{"id":"f","text":"Packing the school tiffin daily"}],"bins":[{"id":"hands","label":"Hands-on care","valence":"pos"},{"id":"provide","label":"Providing only","valence":"neutral"}],"key":{"a":"provide","b":"hands","c":"provide","d":"hands","e":"provide","f":"hands"},"relearn":"Providing matters, but bedtime, fevers and tiffins are the hands-on care children also need from you.","persona":"Vikram","source":"provide and care"},
  {"id":"ep2-918","cat":"share-the-care","type":"sort","hook":"Sort: a sign care is genuinely shared at home, or a sign it's still one-parent-run?","items":[{"id":"a","text":"Either of you can leave for a day"},{"id":"b","text":"Only one knows the bedtime steps"},{"id":"c","text":"Both have the paediatrician's number"},{"id":"d","text":"Tasks pile up if she's unwell"},{"id":"e","text":"Both pack the bag for an outing"},{"id":"f","text":"She writes you a list to manage"}],"bins":[{"id":"shared","label":"Truly shared","valence":"pos"},{"id":"solo","label":"One-parent-run","valence":"neg"}],"key":{"a":"shared","b":"solo","c":"shared","d":"solo","e":"shared","f":"solo"},"relearn":"Either-can-leave, both-know-the-doctor and both-pack point to shared care; pile-ups and a list point to one-parent-run.","persona":"any","source":"shared vs solo"},
  {"id":"ep2-919","cat":"share-the-care","type":"sort","hook":"Sort each move: makes care a swappable two-person job, or keeps it stuck on one?","items":[{"id":"a","text":"Both kept in the school WhatsApp"},{"id":"b","text":"Only her number on the forms"},{"id":"c","text":"Both know where the medicines are"},{"id":"d","text":"Dad never told the daily timings"},{"id":"e","text":"Either can call in the maid's leave"},{"id":"f","text":"One parent holds all the passwords"}],"bins":[{"id":"swap","label":"Swappable","valence":"pos"},{"id":"stuck","label":"Stuck on one","valence":"neg"}],"key":{"a":"swap","b":"stuck","c":"swap","d":"stuck","e":"swap","f":"stuck"},"relearn":"Shared contacts, knowledge and access make care swappable; single-name forms and hidden info keep it stuck on one.","persona":"Meena","source":"swappable vs stuck"},
  {"id":"ep2-920","cat":"share-the-care","type":"sort","hook":"Sort each weekend habit: shares the care, or leaves the real load on her?","items":[{"id":"a","text":"Dad takes the kids the whole Sunday"},{"id":"b","text":"He plays, she does feeds and naps"},{"id":"c","text":"Both cook and clean up after meals"},{"id":"d","text":"He naps while she manages both kids"},{"id":"e","text":"He owns the park-and-bath shift"},{"id":"f","text":"'Fun dad' leaves the hard bits to her"}],"bins":[{"id":"share","label":"Shares it","valence":"pos"},{"id":"leave","label":"Leaves load on her","valence":"neg"}],"key":{"a":"share","b":"leave","c":"share","d":"leave","e":"share","f":"leave"},"relearn":"Taking whole shifts and the messy bits shares the care; being 'fun dad' who skips feeds, naps and clean-up leaves the load on her.","persona":"Vikram","source":"share vs fun-dad"},
  {"id":"ep2-921","cat":"share-the-care","type":"sort","hook":"Sort: a fair way to bring in grandparent help, or a way that sidelines you as a parent?","items":[{"id":"a","text":"Grandparents help; you stay hands-on"},{"id":"b","text":"Your share quietly shifts to Dadi"},{"id":"c","text":"Family covers while both of you work"},{"id":"d","text":"You opt out because Nani's there"},{"id":"e","text":"You still own nights and bath time"},{"id":"f","text":"Grandma becomes the second parent"}],"bins":[{"id":"good","label":"Help, still parenting","valence":"pos"},{"id":"side","label":"Sidelines you","valence":"neg"}],"key":{"a":"good","b":"side","c":"good","d":"side","e":"good","f":"side"},"relearn":"Welcome grandparent help while you stay hands-on; letting your share pass to them sidelines you from your own child.","persona":"Vikram","source":"help not replace"},
  {"id":"ep2-922","cat":"share-the-care","type":"branch","persona":"Vikram","source":"alternate nights","hook":"It is the third night running that she has done the 2am feed while you slept through.","steps":[{"prompt":"At 2am the baby cries and she is already stirring. What do you do?","options":[{"text":"Ask her to wake you tomorrow night","then":"She agrees. Tomorrow she is up first again."},{"text":"Get up and say you'll take tonight's","then":"She sinks back into the pillow. The baby quiets in your arms.","best":true},{"text":"Say you're a heavy sleeper, so she'd hear first","then":"She nods wearily. She is up again by the second cry."},{"text":"Sleep on, since you have an early meeting","then":"She gets up, again."}],"why":"Getting up tonight, without being asked, gives her rest and makes the night feed yours too."},{"prompt":"Next morning, she says she is exhausted. What do you propose?","options":[{"text":"Ask her to nap more during the day","then":"She stares. \"With a baby who never sleeps?\""},{"text":"Alternate nights, starting tonight","then":"She looks up. \"Really? Starting tonight?\"","best":true},{"text":"Say you'll try to wake up more often","then":"You try. Your sleep is deep, and she is up again."},{"text":"Take weekend nights only","then":"Weekends are yours. Five nights a week remain hers."}],"why":"Alternating nights makes rest a shared thing, not a favour."},{"prompt":"A few nights later, you are up at 2am and the baby won't settle. What do you do?","options":[{"text":"Give up and put the baby beside her","then":"The baby settles beside her, and you sleep through the rest."},{"text":"Put on the TV and wait","then":"The baby cries louder. The night gets longer."},{"text":"Wake her, since she knows what works","then":"She gets up and settles the baby in minutes."},{"text":"Stay with it: burp, walk, then try a bottle","then":"You pace the hall. An hour later the baby sleeps on your shoulder.","best":true}],"why":"Staying with it, however clumsy, is how you learn what works."}],"debrief":"Alternate the nights so rest and bonding are shared, not defaulted to one of you.","relearn":"Alternate night feeds; 'heavy sleeper' shouldn't decide who's up every night."},
  {"id":"ep2-923","cat":"share-the-care","type":"branch","persona":"Vikram","source":"own appointments","hook":"Your partner has always taken your child to the doctor, and you realise you never have on your own.","steps":[{"prompt":"The next check-up is booked for Thursday. What do you do?","options":[{"text":"Go along, and let her do the talking","then":"The doctor talks to her. You drive home and hear the summary."},{"text":"Take over the appointment fully","then":"You write questions on your phone. The doctor speaks to you, not past you.","best":true},{"text":"Offer to drive, and wait in the car","then":"The car is warm, and you learn nothing about the visit."},{"text":"Ask her to tell you what to ask the doctor","then":"She writes you a list of questions. It's still her appointment."}],"why":"Owning the whole appointment, questions included, shares the health domain."},{"prompt":"At the next visit the nurse asks about allergies and the last jab, and you are not sure. What do you do?","options":[{"text":"Say you'll come back another day, with her","then":"The nurse rebooks. It's still hers to arrange."},{"text":"Check the jab card, and call her for the rest","then":"The card shows the last jab. She confirms no allergies, and you save it all in your phone.","best":true},{"text":"Call your partner and let her talk to the nurse","then":"She answers fast. She is still the one who knows."},{"text":"Guess the answers, so you don't look unprepared","then":"The nurse writes it down, and the record now has a guess in it."}],"why":"Getting the facts right keeps your child safe, and saving them is how the health story becomes yours."},{"prompt":"Two months later, your child needs the doctor on a busy morning. What do you do?","options":[{"text":"Ask her to go, since she knows the doctor","then":"She reschedules her morning and goes."},{"text":"Wait until the weekend","then":"The cough gets worse over three days."},{"text":"Take them, but call her from the waiting room","then":"You call her twice. Her morning is broken up again."},{"text":"Take them, jab card in hand, and text her after","then":"You have the card and the cough's timeline ready, and the visit is smooth.","best":true}],"why":"Taking them yourself, prepared, makes health truly a shared domain."},{"prompt":"A quarter later, the clinic sends a reminder for the next round of jabs. What do you do?","options":[{"text":"Wait until the day it's due","then":"The slots are full, and the jab slips a week."},{"text":"Book it, and put it in your calendar","then":"You book Saturday at ten, and the reminder is in your phone.","best":true},{"text":"Ignore it, since she'll probably see it","then":"She sees it two days later, and books it herself."},{"text":"Forward it to her and ask what to do","then":"She replies with a date. The booking is hers again."}],"why":"Booking it yourself and keeping it in your calendar makes the health domain yours."}],"debrief":"Own a whole appointment end to end so the health domain is genuinely shared.","relearn":"Own appointments fully; being the silent driver isn't sharing them."},
  {"id":"ep2-924","cat":"share-the-care","type":"branch","persona":"Vikram","source":"learn by doing","hook":"Every time you try a feed, your partner says \"Just leave it. It's faster if I do it.\"","steps":[{"prompt":"She reaches for the bottle before you've started. What do you do?","options":[{"text":"Do it her way, with her giving instructions","then":"She coaches every move. You follow, and the baby watches you both."},{"text":"Say you'll do it next time, once you've watched","then":"She agrees. Next time she does it again."},{"text":"Step aside and let her do it","then":"She feeds quickly. You watch, and the baby is soothed by her."},{"text":"Ask her to step back so you can learn","then":"She hesitates, then sits on her hands. The feed is slow, messy, and yours.","best":true}],"why":"Learning by doing, even slowly, is how you become as capable as she is."},{"prompt":"On another day, halfway through your feed, the baby fusses and she says \"Let me.\" What do you do?","options":[{"text":"Ask her to do it, and you'll watch","then":"She does it in a minute. You watch again."},{"text":"Snap that she never lets you learn","then":"She stiffens. \"I'm only trying to help.\""},{"text":"Say \"I've got this. Give us a minute.\"","then":"She bites her lip and steps back. The baby settles.","best":true},{"text":"Hand the baby over, since the baby is upset","then":"She takes the baby, and it stops crying. The feeding is hers again."}],"why":"Staying calm through the fuss is how you learn, and how she learns to trust you."},{"prompt":"A week later you finish a feed alone and she peeks in. What do you do?","options":[{"text":"Let her take over the burping","then":"She takes over the burping, and the feed is hers again."},{"text":"Ask if you did it right","then":"She gives three tips. She is still the expert."},{"text":"Invite her to check the bottle for herself","then":"She checks it, and she does that every time now."},{"text":"Say the baby is fine, and ask her to rest","then":"She smiles, surprised, and goes back to bed.","best":true}],"why":"Trusting your own care, and asking her to trust it, ends the double duty."}],"debrief":"Push past the 'faster if I do it' habit so both of you become fully capable.","relearn":"Learn by doing, even if slower; stepping aside keeps care one-sided."},
  {"id":"ep2-925","cat":"share-the-care","type":"branch","persona":"Vikram","source":"reframe helping","hook":"At a family function, an uncle praises you for 'helping your wife so much with the kids'.","steps":[{"prompt":"Others nod along and wait for your reply. What do you say?","options":[{"text":"Say nothing and go refill everyone's plates","then":"The talk moves on. Nobody notices you skipped the question."},{"text":"Laugh along and say you are a real help to her","then":"The uncle beams and the others nod. The word 'help' hangs in the air."},{"text":"Smile and say you're parenting your own kids","then":"The uncle blinks, then laughs. Your wife glances across the room and smiles.","best":true},{"text":"Say 'It's nothing special. Any dad would do it.'","then":"The uncle says 'Not every dad does!' and the praise only doubles."}],"why":"Naming it as parenting shows the care is your job, not a favour."},{"prompt":"Days later, your wife says she is tired of being the one who knows everything about the kids. What do you do?","options":[{"text":"Say she could relax if she trusted you more","then":"She goes quiet. 'It isn't trust. It's who notices first.'"},{"text":"Say you always do whatever she asks","then":"She sighs. 'That's the problem. I have to ask.'"},{"text":"Ask which part you could own start to finish","then":"She thinks, then says 'School forms and fees.' It is the first thing that is fully yours.","best":true},{"text":"Offer to do more of the chores she lists","then":"She lists five and you do them all. She is still the one listing."}],"why":"Owning a job end to end moves the noticing to you, not just the doing."},{"prompt":"Your daughter tells a friend, 'Papa helps Mama with us.' What do you do?","options":[{"text":"Ask your wife to explain it to her later","then":"Your wife explains it patiently. Your daughter hears it only from her."},{"text":"Tell her you and Mama both look after her","then":"She thinks about it. 'Both of you?' she asks, and grins.","best":true},{"text":"Correct her sharply so she never says it again","then":"She goes quiet and stares at her plate. She stops talking about it."},{"text":"Let it pass because she is too small to notice","then":"She repeats it at dinner the next week. Your wife raises an eyebrow."}],"why":"Kids copy the words they hear, so say the shared version out loud."}],"debrief":"Reframe 'helping' as parenting so your share is owned, not credited as a favour.","relearn":"You parent your own kids; 'helping' framing leaves her the manager."},
  {"id":"ep2-926","cat":"share-the-care","type":"branch","persona":"Vikram","source":"hold after leave","hook":"You're back from paternity leave, and the feeds and school-runs are sliding back to your wife.","steps":[{"prompt":"Your first week back is hectic and she covers the morning again. What do you do?","options":[{"text":"Tell her work has to come first for now","then":"She nods and says 'Okay.' The morning routine is hers again by default."},{"text":"Do what you can and let her fill the gaps","then":"She fills every gap quietly. By Friday she is doing most of it."},{"text":"Pick fixed shifts you own, like mornings and bedtime","then":"Your wife looks up, surprised. 'Even on office days?' she asks.","best":true},{"text":"Offer to help whenever she asks","then":"She has to ask each time, and mostly she has no time to ask."}],"why":"Fixed shifts you own survive a busy week better than good intentions."},{"prompt":"Your wife has an early call Thursday, so the school-run needs you. Then your manager sets an 8 a.m. meeting. What do you do?","options":[{"text":"Ask your manager to move it, and do the run","then":"Your manager agrees to 9:30. You drop the kids and she takes her call.","best":true},{"text":"Attend the meeting and ask your wife to cover","then":"She covers the run and joins her own call late."},{"text":"Say yes to both and hope the meeting starts late","then":"It starts on time. Your wife ends up doing the run while on her call."},{"text":"Attend and plan to make it up some other day","then":"That other day never quite comes, and she does the next run too."}],"why":"Moving the meeting keeps your word without dumping the run on her."},{"prompt":"A festival week brings guests, and the kids' routines start to blur. What do you do?","options":[{"text":"Leave the kids with the relatives since guests are here","then":"The relatives gladly take over. You are free, and the kids keep looking for you."},{"text":"Let it run and sort it out next week","then":"By Sunday the feeds and cooking are hers. Next week feels far away."},{"text":"Ask what she needs and do that","then":"She lists jobs and you do them. She is still the one noticing what's needed."},{"text":"Sit with her and agree who owns what for the week","then":"It takes ten minutes. She says the guests feel easier this way.","best":true}],"why":"A quick plan for busy weeks keeps the split from quietly reverting."}],"debrief":"Protect owned shifts after leave ends so the share doesn't snap back to her.","relearn":"Hold owned care shifts after leave; don't let work undo the split."},
  {"id":"ep2-927","cat":"share-the-care","type":"branch","persona":"any","source":"share sick days","hook":"Your toddler runs a fever tonight, and one of you must stay home from work tomorrow.","steps":[{"prompt":"Your partner opens their work calendar. What do you do?","options":[{"text":"Wait to see what your partner decides","then":"Your partner takes the day, as they did the last two times."},{"text":"Offer to do tonight's fever checks but not tomorrow","then":"You handle the night. In the morning your partner still stays home."},{"text":"Offer to take tomorrow and plan the next one together","then":"Your partner exhales. 'Thank you.' You both note who is next.","best":true},{"text":"Say your meetings can't move, so it's their day","then":"Your partner nods tightly and messages their manager."}],"why":"Offering the day and planning the next one shares the career cost."},{"prompt":"The fever breaks, but the doctor asks for a follow-up visit. What do you do?","options":[{"text":"Ask your partner to book it, since they know the doctor","then":"They book it and remember the vaccines due, as they always do."},{"text":"Say you'll go if they book it and send the time","then":"They book it, send the details and remind you twice."},{"text":"Book the visit yourself and note the questions to ask","then":"You keep the slot and write your questions. Your partner has nothing to track.","best":true},{"text":"Plan to go, but sort out the date when things settle","then":"The week fills up and the follow-up slips. Your partner notices first."}],"why":"Booking it yourself moves the tracking, not just the trip."},{"prompt":"A week on, your partner says their manager has noticed the sick days. What do you do?","options":[{"text":"Suggest they ask their manager to be understanding","then":"Their manager is polite and nothing changes."},{"text":"Say you are sorry and that your work is hard to leave","then":"Your partner nods. The next sick day is still theirs."},{"text":"Suggest taking sick days in turns and agree a simple rota","then":"Your partner relaxes. 'Next one is yours? Then mine after.'","best":true},{"text":"Offer to cover the next one if your week is slow","then":"The week is busy. Your partner is left holding the plan."}],"why":"Taking turns spreads the career cost, so neither of you carries it alone."}],"debrief":"Take turns on sick days so the career cost and the caregiving are both shared.","relearn":"Share sick days; defaulting them to one parent loads the care and the career cost on them."},
  {"id":"ep2-928","cat":"share-the-care","type":"branch","persona":"Vikram","source":"fun parent gap","hook":"You know your child's favourite snack, but not their shoe size or their doctor's name.","steps":[{"prompt":"The pharmacist asks your child's weight and allergies. You go blank. What do you do?","options":[{"text":"Say 'Mum handles this' and buy the usual","then":"The pharmacist nods and tells you to check with her."},{"text":"Ask your wife to send you every detail afterwards","then":"She sends a long list. She is still the one who holds it all."},{"text":"Say you'll find out, and start owning this","then":"You note the questions. That evening you ask your wife to hand you one whole area.","best":true},{"text":"Call your wife and let her answer","then":"She answers in ten seconds from memory, in the middle of a meeting."}],"why":"Finding out and owning it starts a real habit, not a one-off fix."},{"prompt":"That weekend, your wife offers to hand over one area completely. What do you take?","options":[{"text":"Health, from jabs to the doctor's number","then":"She hands over the vaccine card. 'It's yours now. Really yours.'","best":true},{"text":"Weekend outings, the fun part","then":"She smiles. Every detail behind the fun stays with her."},{"text":"A bit of everything, so it feels fair","then":"You do scattered tasks, and she still tracks which ones."},{"text":"Clothes, but ask her the sizes each time","then":"You shop. She is still the one who knows what fits."}],"why":"A whole area, like health, builds the knowledge you are missing."},{"prompt":"A jab is due next week and nobody has mentioned it. What do you do?","options":[{"text":"Book it and ask her to bring the child along","then":"The slot is booked. She ends up handling the visit anyway."},{"text":"Wait to see if she brings it up herself","then":"She remembers the day before and books it, tired."},{"text":"Check the card and book the slot yourself","then":"The clinic confirms a time. Your wife hears about it after it is done.","best":true},{"text":"Ask her the date and then book it yourself","then":"She recalls the date instantly. She is still the one who remembers."}],"why":"Noticing and booking it yourself is what owning a domain means."}],"debrief":"Own a full domain so you carry real care knowledge, not just the fun bits.","relearn":"Owning a domain builds real knowledge; fun-parent trivia isn't sharing."},
  {"id":"ep2-929","cat":"share-the-care","type":"branch","persona":"Vikram","source":"run it solo","hook":"Your wife is travelling for work for a week, and relatives offer to 'manage the kids'.","steps":[{"prompt":"Your aunt says she will move in for the week. What do you say?","options":[{"text":"Accept gladly and let her take charge of the house","then":"Aunty takes over the kitchen and the school bags. You leave for work relieved."},{"text":"Let her stay but hand her the school mornings","then":"The mornings run smoothly under her. You never learn how they work."},{"text":"Ask your wife to leave a full day by day plan","then":"She spends two evenings writing it. She is still managing the week."},{"text":"Thank her and say you will run the week yourself","then":"Your aunt looks doubtful. 'Alone? With school and meals?' she asks.","best":true}],"why":"Running the week yourself proves you can, and your kids see it too."},{"prompt":"On day two, your child comes to you at bedtime, crying that Mama does it differently. What do you do?","options":[{"text":"Say Mama is away, so this is how it is","then":"Your child sobs harder. Sleep is still an hour away."},{"text":"Ask a relative to come and settle your child","then":"A relative settles them. Your child learns you are not the one to ask."},{"text":"Call your wife to ask how she does it","then":"She answers from her hotel room, tired. She is still on duty."},{"text":"Stay calm and offer a choice of story or song","then":"Your child picks the story and falls asleep halfway through.","best":true}],"why":"Calm and simple choices build your child's trust in you as the parent."},{"prompt":"On day five, work runs late and school pickup is an hour away. What do you do?","options":[{"text":"Ask your wife to arrange the pickup from her trip","then":"She calls three people from a meeting. It takes her whole lunch break."},{"text":"Hand the kids over to the relatives for the rest of the week","then":"The relatives gladly take over. Your child asks why you are never home."},{"text":"Let the school call your wife as usual","then":"The school calls her mid conference. She steps out to sort it."},{"text":"Ask a relative for this one pickup and keep the evening","then":"Your uncle collects your child. You reach home for dinner and bedtime.","best":true}],"why":"Using family for one real clash while owning the rest is help done well."}],"debrief":"Run the solo stretch yourself so your competence and your child's trust both grow.","relearn":"Take the solo week yourself; routinely handing off keeps you deskilled."},
  {"id":"ep2-930","cat":"share-the-care","type":"branch","persona":"Divya","source":"rebalance together","hook":"You both list the daily care and see that almost every job sits with you.","steps":[{"prompt":"Your partner looks at the list and goes quiet. What do you say?","options":[{"text":"Fold up the list and say it doesn't matter","then":"Your partner looks relieved. The list goes into a drawer, but neither of you forgets it."},{"text":"Say it's common and ask to split it together","then":"Your partner exhales. 'Okay. Where should we start?'","best":true},{"text":"Say you have done everything while they never noticed","then":"Your partner bristles. 'I didn't know. You never said.'"},{"text":"Suggest they take two or three tasks for now","then":"They pick two easy ones. You still carry the rest of the list."}],"why":"Naming an unequal split without blame opens the way to fixing it together."},{"prompt":"Later that week, your partner says 'Just tell me what to do and I'll do it.' What do you do?","options":[{"text":"Offer whole areas to own, like meals or school","then":"Your partner chooses school. 'Then I track the dates too?' 'Yes,' you say.","best":true},{"text":"Say you wish they would just notice things","then":"They shrug helplessly. 'Tell me what to notice.'"},{"text":"Write them a task list each morning","then":"They tick every task. You are up before them writing the next list."},{"text":"Keep the hard jobs and hand over the easy ones","then":"They finish the easy ones fast. The hard ones pile up with you."}],"why":"Whole areas move the noticing over, and a task list keeps it with you."},{"prompt":"A month on, something has slipped and the old tension is creeping back. What do you do?","options":[{"text":"Say nothing and hope it improves by itself","then":"It doesn't improve. Your resentment grows without anyone knowing why."},{"text":"Take the job back quietly to avoid a fight","then":"It gets done. Your partner sees the job vanish and says nothing."},{"text":"Point out every slip to prove it isn't working","then":"Your partner feels watched. The next slip goes unmentioned."},{"text":"Raise it calmly at a set check-in and adjust together","then":"You both bring notes. They admit their share got tricky, and you rework it together.","best":true}],"why":"A set check-in fixes drift together before resentment sets in."}],"debrief":"An unequal split is common. Rebalancing it together is the actual work.","relearn":"Don't just name the imbalance; rebalance it into owned shares together."},
  {"id":"ep2-931","cat":"share-the-care","type":"branch","persona":"Vikram","source":"real break","hook":"Your wife wants a weekend away alone, and you feel a flicker of panic about the kids.","steps":[{"prompt":"She asks if you are really okay with it. What do you say?","options":[{"text":"Say yes if she writes out the whole routine first","then":"She spends the evening writing it down. She is still managing from a distance."},{"text":"Say yes if your mother comes to help all weekend","then":"Your mother arrives on Friday and runs the house. You mostly watch."},{"text":"Say it's a bad time and suggest next month","then":"She nods slowly and moves it to next month. That weekend soon comes round."},{"text":"Say yes and tell her the kids are yours all weekend","then":"Her shoulders drop. 'Really? I won't need to check in?'","best":true}],"why":"Owning the full weekend gives her rest and gives you real confidence."},{"prompt":"On the Saturday she's away, your toddler has a meltdown and nothing works. What do you do?","options":[{"text":"Stay close and try one calming thing after another","then":"After twenty minutes your child leans into you and quiets down.","best":true},{"text":"Ask your mother to take over the meltdown","then":"Your mother settles the child. You watch from the doorway."},{"text":"Text your wife to ask what usually works","then":"She replies at once from the train. Her break stops there."},{"text":"Hand your child a phone to quiet things down","then":"The crying stops. The reason for it was never found."}],"why":"Staying with the child builds your skill, and hers is a real break."},{"prompt":"Your wife returns and asks how the weekend went. What do you say?","options":[{"text":"Tell her what went well and what was hard","then":"She laughs at the meltdown story. 'I'd take the next weekend too,' you add.","best":true},{"text":"Say 'All fine' and skip the hard parts","then":"She smiles. Neither of you learns what was hard."},{"text":"Say it was so hard that she shouldn't go again","then":"She goes quiet. The next trip never gets planned."},{"text":"List everything you did and wait to be thanked","then":"She thanks you. It feels like a favour, not a shared job."}],"why":"Sharing the hard parts too turns one weekend into a habit."}],"debrief":"Own the solo weekend end to end so her break is real, not remote-managed.","relearn":"Give a real break by deciding solo, not by texting her every choice."},
  {"id":"ep2-932","cat":"share-the-care","type":"branch","persona":"any","source":"domains not list","hook":"You and your partner keep clashing over who forgot what, and it is getting tense.","steps":[{"prompt":"After a missed school form, you both snap at each other. What do you suggest?","options":[{"text":"Suggest counting who forgot more this month","then":"The count starts a longer fight about who did more."},{"text":"Say you will just do it all to end the fights","then":"The fights stop. Your tiredness starts, and your partner notices."},{"text":"Suggest each of you owns whole areas start to finish","then":"Your partner thinks. 'So nobody reminds anybody?' 'Nobody,' you say.","best":true},{"text":"Suggest a shared list with reminders on both phones","then":"The list fills up. One of you keeps nudging the other about it."}],"why":"Owned areas end the chasing, and a policed list keeps one in charge."},{"prompt":"At the weekend, your partner says they want whole areas of their own. What do you say?","options":[{"text":"Take the important ones and give them the rest","then":"They receive the leftovers. Neither of you feels like an equal."},{"text":"Each pick areas you'd like and share the rest","then":"They pick school and fees. You take health and clothes.","best":true},{"text":"Split by whatever each of you did most before","then":"The old pattern returns with new names on the jobs."},{"text":"Give them the ones you like least","then":"They accept and grumble. You keep the parts you enjoy."}],"why":"Choosing areas together shares out ownership, not just the leftovers."},{"prompt":"Two weeks later, a deadline slips in your partner's area. What do you do?","options":[{"text":"Take the area back so it is done properly","then":"It is done properly. Your partner feels shut out of parenting."},{"text":"Send a reminder every week from now on","then":"The reminders land each Monday. Your partner is managed again."},{"text":"Let them fix it and talk it through later","then":"They sort it out the same day. At your weekend chat they add a calendar alert.","best":true},{"text":"Say nothing and quietly fix it yourself","then":"You fix it. Your partner never learns it slipped."}],"why":"Letting them own the fix builds the skill and keeps the area theirs."}],"debrief":"Split into owned domains, not a list one of you has to enforce on the other.","relearn":"Owned domains stop the chasing; a policed list keeps one parent in charge."},
  {"id":"ep2-933","cat":"share-the-care","type":"match","hook":"Match each recurring duty to a fair way to share it.","pairs":[{"left":"Night wake-ups","right":"Take turns or split the week"},{"left":"Doctor and dentist visits","right":"Each owns some, not all on one"},{"left":"Daily feeds and bathing","right":"Whoever's free, both capable"},{"left":"School drop and pick-up","right":"Own set days each, by name"},{"left":"Sick days off work","right":"Alternate who stays home"}],"relearn":"Nights, appointments, daily care, the school-run and sick days each have a fair, owned split when both parents can do them.","persona":"any","source":"fair splits"},
  {"id":"ep2-934","cat":"share-the-care","type":"match","hook":"Match each shared-care move to what it actually achieves.","pairs":[{"left":"Each owns set tasks","right":"No constant negotiating"},{"left":"Alternating nights","right":"Both rest and both bond"},{"left":"Both know the routines","right":"Either can step in fully"},{"left":"Both on the school forms","right":"Either gets the call"},{"left":"Dad does solo days","right":"Real, not supervised, skill"}],"relearn":"Owned tasks, alternating nights, shared routines and contacts, and solo days make care genuinely two-person.","persona":"any","source":"moves and effects"},
  {"id":"ep2-935","cat":"share-the-care","type":"match","hook":"Match each 'I'm sharing' line to whether it owns the work or just helps.","pairs":[{"left":"'I booked the jab myself'","right":"Owns the health task"},{"left":"'Tell me and I'll do it'","right":"Waits to be managed"},{"left":"'I've got bedtimes this week'","right":"Owns a whole shift"},{"left":"'I helped with the kids today'","right":"Frames care as a favour"},{"left":"'I know our daily routine'","right":"Can run the day solo"}],"relearn":"Booking, owning shifts and knowing the routine is owning care; 'tell me' and 'I helped' is being a helper.","persona":"Vikram","source":"own vs help"},
  {"id":"ep2-936","cat":"share-the-care","type":"match","hook":"Match each care job to who can actually do it.","pairs":[{"left":"Feeding at the breast","right":"Only the nursing mother"},{"left":"Giving a bottle feed","right":"Either parent, learned by doing"},{"left":"Changing and bathing","right":"Either parent, no instinct needed"},{"left":"Soothing back to sleep","right":"Either parent, with practice"},{"left":"Booking the check-up","right":"Either parent owns it"}],"relearn":"Only feeding at the breast is mother-specific; bottle feeds, changing, soothing and appointments are either parent's to own.","persona":"any","source":"who can do it"},
  {"id":"ep2-937","cat":"share-the-care","type":"match","hook":"Match each home setup to what it does to the care load.","pairs":[{"left":"Both names on school forms","right":"Either parent gets reached"},{"left":"Only her on every contact","right":"She fields every call"},{"left":"Both know where medicines are","right":"Either handles a fever"},{"left":"Dad owns Mon-Wed runs","right":"The week is truly split"},{"left":"'Whoever notices' does it","right":"Loads onto whoever cracks"}],"relearn":"Shared contacts, knowledge and named days split the load; single-contact and 'whoever notices' setups pile it on one parent.","persona":"Meena","source":"setup and load"},
  {"id":"ep2-938","cat":"share-the-care","type":"match","hook":"Match each parenting belief to the truth that replaces it.","pairs":[{"left":"'Dad is just helping out'","right":"Dad is parenting his own kids"},{"left":"'Only mum can soothe baby'","right":"Soothing is learned by doing"},{"left":"'I provide, that's my part'","right":"Kids need presence too"},{"left":"'Fair means a scorecard'","right":"Fair means owned domains"},{"left":"'Baby just needs mum early'","right":"Babies bond with both"}],"relearn":"Helping, mum-only soothing, providing-is-enough, scorecards and 'just needs mum' each get replaced by a shared-care truth.","persona":"any","source":"belief to truth"},
  {"id":"ep2-939","cat":"share-the-care","type":"match","hook":"Match each parent's everyday action to the fair-sharing principle it shows.","pairs":[{"left":"Dad runs a full solo day","right":"Both build real competence"},{"left":"They swap the early shift","right":"Flexing, not a fixed default"},{"left":"Each owns whole domains","right":"No one waits to be asked"},{"left":"Both cover sick days","right":"Career hits are shared"},{"left":"Welcome Dadi, still hands-on","right":"Help without being sidelined"}],"relearn":"Solo days, swapping shifts, owned domains, shared sick days and staying hands-on with grandparents each show fair sharing in action.","persona":"any","source":"action to principle"},
  {"id":"ep2-940","cat":"share-the-care","type":"match","hook":"Match each fairness pitfall to the fix that actually shares the care.","pairs":[{"left":"One parent the default backup","right":"Each owns set shifts"},{"left":"'You're better, you do it'","right":"He practises till capable"},{"left":"Care collapses if she's ill","right":"Both can run it solo"},{"left":"Praise for 'helping wife'","right":"Reframe it as parenting"},{"left":"Share shifts back after leave","right":"Lock in work-day shifts"}],"relearn":"Default-backup, 'you're better', single-capable, helper-praise and post-leave drift each have a fix that genuinely shares care.","persona":"any","source":"pitfall to fix"},
  {"id":"ep2-941","cat":"share-the-care","type":"role-play","persona":"Vikram","source":"claim competence","hook":"Your wife is leaving for a full day and hands you a long instruction sheet.","setup":"She is at the door with her keys.","steps":[{"prompt":"Your wife says: \"I wrote down everything. Are you sure you'll be fine?\"","options":[{"text":"\"Thanks. I know most of it. Go and enjoy your day.\"","then":"She glances at the sheet, then puts it down. \"Okay. I'll enjoy it.\"","best":true},{"text":"\"Yes. I'll follow the sheet exactly and text you.\"","then":"She smiles. You will spend the day texting her updates."},{"text":"\"Honestly I'm nervous. Can you just stay home?\"","then":"Her face falls. \"I really need this day.\""},{"text":"\"Please stay on the phone all day in case.\"","then":"She agrees and adds a call every two hours to her plan."}],"why":"Trusting your own know-how frees her to rest without managing from afar."},{"prompt":"Your mother calls: \"He's never had a full day with you. Should I come over?\"","options":[{"text":"\"Come and handle the nap and the bath please.\"","then":"Ma does both. You are left with the easy parts."},{"text":"\"Come for lunch Ma. I'll handle the day myself.\"","then":"Ma laughs. \"Fine. I'll only eat and admire.\"","best":true},{"text":"\"Yes Ma. Please come and take over.\"","then":"Ma arrives and takes the baby. You spend the day fetching things."},{"text":"\"No Ma. Don't come at all today.\"","then":"Ma sounds hurt. \"I only wanted to help.\""}],"why":"Welcoming family warmly while keeping the care yourself shares the day fairly."},{"prompt":"Your wife returns and asks: \"How was it? Tell me honestly.\"","options":[{"text":"\"Tiring and lovely. I'd like a full day each weekend.\"","then":"Her eyes light up. \"Every weekend? Then I get a day too.\"","best":true},{"text":"\"Never again. It's too much for one person.\"","then":"She goes quiet. \"That's what I do every day.\""},{"text":"\"Fine. Next time you take the hard parts.\"","then":"She raises an eyebrow. \"Which parts are those?\""},{"text":"\"Easy. Nothing to it.\"","then":"She looks unsure. \"Then why is the kitchen like this?\""}],"why":"Being honest and asking for more turns a day into a habit."}],"relearn":"Owning solo care builds your competence and frees your partner from being the only capable one."},
  {"id":"ep2-942","cat":"share-the-care","type":"role-play","persona":"Vikram","source":"not babysitting","hook":"At a crowded family lunch, you are feeding the kids while your wife finally eats.","setup":"Your uncle leans over, loud enough for the whole table.","steps":[{"prompt":"Your uncle says: \"Wah, what a dad! Babysitting the kids so nicely!\"","options":[{"text":"\"Ha. Yes, giving the wife a little break today.\"","then":"The table chuckles. Your wife's smile flickers."},{"text":"\"Please don't say that in front of the kids.\"","then":"He stiffens. \"What did I say?\" The lunch turns quiet."},{"text":"\"They're my kids, Uncle. It's not babysitting.\"","then":"He laughs awkwardly. \"Ha. Fair enough. Times have changed.\"","best":true},{"text":"\"Just doing my bit, Uncle.\"","then":"He nods, satisfied. 'Doing your bit' gets repeated all evening."}],"why":"Naming your own kids as yours claims a job, not a favour."},{"prompt":"Your aunt adds: \"A man can't really do it like a mother does, though.\"","options":[{"text":"\"That's an old-fashioned idea. Times have changed.\"","then":"Aunty huffs. \"Everyone is so touchy these days.\""},{"text":"\"You're right, Aunty. She does it better.\"","then":"Aunty nods happily. Your wife looks down at her plate."},{"text":"\"Anyone can learn it. I do it daily.\"","then":"Aunty raises an eyebrow but says nothing more.","best":true},{"text":"\"Let's not argue over lunch.\"","then":"The table goes quiet. The remark stays in the air."}],"why":"Caring is learned by doing, not decided by who you are."},{"prompt":"Your daughter asks: \"Papa, why does everyone say you're helping Mama?\"","options":[{"text":"\"They don't mean anything by it, beta.\"","then":"She frowns, unconvinced, and stores the question away."},{"text":"\"Because Mama does more. Papa just helps.\"","then":"She accepts it and repeats it at school on Monday."},{"text":"\"Ask Mama. She explains these things better.\"","then":"She asks Mama, who explains warmly. You hear none of it."},{"text":"\"Papa is a parent too, just like Mama.\"","then":"She nods. \"Then you and Mama do it together.\"","best":true}],"why":"Kids take their first lesson from the way you explain it."}],"relearn":"Naming it as parenting, not babysitting, claims your real share instead of a favour."},
  {"id":"ep2-943","cat":"share-the-care","type":"role-play","persona":"Vikram","source":"own health domain","hook":"At the clinic, the nurse keeps speaking only to your wife about your son's fever.","setup":"You are both sitting across the desk from her.","steps":[{"prompt":"The nurse asks your wife: \"He needs his fever syrup at set times. Who gives him his medicines?\"","options":[{"text":"\"Stop ignoring me. I'm his father too.\"","then":"The nurse flushes and the room tenses. Your son starts crying."},{"text":"\"We both do. Please explain the dose to me too.\"","then":"The nurse turns to you. \"Sorry, sir. I'll go through the timings with you.\"","best":true},{"text":"\"Ask her. She keeps track of these things.\"","then":"Your wife recites the details. The nurse keeps talking to her."},{"text":"\"She'll answer. I'll note it on my phone.\"","then":"You note it. The nurse still speaks only to your wife."}],"why":"Stepping in politely makes health yours, and the nurse learns to ask you."},{"prompt":"As you get up, the nurse asks you both: \"Next visit is in ten days. Who will bring him?\"","options":[{"text":"\"We'll check our diaries and call you.\"","then":"The desk closes at five. Nobody calls, and the date is left open."},{"text":"\"My wife will. She knows the routine.\"","then":"The nurse writes your wife's name against the date."},{"text":"\"I'll bring him. Please put my number on file.\"","then":"She adds your number. \"Noted, sir.\"","best":true},{"text":"\"Whoever is free. It doesn't matter.\"","then":"She writes no name. Nobody knows who will come."}],"why":"Committing to the visit and giving your number puts you on file."},{"prompt":"Later, your wife says: \"The dose times and the doctor's number are in my phone. Want them?\"","options":[{"text":"\"Just tell me when it's due each time.\"","then":"She says yes. She is still the one who tracks it."},{"text":"\"You keep them. You're better at this.\"","then":"She sighs. She is still the memory for both of you."},{"text":"\"Yes. Send them and I'll keep them from now on.\"","then":"She sends everything and deletes her reminder. She looks relieved.","best":true},{"text":"\"Send me the number and I'll ask if I need more.\"","then":"She sends it. The dose times stay in her phone."}],"why":"Taking the information over is what makes the health domain yours."}],"relearn":"Speaking up at appointments makes the health domain genuinely yours to share."},
  {"id":"ep2-944","cat":"share-the-care","type":"role-play","persona":"Vikram","source":"take the night","hook":"Your wife is up at night again and reaches for the baby.","setup":"It is two in the morning and the baby is crying.","steps":[{"prompt":"Your wife whispers: \"Go back to sleep. I've got him.\"","options":[{"text":"\"I'll take the next feed if I wake up.\"","then":"She takes this one. You sleep through the next."},{"text":"\"You're better at this. I'd only make it worse.\"","then":"She sighs and gets up. You are asleep in minutes."},{"text":"\"I'll take tonight. You sleep.\"","then":"She hesitates, then lies back. \"Really? Thank you.\"","best":true},{"text":"\"Okay. Wake me only if you can't manage.\"","then":"She nods in the dark. She does not wake you."}],"why":"Taking the night yourself gives her real rest and you real practice."},{"prompt":"The next morning your wife asks: \"Should we share the nights from now on?\"","options":[{"text":"\"Sure. Just tomorrow and we'll see.\"","then":"She nods. Tomorrow arrives and she asks again."},{"text":"\"I'll do it when I'm not tired from work.\"","then":"She says it's fine. She sleeps lightly on your nights anyway."},{"text":"\"You take weeknights and I'll do weekends.\"","then":"She counts it up. It is five nights against two."},{"text":"\"Let's swap nights. Odd nights are mine.\"","then":"She smiles. \"Odd nights yours. I'm writing it on the calendar.\"","best":true}],"why":"Fixed swapped nights turn a favour into a shared, dependable routine."},{"prompt":"Your mother says: \"A man doing night feeds? Let your wife manage. You have work.\"","options":[{"text":"\"I only do weekends Ma. Don't worry.\"","then":"Ma nods, mostly satisfied. Weeknights stay your wife's."},{"text":"\"Okay Ma. I'll stop.\"","then":"Ma is pleased. Your wife's dark circles return within days."},{"text":"\"Ma, that's not for you to decide.\"","then":"Ma folds her arms. The next meal is very quiet."},{"text":"\"Ma, he's our baby. We both share the nights.\"","then":"Ma sighs. \"Hmm. In my time... but she does look rested.\"","best":true}],"why":"Explaining the shared nights kindly keeps family close and the split intact."}],"relearn":"Offering to take and swap nights shares the rest and the bonding, instead of defaulting to one of you."},
  {"id":"ep2-945","cat":"share-the-care","type":"role-play","persona":"Vikram","source":"room to learn","hook":"Your wife keeps redoing your nappy changes 'properly'.","setup":"She hovers over the changing mat again.","steps":[{"prompt":"Your wife says: \"Wait. That's too loose. Let me do it.\"","options":[{"text":"\"Fine. You're better at it. You do the changes.\"","then":"She takes over that change, looking tired. The next time you reach for the wipes, she is hovering again."},{"text":"\"Show me once more and I'll copy you exactly.\"","then":"She shows you. Her way is now the standard for every nappy."},{"text":"\"Stop hovering. You're making me nervous.\"","then":"She flinches. \"I'm only trying to help.\""},{"text":"\"Let me do it my way and learn.\"","then":"She pauses, hands hovering. \"Okay. I'll watch.\" She looks pained.","best":true}],"why":"Room to practise is how a beginner turns into an expert."},{"prompt":"Your wife says: \"I'm not trying to take over. I just remember Sunday's leak.\"","options":[{"text":"\"See? Maybe I should stop then.\"","then":"She takes the baby back, then pauses. \"No. I don't want that either.\""},{"text":"\"It leaked once. I'll adjust and try again.\"","then":"She bites her lip. \"Okay. Try again.\"","best":true},{"text":"\"It's the nappy brand. Not me.\"","then":"She rolls her eyes. \"It's the same brand I use.\""},{"text":"\"Show me exactly and you check each one.\"","then":"She shows you. She now checks every change you make."}],"why":"One leak is a lesson, and learning by trying is how you get good."},{"prompt":"Your wife says: \"I still worry when you do it and I'm not watching.\"","options":[{"text":"\"Okay. I'll call you each time to check.\"","then":"She agrees. Her phone rings six times before lunch."},{"text":"\"Then I'll do it when you're not around.\"","then":"She shrugs. She never sees how you are doing."},{"text":"\"Then I'll leave it to you. Less stress.\"","then":"She sighs with relief and picks up the wipes."},{"text":"\"Let me do all the changes this week. Go for a walk.\"","then":"She laughs nervously. \"A whole week? Okay. I'll go for a walk.\"","best":true}],"why":"A trial week without checking lets both of you build trust."}],"relearn":"Asking for room to practise stops one parent staying the only expert."},
  {"id":"ep2-946","cat":"share-the-care","type":"role-play","persona":"Vikram","source":"stay hands-on","hook":"Your mother has come to stay for the first weeks with your newborn.","setup":"She has already lifted the baby out of his cot.","steps":[{"prompt":"Your mother says: \"Give him to me, beta. You two go and rest.\"","options":[{"text":"\"Thanks, Ma. Sit with us. I'll do bath and bedtime.\"","then":"Ma smiles. \"Fine. I'll sit and watch.\"","best":true},{"text":"\"Take him tonight. Tomorrow I'll do everything.\"","then":"Ma agrees. Tomorrow never quite comes."},{"text":"\"Ma, let us manage. We don't need help.\"","then":"Ma looks hurt. \"Am I not family?\""},{"text":"\"Sure, Ma. You know better than we do.\"","then":"Ma beams and carries him off. You sit down feeling useless."}],"why":"Welcoming help while keeping your own tasks keeps you a present parent."},{"prompt":"Your wife whispers: \"She means well. Should we let her take the nights too?\"","options":[{"text":"\"You decide. I'll go with whatever you say.\"","then":"You decide nothing and she quietly adds the nights to her list."},{"text":"\"Ask her for daytime help. Nights stay ours.\"","then":"She nods. \"That works. We keep our own routine.\"","best":true},{"text":"\"Ask her to take baths and feeds too.\"","then":"Ma cheerfully takes both. You are left with very little."},{"text":"\"Yes. It's easier for everyone if she takes nights.\"","then":"Ma takes the nights. Your wife wakes anyway, listening."}],"why":"Clear boundaries let family help without pushing you out."},{"prompt":"Later, as you rock the baby, your mother says: \"In my time the mother did everything. He'll get confused.\"","options":[{"text":"\"Ma, times have changed. Please don't interfere.\"","then":"Ma stiffens. \"I'm only telling you what I know.\""},{"text":"\"He's learning both of us, Ma. That's good for him.\"","then":"Ma looks at the baby in your arms. \"He does seem happy.\"","best":true},{"text":"\"Let's talk about it another day, Ma.\"","then":"Ma shrugs. The question hangs over dinner."},{"text":"\"You're right, Ma. I'll leave it.\"","then":"Ma nods happily and lifts him from your arms."}],"why":"Children bond with both parents, so keeping your role helps everyone."}],"relearn":"Welcoming help while keeping your own care tasks lets you stay a present parent, not a sidelined one."},
  {"id":"ep2-947","cat":"share-the-care","type":"role-play","persona":"Vikram","source":"take a share","hook":"Your wife has quietly taken on nearly all the baby's care, and she is worn out.","setup":"She is folding the baby's clothes at midnight.","steps":[{"prompt":"Your wife says: \"It's just easier if I do everything.\"","options":[{"text":"\"Easier now is harder forever. Give me bedtimes.\"","then":"She stops folding. \"Bedtimes? You mean every night?\"","best":true},{"text":"\"Okay. Shout if you need a hand.\"","then":"She nods. She does not shout."},{"text":"\"You don't have to. Just tell me what to do.\"","then":"She thinks about it. Now she has one more thing to manage."},{"text":"\"You're right. You do it faster anyway.\"","then":"She smiles tiredly and keeps folding."}],"why":"Taking a whole task prevents 'easier' from loading it all on one."},{"prompt":"Days later, your wife admits: \"I'm exhausted. But you don't know the routine. I'd have to teach you.\"","options":[{"text":"\"Write it down and I'll follow.\"","then":"She writes a page. She is still the source of the routine."},{"text":"\"Never mind. Let's leave it as it is.\"","then":"She goes back to the clothes. Days later she sighs. \"I can't keep doing it all.\""},{"text":"\"Teach me once this week. Then I run it.\"","then":"She smiles slowly. \"Okay. Saturday. And then it's yours.\"","best":true},{"text":"\"I'll learn as I go. Don't worry.\"","then":"She sighs. She stays nearby in case something goes wrong."}],"why":"One short lesson beats a lifetime of her doing it all."},{"prompt":"Your wife asks: \"If we share the routine, what about the nights when work runs late?\"","options":[{"text":"\"Then we'd better skip this idea.\"","then":"She gives a small shrug and goes back to folding."},{"text":"\"I'll try to be home. If not, you cover it.\"","then":"She nods. She keeps the plan in her head."},{"text":"\"Then I'll swap a day with you and tell you early.\"","then":"She relaxes. \"Deal. Just tell me by lunch.\"","best":true},{"text":"\"I'll do my best to be there.\"","then":"She smiles. Nobody says who steps in on a late night."}],"why":"A plan for the hard nights keeps a shared job from slipping back."}],"relearn":"Taking whole tasks to own beats letting 'it's easier' quietly load everything onto one parent."},
  {"id":"ep2-948","cat":"share-the-care","type":"spot","hook":"Spot the two lines that quietly leave the care on one parent.","scene":[{"id":"a","text":"'I've got bath and bedtime tonight'","trick":false},{"id":"b","text":"'Just tell me whenever you need help'","trick":true},{"id":"c","text":"'I booked his check-up for Friday'","trick":false},{"id":"d","text":"'You're better at this, you do it'","trick":true},{"id":"e","text":"'I'll take Monday and Tuesday runs'","trick":false}],"why":"'Tell me when you need help' and 'you're better, you do it' both keep her the manager who notices and decides.","relearn":"Catch helper-talk: owning whole tasks shares care; 'tell me' and 'you do it' don't.","persona":"Vikram","source":"spot the helper lines"},
  {"id":"ep2-949","cat":"share-the-care","type":"spot","hook":"Spot the two excuses for opting out of hands-on care.","scene":[{"id":"a","text":"'I provide, so feeds are her job'","trick":true},{"id":"b","text":"'I'll learn the routine by doing it'","trick":false},{"id":"c","text":"'Men's hands are clumsy with nappies'","trick":true},{"id":"d","text":"'I'll own bath time this month'","trick":false},{"id":"e","text":"'Either of us can do the night feed'","trick":false}],"why":"'I provide, so feeds are hers' and 'men's hands are clumsy' are excuses; providing isn't the whole job and care is learned by doing.","relearn":"Catch opt-out excuses: providing and 'clumsy hands' don't excuse skipping hands-on care.","persona":"Vikram","source":"spot the excuses"},
  {"id":"ep2-950","cat":"share-the-care","type":"spot","hook":"In this 'shared' setup, spot the two things that keep it one-parent-run.","scene":[{"id":"a","text":"Both parents on the school contact list","trick":false},{"id":"b","text":"Only Mum knows the bedtime steps","trick":true},{"id":"c","text":"They alternate the night wake-ups","trick":false},{"id":"d","text":"Dad waits for a list before acting","trick":true},{"id":"e","text":"Either can take a day off solo","trick":false}],"why":"Only Mum knowing bedtime and Dad waiting for a list mean care still runs through one parent, not two.","relearn":"Catch the single-points-of-failure: shared care needs both to know the routines and act without a list.","persona":"any","source":"spot one-parent-run"},
  {"id":"ep2-951","cat":"share-the-care","type":"spot","hook":"Spot the two 'fun dad' moves that leave the hard care on her.","scene":[{"id":"a","text":"Plays all evening, skips the feeds","trick":true},{"id":"b","text":"Takes the kids the whole Sunday","trick":false},{"id":"c","text":"Naps while she manages both kids","trick":true},{"id":"d","text":"Owns the park-then-bath shift","trick":false},{"id":"e","text":"Cooks and clears up after meals","trick":false}],"why":"Playing but skipping feeds, and napping while she manages both, hand the real care back to her; sharing means taking the hard bits too.","relearn":"Catch 'fun dad': sharing care means the feeds and clean-up, not only the play.","persona":"Vikram","source":"spot fun-dad"},
  {"id":"ep2-952","cat":"share-the-care","type":"spot","hook":"Spot the two myths hiding in this chat about a new baby.","scene":[{"id":"a","text":"'A baby just needs its mother early on'","trick":true},{"id":"b","text":"'I can do bottle feeds and nappies'","trick":false},{"id":"c","text":"'Only breastfeeding is truly mum-only'","trick":false},{"id":"d","text":"'Soothing is a mother's natural instinct'","trick":true},{"id":"e","text":"'I'll take the early-morning shift'","trick":false}],"why":"'Babies just need mum early' and 'soothing is mum's instinct' are myths; babies bond with both, and soothing is learned by doing.","relearn":"Catch the baby myths: both parents bond from birth and soothing is practice, not instinct.","persona":"any","source":"spot baby myths"},
  {"id":"ep2-953","cat":"share-the-care","type":"spot","hook":"Spot the two lines that frame a father's care as a favour, not his job.","scene":[{"id":"a","text":"'I'm just helping the wife today'","trick":true},{"id":"b","text":"'I've got the kids, you go rest'","trick":false},{"id":"c","text":"'Babysitting my own two this evening'","trick":true},{"id":"d","text":"'Their appointments are mine to book'","trick":false},{"id":"e","text":"'I run our bedtime routine solo'","trick":false}],"why":"'Helping the wife' and 'babysitting my own' frame care as a favour; caring for your own kids is parenting, your job too.","relearn":"Catch favour-framing: parenting your own children is never 'helping' or 'babysitting'.","persona":"Vikram","source":"spot favour-framing"},
  {"id":"ep2-954","cat":"share-the-care","type":"spot","hook":"Spot the two things that quietly make her the only backup when plans change.","scene":[{"id":"a","text":"Only her number on every form","trick":true},{"id":"b","text":"Both know the paediatrician's name","trick":false},{"id":"c","text":"Sick-day leave always falls to her","trick":true},{"id":"d","text":"They split the school week by days","trick":false},{"id":"e","text":"Either can prep and pack the bag","trick":false}],"why":"Her on every form and always taking the sick day make her the default backup; shared care spreads the contacts and the time off.","relearn":"Catch the default-backup traps: share the forms and the sick days so either parent can cover.","persona":"any","source":"spot default backup"},
  {"id":"ep2-955","cat":"share-the-care","type":"reflect","hook":"Lensy: caring for your own child is just your job, never a favour you do your partner. Sit right?","prompt":"What do you think?","options":["Sits right","It's my job","Not a favour"],"affirm":"Shared care is simply both parents doing their own job, not one doing the other a favour.","relearn":"Caring for your own child is your job, not a favour to your partner.","persona":"any","source":"not a favour"},
  {"id":"ep2-956","cat":"share-the-care","type":"reflect","hook":"Lensy: which part of the care feels most 'defaulted' to one of you right now?","prompt":"Sit with it:","options":["The nights","The appointments","The school-run","The daily feeds"],"affirm":"Naming the part that's defaulted is the first step; you can pick it up and own it together.","relearn":"Spotting the defaulted task lets you rebalance it into an owned, shared share.","persona":"any","source":"name the default"},
  {"id":"ep2-957","cat":"share-the-care","type":"reflect","hook":"Lensy: if your partner left for a week tomorrow, which task would you feel least ready for?","prompt":"Be honest:","options":["Bedtime routine","Doctor visits","Packing for school","Soothing at night"],"affirm":"Whatever you picked is just a skill you haven't practised yet, not one only she can do.","relearn":"A task you feel unready for is unpractised, not mother-only; you can learn it.","persona":"Vikram","source":"ready to solo"},
  {"id":"ep2-958","cat":"share-the-care","type":"reflect","hook":"Lensy: think of one care task you'd like to fully own from now on. Which is it?","prompt":"Pick one:","options":["Mornings and school-run","Bath and bedtime","Health and appointments","Night feeds"],"affirm":"Owning even one whole domain end to end shifts you from helper to genuine co-parent.","relearn":"Owning a full domain, not scattered chores, is what makes care truly shared.","persona":"Vikram","source":"pick a domain"},
  {"id":"ep2-959","cat":"share-the-care","type":"reflect","hook":"Lensy: what's one moment from this week where you were the parent your child really needed?","prompt":"Recall it:","options":["A night I settled them","A meal I made them","A worry I eased","A trip I handled"],"affirm":"That moment is proof your hands-on presence matters as much as anything you provide.","relearn":"Your everyday presence and care matter as much as providing; both are your job.","persona":"Vikram","source":"presence matters"},
  {"id":"ep2-960","cat":"share-the-care","type":"reflect","hook":"Lensy: an uneven split isn't a failing; naming it together is the work. How does that land?","prompt":"What comes up?","options":["A relief","Feels fair","Worth a talk","Let's rebalance"],"affirm":"You're not blaming anyone; you're just choosing to share the care more fairly from here.","relearn":"An unequal split is common, not a failing; naming and rebalancing it together is the work.","persona":"any","source":"no blame"},
  {"id":"ep2-961","cat":"share-the-care","type":"reflect","hook":"Lensy: when does a fair split tend to snap back to one parent in your week?","prompt":"Notice it:","options":["After a work crunch","On weekends","When relatives visit","When someone's ill"],"affirm":"Spotting when it slips lets you protect your owned shifts exactly when defaults pull hardest.","relearn":"Defaults snap back at predictable moments; spotting them helps you hold your share.","persona":"any","source":"when it slips"},
  {"id":"ep2-1350","cat":"tools-and-help","type":"branch","persona":"Vikram","source":"fair-start tool","hook":"A new baby is weeks away, and you want a concrete plan for a fair split.","steps":[{"prompt":"Your wife says she'd like to plan before the baby comes. What do you do?","options":[{"text":"List every newborn task and worry together","then":"You fill a page: feeds, nights, jabs, sleep. She adds worries you hadn't noticed.","best":true},{"text":"Say you'll wait and see how the first weeks go","then":"She nods slowly. The plan waits, and so does the sleep."},{"text":"Offer to buy everything on her list","then":"The cot and clothes arrive. The care itself stays unplanned."},{"text":"Say you'll pitch in a lot once the baby is here","then":"She smiles. 'Pitching in' means she will be the one to assign jobs."}],"why":"A list built together makes fair a plan, not a hope."},{"prompt":"Later, the talk turns to who does what, and your wife says only breastfeeding is hers. What do you do?","options":[{"text":"Say everything else can be shared","then":"She looks surprised. \"Nights, nappies, appointments? All of it?\"","best":true},{"text":"Agree and take only what's left over","then":"She keeps most of the list. You take the small leftovers."},{"text":"Say you'll do nappies since that's easiest","then":"You do nappies. Nights, jabs and worries stay with her."},{"text":"Leave the nights to her since she is feeding","then":"The plan has her up every night, even for what you could do."}],"why":"Only breastfeeding is hers. Everything else can be shared."},{"prompt":"Later she asks which domains you would like to own. What do you say?","options":[{"text":"Whichever ones she is happiest to give away","then":"She keeps the parts she likes least. She is still choosing."},{"text":"Health and sleep routines, start to finish","then":"She writes your name against both. \"That's a lot of remembering.\"","best":true},{"text":"Nappies and baths, all the hands-on bits","then":"You get the physical jobs. Tracking and planning stay hers."},{"text":"Play and outings, the fun and easy part","then":"Outings sound fun. Every dull detail is still hers."}],"why":"Owning a whole domain means you notice and plan, not just do."},{"prompt":"Your mother-in-law says babies need only their mothers at first. What do you do?","options":[{"text":"Nod politely and stay quiet about it","then":"She smiles. Your wife hears that you agreed."},{"text":"Say infants bond with both parents","then":"She raises an eyebrow. \"Hmm. That's not how I did it.\"","best":true},{"text":"Agree she should move in and take charge at first","then":"She beams. Your plan for the nights quietly shrinks."},{"text":"Tell her that she is very old-fashioned","then":"She is hurt. The dinner is awkward."}],"why":"Babies attach to both parents, and saying so kindly protects your share."}],"debrief":"List the tasks and the worry, then each own domains: a built plan beats a vague 'pitch in'.","relearn":"Map newborn tasks and the worry, then each own domains; 'pitching in' keeps one the manager."},
  {"id":"ep2-1351","cat":"tools-and-help","type":"branch","persona":"Divya","source":"monthly check-in","hook":"Three months into your split, you're not sure it is still fair.","steps":[{"prompt":"You feel a familiar tiredness creeping back. What do you do?","options":[{"text":"Note every slip to bring up later","then":"You keep a list. It turns into a complaint waiting to happen."},{"text":"Say nothing and quietly take on a bit more","then":"You do more. Nobody knows you are doing it."},{"text":"Wait until someone snaps to talk about it","then":"Nobody snaps yet. The tiredness settles in."},{"text":"Suggest a monthly check-in on who carries what","then":"Your partner nods. \"Okay. First Sunday of the month?\"","best":true}],"why":"A planned check-in catches drift early and keeps it calm."},{"prompt":"Your partner sees you're worn out, but says fairness talks always feel like complaints. What do you do?","options":[{"text":"Send a long message with all your points","then":"They read it twice. They feel put on trial."},{"text":"Keep it light. Just what drifted and one change","then":"They relax. \"That I can do.\"","best":true},{"text":"Say complaints are exactly what it is for","then":"They stiffen and dread the next talk."},{"text":"Drop the subject to avoid another long fight","then":"They look relieved. The drift carries on."}],"why":"A light, simple format keeps check-ins about the team, not blame."},{"prompt":"Weeks later, you notice you are tracking the school calendar again. What do you do?","options":[{"text":"Name it and re-trade so school is theirs","then":"They nod. \"I'll take the dates and forms, all of it.\"","best":true},{"text":"Take it back since it's quicker","then":"It is quicker. You are the one tracking again."},{"text":"Ask them to check with you before each date","then":"They check with you every time. You are still the manager."},{"text":"Say you'll track it just this term","then":"It is a term, and then the next term."}],"why":"Handing back the whole area moves the tracking with it."},{"prompt":"A month later your partner names a drift on their side. What do you do?","options":[{"text":"Listen, thank them and adjust your share","then":"They relax. \"Thanks. I thought you'd be upset.\"","best":true},{"text":"Agree quickly and change nothing at all","then":"They hear the yes. Nothing shifts."},{"text":"Defend yourself against each point they make","then":"They stop talking. The next talk is shorter."},{"text":"Say you are too tired to hear it tonight","then":"They nod. The drift stays as it is."}],"why":"Hearing feedback openly keeps the check-in fair to both of you."}],"debrief":"A calm monthly check-in catches drift early; waiting for a blow-up means it's already entrenched.","relearn":"Schedule a calm monthly check-in to name drift and re-trade domains, not wait for a blow-up."},
  {"id":"ep2-1352","cat":"tools-and-help","type":"branch","persona":"Vikram","source":"shared calendar","hook":"Appointments and class events keep landing only in your wife's head, catching you off guard.","steps":[{"prompt":"You miss another school event you never heard about. What do you do?","options":[{"text":"Say you'll just remember next time","then":"You forget. The next event comes as a surprise again."},{"text":"Set alerts for whatever she tells you","then":"Your phone buzzes on time. She still has to tell you."},{"text":"Ask her to text you a reminder each time","then":"She agrees. She is still tracking everything."},{"text":"Suggest one shared calendar you both add to","then":"She lights up. \"Yes. Let's put the school and the doctor on it.\"","best":true}],"why":"One shared calendar moves the schedule out of one head."},{"prompt":"A shared calendar goes up, but after a week only your wife has added entries. What do you do?","options":[{"text":"Add what you know and check it every morning","then":"You add two events. She notices the new entries with a smile.","best":true},{"text":"Wait for her to add things and then read them","then":"You read it. She is still the one putting it in."},{"text":"Ask her to add everything in one go","then":"She adds it all in an evening. She is the keeper again."},{"text":"Say the calendar is a bit much for you","then":"She shrugs. The old habit returns."}],"why":"Both adding and both checking is what makes it shared."},{"prompt":"A doctor visit and a school event fall on the same day. What do you do?","options":[{"text":"Ask your mother to go to the school event","then":"Ma goes. Neither of you is at the event."},{"text":"Ask her to sort out the clash between them","then":"She sorts it out. She was the one who managed it before."},{"text":"Choose whichever suits your own work better","then":"Your work is fine. She has to rearrange hers."},{"text":"Check the calendar and split the day together","then":"You take the doctor and she takes school. It takes two minutes.","best":true}],"why":"A shared calendar shows the clash so both of you decide."}],"debrief":"A shared calendar you both own moves tracking out of one head; reminders keep one the manager.","relearn":"Use one shared calendar you both keep, so the schedule isn't held in one head."},
  {"id":"ep2-1353","cat":"tools-and-help","type":"branch","persona":"Meena","source":"domain swap","hook":"You own all the health admin and your partner owns school, and both of you are stretched thin.","steps":[{"prompt":"Your partner says the lanes feel stuck and asks for ideas. What do you suggest?","options":[{"text":"Keep the lanes and wait for a calmer term","then":"Things stay as they are. Neither of you can cover the other."},{"text":"Split each area's tasks in half","then":"Both areas now need two people. It gets confusing."},{"text":"Keep lanes and each ask the other for help","then":"You ask for help sometimes. Each lane stays solo."},{"text":"Swap domains for a month and share notes","then":"Your partner grins. \"Deal. I'll take health if you take school.\"","best":true}],"why":"Swapping domains shows each of you what the other carries."},{"prompt":"Your partner covers a doctor visit for you and rings, unsure about the routine. What do you do?","options":[{"text":"Send a full manual and check in daily","then":"They follow the manual. You are still the manager."},{"text":"Say you'll do all the visits from now on","then":"It's simpler. They never learn how it works."},{"text":"Answer the question and let them run it","then":"They write it down. They call less each day.","best":true},{"text":"Refuse to help so they learn fast","then":"They struggle for two days. The clinic gets a wrong date."}],"why":"Answering questions helps them learn without taking the domain back."},{"prompt":"A few weeks on, a new school term brings a fresh wave of admin. What do you do?","options":[{"text":"Compare who has it harder","then":"It becomes a contest. Nobody wins."},{"text":"Decide together which areas to swap","then":"You keep some and swap some. You agree to rotate every few months.","best":true},{"text":"Swap areas for good without discussing it","then":"It works for a while. Then the new lanes get stuck too."},{"text":"Settle back into your usual lanes","then":"The lanes stay fixed. Neither of you can cover the other."}],"why":"Swapping now and then builds backup and respect."}],"debrief":"Swapping a domain now and then builds backup and respect; fixed lanes mean neither can cover.","relearn":"Swap domains now and then so each learns the other's load and can cover it, not lock lanes."},
  {"id":"ep2-1411","cat":"tools-and-help","type":"branch","persona":"Vikram","source":"default snap-back","hook":"Your second baby arrives, and the load quietly slides back to your wife, like the first time.","steps":[{"prompt":"A week after the birth, your wife is doing all the night settling and changing again. What do you do?","options":[{"text":"Offer to help when she asks","then":"She doesn't ask. She has no energy to ask."},{"text":"Tell yourself it's only temporary","then":"It feels temporary. In a month it will be the routine."},{"text":"Say the old default is creeping back","then":"She looks up, tired. \"You noticed it too.\"","best":true},{"text":"Let her since she is feeding anyway","then":"She feeds, settles and changes. Only the breastfeeding had to be hers."}],"why":"Naming the slide early is the first step in stopping it."},{"prompt":"A few days later, worn out, your wife says something has to change. What do you say?","options":[{"text":"I'll take whatever you're too tired for","then":"You take what she can't manage. She still decides."},{"text":"The elder one's care, since you have the baby","then":"She keeps the baby's care. The split slides further."},{"text":"What I owned before, plus the baby's health","then":"She nods. \"That's a lot. Are you sure?\" \"Yes,\" you say.","best":true},{"text":"Let's decide once things settle","then":"Things do not settle. Nothing gets decided."}],"why":"Re-claiming whole areas puts both parents back in charge."},{"prompt":"Your elder child asks if Papa will do bedtime again, like before. What do you do?","options":[{"text":"Say Papa is busy with the baby right now","then":"She nods. She notices who is not busy."},{"text":"Say you'll do it tonight and start again","then":"She hugs you. \"Story too?\" \"Story too,\" you say.","best":true},{"text":"Ask Mama to do bedtime as she has been","then":"Mama does it, tired. The old pattern gets firmer."},{"text":"Promise to do it again very soon","then":"She waits, and asks again tomorrow."}],"why":"Restarting bedtime shows the elder child that both parents show up."},{"prompt":"Your mother says a newborn needs the mother and you should focus on work. What do you do?","options":[{"text":"Say the baby needs both parents","then":"She raises an eyebrow. \"Hmm. Well, he does look calm with you.\"","best":true},{"text":"Agree that work is very busy just now","then":"She smiles. Your wife hears you agree."},{"text":"Say nothing and just let it pass by","then":"She takes your silence as agreement."},{"text":"Say she is completely out of date","then":"She is offended. The next visit is stiff."}],"why":"Both parents matter to a newborn, so say it plainly."},{"prompt":"Two months on, things are steadier. What do you do?","options":[{"text":"Relax and let the routine settle","then":"The routine settles. It settles around the old default."},{"text":"Assume the reset will hold by itself","then":"It holds for six weeks. Then it slips."},{"text":"Wait until the baby's first birthday to review","then":"By the birthday the old pattern is firm."},{"text":"Hold a check-in and re-trade domains","then":"You put it in the calendar. The next check-in is in a month.","best":true}],"why":"Defaults snap back hardest with each baby, so keep checking in."}],"debrief":"Defaults snap back hardest with each baby; name it and re-claim domains before 'temporary' sticks.","relearn":"Name the default creeping back with a new baby and re-claim domains, not 'temporary'."},
  {"id":"ep2-1354","cat":"tools-and-help","type":"branch","persona":"any","source":"grandparent help","hook":"Grandparents at home keep going to your partner for everything, as if care is 'her' department.","steps":[{"prompt":"Your mother asks only your partner when the baby last fed. What do you do?","options":[{"text":"Tell her firmly to stop asking only your partner","then":"Grandma is stung. \"I only asked a question.\""},{"text":"Say your partner knows these things better","then":"Grandma nods happily. Your partner gives you a long look."},{"text":"Answer her yourself and say you both know","then":"Grandma blinks. \"Oh. You know too?\" Your partner smiles at you.","best":true},{"text":"Let your partner answer as she always does","then":"Your partner answers. Grandma's habit is a little stronger."}],"why":"Answering yourself shows you know as much as your partner."},{"prompt":"Later, your mother says she has always asked the mother about babies, and that's how it's done. What do you do?","options":[{"text":"Say old habits are hard and let it go","then":"She relaxes. The questions keep landing on one person."},{"text":"Say she can ask either of you","then":"She hesitates. \"Either? Even you?\" She tries it at dinner.","best":true},{"text":"Say she should try harder to change","then":"She feels criticised. She avoids asking anyone for a day."},{"text":"Ask your partner to talk to her about it","then":"Your partner explains it kindly. It becomes her job to fix it."}],"why":"Naming both parents gives the family a new default to follow."},{"prompt":"You and your partner agree on a plan. How do you tell the grandparents?","options":[{"text":"Send a message to the family group","then":"The family group fills up with thumbs. Nobody discusses it."},{"text":"Tell them together over tea, warmly and simply","then":"They listen. \"So we ask both of you? Fine.\"","best":true},{"text":"Tell them you will decide who does what","then":"They hear a rule from one of you. Your partner feels bypassed."},{"text":"Leave it to your partner to tell them","then":"Your partner tells them. They hear it as her preference."}],"why":"Telling them together shows you both own the care."},{"prompt":"A month on, a grandparent routes a question to your partner again. What do you do?","options":[{"text":"Smile and say you know that one","then":"Grandma laughs. \"You do! I keep forgetting.\"","best":true},{"text":"Stay silent and let your partner reply","then":"Your partner replies. The habit survives another week."},{"text":"Snap that you already told them","then":"The room goes tense. Grandma says she will not ask anyone."},{"text":"Say you'll check with your partner and come back","then":"You check. The question travels through your partner anyway."}],"why":"A light, repeated reminder does more than a one-off talk."}],"debrief":"Warmly tell grandparents you both own the care, so they coordinate with both, not just one.","relearn":"Loop grandparents in to coordinate care with both parents, not route everything to one."},
  {"id":"ep2-1355","cat":"tools-and-help","type":"branch","persona":"Divya","source":"load audit","hook":"You suspect you carry far more of the kids' invisible admin than anyone can see.","steps":[{"prompt":"Your partner says you split things evenly and asks why you are tired. What do you do?","options":[{"text":"Say nothing and keep going as before","then":"You keep going. The tiredness stays."},{"text":"List everything you did in the last month","then":"Your partner can't verify half of it. They dispute two items."},{"text":"Suggest logging one week of who decides what","then":"Your partner shrugs. \"Sure. Let's see.\"","best":true},{"text":"Say you don't know. You just feel it","then":"Your partner nods sympathetically. Nothing else is said."}],"why":"A week of real notes gives you both facts to look at."},{"prompt":"A week later, a school form comes home and you want proof of who handles these. What do you do?","options":[{"text":"Note who spotted it, who decided and who did it","then":"You write three lines. Your partner adds one of their own.","best":true},{"text":"Ask your partner to write down what they handle","then":"They do it after your reminder. The reminding is still yours."},{"text":"Log it and hint loudly that it was you","then":"Your partner reads the hint. The mood tightens."},{"text":"Do it quickly and don't write anything down","then":"The form is done. Your notes for the week are thin, with little to show who handled it."}],"why":"Logging who noticed, decided and did it shows the hidden part."},{"prompt":"A week on, you and your partner go over whatever notes there are, and they look surprised. What do you do?","options":[{"text":"Ask what surprised them most","then":"They pause. \"I didn't know I never noticed.\"","best":true},{"text":"Point out every job you did","then":"They feel cornered and start defending."},{"text":"Say 'See? I told you.'","then":"They stiffen. The talk turns into a scoreboard."},{"text":"Change the subject since they look upset","then":"The moment passes. Days later your partner brings it up again anyway."}],"why":"Asking what surprised them lets them see it for themselves."},{"prompt":"Days later, your partner admits they had not seen all of it. What do you do?","options":[{"text":"Say it doesn't matter now that they know","then":"They relax. The pattern carries on."},{"text":"Ask them to just remember to check more","then":"They try. The noticing stays with you."},{"text":"Choose two domains to hand over so they notice too","then":"They pick school and health. \"I'll start with the calendar.\"","best":true},{"text":"Say you'll keep noticing and they can just do","then":"You keep managing. The record stays the same next week."}],"why":"Handing over whole domains moves the noticing, not only the doing."}],"debrief":"Log a real week of who noticed and decided what; the record settles 'it's even' better than memory.","relearn":"Log a week of who noticed and decided, then read it together, not argue fairness from memory."},
  {"id":"ep2-1356","cat":"tools-and-help","type":"branch","persona":"Vikram","source":"stop assigning","hook":"You keep waiting for your wife to tell you what the kids need before you act.","steps":[{"prompt":"Your child's school shoes are falling apart. What do you do?","options":[{"text":"Check the size and buy the shoes yourself","then":"You measure his foot. He is a size bigger than you guessed.","best":true},{"text":"Say 'Just tell me what to do'","then":"She sighs and sends you a message with shoe sizes."},{"text":"Wait for your wife to mention it","then":"She mentions it on Friday evening. The shop is closing."},{"text":"Ask your wife whether they need new shoes","then":"She tells you the size, the brand and the shop. She is still tracking it."}],"why":"Noticing and buying yourself is what owning it feels like."},{"prompt":"Your wife says she'd love you to take a whole area, not just tasks. What do you say?","options":[{"text":"Take the same tasks, just more often","then":"You do more. Nothing about the noticing has moved."},{"text":"Say you're not sure you can keep track","then":"She nods gently. She keeps track, as she always has."},{"text":"Take whichever tasks she lists each week","then":"She writes a list every Sunday. She is still the manager."},{"text":"Take health end to end: jabs, doctors and medicines","then":"She hands over the vaccine card. \"It's really yours.\"","best":true}],"why":"A whole area means you notice and decide as well as do."},{"prompt":"A month on, a jab date slips by and nobody noticed. What do you do?","options":[{"text":"Say you didn't know it was due","then":"That is true. Nobody has fixed it."},{"text":"Say tracking all this is too much for you","then":"Your wife takes the tracking on. You are back to being told what to do."},{"text":"Book the next slot, set alerts and own it","then":"The clinic gives you a date. Your phone now reminds you first.","best":true},{"text":"Ask your wife to remind you next time","then":"She agrees. She is the one tracking it."}],"why":"A slip is fixed by better routines, not by passing the tracking back to her."}],"debrief":"Own a domain end-to-end so you notice and decide; 'just tell me' keeps your partner the manager.","relearn":"Own a domain so you notice and decide yourself; 'just tell me' keeps your partner the manager."},
  {"id":"ep2-1357","cat":"tools-and-help","type":"branch","persona":"Meena","source":"route burnout","hook":"For weeks your partner has carried most of the parenting load, and it is showing.","steps":[{"prompt":"Your partner snaps over a small spill and then sits down looking exhausted. What do you do?","options":[{"text":"Ask them not to snap at the kids again","then":"They look away. They feel judged on top of tired."},{"text":"Tell them to toughen up and just push on through","then":"They nod stiffly and get up. The exhaustion stays."},{"text":"Say they look depleted and ask how to help","then":"They look up, surprised. \"I didn't think anyone noticed.\"","best":true},{"text":"Suggest a nap and leave it at that for now","then":"They nap. The load is exactly the same when they wake."}],"why":"Naming it kindly makes it easier for them to say what's real."},{"prompt":"The next day, your partner says: 'I'm fine. Everyone's tired.' What do you do?","options":[{"text":"Say you're worried but drop it if they argue","then":"They argue a little and you drop it for the day."},{"text":"Insist they see a doctor today","then":"They bristle. The appointment doesn't happen."},{"text":"Say it seems like more than tired","then":"They go quiet. \"Maybe. I don't know.\"","best":true},{"text":"Accept it and let it be","then":"They go back to the dishes. Nothing changes that day."}],"why":"Naming it gently opens a door without forcing them through."},{"prompt":"Later that week, your partner admits it is too much and asks you to take some jobs. Where do you start?","options":[{"text":"Take over only the jobs that you enjoy","then":"The enjoyable jobs go. The heavy ones stay with them."},{"text":"Take whole domains like meals and school","then":"They exhale. \"You'll track them too?\" \"Yes,\" you say.","best":true},{"text":"Take a few of the tasks from the long list","then":"They still track everything. The list is only slightly shorter."},{"text":"Do the jobs but wait to be told which","then":"They are still the manager. They feel less rested."}],"why":"Whole domains lift the tracking off them, not just a few jobs."},{"prompt":"Weeks later your partner is still flat and worn out. What do you do?","options":[{"text":"Wait a while, since it will pass","then":"Weeks pass. The flatness stays."},{"text":"Say other parents manage without help","then":"They go silent. They stop telling you how they feel."},{"text":"Book a holiday and hope it helps","then":"You go away. The flatness comes back with the suitcases."},{"text":"Offer to call Tele-MANAS 14416 together","then":"They hesitate, then nod. You call together and someone listens.","best":true}],"why":"Long exhaustion is real burnout, not their failing, and reaching out is never weakness."}],"debrief":"Persistent depletion is real burnout: shift domains and reach Looking After You, or Tele-MANAS 14416.","relearn":"Treat persistent depletion as real burnout; rebalance and reach support, not 'toughen up'."},
  {"id":"ep2-1358","cat":"tools-and-help","type":"branch","persona":"Vikram","source":"review as kids grow","hook":"Your split worked for a toddler, but homework, tuitions and clubs now make it feel lopsided.","steps":[{"prompt":"Homework time is chaos, and your wife is doing most of it again. What do you do?","options":[{"text":"Suggest re-mapping the older-kid tasks together","then":"She nods with relief. \"I've been meaning to say something.\"","best":true},{"text":"Say the toddler-era split worked before","then":"She nods slowly. The load stays where it is."},{"text":"Take over homework on the days you're free","then":"You help on Tuesdays. She is still the one who tracks it."},{"text":"Ask her to tell you what needs doing","then":"She sighs and starts a list. She is managing again."}],"why":"Each new stage brings new tasks, so the map needs redrawing."},{"prompt":"Later, your wife lists homework, tuitions, clubs, school events and fees as her weekly load. What do you do?","options":[{"text":"Split every item down the middle","then":"Every item needs two people. Nobody knows who is on duty."},{"text":"Take the parts you're best at","then":"She keeps the parts you're weakest at. That is most of the list."},{"text":"Take the clubs and leave the rest","then":"The clubs are fun. Everything else remains hers."},{"text":"Each choose whole areas from the list","then":"She takes tuitions and fees. You take homework and clubs.","best":true}],"why":"Whole areas keep the noticing with one person, not shared out in pieces."},{"prompt":"A week on, your ten-year-old still takes his homework straight to Mum. What do you do?","options":[{"text":"Say you'll check it when you can","then":"You check it twice. The rest still goes to Mum."},{"text":"Let it be, since Mum knows the syllabus best","then":"He keeps going to Mum with his books."},{"text":"Ask Mum to send him to you instead","then":"She sends him over. He hears it as her idea, not yours."},{"text":"Call him over and sit with it yourself","then":"He looks pleased and uncertain. \"Will you know the maths?\"","best":true}],"why":"Kids notice who does what, so own it in front of them."},{"prompt":"Next year the kids change schools and a fresh set of tasks arrives. What do you do?","options":[{"text":"Let her handle admissions since she knows the school","then":"She handles it, and the rest of the change piles on her too."},{"text":"Re-map again and set a yearly review","then":"You both sit down with a fresh page. It takes less time this time.","best":true},{"text":"Wait until it feels lopsided again","then":"It feels lopsided in a month. By then it is already hers."},{"text":"Assume the last split will still fit","then":"It doesn't. The admissions paperwork lands on her."}],"why":"Reviewing each stage keeps the split fitting the kids' new needs."}],"debrief":"Each new stage adds tasks; re-map and re-divide them or the load piles onto one parent.","relearn":"Re-map the load at each stage; a split that fit toddlers won't fit school-age kids."},
  {"id":"ep2-1359","cat":"tools-and-help","type":"branch","persona":"any","source":"praise trap","hook":"Relatives keep praising you for basic care that your partner does every day without a word.","steps":[{"prompt":"At a wedding, an aunt tells everyone what a wonderful parent you are for feeding the baby. What do you do?","options":[{"text":"Say it's nothing and change the subject","then":"The aunt is puzzled. The praise carries on later."},{"text":"Say thank you and enjoy the praise","then":"Everyone nods approvingly. Your partner looks away."},{"text":"Say you both do this every day","then":"The aunt laughs. Your partner gives you a small smile.","best":true},{"text":"Say your partner deserves the praise, not you","then":"The aunt says \"So modest!\" and praises you again."}],"why":"Naming it as shared resets the bar so care isn't seen as heroic."},{"prompt":"Your partner mutters that they never get thanked for the same jobs. What do you do?","options":[{"text":"Say that's just how families are","then":"They sigh. The praise pattern carries on."},{"text":"Say relatives don't mean any harm","then":"They nod slowly and say nothing more."},{"text":"Agree it's unfair and say so to the family","then":"Your aunt looks surprised. \"Well, I suppose it is.\"","best":true},{"text":"Say you want thanks for your own share too","then":"They stare at you. The conversation stops."}],"why":"Agreeing out loud shows relatives that praise should be equal."},{"prompt":"A few years on, your child says everyone calls you so good for helping. What do you do?","options":[{"text":"Say it isn't helping. It's your job as a parent","then":"Your child thinks for a moment. \"So it's your partner's job too?\"","best":true},{"text":"Ask your child to tell your partner they are good too","then":"Your child does. It sounds like a one-off gift."},{"text":"Say people are just being kind","then":"Your child nods. They store it away as normal."},{"text":"Say you are a good parent and enjoy it","then":"Your child beams. The word 'helping' stays too."}],"why":"Kids hear how you describe care. Call it parenting."}],"debrief":"Redirect over-praise for basic care; calling it 'helping' frames your parenting as a favour.","relearn":"Redirect lavish praise for basic care: it's your job, not a favour you do by 'helping out'."},
  {"id":"ep2-1360","cat":"tools-and-help","type":"branch","persona":"Divya","source":"ask vs own","hook":"Your partner does whatever you ask, but working out what to ask is wearing you out.","steps":[{"prompt":"Your partner says 'Just make me a list and I'll do it.' What do you do?","options":[{"text":"Offer whole areas instead of a list","then":"They pause. \"Whole areas? Like what?\"","best":true},{"text":"Say never mind and do it all yourself","then":"They look relieved and a little guilty."},{"text":"Write the list again this Sunday","then":"You write it. Your Sunday evening is gone again."},{"text":"Give them a shorter list of only urgent tasks","then":"The urgent tasks are done. The planning behind them is still yours."}],"why":"The list is the mental load, so handing it over means handing over areas."},{"prompt":"Later, your partner asks again what they can take off you. What do you say?","options":[{"text":"I'll choose and you follow","then":"You choose. They follow. You are still the planner."},{"text":"Whichever is easiest to learn","then":"They pick the easiest. The heavy areas stay with you."},{"text":"School: dates, forms and fees","then":"They write it down. \"All of that? Okay.\"","best":true},{"text":"Only the parts you're tired of","then":"They take the leftovers. You keep planning around them."}],"why":"Handing over a full area, with its dates and forms, moves the tracking too."},{"prompt":"A week later, your partner asks you what's due this week. What do you do?","options":[{"text":"Say they should really know this by now","then":"They go silent. They stop asking you altogether."},{"text":"Point them to the diary and the school group","then":"They sigh, open the diary and find the dates.","best":true},{"text":"Tell them all the dates just this once","then":"You tell them. Next week they ask again."},{"text":"Say you'll just look it up for them now","then":"You look it up. You are the source again."}],"why":"Pointing to the tools lets them run their share without you."},{"prompt":"A form goes missing on their watch. What do you do?","options":[{"text":"Let them fix it and pick a way to track","then":"They ring the school and set a phone alert.","best":true},{"text":"Tell them off in front of the kids","then":"The kids stare. Your partner sees you as the boss."},{"text":"Fix it yourself quietly and say nothing","then":"It is fixed. The area drifts back to you."},{"text":"Take the area back until they've learned it","then":"The forms are safe. The area is yours again."}],"why":"A slip in a new area is the learning, so let them own the fix."}],"debrief":"Hand over whole domains, not tasks-to-assign; else the tracking that tires you most stays with you.","relearn":"Hand over whole domains to own; writing the task list keeps the tracking load on you."},
  {"id":"ep2-1361","cat":"tools-and-help","type":"branch","persona":"Vikram","source":"model for kids","hook":"Your kids only ever see their mother pack bags, cook and plan. You want them to see shared care.","steps":[{"prompt":"Your daughter asks why only Mama packs the bags. What do you do?","options":[{"text":"Say Mama is just better at it","then":"She accepts it. She adds it to what she knows about home."},{"text":"Say you're busy but will start soon","then":"She waits. Soon does not come this week."},{"text":"Say you'll pack them tonight","then":"She watches closely. \"Papa, you forgot the water bottle.\"","best":true},{"text":"Ask Mama to explain it to her","then":"Mama explains. Your daughter still never sees you pack."}],"why":"Doing it where they can see it teaches more than explaining."},{"prompt":"The evening rush begins and nobody has started dinner. What do you do?","options":[{"text":"Cook later when the kids are in bed","then":"Dinner is late. The kids never see the cooking."},{"text":"Ask your wife to start while you finish work","then":"She starts. The kids see her in the kitchen again."},{"text":"Cook in the kitchen where the kids can see","then":"They pull up stools. \"Papa is cooking!\"","best":true},{"text":"Order food and skip the kitchen","then":"Dinner arrives in twenty minutes. Nobody has cooked."}],"why":"Kids copy what they see. Cooking where they see it teaches it as ordinary."},{"prompt":"Your son says folding laundry is Mama's job. What do you do?","options":[{"text":"Say you're only helping Mama today","then":"He nods. 'Helping' sticks in his head."},{"text":"Tell him firmly not to say that again","then":"He goes quiet. He still believes it."},{"text":"Laugh and say he's right. You'll stop","then":"He grins. He learned what he wanted to."},{"text":"Say it's everyone's job and hand a towel","then":"He folds it badly. \"Like this, Papa?\"","best":true}],"why":"Chores have no gender, and handing over a towel shows it."},{"prompt":"Your mother visits and says kids shouldn't see men do house chores. What do you do?","options":[{"text":"Say kids learn from what they see","then":"She looks at the kids. \"Hmm.\"","best":true},{"text":"Stay quiet and let her have her way","then":"Your wife ends up in the kitchen alone. The kids watch."},{"text":"Do the chores when the kids are out","then":"The chores get done. The lesson doesn't happen."},{"text":"Tell her she is wrong","then":"She is hurt. The kids stop talking."}],"why":"Modelling in front of the kids is the lesson, even when family disagrees."}],"debrief":"Do care visibly so kids see it as everyone's job; hidden care quietly teaches the old divide.","relearn":"Do visible care in front of the kids on purpose; they learn the divide from what they see."},
  {"id":"ep2-1362","cat":"tools-and-help","type":"branch","persona":"Meena","source":"first-week setup","hook":"Your parental leave ends soon, and you worry the routines you built will collapse onto one of you.","steps":[{"prompt":"Your last week of leave begins, and your routines work well. What do you do?","options":[{"text":"Assume you'll both remember how it ran","then":"It feels obvious now. It won't in three weeks."},{"text":"Write down each owned domain and its handover","then":"You fill two pages. Your partner adds notes you hadn't thought of.","best":true},{"text":"Plan to sort it out once you're back at work","then":"Your partner shrugs. The last days of leave pass with nothing written."},{"text":"Ask your partner to keep it all in their head","then":"They nod. Their head is already full."}],"why":"Written handovers protect the routines from the first hectic weeks."},{"prompt":"Your first work morning arrives and the school bag isn't packed. What do you do?","options":[{"text":"Pack it together and note who owns it","then":"It takes two minutes. You jot 'bag: packed the night before, by me' on the fridge.","best":true},{"text":"Pack it yourself and rush out","then":"It's packed. Your partner is now thinking of the next thing."},{"text":"Ask your partner where the bag is","then":"They point to a shelf. You are late anyway."},{"text":"Leave it for whoever is home","then":"Whoever is home turns out to be your partner."}],"why":"A handover note shows who does what, so nobody has to ask."},{"prompt":"A big deadline falls on your pickup day. What do you do?","options":[{"text":"Swap days with your partner and note it","then":"They agree, and add a matching swap for next week.","best":true},{"text":"Skip it this week and sort it out later","then":"Your partner covers at the last minute. Next week it is easier to skip again."},{"text":"Ask your mother to cover pickup","then":"Ma covers it. Your partner is unsure who is in charge."},{"text":"Do the pickup and let the deadline slip","then":"You make pickup. The deadline slips, and you feel torn all evening."}],"why":"Swapping and noting it keeps the routine flexible without letting it slip."},{"prompt":"A month on, the routines have drifted from how you meant them to run. What do you do?","options":[{"text":"Keep going as things are for now","then":"Nobody is sure who does what, and things slip."},{"text":"Write a new plan yourself, quietly","then":"It is neat. Your partner was not part of the choices."},{"text":"Update who owns what together on Sunday","then":"You change four things and write them down. It takes twenty minutes.","best":true},{"text":"Assume you both know the routines by now","then":"Each of you remembers a different version."}],"why":"Routines need updating together, in writing, as things change."}],"debrief":"Write down owned domains and handovers before leave ends so they survive the return to work.","relearn":"Document owned domains and handovers before leave ends; 'we'll remember' lets the load slide back."},
  {"id":"ep2-1363","cat":"tools-and-help","type":"branch","persona":"any","source":"tool not scorecard","hook":"Your fairness chats keep turning into tallying who did more nappies this week.","steps":[{"prompt":"Tonight your partner counts the week's nappies aloud. What do you do?","options":[{"text":"Count back with your own tally","then":"You each recount. Nobody agrees on the total."},{"text":"Suggest checking that each of you owns whole areas","then":"They pause. \"Instead of counting?\" \"Yes,\" you say.","best":true},{"text":"Say 'Fine. You win' and drop it","then":"They win a point. The mood is worse."},{"text":"Suggest a chart on the fridge for every chore","then":"The chart goes up. The counting gets more detailed."}],"why":"A tally turns parenting into a scoreboard, so owned areas are the fix."},{"prompt":"A week on, your partner says they want a fair split without keeping score. What do you say?","options":[{"text":"Each runs an area and we flex when stuck","then":"They nod. \"So no counting?\" \"No counting.\"","best":true},{"text":"Whoever happens to have the time does it","then":"Whoever has time is usually one of you."},{"text":"Everything split exactly by the clock hours","then":"You each get exactly two hours. Nobody enjoys it."},{"text":"An equal number of tasks for each day","then":"You are back to counting, just by the day."}],"why":"Owning areas and flexing gives fairness without a scorecard."},{"prompt":"A busy week at work means your partner covers more than usual. What do you do?","options":[{"text":"Thank them and shift a job next week","then":"They smile. Next week you take an extra bath time.","best":true},{"text":"Say you will owe them one for it","then":"They now hold a favour. It is another tally."},{"text":"Ignore it since they'd do the same","then":"They said nothing. They noticed."},{"text":"Note it down so it evens out later","then":"The note is a debt. It grows every week."}],"why":"Flexing for each other fairly needs thanks and a shift, not a debt."}],"debrief":"Measure fairness by owned domains and flexibility, not a nappy tally that becomes a scoreboard.","relearn":"Check each owns whole domains and flexes, rather than tallying every chore into a scoreboard."},
  {"id":"ep2-1364","type":"match","persona":"any","source":"tool to job","hook":"Match each fair-parenting tool to the job it does.","pairs":[{"left":"The task-and-load map","right":"See and split everything fairly"},{"left":"A shared family calendar","right":"Both hold the schedule"},{"left":"A monthly parenting check-in","right":"Rebalance as life changes"},{"left":"Owned whole domains","right":"End the 'wait to be told' habit"},{"left":"A domain swap now and then","right":"Build backup and see each other's load"}],"relearn":"Map, shared calendar, check-in, owned domains and a domain swap each do a distinct job in fair parenting.","cat":"tools-and-help"},
  {"id":"ep2-1365","type":"match","persona":"any","source":"problem to fix","hook":"Match each common snag to the tool that fixes it.","pairs":[{"left":"Split drifted back to one parent","right":"A regular rebalancing check-in"},{"left":"Appointments only in one head","right":"One shared calendar you both keep"},{"left":"You keep waiting to be told","right":"Take a whole domain to own"},{"left":"Arguing fairness from memory","right":"A written week-long load audit"},{"left":"Persistent burnout from the load","right":"Reach Tele-MANAS 14416"}],"relearn":"Each parenting snag has a tool: a check-in, a shared calendar, owned domains, a load audit, or support.","cat":"tools-and-help"},
  {"id":"ep2-1366","type":"match","persona":"Vikram","source":"helper to owner","hook":"Match each 'helper' line to the 'owner' move that replaces it.","pairs":[{"left":"'Just tell me what to do'","right":"'I'll own health end-to-end'"},{"left":"'I babysat the kids today'","right":"'I parented our kids today'"},{"left":"'Remind me when it's due'","right":"'It's on my shared calendar'"},{"left":"'I helped her out a lot'","right":"'We split it as equals'"},{"left":"'You're better at this stuff'","right":"'I'll learn it by doing it'"}],"relearn":"Each helper line has an owner version: own a domain, call it parenting, track it, split it, learn by doing.","cat":"tools-and-help"},
  {"id":"ep2-1367","type":"match","persona":"any","source":"visible vs invisible","hook":"Match each parenting job to whether it's visible care or the invisible mental load.","pairs":[{"left":"Changing a nappy","right":"Visible care, anyone can see it"},{"left":"Remembering the next vaccine is due","right":"Invisible load, runs in the background"},{"left":"Packing the school bag","right":"Visible care, a clear task"},{"left":"Noticing shoes are outgrown","right":"Invisible load, the tracking work"},{"left":"Booking the dentist","right":"Invisible load, the planning work"}],"relearn":"Some jobs are visible care; the remembering, noticing and planning are the invisible load: both get shared.","cat":"tools-and-help"},
  {"id":"ep2-1368","type":"match","persona":"any","source":"check-in cadence","hook":"Match each parenting milestone to the check-in it calls for.","pairs":[{"left":"New baby arrives","right":"Re-map the whole split from scratch"},{"left":"Parent returns to work","right":"Document domains and handovers"},{"left":"Child starts school","right":"Add the new school admin to the split"},{"left":"One parent is depleting","right":"Shift domains and reach support"},{"left":"A quiet ordinary month","right":"A short routine rebalancing check-in"}],"relearn":"Each milestone calls for its own check-in: re-map, document, add new admin, shift load, or routine rebalance.","cat":"tools-and-help"},
  {"id":"ep2-1369","type":"match","persona":"any","source":"myth to tool","hook":"Match each parenting myth to the tool that quietly disproves it.","pairs":[{"left":"'She's just naturally better at it'","right":"A domain swap proves it's practice"},{"left":"'We split it once, so it's fair'","right":"A rebalancing check-in catches drift"},{"left":"'It's all even, I'm sure'","right":"A written load audit shows the truth"},{"left":"'I help plenty when asked'","right":"Owning a domain ends the asking"},{"left":"'Coping alone shows I'm strong'","right":"Tele-MANAS 14416 is for real burnout"}],"relearn":"A swap, a check-in, an audit, owned domains and support each disprove a common fair-parenting myth.","cat":"tools-and-help"},
  {"id":"ep2-1370","type":"match","persona":"any","source":"domain to owner-task","hook":"Match each owned domain to what owning it actually means end-to-end.","pairs":[{"left":"Own 'health'","right":"Track jabs, book and attend, refill medicine"},{"left":"Own 'school'","right":"Hold the calendar, forms, fees and homework"},{"left":"Own 'food'","right":"Plan meals, shop, cook, watch what's running low"},{"left":"Own 'sleep'","right":"Run the bedtime routine and the night wakings"},{"left":"Own 'clothes'","right":"Notice sizes, buy ahead, sort the laundry"}],"relearn":"Owning a domain means the whole loop of tracking, deciding and doing, not just the visible task.","cat":"tools-and-help"},
  {"id":"ep2-1371","type":"reflect","persona":"any","source":"tools recap","hook":"Lensy: the toolkit is a map, a shared calendar and a regular check-in. Which feels most useful to you?","prompt":"Which would help most?","options":["The task-and-load map","The shared calendar","The regular check-in"],"affirm":"Any of these is a real start: a map, a shared calendar or a check-in each moves you toward a fairer split.","relearn":"The map, the shared calendar and the regular check-in are the core tools; any one is a real start.","cat":"tools-and-help"},
  {"id":"ep2-1372","type":"reflect","persona":"any","source":"difficulty is normal","hook":"Lensy: keeping a fair split going takes ongoing effort for everyone. That difficulty is normal, not a sign to quit. Sit with that?","prompt":"How does that land?","options":["It's reassuring","Makes it feel workable","Good to hear it's normal"],"affirm":"It's true: the difficulty is normal and workable with tools and check-ins, never a reason to give up on fair.","relearn":"Keeping equal parenting going is ongoing effort for all; the difficulty is normal and workable, not a quit signal.","cat":"tools-and-help"},
  {"id":"ep2-1373","type":"reflect","persona":"Divya","source":"naming not blame","hook":"Lensy: an unequal split is common, not a failing. Naming it together is the work, not blaming anyone. Ready to name it?","prompt":"What's your honest take?","options":["I can name it","No blame, just fix it","It's common, not a flaw"],"affirm":"Exactly, an unequal split is common, not a failing; naming and rebalancing it together is the actual work.","relearn":"An unequal split is common, not a failing; naming and rebalancing it together, without blame, is the work.","cat":"tools-and-help"},
  {"id":"ep2-1374","type":"reflect","persona":"any","source":"over-the-years","hook":"Lensy: rebalancing isn't a one-time fix. It's a practice you maintain over the years as the kids grow. Picture that?","prompt":"What do you think?","options":["A practice, not a fix","I can keep it up","Makes sense over years"],"affirm":"Yes, rebalancing is a maintained practice over the years, not a single fix; you revisit it as life changes.","relearn":"Rebalancing the split is a maintained, over-the-years practice, not a one-time fix done and forgotten.","cat":"tools-and-help"},
  {"id":"ep2-1375","type":"reflect","persona":"any","source":"burnout not weakness","hook":"Lensy: parental burnout is real, not weakness. Reaching for support is strength, not failure. How does that sit?","prompt":"What's your take?","options":["Reaching out is strength","It's real, not weakness","Good to know support exists"],"affirm":"Right, parental burnout is real, not weakness; persistent depletion routes to Looking After You, or Tele-MANAS 14416.","relearn":"Parental burnout is real, not weakness; persistent depletion routes to Looking After You, or Tele-MANAS 14416.","cat":"tools-and-help"},
  {"id":"ep2-1376","type":"reflect","persona":"any","source":"set the tone early","hook":"Lensy: tools work best when you set the tone early and keep supporting, not undermining, each other. Feel ready to set it?","prompt":"Where are you?","options":["Ready to set the tone","We support each other","Early is better"],"affirm":"Tools support a fair-from-day-one path: set the tone early and keep backing each other, not undercutting it.","relearn":"Tools work best set early, with partners supporting, not undermining, each other on a fair-from-day-one path.","cat":"tools-and-help"},
  {"id":"ep2-1377","type":"reflect","persona":"any","source":"equipped","hook":"Lensy: map it, own domains, check in, route burnout to support. That's the whole kit. Feel equipped?","prompt":"How equipped do you feel?","options":["Equipped","I've got the kit","Ready to use it"],"affirm":"You hold the kit: map the load, own whole domains, check in to rebalance, and route real burnout to support.","relearn":"The kit: map the load, own whole domains, check in to rebalance, and route real burnout to support.","cat":"tools-and-help"},
  {"id":"ep2-1378","type":"reflect","persona":"any","source":"tools serve family","hook":"Lensy: every tool here serves the same goal, a sustainable, fair split that's better for the whole family. Worth it?","prompt":"What do you feel?","options":["Worth the effort","Better for everyone","A goal we share"],"affirm":"Every tool here serves a sustainable, fair split: one that's genuinely better for the kids and both of you.","relearn":"The tools all serve one goal: a sustainable, fair split that's better for the kids and both parents alike.","cat":"tools-and-help"},
  {"id":"ep2-1379","type":"strike-rewrite","persona":"any","source":"tools too rigid","hook":"\"All these maps and check-ins make parenting feel like a corporate project, not a family.\"","myth":{"un":"All these maps and check-ins make parenting feel like a corporate project, not a family.","re":"The tools just make the invisible load visible so it can be shared; they free you to be present, not rigid.","why":"Naming who-does-what removes the daily friction, leaving more space for the warmth."},"relearn":"Fair-parenting tools make the hidden load visible so it can be shared and you can be more present, not rigid.","cat":"tools-and-help"},
  {"id":"ep2-1380","type":"strike-rewrite","persona":"Vikram","source":"set once","hook":"\"We agreed a fair split once, so we're sorted for good.\"","myth":{"un":"We agreed a fair split once, so we're sorted for good.","re":"Rebalancing is a practice you maintain over the years; a split set once quietly drifts back to one parent.","why":"Kids' needs and your schedules keep changing, so the split has to be revisited to stay fair."},"relearn":"A fair split set once drifts back over time; rebalancing is a maintained practice as needs keep changing.","cat":"tools-and-help"},
  {"id":"ep2-1381","type":"strike-rewrite","persona":"any","source":"asking is anti-men","hook":"\"Asking dads to use 'fair-split tools' is just nagging men into extra chores.\"","myth":{"un":"Asking dads to use 'fair-split tools' is just nagging men into extra chores.","re":"The tools help fathers claim real ownership and bond with their kids: that's pro-men, not a chore list.","why":"Owning whole domains builds a father's confidence and closeness, which is a gain, not a burden."},"relearn":"Fair-split tools help fathers claim ownership and bond; that's pro-men and a gain, not nagging into chores.","cat":"tools-and-help"},
  {"id":"ep2-1382","type":"strike-rewrite","persona":"Divya","source":"needing tools = failing","hook":"\"If we need tools and check-ins to share parenting, we must be bad at it.\"","myth":{"un":"If we need tools and check-ins to share parenting, we must be bad at it.","re":"Using tools is what good co-parents do; an unequal split is common, not a failing, and tools are how you fix it.","why":"Defaults pull hard toward one parent, so naming and rebalancing on purpose is skill, not weakness."},"relearn":"Needing tools isn't failing; an unequal split is common, and using tools to rebalance is exactly the skill.","cat":"tools-and-help"},
  {"id":"ep2-1383","type":"strike-rewrite","persona":"any","source":"burnout = weak","hook":"\"A good parent should be able to cope with the load without asking for help.\"","myth":{"un":"A good parent should be able to cope with the load without asking for help.","re":"Parental burnout is real, not weakness; reaching Looking After You, or Tele-MANAS 14416, is strength.","why":"Persistent depletion is a health issue that rest and support fix, not a character test to pass alone."},"relearn":"Parental burnout is real, not weakness; reaching Looking After You, or Tele-MANAS 14416, is the strong move.","cat":"tools-and-help"},
  {"id":"ep2-1384","type":"strike-rewrite","persona":"Vikram","source":"delegating is sharing","hook":"\"I share the load: my partner just tells me what to do and I do it.\"","myth":{"un":"I share the load. My partner just tells me what to do and I do it.","re":"Being told tasks isn't sharing; sharing means owning whole domains so you do the noticing and planning too.","why":"If one parent still tracks and assigns everything, they remain the manager carrying the real load."},"relearn":"Doing tasks when told isn't sharing; owning whole domains, including the noticing and planning, is.","cat":"tools-and-help"},
  {"id":"ep2-1385","type":"strike-rewrite","persona":"any","source":"tools steal spontaneity","hook":"\"Planning the split ahead kills the natural, spontaneous side of being a parent.\"","myth":{"un":"Planning the split ahead kills the natural, spontaneous side of being a parent.","re":"Owning domains is about responsibility, not a rigid script; you still flex for each other day to day.","why":"Fair sharing is ownership plus flexibility, so the plan handles the load and leaves room to be spontaneous."},"relearn":"Owning domains is responsibility plus flexibility, not a rigid script; you still flex and stay spontaneous.","cat":"tools-and-help"},
  {"id":"ep2-1386","cat":"tools-and-help","type":"role-play","persona":"Vikram","source":"claim a domain","hook":"Your wife is drowning in kid admin, and you want to take real ownership, not just offer to help.","setup":"She sits down beside you with a pile of forms.","steps":[{"prompt":"Your wife says: \"I don't know where to start with all this.\"","options":[{"text":"\"Leave it here and I'll look later.\"","then":"She leaves it. Later is a long way off."},{"text":"\"I'll help with whatever's most urgent.\"","then":"She picks the urgent ones. The rest is still hers."},{"text":"\"Let me fully own health from now on.\"","then":"She looks at you. \"All of it? The jabs and the doctors?\"","best":true},{"text":"\"Tell me what needs doing and I'll do it.\"","then":"She starts listing. She is still the one who knows."}],"why":"Owning a whole area takes the tracking off her, not just a few tasks."},{"prompt":"Later she says: \"If health were yours, you'd have to keep every jab and doctor in your head.\"","options":[{"text":"\"I'll do it but tell me the dates.\"","then":"She writes down the dates. She is holding the calendar."},{"text":"\"I'll ask you when something comes up.\"","then":"She nods. She is still the one who remembers."},{"text":"\"Yes. I'll set alerts and keep the card.\"","then":"She smiles slowly and hands you the vaccine card.","best":true},{"text":"\"I'll try my best.\"","then":"She nods. Her face says she'll believe it when she sees it."}],"why":"Alerts and a card put the memory in your hands."},{"prompt":"She says: \"The next jab is due next week. Do you know when?\"","options":[{"text":"\"You tell me and I'll take him.\"","then":"She tells you. She is still the one who knows."},{"text":"\"Not yet. I'll check the card and book it today.\"","then":"She watches you book it. Her shoulders drop.","best":true},{"text":"\"Let's check it together.\"","then":"You check it together. She is still doing half the remembering."},{"text":"\"I thought that was on your list.\"","then":"She flinches. \"It was. It's not now.\""}],"why":"Checking and booking it yourself completes the handover."},{"prompt":"Your mother says: \"Why is a father taking him to the clinic? That's the mother's work.\"","options":[{"text":"\"She'll go next time.\"","then":"Ma nods. The next visit lands on your wife again."},{"text":"\"Ma, don't say that in front of her.\"","then":"Ma is offended. She goes to her room."},{"text":"\"Ma, health is my job now. She has enough.\"","then":"Ma goes quiet. Your wife looks at you across the room.","best":true},{"text":"\"I'm just helping her out a bit, Ma.\"","then":"Ma is pleased. Your wife's smile goes."}],"why":"Saying it's yours to family makes the handover real."}],"relearn":"Claiming a whole domain end-to-end lifts the tracking off your partner, not just the odd assigned task."},
  {"id":"ep2-1387","cat":"tools-and-help","type":"role-play","persona":"Divya","source":"ask for the check-in","hook":"You feel the split has drifted, but raising it keeps feeling like a complaint.","setup":"You find a calm moment after dinner.","steps":[{"prompt":"Your partner says: \"You look like you want to say something.\"","options":[{"text":"\"You never notice how much I do.\"","then":"They stiffen. \"That's not fair. I do lots.\""},{"text":"\"It's nothing. Just tired.\"","then":"They nod. You are both a little more tired."},{"text":"\"I feel like I'm doing everything again. Never mind.\"","then":"They look away. \"Okay.\" The moment closes."},{"text":"\"Can we do a monthly check-in on who carries what?\"","then":"They nod. \"A regular one? Okay. Sure.\"","best":true}],"why":"A regular check-in makes it about the team, not a complaint."},{"prompt":"The next day, your partner asks: \"You've seemed off. Have I done something wrong?\"","options":[{"text":"\"It's just how I have been feeling lately.\"","then":"They nod and look worried. They don't know what to do."},{"text":"\"Well. You did forget the school form again.\"","then":"They wince. The talk is already a complaint."},{"text":"\"No. I want to catch drift before it builds.\"","then":"They relax. \"Okay. That sounds fair.\"","best":true},{"text":"\"Not really. Please forget I said anything.\"","then":"They frown. \"I can't just forget it. Something's up.\""}],"why":"Naming the purpose keeps a check-in about the future, not the past."},{"prompt":"Later, your partner asks: \"If we did check in on the split, what would that even look like?\"","options":[{"text":"\"You'd ask me what needs doing this week.\"","then":"They nod. You are still the manager."},{"text":"\"A long chat about absolutely everything.\"","then":"They wince. \"That sounds exhausting.\""},{"text":"\"Ten minutes. What drifted and one change.\"","then":"They grin. \"That I can do. First Sunday?\"","best":true},{"text":"\"I'll tell you when I'm ready to talk.\"","then":"They wait. They don't know when."}],"why":"A short, simple format makes it easy to keep doing."}],"relearn":"Proposing a regular calm check-in catches drift early and keeps it a shared task, not a stored-up complaint."},
  {"id":"ep2-1388","cat":"tools-and-help","type":"role-play","persona":"Vikram","source":"set tone with grandparents","hook":"Your mother keeps handing all the baby-care questions to your wife in front of you.","setup":"She turns to your wife again at lunch.","steps":[{"prompt":"Your mother asks your wife: \"When did he last nap? Did he eat well?\"","options":[{"text":"\"Ha. She's the baby expert in this house.\"","then":"Ma smiles. Your wife gives you a small look."},{"text":"\"She'll know. Ask her.\"","then":"Ma nods and turns back. Your wife answers again."},{"text":"\"Ma, ask me too. I know that one.\"","then":"Ma turns, surprised. \"You know? Well, tell me.\"","best":true},{"text":"\"Ma, you never ask me anything about him!\"","then":"Ma frowns. \"I'm only asking a question.\""}],"why":"Inviting the question shows Ma that you are a go-to parent too."},{"prompt":"Over dessert, your mother says: \"In our day, the mother just knew. Fathers didn't need to.\"","options":[{"text":"\"Ma, that's a very old-fashioned idea.\"","then":"Ma stiffens. \"Everyone is so touchy now.\""},{"text":"\"He's ours, Ma. I do half his care.\"","then":"Ma blinks. \"Half?\" Your wife nods.","best":true},{"text":"\"Let's not discuss it at the table.\"","then":"The table goes quiet. The remark stays."},{"text":"\"You're right, Ma. I'll let her handle it.\"","then":"Ma is content. Your wife's smile fades."}],"why":"A calm, simple fact helps family see both parents at work."},{"prompt":"Later your mother says: \"Tell me what he ate this morning.\"","options":[{"text":"\"Something. I forget.\"","then":"Ma gives a small smile. \"See?\""},{"text":"\"I'll check with her.\"","then":"Ma nods slowly. She says nothing."},{"text":"\"Daliya and banana. He ate half.\"","then":"Ma is quiet. \"You gave him breakfast? Hmm.\"","best":true},{"text":"\"Ma, he ate. Stop worrying so much.\"","then":"Ma purses her lips. \"Ate what, though?\""}],"why":"Knowing the details is what makes the words true."}],"relearn":"Telling family to ask you too makes both parents the go-to, instead of routing all care to the mother."},
  {"id":"ep2-1389","cat":"tools-and-help","type":"role-play","persona":"Meena","source":"name burnout kindly","hook":"Your partner is exhausted and short-tempered from the load but won't admit they're struggling.","setup":"You catch them alone at the kitchen counter.","steps":[{"prompt":"Your partner says sharply: \"I said I'm fine. Stop asking.\"","options":[{"text":"\"Everyone's tired. You'll just have to power through.\"","then":"They go stiff and turn away. The tiredness stays hidden, for now."},{"text":"\"You're fine? Then why are you snapping at everyone?\"","then":"They flare up. \"See? That's exactly my point.\""},{"text":"\"You sound burnt out. That's real, and I'm here.\"","then":"Their shoulders drop a little. \"I didn't think you'd noticed.\"","best":true},{"text":"\"Okay. I'll leave you alone.\"","then":"They nod and stay at the counter. Nothing changes."}],"why":"Naming burnout as real opens the door without pushing anyone through."},{"prompt":"Later that night, your partner admits: \"I can't keep up with everything. I don't know what to drop.\"","options":[{"text":"\"Make a list and I'll do what you tell me.\"","then":"They start a list. The list is one more job."},{"text":"\"Let me take some domains tonight.\"","then":"They let out a long breath. \"Domains? Like what?\"","best":true},{"text":"\"Maybe try to sleep more.\"","then":"They shrug wearily. Sleep is not the problem."},{"text":"\"Drop the small things and keep going.\"","then":"They nod. The small things were half the day."}],"why":"Taking whole domains lifts the tracking, not just a few jobs."},{"prompt":"A few days later, your partner says: \"It's not just tired. I feel flat all the time.\"","options":[{"text":"\"It's probably just a phase you're in.\"","then":"They nod uncertainly. The feeling doesn't pass."},{"text":"\"Want to call Tele-MANAS 14416 together?\"","then":"They're quiet. \"Together? Okay.\" You write the number down.","best":true},{"text":"\"Let's book a holiday somewhere quiet.\"","then":"You go. The flat feeling packs with you."},{"text":"\"Let's not tell anyone. We'll manage.\"","then":"They nod. You are now both handling it alone."}],"why":"Long-lasting flatness deserves support, and reaching out together helps."},{"prompt":"One evening, your partner says: \"I feel like a bad parent for needing help.\"","options":[{"text":"\"Everyone needs help sometimes. Forget it.\"","then":"They nod. The moment ends without an answer."},{"text":"\"It's not weakness. The load is too big.\"","then":"Their eyes fill. \"Really? You think so?\"","best":true},{"text":"\"You're a great parent. Don't say that.\"","then":"They smile faintly. The guilt stays."},{"text":"\"Maybe you're right. Try harder.\"","then":"They nod, hurt. They stop talking about it."}],"why":"Needing help is never weakness, and saying so lets them believe it."}],"relearn":"Name burnout as real, share domains, and reach Looking After You or Tele-MANAS 14416."},
  {"id":"ep2-1390","cat":"tools-and-help","type":"role-play","persona":"Vikram","source":"fair from day one","hook":"You and your wife are expecting your first child and planning how you'll parent.","setup":"You are painting the nursery together.","steps":[{"prompt":"Your wife says: \"So how will we do this when the baby comes?\"","options":[{"text":"\"You'll be home more, so you lead.\"","then":"She swallows. \"Okay. If you're sure.\""},{"text":"\"Let's each own real domains from day one.\"","then":"She nods slowly. \"Real domains. I'd like that.\"","best":true},{"text":"\"Let's just see how it shakes out.\"","then":"She smiles. She has seen how it shakes out for others."},{"text":"\"I'll pitch in a lot once the baby comes.\"","then":"She nods. \"Pitch in\" sounds like helping."}],"why":"Agreeing domains before the baby arrives stops defaults from settling in."},{"prompt":"Your wife says: \"Let's be specific. What would you take on?\"","options":[{"text":"\"Let's decide when the baby's here.\"","then":"She nods. The decision waits for a tired time."},{"text":"\"The fun bits, like play and outings.\"","then":"She smiles. The dull parts stay hers."},{"text":"\"Whatever you don't feel like doing.\"","then":"She keeps her favourites. You take the leftovers."},{"text":"\"Health and sleep, start to finish.\"","then":"She writes both down. \"Jabs and doctors too?\" \"All of it.\"","best":true}],"why":"Choosing whole domains up front means you own the noticing too."},{"prompt":"Your wife says: \"What about the nights? I'll be the one feeding.\"","options":[{"text":"\"You take nights and I'll take days.\"","then":"She nods. She sleeps in broken pieces."},{"text":"\"I'll take everything except the feed.\"","then":"She looks relieved. \"Changing, settling, all of it?\" \"All of it.\"","best":true},{"text":"\"Wake me if you need me.\"","then":"She nods. She rarely does."},{"text":"\"I'll sleep so I can work well.\"","then":"She nods. She is up alone at 3 am."}],"why":"Only breastfeeding is hers, so everything else in the night can be shared."},{"prompt":"Your wife says: \"And how do we make sure it doesn't slip?\"","options":[{"text":"\"We'll deal with it when it happens.\"","then":"She looks uncertain. It happens in a month."},{"text":"\"We'll just be very careful with it.\"","then":"She nods. Careful lasts a fortnight."},{"text":"\"A monthly check-in to re-trade.\"","then":"She smiles. \"Monthly. Put it in the calendar.\"","best":true},{"text":"\"You'll tell me if it slips.\"","then":"She sighs. \"So I'm the one watching.\""}],"why":"A regular check-in keeps fair as the default, not a fight."}],"relearn":"Agreeing owned domains and a monthly check-in from day one makes fairness the default instead of a recurring fight."},
  {"id":"ep2-1391","cat":"tools-and-help","type":"role-play","persona":"any","source":"decline the scorecard","hook":"Your weekly fairness chat is turning into a count of who did what.","setup":"Your partner is mid-list when you step in.","steps":[{"prompt":"Your partner says: \"I did three more nappies than you this week.\"","options":[{"text":"\"Let's not count. Do we each own areas?\"","then":"They pause. \"Whole areas? Instead of counting?\"","best":true},{"text":"\"You're right. I'll do three more.\"","then":"They nod. The debt is paid and the counting stays."},{"text":"\"I did more night feeds, so we're even.\"","then":"They frown. \"Feeds don't cancel nappies.\""},{"text":"\"Fine. I'll write down everything I do.\"","then":"You start a list. So do they."}],"why":"Counting turns care into a scoreboard, so check ownership instead."},{"prompt":"Your partner says: \"Honestly, I only count because I can't tell if it's fair.\"","options":[{"text":"\"You'll just have to trust me.\"","then":"They look unsure. Trust without a plan is a guess."},{"text":"\"Let's ask your mother who is right.\"","then":"They laugh. Now there are three opinions."},{"text":"\"We'll tally monthly instead.\"","then":"They nod. It is the same scoreboard, monthly."},{"text":"\"Let's each run an area and flex.\"","then":"They think. \"So no scoreboard, just trust and check-ins?\"","best":true}],"why":"Fair means ownership and flexing, so trust rests on how you run it."},{"prompt":"Your partner says: \"What if you're busy and I cover for you?\"","options":[{"text":"\"It'll all balance out somehow. Don't worry.\"","then":"They nod. It doesn't balance out."},{"text":"\"Then I'll note it on a chart.\"","then":"They nod. The chart grows a new column."},{"text":"\"Then I cover for you when you're stuck.\"","then":"They smile. \"Okay. That's fair.\"","best":true},{"text":"\"Then I owe you three nappies for it.\"","then":"They laugh. \"Written down?\" You both hear the tally."}],"why":"Flexing for each other, without a ledger, keeps the shared job light."}],"relearn":"Steering a fairness talk to owned domains and flexibility beats turning it into a chore-by-chore scoreboard."},
  {"id":"ep2-1392","cat":"tools-and-help","type":"role-play","persona":"Vikram","source":"stop saying babysitting","hook":"You've mentioned at work that your weekend is all about the kids.","setup":"You are at the coffee machine.","steps":[{"prompt":"Your colleague asks: \"Babysitting the kids this weekend?\"","options":[{"text":"\"Please don't call it that.\"","then":"His smile drops. \"Sorry. It's just a joke.\""},{"text":"\"Ha. Yes, on dad duty, giving my wife a break.\"","then":"He laughs. The joke sticks and so does the favour idea."},{"text":"\"Not babysitting. They're mine. I'm parenting.\"","then":"He grins. \"Ha. Fair point.\"","best":true},{"text":"\"Yeah. She needs a rest after all this.\"","then":"He nods. Your weekend gets described as a gift."}],"why":"A light reframe keeps things friendly and still names it as parenting."},{"prompt":"Another colleague laughs: \"Babysitting! Does your wife pay you by the hour?\"","options":[{"text":"\"That's a bit offensive, actually. Come on.\"","then":"He bristles. \"Relax. I didn't mean anything.\""},{"text":"\"Ha. Double rates on Sundays, of course.\"","then":"Everyone laughs. The joke follows you back to your desk."},{"text":"\"Let's not get into it. It's only Friday.\"","then":"He shrugs. He'll say it again next week."},{"text":"\"No pay. It's my job, not a favour.\"","then":"He pauses. \"Huh. I never thought of it that way.\"","best":true}],"why":"Saying lightly why the word matters helps without starting a fight."},{"prompt":"On Monday, your colleague asks: \"So what did you actually do with them all weekend?\"","options":[{"text":"\"The fun things. She did the boring stuff.\"","then":"He chuckles. Your wife would not laugh."},{"text":"\"Whatever she left on the list.\"","then":"He nods. Your wife is the one who wrote the list."},{"text":"\"Mostly cartoons and snacks.\"","then":"He laughs. \"Sounds easy.\""},{"text":"\"Meals, baths, homework, lots of stories.\"","then":"He lifts his eyebrows. \"That's a full-time job.\"","best":true}],"why":"Naming what you do shows it is real parenting, not a day off."}],"relearn":"Naming that caring for your own kids is parenting, not babysitting, resets the favour framing in one line."},
  {"id":"ep2-1393","cat":"tools-and-help","type":"role-play","persona":"Divya","source":"hand over not delegate","hook":"Writing the family's to-do list each week has become your most tiring job.","setup":"You are writing the Sunday list once more.","steps":[{"prompt":"Your partner says: \"Just give me the list and I'll do it all.\"","options":[{"text":"\"Okay. I'll write you a list every Sunday night.\"","then":"You write it. Sunday evenings are gone again."},{"text":"\"Take school fully. Track the dates, forms and fees.\"","then":"They blink. \"All of it? Not just tasks from you?\"","best":true},{"text":"\"Then write it yourself for once.\"","then":"They look startled. \"I wouldn't know what to put.\""},{"text":"\"Never mind. I'll do it myself.\"","then":"They look relieved. You are back where you started."}],"why":"Handing over a whole area moves the tracking as well as the tasks."},{"prompt":"Your partner admits: \"I never know when things are due. That's why I ask.\"","options":[{"text":"\"I'll keep the calendar. You just look at it.\"","then":"They look at it. You are still the one who fills it in."},{"text":"\"I'll tell you all the dates today.\"","then":"You tell them. Next week they ask again."},{"text":"\"I'll text you a reminder each week.\"","then":"You text every Sunday. You are still the keeper."},{"text":"\"Then the school diary and group are yours.\"","then":"They sigh and take the diary. \"Okay. I'll check daily.\"","best":true}],"why":"Giving them the tools makes the area theirs to run."},{"prompt":"Your partner says: \"What if I miss one?\"","options":[{"text":"\"Then I'll be really annoyed.\"","then":"They look worried. The area feels like a test."},{"text":"\"Just ask me first. I'll double check.\"","then":"They ask you every time. You are still the manager."},{"text":"\"Then you fix it and adjust.\"","then":"They nod. \"Okay. I'll set alerts.\"","best":true},{"text":"\"Then I'll take it back.\"","then":"They nod, relieved. School drifts back to you."}],"why":"A slip is part of learning, so trust them to fix it."}],"relearn":"Handing over a whole domain to track and run beats being asked for a list, which keeps the load on you."},
  {"id":"ep2-1394","type":"sort","persona":"any","source":"supports vs undermines","hook":"Sort each habit: does it support a fair split, or quietly undermine it?","items":[{"id":"a","text":"A monthly rebalancing check-in"},{"id":"b","text":"Both owning whole domains"},{"id":"c","text":"One shared calendar you both keep"},{"id":"d","text":"Praising dad for the bare minimum"},{"id":"e","text":"Gatekeeping so only mum 'does it right'"},{"id":"f","text":"Waiting to be told every task"}],"bins":[{"id":"support","label":"Supports a fair split","valence":"pos"},{"id":"undermine","label":"Undermines it","valence":"neg"}],"key":{"a":"support","b":"support","c":"support","d":"undermine","e":"undermine","f":"undermine"},"relearn":"Check-ins, owned domains and a shared calendar support a fair split; gatekeeping, bare-minimum praise and waiting undermine it.","cat":"tools-and-help"},
  {"id":"ep2-1395","type":"sort","persona":"any","source":"visible vs mental load","hook":"Sort each job: is it visible care, or the invisible mental load?","items":[{"id":"a","text":"Giving the baby a bath"},{"id":"b","text":"Remembering the next vaccine date"},{"id":"c","text":"Cooking the kids' dinner"},{"id":"d","text":"Noticing the school shoes are too tight"},{"id":"e","text":"Tracking when nappies are running low"},{"id":"f","text":"Dropping them at school"}],"bins":[{"id":"visible","label":"Visible care","valence":"neutral"},{"id":"mental","label":"Invisible mental load","valence":"tell"}],"key":{"a":"visible","c":"visible","f":"visible","b":"mental","d":"mental","e":"mental"},"relearn":"Baths, cooking and drop-offs are visible care; remembering, noticing and tracking are the invisible load: share both.","cat":"tools-and-help"},
  {"id":"ep2-1396","type":"sort","persona":"any","source":"fix vs practice","hook":"Sort each idea: is it a one-time fix, or an ongoing practice fair parenting needs?","items":[{"id":"a","text":"Agree the split just once and stop"},{"id":"b","text":"Revisit the split at each new stage"},{"id":"c","text":"Assume it'll stay fair on its own"},{"id":"d","text":"Hold a regular rebalancing check-in"},{"id":"e","text":"Re-map tasks when a baby arrives"},{"id":"f","text":"Set it and never look again"}],"bins":[{"id":"ongoing","label":"Ongoing practice","valence":"pos"},{"id":"onetime","label":"One-time-and-forget","valence":"uhoh"}],"key":{"b":"ongoing","d":"ongoing","e":"ongoing","a":"onetime","c":"onetime","f":"onetime"},"relearn":"Fair parenting is an ongoing practice: revisit, check in, re-map; set-once-and-forget lets the default return.","cat":"tools-and-help"},
  {"id":"ep2-1397","type":"sort","persona":"Vikram","source":"owning vs helping","hook":"Sort each line: is it owning the load, or just helping when asked?","items":[{"id":"a","text":"'I track and book all the dentist visits'"},{"id":"b","text":"'I do whatever she puts on my list'"},{"id":"c","text":"'I run bedtime start to finish'"},{"id":"d","text":"'I help out when she's overwhelmed'"},{"id":"e","text":"'I notice when supplies run low and restock'"},{"id":"f","text":"'I step in if she asks me to'"}],"bins":[{"id":"owning","label":"Owning a domain","valence":"pos"},{"id":"helping","label":"Helping when asked","valence":"uhoh"}],"key":{"a":"owning","c":"owning","e":"owning","b":"helping","d":"helping","f":"helping"},"relearn":"Owning means tracking and running a domain yourself; helping when asked leaves your partner the manager.","cat":"tools-and-help"},
  {"id":"ep2-1398","type":"sort","persona":"any","source":"when to route support","hook":"Sort each situation: a normal rough patch to ride out, or a sign to reach for support?","items":[{"id":"a","text":"A hard week after a new baby"},{"id":"b","text":"Weeks of exhaustion and dread that won't lift"},{"id":"c","text":"Feeling tired but bouncing back by the weekend"},{"id":"d","text":"Losing interest in the kids and yourself"},{"id":"e","text":"A tough day that a rest fixes"},{"id":"f","text":"Persistent low mood that's not shifting"}],"bins":[{"id":"normal","label":"Normal rough patch","valence":"neutral"},{"id":"support","label":"Reach for support","valence":"tell"}],"key":{"a":"normal","c":"normal","e":"normal","b":"support","d":"support","f":"support"},"relearn":"A hard week or a tired day is normal; weeks of dread, low mood or losing interest signal reaching for support.","cat":"tools-and-help"},
  {"id":"ep2-1399","type":"sort","persona":"any","source":"tool to load type","hook":"Sort each tool: does it mainly map who-does-what, or keep the split fair over time?","items":[{"id":"a","text":"The task-and-load map"},{"id":"b","text":"The monthly rebalancing check-in"},{"id":"c","text":"Listing owned domains up front"},{"id":"d","text":"Re-mapping when a new stage hits"},{"id":"e","text":"A week-long who-decided-what audit"},{"id":"f","text":"Swapping domains now and then"}],"bins":[{"id":"map","label":"Maps who-does-what","valence":"neutral"},{"id":"maintain","label":"Maintains it over time","valence":"pos"}],"key":{"a":"map","c":"map","e":"map","b":"maintain","d":"maintain","f":"maintain"},"relearn":"Mapping tools name who-does-what; check-ins, re-maps and swaps keep the split fair over the years.","cat":"tools-and-help"},
  {"id":"ep2-1412","type":"sort","persona":"any","source":"concrete vs vague","hook":"Sort each plan: a concrete tool that shifts the split, or a vague intention?","items":[{"id":"a","text":"Each picks two domains to own this month"},{"id":"b","text":"'We'll just try to be fairer somehow'"},{"id":"c","text":"Book a monthly check-in in the diary"},{"id":"d","text":"'I'll help out more when I can'"},{"id":"e","text":"Put every kid date on a shared calendar"},{"id":"f","text":"'We'll sort it out as we go along'"}],"bins":[{"id":"concrete","label":"Concrete tool","valence":"pos"},{"id":"vague","label":"Vague intention","valence":"uhoh"}],"key":{"a":"concrete","c":"concrete","e":"concrete","b":"vague","d":"vague","f":"vague"},"relearn":"Owned domains, a booked check-in and a shared calendar are concrete; 'be fairer' or 'help more' are vague wishes that don't shift things.","cat":"tools-and-help"},
  {"id":"ep2-1400","type":"spot","persona":"any","source":"red flags vs sustainable","hook":"Spot the two moves that will quietly let a fair split slide back.","scene":[{"id":"a","text":"Small regular rebalancing check-ins","trick":false},{"id":"b","text":"One grand promise, never revisited","trick":true},{"id":"c","text":"Both owning whole domains over time","trick":false},{"id":"d","text":"Assuming a one-time split holds forever","trick":true},{"id":"e","text":"Re-mapping the load at each new stage","trick":false}],"why":"A one-off promise and assuming the split holds forever both let the default creep back; the rest sustain it.","relearn":"A fair split lasts on regular rebalancing and shared ownership, not a one-off promise left unrevisited.","cat":"tools-and-help"},
  {"id":"ep2-1401","type":"spot","persona":"Vikram","source":"helper-talk red flags","hook":"Spot the two lines that keep one parent the manager instead of sharing the load.","scene":[{"id":"a","text":"'I own health end-to-end'","trick":false},{"id":"b","text":"'Just tell me what to do and I'll do it'","trick":true},{"id":"c","text":"'It's on our shared calendar'","trick":false},{"id":"d","text":"'Remind me each time something's due'","trick":true},{"id":"e","text":"'I track when supplies run low'","trick":false}],"why":"'Just tell me' and 'remind me each time' keep your partner tracking and assigning: they stay the manager.","relearn":"Lines that wait to be told keep one parent the manager; owning and tracking a domain shares the real load.","cat":"tools-and-help"},
  {"id":"ep2-1402","type":"spot","persona":"any","source":"undermining red flags","hook":"Spot the two habits that undermine a fair split.","scene":[{"id":"a","text":"A monthly rebalancing check-in","trick":false},{"id":"b","text":"Gatekeeping so only mum 'does it right'","trick":true},{"id":"c","text":"Both holding the shared calendar","trick":false},{"id":"d","text":"Praising dad for the bare minimum","trick":true},{"id":"e","text":"Each owning whole domains","trick":false}],"why":"Gatekeeping and praising the bare minimum both push the load back onto one parent; the rest keep it shared.","relearn":"Gatekeeping and bare-minimum praise undermine a fair split; check-ins, a shared calendar and owned domains keep it.","cat":"tools-and-help"},
  {"id":"ep2-1403","type":"spot","persona":"any","source":"stale-split red flags","hook":"Spot the two beliefs that let an old split go stale as the kids grow.","scene":[{"id":"a","text":"Revisiting the split as kids change","trick":false},{"id":"b","text":"'The toddler-era split is fine forever'","trick":true},{"id":"c","text":"Both staying hands-on and informed","trick":false},{"id":"d","text":"'We sorted this once, so we're done'","trick":true},{"id":"e","text":"Adding new school admin to the split","trick":false}],"why":"Treating an old split as final ignores new tasks each stage brings; revisiting and staying hands-on keep it fair.","relearn":"An old split goes stale as kids grow; revisit it and both stay hands-on rather than calling it done for good.","cat":"tools-and-help"},
  {"id":"ep2-1404","type":"spot","persona":"any","source":"fake-sharing red flags","hook":"Spot the two things that look like sharing but leave the mental load on one parent.","scene":[{"id":"a","text":"Both owning whole domains end-to-end","trick":false},{"id":"b","text":"One parent assigning tasks to the other","trick":true},{"id":"c","text":"A check-in to rebalance the load","trick":false},{"id":"d","text":"Writing the to-do list for your partner","trick":true},{"id":"e","text":"Each tracking their own domain","trick":false}],"why":"Assigning tasks and writing the list keep one parent doing the tracking: the heaviest, invisible part of the load.","relearn":"Assigning tasks or writing the list keeps the tracking on one parent; owning domains shares the real load.","cat":"tools-and-help"},
  {"id":"ep2-1405","type":"spot","persona":"any","source":"burnout red flags","hook":"Spot the two responses to a burning-out parent that make things worse.","scene":[{"id":"a","text":"Take over some domains for a while","trick":false},{"id":"b","text":"'Just toughen up and push through'","trick":true},{"id":"c","text":"Reach Looking After You together","trick":false},{"id":"d","text":"'A real parent copes alone'","trick":true},{"id":"e","text":"Reach Tele-MANAS 14416 for support","trick":false}],"why":"'Toughen up' and 'cope alone' shame real burnout and risk the parent; taking load and reaching support help.","relearn":"Telling a burnt-out parent to toughen up or cope alone makes it worse; share load and reach support instead.","cat":"tools-and-help"},
  {"id":"ep2-1406","type":"spot","persona":"any","source":"scorecard red flags","hook":"Spot the two ways of doing 'fairness' that turn parenting into a tense scoreboard.","scene":[{"id":"a","text":"Each owning whole domains and flexing","trick":false},{"id":"b","text":"Tallying every nappy each parent did","trick":true},{"id":"c","text":"Checking in on who feels overloaded","trick":false},{"id":"d","text":"Keeping a running chore scoreboard","trick":true},{"id":"e","text":"Covering for each other on a hard day","trick":false}],"why":"Tallying nappies and keeping a chore scoreboard breed resentment; owned domains and flexing keep it fair and warm.","relearn":"Fairness is owned domains and flexibility, not a nappy tally or chore scoreboard that breeds resentment.","cat":"tools-and-help"},
  {"id":"ep2-1407","type":"spot","persona":"any","source":"grandparent-routing red flags","hook":"Spot the two patterns that quietly route all the care back to one parent in a joint family.","scene":[{"id":"a","text":"Family asks both parents about the kids","trick":false},{"id":"b","text":"Every care question goes to mum only","trick":true},{"id":"c","text":"Both parents coordinate with grandparents","trick":false},{"id":"d","text":"'Leave the baby stuff to the women'","trick":true},{"id":"e","text":"Dad's named on the school and clinic lists","trick":false}],"why":"Routing every care question to mum and 'leave it to the women' rebuild the default; involving both keeps care shared.","relearn":"Care routed only to mum, or 'leave it to the women', rebuilds the default; involve both parents.","cat":"tools-and-help"},
  {"id":"ep2-1408","type":"spot","persona":"any","source":"vague-intent red flags","hook":"Spot the two vague intentions that won't actually shift a default split.","scene":[{"id":"a","text":"Each picks domains to own this month","trick":false},{"id":"b","text":"'I'll try to be more helpful around here'","trick":true},{"id":"c","text":"Put all kid dates on a shared calendar","trick":false},{"id":"d","text":"'We'll just be fairer from now on'","trick":true},{"id":"e","text":"Book a monthly check-in in the diary","trick":false}],"why":"'Be more helpful' and 'just be fairer' are vague wishes; owned domains, a shared calendar and a booked check-in are concrete.","relearn":"Vague wishes like 'be more helpful' don't shift a default; owned domains, a shared calendar and a check-in do.","cat":"tools-and-help"},
  {"id":"ep2-1409","type":"spot","persona":"Priya","source":"modelling red flags","hook":"Spot the two habits that teach kids the old divide instead of shared care.","scene":[{"id":"a","text":"Dad cooks and packs bags where kids see","trick":false},{"id":"b","text":"Only mum is ever seen caring for the kids","trick":true},{"id":"c","text":"Both parents do drop-offs and bedtime","trick":false},{"id":"d","text":"Telling a son 'that's not boys' work'","trick":true},{"id":"e","text":"Sons and daughters share chores alike","trick":false}],"why":"Kids copy what they see; only-mum-caring and 'not boys' work' teach the divide, while shared visible care unteaches it.","relearn":"Kids learn from what they see; only-mum care and 'not boys' work' teach the divide: model shared care instead.","cat":"tools-and-help"},
  {"id":"ep2-1410","type":"spot","persona":"any","source":"quit-signal red flags","hook":"Spot the two thoughts that wrongly treat normal difficulty as a reason to give up on fair parenting.","scene":[{"id":"a","text":"'This is hard, so let's use the tools'","trick":false},{"id":"b","text":"'It's hard, so fair just isn't for us'","trick":true},{"id":"c","text":"'Let's check in and rebalance again'","trick":false},{"id":"d","text":"'Too much effort, back to the old way'","trick":true},{"id":"e","text":"'Difficulty is normal, we can work it'","trick":false}],"why":"Treating normal difficulty as proof fair 'isn't for us' is the quit trap; the rest meet the hard part with tools.","relearn":"Keeping a fair split is ongoing effort; difficulty is normal and workable, never a reason to quit.","cat":"tools-and-help"},
];

